WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[25891] = { title = "Last Ditch Effort", description = "The Horde have signaled a retreat. Look now, they fall back from the field of battle - portends of disaster.\n\nWe must make one final descent into Thal'darah Grove. I could not live with myself if any of our young druids were left behind.\n\nAssist me, hero. I will take the reins. You search for any druids that might be left behind.\n\nWe will go when you are ready. ", objectives = "Assist Master Thal'darah in search of any druids left behind at Thal'darah Grove.", completion = "Do you know why the Horde destroys? The Horde destroys because they cannot comprehend beauty. They fear it and that which they fear they must destroy. Why else would they destroy Thal'darah Grove?\n\nTogether, we will make them understand. They will know that what they do comes at a great cost." }
WordHunterWoW_QuestEN[25892] = { title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", objectives = "Use Wavespeaker Valoren's sea horse to return to Admiral Dvorek under the southern terrace in the Ruins of Vashj'ir.", completion = "You made it! After the attack at the forward post, I thought we might be the only ones left. I'm very glad to see you." }
WordHunterWoW_QuestEN[25893] = { title = "Desperate Plan", description = "Jorlan and Hexascrub left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", objectives = "Meet with Engineer Hexascrub on Biel'aran Ridge.", completion = "Impeccable timing. Like clockwork! Trouble comes. You come. Save the day.  Clockwork!\n\nWe've devised our brilliant plan. Gloriously simple, barring the hostility of local life. Simpler yet with a you available!" }
WordHunterWoW_QuestEN[25894] = { title = "Hostile Waters", description = "Hexascrub came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those gill goblins. Or at the very least, enough of them to make them a bit more wary of us.", objectives = "Kill 10 Muckskin Scroungers.", completion = "Less gill goblins is good!\n\nI'm glad that they're so primitive. I don't think I'd want to be dealing with a race of aquatic tech-freaks right now. Not at all." }
WordHunterWoW_QuestEN[25895] = { title = "Come Prepared", description = "We must always come prepared. Prepared with gear. Prepared with plans. Prepared with gear plans!\n\nAll of the ships in all of the Alliance fleets stow a survival kit. A lot of our tools came from a survival kit. My balloon came from a survival kit too! But now it's gone. I need another survival kit!\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us!", objectives = "Retrieve an Alliance Survival Kit.", progress = "A whole big box of amazing! That's what it is. I need more amazing in my life.\n\nDon't worry, I'll share.", completion = "Let me see, let me see... flare gun... balloon... no rope. Never any rope. Terribly impractical if you do ask me. Rope should be mandatory." }
WordHunterWoW_QuestEN[25896] = { title = "Devout Assembly", description = "Ah, Battlemaiden. You carry with you the word and the will of our Lady. I might ask a favor of you...\n\nI need Fathom-Caller Azrajar and my Tide Priestesses to return so that we can begin the ritual. Can you carry my will to them as such? You should find them spread upon the temple terrace. Azrajar will be at the stairs to the north.", objectives = "Seek out Fathom-Caller Azrajar midway down the northern stairs and 6 Sira'kess Tide Priestesses on the upper portion of the ruins, and instruct them to return to the temple.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "The Kvaldir have proved a greater threat than we anticipated, but our plans are not hindered in the least. As our allies arrive, we will have a force more than sufficient to usurp the Tidehunter.\n\nAll that remains is to ensure that the ritual of summoning is completed." }
WordHunterWoW_QuestEN[25897] = { title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! No sense at all.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. Absolutely must.", objectives = "Collect 8 Coils of Kvaldir Rope.", progress = "The rope ties the whole plan together!", completion = "This is great! I love it. It should work per... ewww! Is this stuff braided with hair?\n\nDoesn't matter. Almost done. This thing will be ready in the twist of a rope." }
WordHunterWoW_QuestEN[25898] = { title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Fortuitous.\n\nJorlan already swam up to catch it. Swam up and stopped to wait for it. He said you'd get the honors though. Jorlan's nice like that.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Alliance ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", objectives = "Swim to the surface, retrieve the flare gun, and fire a rescue flare towards the Alliance Ships.", progress = "Those aren't trade ships, those are war ships. Still, this is an incredible stroke of luck. Fire that flare off and pray that they see it.", completion = "Perfect! There's no way they missed that, fighting or not." }
WordHunterWoW_QuestEN[25899] = { title = "Breakthrough", description = "The fiery army that caused so much devastation up the hill has retreated east of here. Only the Scorchlords remain in action. If we can punch a hole through their lines to regroup with Captain Irontree's forces, the whole offensive may collapse.\n\n{class}, I'm in no shape to continue fighting, but you look like you can do some damage. Slay those Scorchlords and regroup with Captain Irontree!", objectives = "Slay 10 Twilight Scorchlords.", completion = "You killed how many? Well, well. Quite a show. I guess my men don't have any more excuses." }
WordHunterWoW_QuestEN[25900] = { title = "Making Contact", description = "I can't believe that Nespirah would willingly allow these naga to take residence inside her shell.  As I see it, one of two things has happened: they have convinced her to willingly join their cause, or they have weakened her to a point where she cannot fight back.  Either one is bad.\n\nHere in this chamber, I should be able to communicate directly with Nespirah.  Let us find out for ourselves.  Speak to me when you are prepared, {class}.", objectives = "Observe as Earthmender Duarn attempts to communicate with Nespirah.", progress = "Nespirah needs our help.  If nothing else, I can sense that.", completion = "That didn't go well.  For some reason, the beast won't speak back to me.\n\n<Duarn is clearly frustrated.>\n\nIf only Erunak had not left us!  He would know what to do." }
WordHunterWoW_QuestEN[25901] = { title = "Hyjal Recycling Program", description = "Reinforcements! I thought we were going to fight this out to the bitter end.\n\nVery few of the Guardians of Hyjal remain, and our supplies are running out. The battlefield around our holdout here must be littered with serviceable arrows.\n\nI know it's beneath your abilities, but can you gather up our spent ammunition? It's the only way we can replenish our supplies!", objectives = "Gather 15 Warden's Arrows.", progress = "Warden's arrows are crafted of living oak, blessed in the moonwells, and tipped with obsidian arrowheads scrawled with runes invoking the blessings of nature.\n\nThey're not cheap.", completion = "Wonderful! Still sharp. A little blood on the fletching, but they'll fly true.\n\nThank you, <name>. Our defense of Hyjal can continue." }
WordHunterWoW_QuestEN[25902] = { title = "Your First Totem!", description = "", objectives = "You will also receive:" }
WordHunterWoW_QuestEN[25903] = { title = "It's Hot and it Might Explode", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[25904] = { title = "The Hammer and the Key", description = "My Nemesis. Still lives.\nThe servants of fire still come.\nWe must pursue. Into their den.\n\nThe ogres know the way.\nSlay the Field Captains.\nRecover the Glyph of Opening.\n\nThis is the way.", objectives = "Kill a Twilight Field Captain and recover the Glyph of Opening.", progress = "The glyph. Show it to me.", completion = "This power is ancient.\nPrimitive.\nEasy.\n\nWe will use it against them." }
WordHunterWoW_QuestEN[25905] = { title = "Rams on the Lam", description = "The rams we raise and train here at Amberstill ranch have long been the mounts of choice for Dun Morogh's mountaineers. Aye, there're a few here, but not enough to guard my family and all the animals.\n\nA few brave Frostmane raiders have taken to stealing our rams under the cover of night, taking them south into the Tundrid Hills. Would you be willing to help return them? You'll need to get fairly close to them and give a sharp whistle to get their attention. Their training will take over from there.", objectives = "Recover 6 Stolen Rams from the Tundrid Hills by using /whistle.", completion = "The rams you rescued have made their way back into the pen. I've got members of the family on a day and night watch now. Those trolls won't take us by surprise again!" }
WordHunterWoW_QuestEN[25906] = { title = "The Third Flamegate", description = "Memorize the glyph.\nTake it within yourself.\n\nDraw it on the ground before the flamegate.\nEast of here.\nEnter the Firelands.\n\nI cannot come with you.\nBut my children await. Inside.\n\nFind Garunda Mountainpeak within the realm of flame.", objectives = "Travel through the flamegate in the Scorched Plain and locate Garunda Mountainpeak within.", completion = "You were sent by the turtle god? Bless his almighty shell! I thought I was trapped down here forever." }
WordHunterWoW_QuestEN[25907] = { title = "Slave Labor", description = "It will take me some time to break through this barrier and communicate with Nespirah.  In the meantime, you can save some of those men that the naga have enslaved in the pits below.\n\n<Duarn produces a length of rope from within his robes.>\n\nThis should come in handy.", objectives = "Use Duarn's Rope to save 8 Enslaved Pearl Miners.", completion = "Excellent work, <name>... although I'm afraid I haven't been nearly as productive as you have." }
WordHunterWoW_QuestEN[25908] = { title = "Stick it to Them", description = "I may be unable to communicate directly with the beast Nespirah, but I can still feel some things indirectly.  For example, I can clearly sense that Nespirah is not happy about the naga's presence here.\n\nWhen we first entered Nespirah's body, I saw dozens of sentinels and enchantresses patrolling the central chamber floor.  Perhaps some of the ancient one's pain will be alleviated if you remove them.", objectives = "Kill 7 Idra'kess Sentinels and 7 Idra'kess Enchantresses.", completion = "Can you sense it?  If you have an ounce of shaman's blood in you, you must feel the sense of relief in the air.\n\nNespirah is pleased.  Perhaps she will finally speak with us." }
WordHunterWoW_QuestEN[25909] = { title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", objectives = "Use Duarn's Net to capture a Deepseeker Crab inside of Nespirah.", progress = "I hope this works.  My skills as a shaman are limited, and I fear that this task may be too much for us.", completion = "<Duarn looks at the crab and disguises a frown.>\n\nIt doesn't look very impressive, does it?" }
WordHunterWoW_QuestEN[25910] = { title = "The Time for Mercy has Passed", description = "This cavern is an abomination, {name}. And it's filled with horrors from the depths.\n\nI don't want any of these - things - getting through the portal to the outside world. Slay everything!", objectives = "Slay 10 Molten Tormentors and 4 Shadowflame Masters.", completion = "So it is done.\n\nKnowing that Twilight's Hammer is in league with creatures of malice such as these... it really curdles the blood." }
WordHunterWoW_QuestEN[25911] = { title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}. ", objectives = "Return to Captain Taylor at the Tranquil Wash.", completion = "That is the best news I've heard in what seems like an eternity. We'll get the survivors moving over there to the surface as soon as possible. Perhaps we can forget that this whole nightmare ever happened.\n\nThank you, <name>. I'm not sure there's anything I can do to repay you for everything you've managed to accomplish in this ocean, but I will try to find a way.\n\nYou should consider meeting us at the ships later, when you finish saying your goodbyes to the naga." }
WordHunterWoW_QuestEN[25912] = { title = "Seen Better Days", description = "The world is unraveling around us, {name}. Old enemies seek to destroy us from one end, while ancient forces close in on the other.\n\n<Elder Sareth'na sighs.>\n\nI have seen better days - brighter days, and I long for them...\n\nAcross Stonetalon Peak lies the ruins of our old outpost - now overrun with darkness. If you happen to go that way, could you search for my sketch book? It holds many happy memories. I would reward you well for its return.", objectives = "Find Elder Sareth'na's Sketch Book.", progress = "Have you found my sketch book?", completion = "You've found it! Elune bless you, child! Perhaps this book will give me the strength to carry on." }
WordHunterWoW_QuestEN[25913] = { title = "Putting Them to Rest", description = "As the Horde were marching upon Stonetalon, I noticed that some of the sentinels had fallen ill. Not long after, they started acting strangely. When the first tentacle burst from the ground the ill sentinels began attacking us. We lost the outpost shortly after...\n\nThe sentinels in the peak are now nothing more than shells - husks for something far more sinister. I want you to put the sentinels to rest and retrieve their glaives. Each glaive returned can identify a fallen sister.", objectives = "Recover 8 Sentinel's Glaives.", progress = "Recover the sentinel's glaives, <name>. Each glaive is unique to a sentinel.", completion = "Thank you, <name>. Each glaive has the name of the sentinel it belonged to imprinted upon its blade. We can now send word to their families and put their souls to rest." }
WordHunterWoW_QuestEN[25914] = { title = "Back to the Depths!", description = "Tendrils are bursting forth from the earth and terrorizing Stonetalon Peak. My sentinels are hardly making a dent in their numbers.\n\nI suspect that there is a force at the heart of Stonetalon Peak that controls the tendrils. Perhaps if we can put a stop to that force, the tendrils will return to the depths from whence they came!", objectives = "Kill Harbinger Aph'lass and 10 Invading Tentacles.", completion = "I'm afraid that the death of Harbinger Aph'lass has not ceased the tendril attacks. You've done all that you can, <name>, and for that I thank you." }
WordHunterWoW_QuestEN[25915] = { title = "The Strength of Tortolla", description = "The dark usurper Nemesis fled here when the fires of Hyjal receded. We are not yet strong enough to defeat Nemesis, {name}, but we may be able to turn his own strength against him.\n\nI will send a child of Tortolla with you, one of the children you freed earlier from the Twilight's corruption.\n\nSearch the depths of this cave for a Nemesis Crystal, and allow the young turtle to examine it.\n\nSee me if you lose your companion!", objectives = "Escort a Child of Tortolla to a Nemesis Crystal. See Garunda Mountainpeak if you lose your companion.", completion = "Ah yes, yes... the secret strength of Nemesis, unearthed here in these caverns.\n\nWe know all that we need to know, <name>. It is time to finish this." }
WordHunterWoW_QuestEN[25916] = { title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", objectives = "Observe as Earthmender Duarn attempts to speak with Nespirah.", progress = "The ritual is not yet complete, <name>.", completion = "I had assumed that the naga were only here for those pearls.  No, this makes much more sense.  If they had Nespirah's power under their control, the amount of damage the naga could do would be catastrophic!\n\nSomething must be done." }
WordHunterWoW_QuestEN[25917] = { title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Alliance slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", objectives = "Find the Alliance survivors inside of Nespirah in Vashj'ir.", completion = "<name>... is that you?" }
WordHunterWoW_QuestEN[25918] = { title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", objectives = "Obtain 4 Purloined Polearms from the weapon racks inside of Nespirah.", progress = "In my youth, I was given some training on spearfighting.\n\n\"Stick them with the pointy end,\" I think it was.", completion = "<Admiral Dvorek admires the polearms you present him.>\n\nOh, I'm sorry.  I was just imagining what these will look like with little bits of naga stuck to the ends of them.  Thank you, <name>.  We'll put these to good use." }
WordHunterWoW_QuestEN[25919] = { title = "Body Blows", description = "<Captain Taylor listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", objectives = "Attack 7 Nespirah Abscesses along the walls of Nespirah's body chamber.", completion = "Hopefully we made some progress.  I'm not sure how we'll know when the creature wakes up, but something tells me that it will be pretty obvious when it does." }
WordHunterWoW_QuestEN[25920] = { title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", objectives = "Obtain 5 Mysterious Pearls from Idra'kess Warlords and Idra'kess Prophets inside of Nespirah.", progress = "The naga must have some ulterior motive with these pearls.  If I had time to study them, I'm certain I could figure it out.", completion = "Brilliant work!\n\n<Valoren tucks the pearls away beneath her armor.>\n\nNow I just need you and Captain Taylor to get me safely out of here.  I can handle the studies from there on." }
WordHunterWoW_QuestEN[25921] = { title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall to the southeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.", objectives = "Head to the top of Nespirah and slay Overseer Idra'kess.", completion = "No need to bring me up to speed... Nespirah has been narrating your adventures as they happened, and Captain Taylor filled me in on the rest.\n\n<Duarn closes his eyes and nods.>\n\nNespirah says that she is quite grateful, and that she has a small surprise ready for the naga." }
WordHunterWoW_QuestEN[25922] = { title = "Waking the Beast", description = "Thanks to you and the Captain, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", objectives = "Speak with Earthmender Duarn inside of Nespirah to activate her bio-defenses, then escape from Nespirah's body.", completion = "It appears that I owe you my life, yet again.  Thank the Light that you found me before you and your shaman activated those bio-defenses." }
WordHunterWoW_QuestEN[25923] = { title = "Finish Nemesis", description = "Your turtle companion can use this newfound power to render the two of you invulnerable for a short period of time. You can \"turtle up\" to avoid the worst of Nemesis and his fury. To do so, simply invoke this totem.\n\nThis is all I can do for you. Together, you and a Child of Tortolla must defeat Nemesis, once and for all. Finish the Usurper!\n\nReturn to me if you lose your turtle friend.", objectives = "Use the Totem of Tortolla and the help of a Child of Tortolla to defeat Nemesis. See Garunda Mountainpeak if you lose your turtle companion.", progress = "Is Nemesis dead?", completion = "The usurper has perished!\n\nTwilight's Hammer dreamed of creating their own pantheon of twisted ancients to rule over the land, sea, and air. With your help, they've all been executed.\n\nWe must tell Tortolla at once!" }
WordHunterWoW_QuestEN[25924] = { title = "Call of Duty", description = "Listen up, {race}!\n\nA new landmass has emerged off the coast of Eastern Kingdoms and we are engaged in a critical battle for control of the island!\n\nVictory there will leave Stormwind completely defenseless!\n\nNow is the time to strike!\n\nReport to the docks at once for transport to the battle.\n\nEvery warship is engaged, so you'll be boarding a mercenary vessel commissioned by the Warchief himself.", objectives = "Ride the mercenary ship to battle.", completion = "Not exactly the battle you had anticipated, I'll wager. But a battle nonetheless, as you shall soon see...." }
WordHunterWoW_QuestEN[25925] = { title = "Thal'darah's Vengeance", description = "We must attempt to establish communication with Farwatcher Glen, to the south. Our Darnassian glaive throwers are at your disposal, {name}. Use them to cut a swath through the encroaching Horde forces and clear a path to Farwatcher Glen.\n\nI only hope we're not too late to save the Glen. Should Farwatcher Glen be intact, find Hierophant Malyk and inform him of our status.", objectives = "Kill 20 Horde soldiers and destroy 3 Krom'gar Demolishers in Battlescar Valley.", completion = "We witnessed the detonation of the bomb. Terrible, terrible destruction... Farwatcher Glen, for better or for worse, is still intact. Unfortunately we've nowhere to run." }
WordHunterWoW_QuestEN[25926] = { title = "Mired in Hatred", description = "The mirebeasts to the west are not my brethren... they are symptoms of the earth's disturbance, a foulness of rot given form.\n\nYou would not understand... they take the shape of my kind, infested within with decaying spores, forcing out flourished life in the swamp. They take all and leave only rot. Nothing left, nothing left!\n\nSoothe my mind, {race}. Slay the mirebeasts, cleanse the land, and perhaps my mind will settle.", objectives = "Kill 10 Mouldering Mirebeasts.", progress = "They aren't gone... I can still FEEL them...", completion = "Ahhh... yes. The swamp suffers less now.\n\nMore threats, though. More lurk. I can see them!" }
WordHunterWoW_QuestEN[25927] = { title = "The Threat of Flame", description = "Flame has threatened me for far too long... far too long... but it is no longer the little ones, no longer mere gnats...\n\nThe fields burn! The hills and highlands scream, {race}, they scream. The elementals brought here consume all life in their wake.\n\nThey cannot stand, they cannot stand. Stop them. STOP THEM! Destroy the bringers of flame...", objectives = "Kill 8 Rampant Fire Elementals.", completion = "Yes... the flames die. There is peace now. Peace for the land." }
WordHunterWoW_QuestEN[25928] = { title = "Tortolla's Triumph", description = "I'll escort the children of Tortolla out of here and seal up this accursed portal.\n\nI'll leave it to you to inform Tortolla of our victory. Simply step back through the flamegate. The ancient will be pleased!", objectives = "Step back through the flamegate and return to Tortolla at the Scorched Plain in Hyjal.", completion = "You've been to the firelands?\n\nNemesis is dead?\n\nSo it is finished.\n\nThank you." }
WordHunterWoW_QuestEN[25929] = { title = "Sea Legs", description = "Greetings, {class}. I am Erunak, a fellow survivor of this savagery.\n\nI'm afraid your travails have only just begun. The naga have been scouring these waters, attacking anyone that still lives.\n\nYou are not yet equipped to survive here, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help you grow accustomed to your environment.", objectives = "Collect 3 Saltwater Starfish and a Conch Shell from the Sea Floor at Legion's Fate.", progress = "Were you able to gather the items I requested, <race>?", completion = "Here you are, <class>. With this you should find maneuvering in the sea to be nearly effortless. \n\nNow we must get to work. There is much to be done in little time." }
WordHunterWoW_QuestEN[25930] = { title = "Ascending the Vale", description = "I am told that before the great upheaval the Charred Vale was a valley, closed off to the sea. One has merely to look to the south to see that the Charred Vale is no longer a valley and in fact has become an area of great volcanic activity.\n\nSalsbury here has configured a device that will allow us to ascend the volcano. Use it to get to the top and assess the goings on.\n\nI will keep in touch with this Gnomecorder device, which Salsbury has so kindly gifted upon me.", objectives = "Use Salsbury's Rocket Pack to ascend the Charred Vale's volcano.", completion = "<The Gnomecorder crackles with energy.>\n\nI say, are you there, <name>? It would appear that you are in the center of a dragon's lair." }
WordHunterWoW_QuestEN[25931] = { title = "Brood of Seldarria", description = "<The Gnomecorder buzzes.>\n\nBe very careful, {name}. You do not want to rouse that black dragon.\n\nNow, look around you. If this is a nest then there must be black dragon eggs nearby. Search the premises for eggs and destroy any that you see.\n\nReturn to me should you find and destroy Seldarria's eggs.\n\nGoldrinn watch over you.", objectives = "Destroy 5 of Seldarria's Eggs.", completion = "A smashing success! Perhaps only a minor victory against the brood of Deathwing, but a victory nonetheless!" }
WordHunterWoW_QuestEN[25932] = { title = "It's Raid Night Every Night", description = "The reports I'm sending Captain Tharran can't really convey the amount of trouble the Frostmanes have created for us. Your assault on the village has started to relieve some of the pressure. The raids are still frequent, but the trolls don't have the numbers they once did.\n\nEven so, my men are tired and their morale is flagging. Would you help us keep watch for the Frostmane raiders? They could turn up at any time.", objectives = "Help Sergeant Flinthammer and his mountaineers defend Amberstill Ranch from Frostmane Raiders.", progress = "We're glad to have your help, <name>.", completion = "With your help, we've managed to weaken the raiders considerably. They haven't suffered such losses since the raids began. Now is the time to press our advantage." }
WordHunterWoW_QuestEN[25933] = { title = "Help for the Quarry", description = "Thank you again for all your help here, {name}.\n\nI have a cousin who used to work in the mines beneath the Gol'Bolar Quarry, but he hasn't been able to work since troggs flooded into the mines and took control. The quarry and its camp are just to the southeast of the ranch. Would you be willing to check in with the foreman there and see if there's anything to be done?", objectives = "Speak to Foreman Stonebrow at the Gol'Bolar Quarry.", completion = "Sergeant Flinthammer? I'm not familiar with the name, but, aye, there is a Flinthammer among the miners. He's one of the ones lucky enough to make it out of the mine, but most of my men are still trapped down there." }
WordHunterWoW_QuestEN[25934] = { title = "World First: Gnomegen", description = "Good day, citizen, allow me to introduce myself. I am Salsbury, soon to be the world's first gnomegen. Malyk has assured me that as soon as my work here is complete he will grant me the gift of the worgen.\n\nSo with the introduction out of the way, I've a request!\n\nWithin the Charred Vale, south of here, roam newly created fire elementals. I desperately need a rare blazing heart of fire from one of the fiends. Get it for me and you bring me one step closer to becoming a gnomegen!", objectives = "Collect 1 Blazing Heart of Fire.", progress = "Have you recovered the blazing heart of fire?", completion = "Excellent. This will allow me to finish my last task and hopefully gain the form of the wolf!\n\n<Salsbury howls.>" }
WordHunterWoW_QuestEN[25935] = { title = "Hungry Pups", description = "Ah, a new arrival! Good that you're here lad! The pups are hungry and we're completely out of food.\n\nThankfully they love dragon meat, which fortuitously exists in abundance within the Charred Vale, south of here.\n\nBe a good boy and fetch me several pounds of black dragon whelp filet.", objectives = "Collect 6 Black Dragon Whelp Filets.", progress = "Hurry, <name>, the pups are hungry!", completion = "Excellent. The dogs will be well fed and ready to defend our outpost for weeks!" }
WordHunterWoW_QuestEN[25936] = { title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", objectives = "Use the Enchanted Conch to rescue 6 Drowning Warriors.", completion = "While you were away, I was able to revive some of the fallen warriors.\n\nWe'll need every hand if we are to survive here." }
WordHunterWoW_QuestEN[25937] = { title = "Priceless Treasures", description = "Mining wasn't the only thing going on in the quarry, you know. I led a team of Explorers' League excavators recovering priceless ancient artifacts.\n\nI managed to escape, but my colleagues were much deeper in the mine and didn't survive the initial trogg attack.\n\nThey took great pride in their work and they risked their lives to learn more of our history. If you're going into the mines, take this pick with you and see if you can find anything in the digs the prospectors started.", objectives = "Recover 8 Frozen Artifacts from inside the Gol'Bolar Quarry Mine.", progress = "Were you able to find any artifacts down there?", completion = "Thank you for recovering these artifacts. I will see to it that they are displayed in the Ironforge museum along with the story of those who died to recover them." }
WordHunterWoW_QuestEN[25938] = { title = "Help for Desolace", description = "I've received a disturbing message from Nijel's Point in Desolace. It would seem as if the great upheaval has created some new problems for them, which they are ill-equipped to handle. I was given no further information.\n\nReport to Office Jankie in Desolace. She will direct you to Nijel's Point.\n\nGood luck, {name}.", objectives = "Report to Officer Jankie at Tethris Aran in Desolace.", completion = "Hold there, stranger!" }
WordHunterWoW_QuestEN[25939] = { title = "For Peat's Sake", description = "The elementals rampaging across Direforge Hill are setting the very land beneath them ablaze. In a marsh such as this, fire can find many places to smoulder through the deep moss and peat.\n\nYou must quench the fires before they spread further. Take this flower... blessed by nature's rain, it will let you douse the fires.\n\nThe blossom may also prove useful against the elementals themselves.", objectives = "Use the Blessed Floodlily to extinguish 7 Marsh Fires.", completion = "In sparing the land further suffering, you've also helped us soothe the greenwarden.\n\nMany thanks, <name>." }
WordHunterWoW_QuestEN[25940] = { title = "Last Stand at Whistling Grove", description = "We might have a chance to beat these flames back thanks to your work in the Inferno.\n\nStill, more wildlife is threatened. Keeper Taldros ran north through the flames, to Whistling Grove.\n\nSee if you can help him!", objectives = "Report to Keeper Taldros at Whistling Grove in Mount Hyjal.", completion = "The forest is being devoured!" }
WordHunterWoW_QuestEN[25941] = { title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", objectives = "Speak to Legionnaire Nazgrim.", completion = "I hear you, <race>.\n\nI understand the urgency, but these men are in no condition to fight." }
WordHunterWoW_QuestEN[25942] = { title = "Buy Us Some Time", description = "Many good warriors have been lost today.\n\nIf what the shaman says is true, then we must act swiftly or we will add to their numbers.\n\nThe naga are out there, scouring these waters looking for survivors.\n\nWe are not yet ready to fight, {race}. You must buy us time to make preparations.\n\nFind the naga that hunt us and delay their efforts.", objectives = "Kill 8 Zin'jatar Raiders at Legion's Fate.", progress = "You give those scaly scum something to think about, <race>?", completion = "Let us hope that your work has bought us the time we need..." }
WordHunterWoW_QuestEN[25943] = { title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these orcs ready for battle.\n\nAny worthy leader knows that his warriors travel and fight on their stomachs. No food, no victory.\n\nThese warriors are weary from their struggle out there. They need food before they're ready to overcome a naga attack.\n\nSpeaking of traveling on stomachs, I saw plenty of crabs out on the sea floor...", objectives = "Collect 8 Succulent Crab Meat from Splitclaw Skitterers.", progress = "You got food for the troops, <race>?", completion = "Good grub.\n\nSoon we'll be back to fighting strength." }
WordHunterWoW_QuestEN[25944] = { title = "Girding Our Loins", description = "As we struggled not to drown, my orcs and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I believe him.\n\nIf we're going to be victorious, we'll need your help to recover our lost equipment.\n\nYou should find it scattered around the sea floor near our shipwrecks here and to the north.\n\nMake haste, {race}. The enemy could arrive at any moment.", objectives = "Collect 5 Orgrimmar Axes, 5 Orgrimmar Breastplates and 5 Orgrimmar Helms from the sea floor and from Gilblin Plunderers in Legion's Fate.", progress = "Were you able to gather up our gear, <race>?", completion = "You have done well, <race>.\n\nOur chances of survival are increasing." }
WordHunterWoW_QuestEN[25945] = { title = "We're Here to Do One Thing, Maybe Two...", description = "You're in Hellscream's army now, {name}, and in Hellscream's army we kick butt and take names. Gone are the days of our people starving in the streets of Orgrimmar as we sign treaties with elves. We take what we need now. Kalimdor belongs to the Horde!\n\nThe Alliance attempts to stop our expansion every chance they get. Unsatisfied with owning most of the Eastern Kingdoms, those pig-lickers want it all!\n\nOverlord Krom'gar has called for more troops in Stonetalon. Get on the caravan west of here and go!", objectives = "Take the Krom'gar Wagon to the Fold in Stonetalon Mountains.", completion = "While you remain in Stonetalon and fight as a Krom'gar soldier you will remain suited up! Am I clear? DO you hear me, grunt? If I see you without Hellscream's beloved tabard I will put my foot so far up your backside that you'll be spitting up laces." }
WordHunterWoW_QuestEN[25946] = { title = "Helm's Deep", description = "This helm and its associated components are marked with the seal of Stormwind. It was no doubt cast off from an Alliance ship that suffered a similar fate to yours.\n\nLooking closer, this seems far too intricate and sturdy to be everyday diving equipment. Perhaps Nazgrim can make some sense of this...", objectives = "Take the Alliance S.E.A.L. Equipment to Legionnaire Nazgrim at The Immortal Coil.\n\nProvided item:", completion = "Blood and Thunder!\n\nThis changes everything, <class>!" }
WordHunterWoW_QuestEN[25947] = { title = "Finders, Keepers", description = "I recognize this helm, {race}. You were wise to bring it to me.\n\nThe Alliance have a special unit, trained and equipped to explore and fight beneath the sea.\n\nIt would seem that they are in this region to do more than just defend against our attack.\n\nThere must be more of these down here, and if you can find them it could turn things around for the Vanguard.", objectives = "Gather 5 pieces of Stormwind S.E.A.L. Equipment.", progress = "Were you able to locate more of the Alliance gear, <name>?", completion = "Well done!\n\nNow, more than ever, we are prepared to face the naga!" }
WordHunterWoW_QuestEN[25948] = { title = "Bring It On!", description = "It is time, {class}.\n\nWe are as ready as we ever will be!\n\nI shall address the Vanguard, and then we shall swim into the sea to meet our fate.", objectives = "Speak with Legionnaire Nazgrim aboard the Immortal Coil.", completion = "No time to address the Vanguard.\n\nJust as well..." }
WordHunterWoW_QuestEN[25949] = { title = "Blood and Thunder!", description = "The time has come to make our stand, {race}.\n\nWe'll defend this ship to our last breath, and make these naga scum think twice before approaching it again!\n\nFor the Horde!", objectives = "Assist Legionnaire Nazgrim in the defense of The Immortal Coil.", completion = "The Earthen Ring has received my distress message and sent help - just in time it would seem.\n\nHopefully more can be sent soon. We are but few against a great many." }
WordHunterWoW_QuestEN[25950] = { title = "Sira'kess Slaying", description = "You're the {name} everyone's been talking about? Good to meet ya, love. Let's have a butcher's hook.\n\nWell, enough rabbit, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and read and write them snakes something quick.\n\nNothing fancy. They're looking for a bother, and we'll give 'em a right good one in the ol' boat race.", objectives = "Slay 10 Sira'kess Naga.", completion = "Chicken and rice, <name>! That will show those sorry and sad snakes who's the ol' pitch and toss!\n\nNow it's bird lime for that tiddlywink. Finger and thumb or plink plonk?" }
WordHunterWoW_QuestEN[25951] = { title = "Final Judgment", description = "Get to the bridge on the east, quickly. Lady Naz'jar and the Fathom-Lord should be there with whatever forces remain.\n\nFollow our Lady's direction, as always. Hold the bridge until we can complete the ritual.\n\nOnce our allies arrive, the Kvaldir will be doomed.", objectives = "Hold the bridge on Quel'Dormir Terrace until Lady Sira'kess' allies arrive.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "Stand with us, Battlemaiden. We shall not fall this day.", completion = "I could ask for no more proficient a Battlemaiden than you. You have done yourself a great honor this day." }
WordHunterWoW_QuestEN[25952] = { title = "Caught Off-Guard", description = "Our escape from the shell can't have gone unnoticed, but either the naga at these ruins weren't informed or they don't consider us a threat. I don't intend to take the opportunity for granted - we strike now.\n\nI need you to slip into the lower level of the ruins to our west and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", objectives = "Kill 10 Azsh'ir Patrollers.", completion = "Excellent work, <class>.\n\nI will get some patrols out of our own to make sure that no more naga get within sight of this cave. We should have the area secured within the hour." }
WordHunterWoW_QuestEN[25953] = { title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of our position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", objectives = "Destroy 8 Azsh'ir Monitors.", completion = "Well done, <name>, and just in time too. The Captain just started sending more men out. Strong axe arms, but I doubt they possess quite the same awareness and finesse that you do.\n\nWe were lucky to have you here when things went south. I suspect you will have a large role to play in things to come as well." }
WordHunterWoW_QuestEN[25954] = { title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but I cannot dismiss my ancestors so readily.\n\nThis was one of the royal cities of the elves in the days when Azshara was queen. In this city lie the keys to lore long lost and artifacts of unimaginable historical value. All I want from you, while you're out in the city proper, is to keep a watchful eye out for objects of significance.", objectives = "Investigate the 4 intact statues in the Vashj'ir Gardens.", completion = "Thank you so much for taking this seriously.\n\nThis is some of the first definitive proof of other members of the Vashj family. Very interesting. And I'd never even heard of either of the other two figures you mentioned until now.\n\nSo much of our history was lost during the sundering - it's exciting to have a chance at reclaiming some of it." }
WordHunterWoW_QuestEN[25955] = { title = "A Better Vantage", description = "This cave is our only refuge. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nWe need a forward post to launch our attacks from. Something defensible.\n\nIn the eastern portion of the ruins on the lowest level, scout the north end of the gardens, the passage leading under the main structure just west of the gardens, and the cluster of buildings at the southeast corner of the ruins, under the bridges.\n\nBring me back any information you can.", objectives = "On the lowest level of the ruins, scout the northern end of the Quel'Dormir Gardens, the passage that leads under the ruins west of the gardens, and the structures at the southeast corner of the ruins, below the bridges.", completion = "This is good intel. You have a sharp eye, <class>.\n\nIt sounds like the building north of the gardens will make a suitable forward post. I will send some men immediately to start defensive preparations and we will reposition there as soon as possible." }
WordHunterWoW_QuestEN[25956] = { title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", objectives = "Bring the broken shard back to the Legion's Rest.", progress = "Yes, <class>?", completion = "A shard of metal?\n\nThe remains you describe sound much like the sea vrykul we encountered in Northrend. We'll not be striking any alliances with their sort, no matter the cause. Still, this information may prove useful in the future.\n\nI will think on it further if time permits. Thank you for bringing it to my attention." }
WordHunterWoW_QuestEN[25957] = { title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", objectives = "Use the Blade of the Naz'jar Battlemaiden at the battle site at the southeast end of the ruins.", completion = "A Battlemaiden? I never heard of such a thing.\n\nThe way you explain it, it sounds like the naga forces are far greater in scope than the Captain could possibly have realized. We might be able to learn more through the blade if we can find other locations where this Battlemaiden was present, but the information you gave me makes me fear for the captain and his soldiers. We must warn them." }
WordHunterWoW_QuestEN[25958] = { title = "Looking Forward", description = "The Captain used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", objectives = "Find and speak to Captain Vilethorn north of the Quel'Dormir Gardens.\n\nUse Wavespeaker Tulra's sea horse to reach the forward post quickly.", completion = "Good to see you again, <class>. I almost thought we'd lost you to the Wavespeaker's fool errand.\n\nDid anything come of it?" }
WordHunterWoW_QuestEN[25959] = { title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south, under the far terrace?", objectives = "Kill 10 of the naga forces building up on the ground level, under the southwestern terrace.", completion = "More naga are amassing to the south than reported too it seems. We shall have to move quickly then." }
WordHunterWoW_QuestEN[25960] = { title = "Not Entirely Unprepared", description = "I overheard your conversation with the Captain. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Bring them more crossbow bolts to buy us some extra time.", objectives = "Deliver 8 Bundles of Crossbow Bolts to Horde Lookouts on ledges around the north end of Quel'Dormir Gardens.", completion = "You are perhaps the most dependable <race> I've ever met. I wish I could have more men that showed half as much pride as you do." }
WordHunterWoW_QuestEN[25961] = { title = "Curious Distraction", description = "Hah! Did you see the Captain giving me dirty looks and decide you'd throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offers us some opportunity to salvage some usefulness out of this whole  mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. I've seen a few tablets like this one spread about the nearby ruins and I put together a rubbing kit for transcribing them. Up to the task?", objectives = "Transcribe the 4 Highborne Tablets.", completion = "Brilliant! I can't have expected much more with the tools I gave you.\n\nI should be able to fill in the blanks and get this all written out shortly. There's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, <name>. You're not bad." }
WordHunterWoW_QuestEN[25962] = { title = "Properly Inspired", description = "Been all over the place. Blown all kinds of things up. I thought I might have some trouble carrying on the trend, what with the water and all, but it's all just a matter of inspiration.\n\nI found something volatile enough to make bombs out of! There's a bunch of kelp hanging under the terrace to the southwest. Normally kelp stores gas that makes it float - this kelp produces a different kind of heavy gas. It keeps it hanging, but also makes for great explosions.\n\nGather me some?", objectives = "Gather 8 Bloated Kelp Bulbs hanging under the southwestern terrace.", progress = "Tick, tock, tick, tock. Always in such a hurry. No time for innovation. What I wouldn't give for a lab again!", completion = "You are brave indeed! I've seen you battling all manner of murloc, naga, and pointy-toothed fish, but that was nothing! The way you just sling those kelp bulbs under your arm like that is a whole new kind of fearless. BOOM! You could blow up at any second.\n\nYou're my kind of <race>." }
WordHunterWoW_QuestEN[25963] = { title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the run. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the southern terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", objectives = "Speak to Fiasco Sizzlegrin just outside of the building to join the assault, then use your improvised explosives to kill 100 Azsh'ir Soldiers, 20 Azsh'ir Wave Screamers, and 12 Azsh'ir Archaens.", completion = "You did great up there, soldier! You devastated their ranks, but there were far more than we accounted for, and most of my men went down out there in the masses of naga.\n\nWe'll need to hold this position as long as possible to buy them time. Hopefully some of them will still make it to the rendezvous." }
WordHunterWoW_QuestEN[25964] = { title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", objectives = "Rescue 6 Injured Assault Volunteers.", progress = "These guys aren't in good shape. We may need to retreat sooner than we'd like.", completion = "Thank you. Truly.\n\nWe need to get these men moving as soon as possible. I'll meet you back at the forward post soon, I'm sure." }
WordHunterWoW_QuestEN[25965] = { title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The captain winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", objectives = "Scout the northwestern portion of the circular terrace and the tunnel under the main stairs to the north. Both locations are on Nar'shola Terrace, the middle level of the ruins.", completion = "Still so many? They must want something very important here to come in such numbers.\n\nI will be honest with you, <name>, because you deserve at least that: I don't know how much hope there is. We will retreat shortly, but we won't be able to defend ourselves when they strike back. We don't have anywhere to run... we're running out of options.\n\nI'm sorry, I should keep such thoughts to myself. Do me a favor and don't mention any of that to the men. I'll figure something out." }
WordHunterWoW_QuestEN[25966] = { title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", objectives = "Witness the continuing story of the Battlemaiden by using her broken blade at the site of the Kvaldir General's death.", completion = "You're finished! Just in time. I don't think we could have held them much longer.\n\nAn artifact? Could this be something we can use against the naga? I suppose that would require finding it.\n\nWe may have to attend to more pressing matters first, until an opportunity to pursue this further presents itself." }
WordHunterWoW_QuestEN[25967] = { title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", objectives = "Use Wavespeaker Tulra's sea horse to return to Captain Vilethorn just north of the Quel'Dormir Gardens.", completion = "You made it! After the attack at the forward post, I thought we might be the only ones left. It's good to see you in one piece, <class>." }
WordHunterWoW_QuestEN[25968] = { title = "Desperate Plan", description = "Toldrek and Fiasco left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", objectives = "Meet with Fiasco Sizzlegrin on Biel'aran Ridge.", completion = "Look at you, a regular aquatic hero! Trouble comes. You come. Save the day.  You must be proud of yourself!\n\nWe've devised our brilliant plan. Gloriously simple, barring the hostility of local life. Simpler yet with a you available!" }
WordHunterWoW_QuestEN[25969] = { title = "Hostile Waters", description = "Fiasco came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those giblins. Or at the very least, enough of them to make them fear us.", objectives = "Kill 10 Muckskin Scroungers.", completion = "Less gilblins is good.\n\nI'm glad that they're so primitive. I don't think I'd want to be dealing with a race of aquatic tech-freaks right now." }
WordHunterWoW_QuestEN[25970] = { title = "Come Prepared", description = "It's a short swim to the top. Not much trouble really. Hard to get any supplies up there though. Too heavy.\n\nAll of the ships in all of the Horde fleets stow a survival kit. I had a balloon from the old survival kit, but it fell on hard times recently. I need another survival kit.\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us.", objectives = "Retrieve a Horde Survival Kit.", progress = "A whole big box of amazing! That's what it is. I need more amazing in my life.\n\nDon't worry, I'll share.", completion = "Let me see, let me see... flare gun... balloon... no rope. Never any rope. Terribly impractical if you do ask me. Rope should be mandatory." }
WordHunterWoW_QuestEN[25971] = { title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! Rope and bombs, that's all they should store. The rest of this stuff is just a waste of space.\n\nExcept maybe the balloon. That's coming in handy right now.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. It is non-optional.", objectives = "Collect 8 Coils of Kvaldir Rope.", progress = "The rope ties the whole plan together!", completion = "This is great! I love it. It should work per... ewww! Is this stuff braided with hair?\n\nDoesn't matter. Almost done. This thing will be ready in the twist of a rope." }
WordHunterWoW_QuestEN[25972] = { title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Well played.\n\nToldrek already swam up to catch it, all concerned about currents and what not. He said you'd get the honors though. Nice guy - don't know how he lasts.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Horde ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", objectives = "Swim to the surface, retrieve the flare gun, and fire a rescue flare towards the Horde Ships.", progress = "Those aren't trade ships, those are war ships. Still, this is an incredible stroke of luck. Fire that flare off and pray that they see it.", completion = "Perfect! There's no way they missed that, fighting or not." }
WordHunterWoW_QuestEN[25973] = { title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}. ", objectives = "Return to Legionnaire Nazgrim at Legion's Rest.", completion = "That is the best news I've ever heard. We'll get the survivors moving over there to the surface as soon as possible. Perhaps we can forget that this whole nightmare ever happened.\n\nThank you, <name>. You've shown your worth down here. There will be a glorious spot in the Horde for you.\n\nYou should consider meeting us at the ships later, when you finish saying your goodbyes to the naga." }
WordHunterWoW_QuestEN[25974] = { title = "Sira'kess Slaying", description = "So, you're the {name} everyone's been talking about? It's good to finally meet you.\n\nWell, enough talk, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and kill those naga real quick.\n\nNothing fancy. They're looking for a fight, and we'll give them one! Well, you will.", objectives = "Slay 10 Sira'kess Naga.", completion = "Nice, <name>! That will show those naga who's the boss!\n\nNow it's time for that drink. You want rum or wine?" }
WordHunterWoW_QuestEN[25975] = { title = "Treasure Reclamation", description = "We've got our reinforcements, but we still need to find a way to pay them. That kind of action doesn't come cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. I think that it's time to reclaim some of it for the cause.", objectives = "Collect 6 Deepfin Plunder.", progress = "How much plunder have you managed to reclaim, <name>?", completion = "That should be enough for now. We know where there's more should the need arise." }
WordHunterWoW_QuestEN[25976] = { title = "Treasure Reclamation", description = "Blood and thunder! We have our reinforcements, but they still need to be paid. They won't be cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. It's time to reclaim some of it for the Horde.\n\nHellscream's eyes are upon you, {name}!", objectives = "Collect 6 Deepfin Plunder.", progress = "How much plunder did you get, <name>?", completion = "That's a lot! And we know where there's more should the need arise." }
WordHunterWoW_QuestEN[25977] = { title = "A Standard Day for Azrajar", description = "{name}, the snakes are after our daft and barmy. Go back northwest to Deepfin Ridge and plant some do me good in that pot and pan pitch and toss of theirs.\n\nThey'll kick and prance away with their alderman's nails tucked between their nutmegs when they see that. Not that they've got any nutmegs mind you.", objectives = "Plant the Alliance Standard in Fathom-Caller Azrajar's corpse.", completion = "Nice Uncle Bob of pokin' their general.\n\n<The lieutenant shakes her head and grins.>" }
WordHunterWoW_QuestEN[25978] = { title = "Entombed in Ice", description = "Khurgorn tells me the cataclysm upset the balance of the elements all over the world. Helm's Bed Lake, to the south, used to be beautiful and tranquil, but it is now overrun with agitated water elementals. When they started to leave the confines of the lake, I sent my troops in to keep them busy, but most have been frozen in blocks of ice.\n\nIf we can break them free, they have a good chance of recovering. I cannot spare the men for a second expedition out onto the lake. Would you be willing to try?", objectives = "Break open six Icy Tombs to free the Frozen Mountaineers trapped inside at Helm's Bed Lake.", progress = "Were you able to help any of the mountaineers?", completion = "You've done it! The mountaineers are returning to camp and our medics will have their hands full. We are all in your debt, <name>." }
WordHunterWoW_QuestEN[25979] = { title = "Dealing with the Surge", description = "The elements are in turmoil, {class}. The cataclysm stirred up the long-dormant water spirits of Helm's Bed Lake, just to the south. They're angry, confused, and unwilling to hear my pleas.\n\nI have tried everything I know to calm them, to persuade them to stop lashing out and attacking the sergeant's mountaineers.\n\nIt pains me to say this, but no other options remain -- we must kill the elementals.", objectives = "Kill 6 Helm's Bed Surgers at Helm's Bed Lake.", completion = "It is never easy to countenance violence against the very elements whose powers I wield, but sometimes there is no other solution. Our duty to the people of Dun Morogh comes first." }
WordHunterWoW_QuestEN[25980] = { title = "A Standard Day for Azrajar", description = "{name}, the naga are after our forces. I need you to go back northwest to Deepfin Ridge and stick our standard in their general, Fathom-Caller Azrajar.\n\nThey'll swim away with their tails tucked between their... er. Well, I guess they don't have any legs, now do they?", objectives = "Plant the Horde Standard in Fathom-Caller Azrajar's corpse.", completion = "Stuck him right through, did you? I would have loved to have seen that!" }
WordHunterWoW_QuestEN[25981] = { title = "Those Aren't Masks", description = "{name}, there are these demon squid-things out there that are eating gilblins' heads and then taking them over! That's one way to get slaves.\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things?", objectives = "Collect 6 Merciless Heads.", progress = "How many you got?", completion = "Ah, they're ugly, but they mostly look harmless. Smelly though.\n\nHere, let me clean the gilblin stuff out of these. I've got an idea...." }
WordHunterWoW_QuestEN[25982] = { title = "Those Aren't Masks", description = "{name}, there are demon squids out there that are eating gilblins' heads and then taking them over! They better not come in here!\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things? Preferably dead, I think.", objectives = "Collect 6 Merciless Heads.", progress = "What's that smell?", completion = "Ah, they're ugly, but they mostly look harmless. Mostly. They're almost cute in a way.\n\nHere, let me clean the gilblin stuff out of these. I've got an idea...." }
WordHunterWoW_QuestEN[25983] = { title = "Promontory Point", description = "We need to get this information up to Captain Taylor on Promontory Point! He's out there to the northwest with Erunak Stonespeaker and the Earthen Ring.", objectives = "Speak with Captain Taylor on Promontory Point in Vashj'ir.", completion = "That's very disturbing news, but I believe our Earthen Ring friends here have a plan.\n\nAnd now that you're here...." }
WordHunterWoW_QuestEN[25984] = { title = "Promontory Point", description = "{name}, I need you to get this information to Legionnaire Nazgrim on Promontory Point. He's up there to the northwest with Erunak Stonespeaker and those Earthen Ring people.", objectives = "Speak with Legionnaire Nazgrim on Promontory Point in Vashj'ir.", completion = "If it weren't you saying it, I wouldn't believe what that troublesome goblin has to say. This is troubling indeed, but I think our Earthen Ring friends have a few ideas.\n\nAnd now that you're here...." }
WordHunterWoW_QuestEN[25985] = { title = "Wings Over Mount Hyjal", description = "{name}, is it true you're going to try to commune with the ancients?\n\nSouthwest of here is the Shrine of Aviana, the matron of all flying creatures. It's the home of my favorite instructor, Choluna. I've never encountered one who was so deeply in touch with the spirits of this world. You could learn a lot from her!\n\nThe recent attacks have isolated the shrine. But it's easily accessible from the air - look for the second biggest tree on Hyjal. Good luck!", objectives = "Locate Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "Oh, you were sent here by Tiala? A wonderful student, she'll do many great things.\n\nAlthough I sense even greater potential from you.\n\nPlease, stay a while in our shrine. There's much to do, but you can't accomplish anything with a troubled mind." }
WordHunterWoW_QuestEN[25986] = { title = "Trouble at the Lake", description = "You've been a great help in securing the mines and rescuing the trapped miners.\n\nThe Senate will be heartened to hear that you and Captain Tharran's mountaineers have made progress in securing Dun Morogh.\n\nWhat worries me is that I haven't seen any reports from Sergeant Bahrum and his detachment. They were sent east, along the road toward Helm's Bed Lake, and ordered to set up a small outpost. Would you go to Bahrum's Post and check in on the sergeant?", objectives = "Speak with Sergeant Bahrum at Bahrum's Post.", completion = "It's a good thing the Senator didn't come out here on his own. It's dangerous, and we're going to need all the help we can get to get the situation under control." }
WordHunterWoW_QuestEN[25987] = { title = "Put It On", description = "Hey, {name}, I've got an idea for a disguise! Take one of these merciless whatchamacallits and put it on your head.\n\nWhat could possibly go wrong?\n\nReady to put it on?", objectives = "Witness what occurs when you place the Merciless One on your head.", completion = "What happened? That thing wasn't completely dead! Maybe I should stick to mechanical stuff.\n\nIt gave you a vision? Of killing all of us?! That doesn't sound good.\n\nWell, in any case, that Earthen Ring fellow, Erunak Stonespeaker, wants these specimens all taken out to him. I'll make sure he gets them. I don't want them anywhere near me." }
WordHunterWoW_QuestEN[25988] = { title = "Put It On", description = "I've got an idea for a sweet disguise, but I'm going to need your help, {name}! Take one of these merciless corpses and put it on your head.\n\nI know, I know, but it's dead, so what could possibly go wrong other than you smelling bad for a day or two?\n\nReady to put it on?", objectives = "Witness what occurs when you place the Merciless One on your head.", completion = "My bad. My name is Fiasco for a reason. I should have known that thing wasn't completely dead when it wiggled a little.\n\nYou say it gave you a vision? Of killing all of us?! That doesn't sound good.\n\nHrm, well that Earthen Ring fellow, Erunak Stonespeaker, wants these specimens all taken out to him. I'll make sure they get out there. It's not like I want them stinking up the place around here." }
WordHunterWoW_QuestEN[25989] = { title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", objectives = "Use Duarn's Net to capture a Deepseeker Crab inside of Nespirah.", progress = "I hope this works.  My skills as a shaman are limited, and I fear that this task may be too much for us.", completion = "<Duarn looks at the crab and disguises a frown.>\n\nIt doesn't look very impressive, does it?" }
WordHunterWoW_QuestEN[25990] = { title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", objectives = "Observe as Earthmender Duarn attempts to speak with Nespirah.", progress = "The ritual is not yet complete, <name>.", completion = "I had assumed that the naga were only here for those pearls.  No, this makes much more sense.  If they had Nespirah's power under their control, the amount of damage the naga could do would be catastrophic!\n\nSomething must be done." }
WordHunterWoW_QuestEN[25991] = { title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Horde slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", objectives = "Find the Horde survivors inside of Nespirah in Vashj'ir.", completion = "<name>... is that you?" }
WordHunterWoW_QuestEN[25992] = { title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", objectives = "Obtain 4 Purloined Polearms from the weapon racks inside of Nespirah.", progress = "In my youth, I was given some training on spearfighting.\n\n\"Stick them with the pointy end,\" I think it was.", completion = "<Captain Vilethorn admires the polearms you present him.>\n\nOh, I'm sorry.  I was just imagining what these will look like with little bits of naga stuck to the ends of them.  Thank you, <name>.  We'll put these to good use." }
WordHunterWoW_QuestEN[25993] = { title = "Body Blows", description = "<Legionnaire Nazgrim listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", objectives = "Attack 7 Nespirah Abscesses along the walls of Nespirah's body chamber.", completion = "Hopefully we made some progress.  I'm not sure how we'll know when the creature wakes up, but something tells me that it will be pretty obvious when it does." }
WordHunterWoW_QuestEN[25994] = { title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", objectives = "Obtain 5 Mysterious Pearls from Idra'kess Warlords and Idra'kess Prophets inside of Nespirah.", progress = "The naga must have some ulterior motive with these pearls.  If I had time to study them, I'm certain I could figure it out.", completion = "Brilliant work!\n\n<Tulra tucks the pearls away beneath her armor.>\n\nNow I just need you and Legionnaire Nazgrim to get me safely out of here.  I can handle the studies from there on." }
WordHunterWoW_QuestEN[25995] = { title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall northeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.  Hellscream's eyes are upon you!", objectives = "Head to the top of Nespirah and slay Overseer Idra'kess.", completion = "No need to bring me up to speed... Nespirah has been narrating your adventures as they happened, and Legionnaire Nazgrim filled me in on the rest.\n\n<Duarn closes his eyes and nods.>\n\nNespirah says that she is quite grateful, and that she has a small surprise ready for the naga." }
WordHunterWoW_QuestEN[25996] = { title = "Waking the Beast", description = "Thanks to you and the Legionnaire, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", objectives = "Speak with Earthmender Duarn inside of Nespirah to activate her bio-defenses, then escape from Nespirah's body.", completion = "It appears that I owe you my life, yet again.  Thank Hellscream that you found me before you and your shaman activated those bio-defenses." }
WordHunterWoW_QuestEN[25997] = { title = "Dark Iron Scheming", description = "A cadre of Dark Iron spies have taken over Ironband's Compound to the south, beyond Helm's Bed Lake. The mountaineers are normally able to keep them from getting into Dun Morogh, but everything is in disarray right now.\n\nThe Dark Iron dwarves would be fools if they didn't take advantage of the chaos. We have to find out what they're planning and stop them before they do any damage.\n\nWill you see if you can discover what they're doing down at Ironband's Compound?", objectives = "Kill 5 Dark Iron Spies and capture the Dark Iron Attack Plans from Captain Beld at Ironband's Compound.", progress = "What are the Dark Irons up to?", completion = "I knew they weren't here to see the sights.\n\n<The sergeant examines the plans you captured, his eyes wide.>\n\nThis is more serious than we thought! This is no mere raid. The Dark Irons intend to cripple the defense of Ironforge itself!" }
WordHunterWoW_QuestEN[25998] = { title = "Get to the Airfield", description = "According to the plans you captured, the Dark Irons are planning a large-scale attack on the Ironforge Airfield! The council has moved most of our forces down into Dun Morogh to deal with the instability brought by the cataclysm, leaving our defenses weakened at the airfield.\n\nWe need a way to get you to the airfield quickly. Take the road back west toward Gol'Bolar Quarry and find Mathel Rustwrench. He should have a flying machine you can use. Go!", objectives = "Board Mathel's Flying Machine at the Gol'Bolar Quarry.", completion = "Thank goodness you're here, <name>. The airfield's been attacked by the Dark Irons and I don't think we can hold out much longer." }
WordHunterWoW_QuestEN[25999] = { title = "Barrier to Entry", description = "Filthy, good-for-nothin' night elves have managed to disarm our entire minefield in Talondeep Pass. Somebody is gonna have to go back up there and re-arm them all! A perfect task for a worthless grunt like you, {name}. Here's to hopin' you don't blow yourself up in the process.\n\nYou'll find our \"Elf Killers\" scattered across Talondeep Pass, directly north of here. Take this wrench and get to work, maggot.", objectives = "Arm 8 Krom'gar \"Elf Killers.\"", progress = "What do you have to report, grunt?", completion = "<Saurboz looks you over.>\n\nYou have all of your limbs intact. This is a first." }
WordHunterWoW_QuestEN[26000] = { title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", objectives = "Speak to Gurrok in Deepmist Grotto.", completion = "...<race>? Here?\n\nI must be mad..." }
WordHunterWoW_QuestEN[26001] = { title = "The Missing Blastgineer", description = "It looks like you might not be completely useless after all. Perhaps you can handle something a little more important.\n\nAbout two days ago I sent Blastgineer Fuzzwhistle to Windshear Mine. He was supposed to get there, make sure everything was going according to plan with the bomb, and report back. Two days and nothin'...\n\nHead out to the woods south of here and find him. For his sake, he better be dead.", objectives = "Find Blastgineer Fuzzwhistle.", completion = "Blastgineer Fuzzwhistle is definitely dead. It's probably for the best.\n\nIt looks like he's holding a note in his hand." }
WordHunterWoW_QuestEN[26002] = { title = "Alliance Attack Plans", description = "<You pry the note loose from Fuzzwhistle's hand.>\n\nThey're onto us! They know all about the bomb. Planning an attack on Krom'gar Fortress! I think they sent a search party after me. Won't go out like a chump. They'll get a fight.\n\nI think I hear them coming now! Their leader is a high elf huntress named Davinia. She spoke of attack plans. Avenge me by killing her and getting those plans! Her tent is nearby, to the east.\n\nHellscream's eyes are upon you...", objectives = "Recover the Alliance Attack Plans from Huntress Davinia.", progress = "Did you find Fuzzwhistle?", completion = "Damn shame... He was a good goblin.\n\n<Saurboz shakes his fist.>\n\nAs for you, <name>, you've done well. These attack plans will help us prepare. I want you to deliver the plans to Overlord Krom'gar personally! There's sure to be a promotion in it for you." }
WordHunterWoW_QuestEN[26003] = { title = "Lessons from the Lost Isles", description = "There are great dangers in the woods south of here. They are crawling with Darnassian scouts - assassins sent from Darnassus to kill us. Perhaps we can turn the tables on them, eh?\n\nWhen I was marooned on the Lost Isles a goblin gave me these infrared heat focals. They allow the wearer to see heat signatures of certain creatures. Take the focals and use them while in the woods to the south. They will allow you to easily spot the scouts. Kill as many of them as you can! For the Horde!", objectives = "Kill 12 Darnassian Scouts.", completion = "Well done, brother! Now they will know that they cannot sneak up on the Horde!" }
WordHunterWoW_QuestEN[26004] = { title = "Krom'gar Fortress", description = "Our main base of operations in Stonetalon Mountains is Krom'gar Fortress. It is from there that Overlord Krom'gar oversees all Horde military activity in the region. Krom'gar reports everything that happens directly to the Warchief.\n\nThe attack plans you brought back detail an assault that's supposed to take place against Krom'gar Fortress soon. Take the plans and head to the fortress, southwest of here. Give them to the Overlord.\n\nSo long, {name}. Truly, Hellscream's eyes are upon you.", objectives = "Deliver the Alliance Attack Plans to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", progress = "What is the meaning of this interruption? Why does this grunt stand before Overlord Krom'gar?", completion = "<Overlord Krom'gar takes the plans from you.>\n\nHmm. Perhaps this grunt is more than he would appear. Perhaps this grunt is in actuality a sergeant.\n\nLook now upon Krom'gar Sergeant <name>, soldiers. He has come to serve warning of a cowardly Alliance attack. An attack that we will CRUSH!" }
WordHunterWoW_QuestEN[26005] = { title = "A Breath of Fresh Air", description = "Captain Taylor and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nHexascrub left these behind for you. They should speed your trip up a bit.", objectives = "Find Captain Taylor aboard Voldrin's Hold, on the surface above the Ruins of Vashj'ir.\n\nProvided item:", completion = "You made it out! Good to see you, <name>.\n\nIt's good to be out of the water for a bit, and to have some resources at our disposal again. I'm sure many of the boys would give anything to turn around and head home after what we've been though, but we still have a grim task ahead.\n\nWhat about you? Want to stick it through to the end with us? I wouldn't blame you if you've had your fill." }
WordHunterWoW_QuestEN[26006] = { title = "A Breath of Fresh Air", description = "Legionnaire Nazgrim and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nFiasco left these behind for you. They should speed your trip up a bit.", objectives = "Find Legionnaire Nazgrim aboard the Stygian Bounty, on the surface above the Ruins of Vashj'ir.\n\nProvided item:", completion = "Looks like you make it out in one piece, <class>!\n\nIt's good to be out of that foul pit of water for a moment, and to have some resources at our disposal again. Don't get too comfortable though, we still have a grim task ahead.\n\nWhat about you? Had enough honor for one day, or do you want to get back in there and make Hellscream proud?" }
WordHunterWoW_QuestEN[26007] = { title = "Debriefing", description = "This warrior was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", objectives = "Speak with Gurrok and learn about his ordeal.", completion = "Well, it's not encouraging, but it's something..." }
WordHunterWoW_QuestEN[26008] = { title = "Decompression", description = "I simply cannot bear the thought of so many others like this warrior imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use  it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", objectives = "Use Moanah's Breathstone on 10 Imprisoned Warriors in The Clutch.", completion = "Let us hope for the safety of those released prisoners.\n\nIn return for your noble efforts, please accept this gift." }
WordHunterWoW_QuestEN[26009] = { title = "Seek and Destroy", description = "The Alliance encroaches upon our territories within Stonetalon. The forces of Northwatch have broken through our blockade in the south and occupy Windshear Valley, to our west. From the northern front comes an onslaught of night elf soldiers. All must be stopped!\n\nVenture forth into Stonetalon and destroy all Alliance soldiers that cross your path. Let their deaths serve as a message.\n\nStonetalon belongs to the Horde!", objectives = "Slay any 20 soldiers of the Alliance in Stonetalon Mountains.", completion = "Much more blood shall be spilled upon this soil before this war is over. Alliance blood..." }
WordHunterWoW_QuestEN[26010] = { title = "Ashes to Ashes", description = "The Alliance have grown bold. Just west of here, in Windshear Valley, Northwatch troops have set up camp. No doubt they are preparing for the assault you warned us of, {name}. They will never get the chance!\n\nTake this flame thrower. It is the same flame thrower my incinerators use to burn our enemies out of hiding in the forests. Use it to destroy the Northwatch tents. Leave only ashes in your wake!", objectives = "Use the Krom'gar Flamethrower to destroy 8 Northwatch Tents.", completion = "Lok'tar! Alliance pigs!\n\n<Overlord Krom'gar spits on the ground.>\n\nEnjoy the victory for it shall be short lived. Your bravery has given us more time to prepare, nothing more." }
WordHunterWoW_QuestEN[26011] = { title = "Enemy of the Horde: Marshal Paltrow", description = "My scouts have tracked the cause of this latest fiasco to one man: Marshal Paltrow. He commands the Northwatch forward camp that has established itself in Windshear Valley, west of here. Take him out and you remove a powerful Alliance field commander from the equation.\n\nPaltrow must die, {name}.", objectives = "Kill Marshal Paltrow.", completion = "Did you find any suspicious documents at Paltrow's camp? Perhaps on his rotting corpse? Any insight into the Alliance's attack patterns would be extremely helpful in the battle for Stonetalon." }
WordHunterWoW_QuestEN[26012] = { title = "Trouble at Wyrmrest", description = "My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple.\n\nPressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?", objectives = "Speak with Krasus at Wyrmrest Temple in Dragonblight.", completion = "Thank you for heeding Rhonin's call, brave adventurer.\n\nLet me share with you what we know regarding recent events, and any assistance you might offer would be greatly appreciated." }
WordHunterWoW_QuestEN[26013] = { title = "Assault on the Sanctum", description = "{race}, something terrible has transpired within the Ruby Sanctum beneath the Temple.\n\nThe entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst.\n\nEnter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.", objectives = "Investigate the Ruby Sanctum beneath Wyrmrest Temple.", completion = "Thank you again, <class>, for rescuing me from Baltharus's clutches!\n\nThere is still much work to be done, however...." }
WordHunterWoW_QuestEN[26014] = { title = "The Brothers Digsong", description = "Private {name}, at attention!  Ve are havink a small problem!\n\nVe have sent Humphrey and Oskar Digsong out to Underlight Canyon, to the northvest, but they are not comink back.  They vere supposed to scout out the area, but ve have lost all contact with them.\n\nYour assignment, Private {name}, is to locate our comrades and, if they live, bring them back to me!", objectives = "Report to Humphrey Digsong at Underlight Canyon in Vashj'ir.", completion = "Of course we haven't returned yet!  We've had our fair share of setbacks... not the least of which was the passing of my dear brother Oskar.\n\n<Humphrey sniffles loudly.>\n\nHe lost his grip and floated away, the poor lad!  He thought he'd grab some fish to bring back to the captain, but he floated off, and was eaten by one o' those... those great-eels!  Bwaaaah ha ha haaaah!" }
WordHunterWoW_QuestEN[26015] = { title = "Phosphora Hunting", description = "Oskar's last wish, before he floated up into that great-eel's gullet, was to bring back food for the captain, so that's what we'll do.\n\nMy brother had a genius plan.  He saw those murlocs luring fish out of the reeds with a phosphorescent antenna, and devised a way to make one of his own.  All ya need is something that glows.\n\nKill the crabs and groupers that roam the canyon's floor.  They aren't edible themselves, but their phosphora is far more valuable than their meat.", objectives = "Obtain 6 Underlight Phosphora from Pyreshell Scuttlers and Luxscale Groupers in Underlight Canyon.", progress = "We need enough phosphora to make a really bright light, especially if you're going to be competing with those murlocs.", completion = "<Humphrey grabs the phosphora from you and attaches it to an unusual device.>\n\nThere ya go.  It's beautiful!  Oskar would be proud." }
WordHunterWoW_QuestEN[26016] = { title = "Orders from Base Camp", description = "Paltrow, establish a foothold in Windshear Valley. A strong ground assault is vital to our campaign! When we make our assault against Krom'gar, your men will provide the chaos and confusion that the gnome flying machines will need to get close enough to bomb the orc fortress.\n\nThe flying machines will detonate the Krom'gar bomb while it's sitting in their base, taking out the entire fortress in the process.\n\nBurn after reading.\n\n-Force Commander Valen\n\nNorthwatch Expedition Base Camp", objectives = "Deliver the Orders from Base Camp to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", progress = "More gnomes?", completion = "Gnomish flying machines? Our anti-air cannons are still not functional! We will be sitting ducks.\n\nI require time to plan... to think...\n\nThe hot air balloon and its payload cannot remain at Krom'gar Fortress. I must make arrangements to move the balloon to another location. Our plans to destroy Windshear Hold with it are foiled." }
WordHunterWoW_QuestEN[26017] = { title = "A Lure", description = "Stick this device on your head, then swim through the kelp and coral along the canyon's edge.  There should be all kinds of little fish in there that find your new antenna irresistible.\n\nWhen we return to Darkbreak Cove, we'll have armfuls of fish for everyone!", objectives = "Put on the Phosphora Fedora, then swim through the coral in Underlight Canyon to attract 30 Underlight Nibblers.", progress = "How many did ya catch?", completion = "Ya did good, <name>!  Ya did real good!" }
WordHunterWoW_QuestEN[26018] = { title = "Coldlights Out", description = "Oh yeah!  I was supposed to put together a report!  I'd almost forgotten!\n\nLooks like mostly harmless wildlife around here... 'cept for those blasted eels... and a few murlocs.  Cap'n will be more interested in the murlocs, I think.\n\nGo engage a few of 'em in combat and see what kinda moves they got.  From what I've seen, the big ones hunt for fish in the kelp, and the little ones practice some kind o' magic or another... but that's all I know.", objectives = "Kill 4 Coldlight Hunters and 4 Coldlight Oracles.", completion = "<Humphrey listens as you recount your fights with the Coldlight murlocs.>\n\nHmm... they sound like regular ol' murlocs... just underwater.  That'll make Cap'n Glovaal happy." }
WordHunterWoW_QuestEN[26019] = { title = "Enormous Eel Egg", description = "<This appears to be an egg from one of the devious great-eels that float up above the canyon.  You wonder whether or not Humphrey might be interested in something like this.>", objectives = "Deliver the Enormous Eel Egg to Humphrey Digsong at the bottom of Underlight Canyon in Vashj'ir.", progress = "What've ya got there, <name>?", completion = "Whaaa... an egg?  An EEL egg?\n\n<Even upside-down, you can see the gears in Humphrey's head turning.>\n\nWe can definitely do something with this!  Get ready kid, 'cause it's time for some good ol'-fashioned Digsong revenge!" }
WordHunterWoW_QuestEN[26020] = { title = "Report to Bombgutz", description = "We must prepare for the impending attack. I will have our soldiers prepare the bomb for transport. I want you to report to Chief Blastgineer Bombgutz. She has been working to fix our anti-air cannons, but has thus far failed. Make sure that she is properly motivated to repair our guns, {name}.", objectives = "Report to Chief Blastgineer Bombgutz at Krom'gar Fortress in Stonetalon Mountains.", completion = "Properly motivated? Wha... what does that mean? Listen, Sergeant, I have a built in mechanism for survival called self-interest. That is, it's in my best interest to NOT DIE. With that said, there's no fixing these guns without the right materials." }
WordHunterWoW_QuestEN[26021] = { title = "The Brothers Digsong 2: Eel-Egg-Trick Boogaloo", description = "Those eels ate my brother.  My brother, {name}!  It's time someone showed 'em who's boss.\n\n<Humphrey removes several sticks of dynamite from his vest and shoves them through the egg's outer membrane.>\n\nThe great-eels to the south are too tough to fight one-on-one, but with this egg, we should be able to even the odds.  Place it near one of those creatures, then... kablooie!\n\nIf the bomb doesn't kill the eel outright, it should be near enough to death for you to finish it off.", objectives = "Use the Eel-splosive Device near a Devious Great-Eel in Underlight Canyon, then defeat the Weakened Great-Eel.", completion = "Oskar's alive?  Wait... what did ya say?  Ya let him FLOAT AWAY AGAIN?!\n\nWell... ya held up your end of the bargain, and I appreciate everything ya've done, <name>.\n\nHere... take this.  I've only been hanging onto it as ballast, but it doesn't seem to be doing much good." }
WordHunterWoW_QuestEN[26022] = { title = "First Blood", description = "Be prepared, {name}. You will cast the first blood upon this land for us.\n\nThe Syndicate, as they call themselves, are cowardly humans who betray even their own kind. Their isolation will make them easy prey.\n\nTravel north, slay any Syndicate members you find, and claim Northfold Manor in the name of the Forsaken. Bring me the Bloodstone Amulets they wear as proof of your conquest. ", objectives = "Collect 10 Bloodstone Amulets from members of the Syndicate.", progress = "I won't be swayed by empty claims. Have you proof of your loyalty?", completion = "This is but a prelude to the slaughter we will visit upon these lands. All will know our name.\n\nYou have done well, <name>. Victory for Sylvanas!" }
WordHunterWoW_QuestEN[26023] = { title = "The Forsaken Trollbane", description = "Let me tell you a story.\n\nOnce, there was a foolish troll named Zengu. He was tasked to find the sword Trol'kalar, the legendary blade of the human Trollbane line. He succeeded, and thinking his task done, went to leave Arathi by himself. There he was cut down by the humans, and the sword simply reclaimed.\n\nWe will not be so foolish. Our apothecaries have given us the perfect guide to reobtain Trol'kalar: the prince who once held it.\n\nHe stands ready to guide you, {name}. Speak with him.", objectives = "Speak with Galen Trollbane.", completion = "Yes... I was once Prince of the fallen kingdom of Stromgarde. I was cut down by the one seeking Trol'kalar.\n\nI rue my foolish life now. I serve...only Sylvanas." }
WordHunterWoW_QuestEN[26024] = { title = "Wanted!  Marez Cowl", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", objectives = "Bring Marez's head to Captain Nials at Refuge Pointe.", progress = "Greetings, <class>.  You have a report to make?", completion = "You took down Marez Cowl?  Well done, <name>.  Well done indeed!\n\nMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power.  We are glad to see that she'll no longer ply her powers against us." }
WordHunterWoW_QuestEN[26025] = { title = "The Traitor Orc", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of her energy.\n\nFind the warlock and kill her. Bring me whatever magical object you find on her person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", objectives = "Retrieve Marez Cowl's Befouled Bloodstone Orb.", progress = "The burning in my blood... it grows by the day. The warlock must be stopped.", completion = "My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, <name>. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse." }
WordHunterWoW_QuestEN[26026] = { title = "Dream of a Better Tomorrow", description = "Mr. D is sick, mister. Won't you help him? All you have to do is find his hat and batteries and he'll be all better. I'd go get them myself, but I can't leave Mr. D alone!\n\nHis hat was stolen by the meanies in the Venture Co. over at the water wheel and his batteries are hidden around Windshear Crag. You'll just have to look real hard for those!\n\nWould you kindly bring Mr. D's stuff back so he can teach those baddies in the Alliance a lesson?", objectives = "Recover the BD-816 War Apparatus, Mechanized Fire, Mechanized Ice and Mechanized Air.", progress = "Mr. D is so sad. We need to make him happy!", completion = "<Clarissa claps excitedly.>\n\nMr. D you're gonna be ok! Hooray!\n\n<Clarissa expertly places all of the parts you collected into Large Daddy.>\n\nOh, Mr. D! I knew it!" }
WordHunterWoW_QuestEN[26027] = { title = "Call to Arms", description = "Our next strike against the ogres will bring you further east to Stromgarde. The living consider these gutted ruins worth clinging to. Their sentimentality is disgusting!\n\nAll that Stromgarde holds for us is a foul den of more ogres, waiting to be struck down. Travel there and slay their shamans and lords, and ensure what passes for leadership among the ogres is snuffed out.", objectives = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords in Stromgarde.", completion = "Cleared out properly? Good. I doubt we'll even bother to lurk in Stromgarde. That ramshackle hole needs to be razed into dust.\n\nThe land would make a decent spot for a new Undercity in its place." }
WordHunterWoW_QuestEN[26028] = { title = "Mr. D's Wild Ride", description = "Now Mr. D just needs an angel to help him navigate. Will you be that angel, mister? With you helping we can go out into the crag and kill bunches and bunches of Alliance! Waddya say? Come on, mister! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Alliance Mr. Krom'gar will buy us all ice cream!", objectives = "Kill 20 Gnome Engineers and 5 Gnome Pounders.", progress = "This is awkward.", completion = "<Overlord Krom'gar coughs.>\n\nI am - perhaps for the first time in my life - at a loss for words.\n\nI am really not sure where Clarissa even came from..." }
WordHunterWoW_QuestEN[26029] = { title = "The Real Threat", description = "Or'Kalar leads the ogres here. He has evaded slaughter for years. His very presence is an affront to the Dark Lady; Mug'thol, traitor to the Forsaken, commands him from afar!\n\nWe do not suffer ogres or traitors on Forsaken land. Bring me this ogre's head and I will make sure it's burned properly this time.", objectives = "Slay Or'Kalar and take his head.", progress = "Speak quickly.", completion = "This is the fate of all who would stand in our way." }
WordHunterWoW_QuestEN[26030] = { title = "Sigil of Strom", description = "In ancient times, Lord Ignaeus of Strom, named Trollbane, led the first human civilization of Arathor in war against the trolls. His blade was Trol'kalar--troll slayer, in their ancient tongue.\n\nI was one of the last of his line, sworn with guarding Trol'kalar...a duty in which I failed. But now, we will obtain it once more, for my new master.\n\nThe sword is bound by three sigils. The first is held by the Syndicate traitors that lurk the ruins of Stromgarde. Slay them, and return the sigil to me.", objectives = "Collect the Sigil of Strom from Syndicate members in Stromgarde Keep.", progress = "Only the Syndicate agents in Stromgarde will have the sigil. Spilling blood outside the fortress's walls will be a waste of your time.", completion = "I hated the Syndicate in life as much as I do in death. To see the sigil again is a small comfort.\n\nBut we have much more work to do... for Sylvanas." }
WordHunterWoW_QuestEN[26031] = { title = "Sigil of Thoradin", description = "In life, I divided the sigil of Thoradin into five pieces to protect it, spreading it among my most loyal men. This too failed, but my successor will have done the same.\n\nThe defenders of Stromgarde hold the pieces of the sigil yet again. Slay them, and bring the shards to me; I will reassemble them.", objectives = "Collect 5 Sigil Fragments from Stromgarde defenders in Stromgarde Keep.", progress = "All five pieces are needed to restore the sigil...", completion = "Thoradin was the founder of Arathor. Just as I join these fragments together, he joined the scattered tribes of humans into their first great nation.\n\nBut I'm sure you're not interested in such drivel. Forgive me. Old memories are often hard to bury." }
WordHunterWoW_QuestEN[26032] = { title = "Sigil of Arathor", description = "I entrusted the sigil of Arathor to Lieutenant Valorcall, leader of my cavalry. He barely escaped with his life when it was taken.\n\nIt is unlikely he will do so again. Valorcall patrols the road between Stromgarde Keep and Refuge Point. Find him, and take the sigil from him once more.", objectives = "Collect the Sigil of Arathor from Lieutenant Valorcall.", progress = "Have you the sigil?", completion = "Valorcall was loyal to me in life. His death will not be something I bear lightly.\n\nBut bear it I must. I am Forsaken. My old existence means nothing.\n\nThe sigils are ours; Trol'kalar awaits." }
WordHunterWoW_QuestEN[26033] = { title = "Trol'kalar", description = "The last sigil is mine...and with it, the four combine to the Sigil of Trollbane, key to the tomb. We are ready.\n\nTrol'kalar lies sealed with its master's remains, within Trollbane's tomb in the catacombs of Stromgarde. It will be defended heavily...but my presence before you is proof enough that the defenders can be overcome.\n\nEnter the tomb, retrieve Trol'kalar, and bring it here.", objectives = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde Keep.", progress = "Have you Trol'kalar?", completion = "Trol'kalar, my father's blade... it seems like it's been an eternity since I saw it." }
WordHunterWoW_QuestEN[26034] = { title = "The Twilight Destroyer", description = "This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight.\n\nZarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion. Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen.\n\nSlay him, {name}, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.", objectives = "Defeat Halion and repel the invasion of the Ruby Sanctum.", completion = "<Krasus listens intently as you relate your battle with Halion, and then his eyes go wide at the mention of Deathwing.>\n\nWe owe you a debt of gratitude, mortal, for driving the invaders from the Sanctum. But this news of the Destroyer is troubling beyond words. I have much to discuss with the other members of the Accord.\n\nTake these as a token of my thanks, as you gird yourselves for the coming storm." }
WordHunterWoW_QuestEN[26035] = { title = "Worth Its Weight in Gold", description = "Archmage Malin sent me here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need Witherbark tusks and Witherbark medicine pouches.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", objectives = "Collect 10 Witherbark Tusks and 4 Witherbark Medicine Pouches from Witherbark Trolls.", progress = "Have you had any luck so far?", completion = "Not bad. Since it's clear you've got your head on straight, I was hoping you could help us with a more pressing job." }
WordHunterWoW_QuestEN[26036] = { title = "Wand over Fist", description = "Hey, {name}. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", objectives = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.", progress = "Our goal is the wand, <name>. Focus on that for now.", completion = "Brilliant, <name>. One item down an' three more to go, based on my list. The other three items are all in Stromgarde.\n\nTake a rest an' get your strength back--the next phase of my plan'll require a little more time an' effort. Come back to me after you've gotten a warm meal an' some rest." }
WordHunterWoW_QuestEN[26037] = { title = "Trelane's Defenses", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to ward you against the tower's defenses. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant it.", objectives = "Find an Azure Agate and bring it to Apprentice Kryten at Stromgarde Keep.", progress = "<name>, hello again. Have you found an azure agate yet?", completion = "You amaze me, <name>. Well done again.\n\nGive me a moment to cast the proper spell an' you'll be ready." }
WordHunterWoW_QuestEN[26038] = { title = "Attack on the Tower", description = "Here's what you're looking for: Trelane's phylactery, Trelane's orb, and Trelane's ember agate.\n\nAll three should be in chests within the tower.  You shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nYou'll need to have your weapons at the ready. Those ogres find out you're there and stealing from them, and they'll be sure to put the hurt on you.\n\nBe careful, and good luck.", objectives = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", progress = "You do this, an' I'm sure Malin'll be more than pleased with you.", completion = "Malin couldn't've asked a worthier person to come here an' aid us, <name>. You've done a grand job!\n\nHe'll be pleased to see what an overwhelming success our mission's been." }
WordHunterWoW_QuestEN[26039] = { title = "The Princess Trapped", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, {name}, aid me!", objectives = "Gather 12 Motes of Myzrael from Drywhisker Kobolds.", progress = "This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.", completion = "Ah!  You activated these shards.  Already I feel more myself!\n\nBut alas, I am still far from free..." }
WordHunterWoW_QuestEN[26040] = { title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", objectives = "Collect 7 Wiggleweed Sprouts from Shimmerspine Harvesters in The Clutch.", progress = "Were you able to find me any of their seaweed, <race>?", completion = "Yes, yes. This is the stuff.\n\nMaybe I can wean off of it and avoid the side-effect.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[26041] = { title = "Stones of Binding", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", objectives = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.", progress = "This is the Stone of Inner Binding.  It is the strongest of the binding stones and must be unlocked for the others to open.", completion = "<Myzrael speaks through the stone.>\n\nYou have done it!  You opened the Stones of Binding!  I can feel the shackles about me loosen, and freedom draws ever closer.\n\nYou are a noble <class>, <name>.  My rescuer!" }
WordHunterWoW_QuestEN[26042] = { title = "Breaking the Keystone", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n{name}, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", objectives = "Obtain the Rod of Order from Fozruk.", progress = "The Keystone is charged with tremendous geomantic energy.", completion = "You place the rod in the keystone.  And a shudder is felt beneath you..." }
WordHunterWoW_QuestEN[26043] = { title = "BEWARE OF CRAGJAW!", description = "By order of Overlord Krom'gar, Cragpool Lake is OFF LIMITS!\n\nThe ferocious beast known as Cragjaw has made the lake a death trap. Should you dispatch of Cragjaw, take his huge tooth as a trophy and return it to Spy-Mistress Anara for a reward.", objectives = "Kill Cragjaw and take Cragjaw's Huge Tooth.", progress = "What is it that you require?", completion = "A testament to the might of the Horde!" }
WordHunterWoW_QuestEN[26044] = { title = "Where Are the Parts?", description = "I've been waiting on parts for these guns for days! I sent one of my best blastgineers and two dozen miners into the Deep Reaches five days ago for the parts. After not hearing from anybody for three days I began to get a little worried. The Overlord sent two of his best orcs in to see what was going on. We've received no reports since then...\n\nHead into the Deep Reaches, directly below this fortress, and find out what's going on! I need parts!", objectives = "Speak to Sergeant Dontrag inside the Deep Reaches in Stonetalon Mountains.", completion = "Um... Well you see, it's quite simple... THIS CAVE IS SWARMING WITH SOULLESS KILLING MACHINES!" }
WordHunterWoW_QuestEN[26045] = { title = "I Got Your Parts Right Here...", description = "Here's the dilemma: I could do one of two things, get killed down here like everyone else or get killed up at Krom'gar Fortress when Krom'gar realizes we've lost the mine. I'm choosing the third option, do nothing. So far, so good.\n\nYou need parts? Plenty from the left over junk scattered about in this mine. You just gotta go get 'em.\n\nGood luck! Maybe if you get those parts we might be able to show our faces at Krom'gar Fortress.", objectives = "Collect 10 Spare Parts.", progress = "How's that part hunt going?", completion = "I'll be damned! You managed to get the parts and not die. How are you only a sergeant?" }
WordHunterWoW_QuestEN[26046] = { title = "Between a Rock and a Hard Place", description = "Dontrag can explain it better than me. Basically, we're stuck between a rock and a hard place. Can't do anything down here due to all of the things that can kill us and can't go back to the base due to all of the things that can kill us - you know?\n\nPerhaps if we worked together we might be able to get this mess sorted out. How about you get started by clearing out some of these elementals that have apparently killed everything in the mine, ok?", objectives = "Kill 12 Raging Earth Elementals.", progress = "Those elementals aren't going to kill themselves, buddy.", completion = "Get the parts, kill the elementals and rescue the peons... We get all of that done and we're as good as promoted!" }
WordHunterWoW_QuestEN[26047] = { title = "And That's Why They Call Them Peons...", description = "These two are USELESS! When they first arrived I thought we were saved. Not so! Instead, Dontrag and Utvoch took one look at the mine and concocted some idiotic plan that involved standing here until... until we all died, I guess. \n\nYou don't look nearly as useless. How about you lend a hand, friend? I've got dozens of peons, scared out of their gourds, hiding in the Deep Reaches. Find them and get them out!", objectives = "Rescue 10 Frightened Peons.", completion = "I knew it! You are a hero! If I have anything to do with it, you'll be promoted to legionnaire!" }
WordHunterWoW_QuestEN[26048] = { title = "Spare Parts Up In Here!", description = "Whew, that was tough. I didn't think we'd make it, {name}. We better get these parts back to Chief Blastgineer Bombgutz. I think I hear the gnome flying machines buzzing outside. We haven't got a minute to lose!", objectives = "Deliver the Crate of Spare Parts to Chief Blastgineer Bombgutz at Krom'gar Fortress in Stonetalon Mountains.", progress = "Get my parts?", completion = "Just in time! The flying machines are starting to mass. Attack is imminent!" }
WordHunterWoW_QuestEN[26049] = { title = "The Princess Unleashed", description = "Myzrael's no innocent princess. She's a terribly dangerous force, and the giants had every reason to chain her down there. I'm afraid you've been had.\n\nAccording to Gerrig, you have to summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards.\n\nHere's the scroll you'll need. Be careful with it; I risked a few teeth to get it. Good luck, {name}.", objectives = "Summon and defeat Myzrael at the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface." }
WordHunterWoW_QuestEN[26050] = { title = "Goggle Boggle", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", objectives = "Escort Professor Phizzlethorpe to the cave and back.", progress = "This is no time to talk! The goggles need to be charged with the power of the stone!", completion = "The goggles work perfectly now! Well done, <name>." }
WordHunterWoW_QuestEN[26051] = { title = "Sunken Treasure", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, {name}, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", objectives = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", progress = "How did the goggles work? Did everything function properly? Adjustments can be made if necessary.\n\nOh, and I'll need those goggles back when you're done. I am sure Captain O'Breen will have many uses for them later on.", completion = "Most superb, <name>! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!" }
WordHunterWoW_QuestEN[26052] = { title = "Speak to Shakes", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, {name}, take these to O'Breen.", objectives = "Take the Elven Gems to Captain O'Breen at Faldir's Cove in Arathi Highlands.", progress = "Ahoy, <class>.  What brings you to the bridge?", completion = "So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!" }
WordHunterWoW_QuestEN[26053] = { title = "Clearing the Highlands", description = "No threat here will go overlooked. If we are to secure these lands under the Dark Lady's rule, we will tear from them everything living, inch by inch, piece by piece.\n\nTo the northeast, not a stone's throw away from this camp is an ogre mound. The Boulderfist ogres that dwell in it must be eradicated, {class}.\n\nThey are in the way. Show no mercy or hesitation.", objectives = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers.", completion = "Excellent. The march of the Forsaken continues." }
WordHunterWoW_QuestEN[26054] = { title = "Water They Up To?", description = "Sandfury trolls working with the Twilight's Hammer?!\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", objectives = "Slay Kai'ju Gahz'rilla and inform General Marcus Jonathan in Stormwind City.", completion = "Sandfury trolls and the Cult of Twilight's Hammer, you say?\n\nAnd they meant to send some giant monster into the heart of the city?!\n\nWell done! Stormwind is in your debt." }
WordHunterWoW_QuestEN[26055] = { title = "Drowned Sorrows", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", objectives = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.", progress = "Bah, maybe I should go kill those naga scum myself.  It's obvious you're not goin' to do it.\n\nMaybe I can find some knitting needles so you can keep yourself busy.", completion = "Nice work out there, <name>.\n\nThose scum deserved what they got. While nothin' will ever bring me ship or me crew back, the death of those naga gives me some solace." }
WordHunterWoW_QuestEN[26056] = { title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", objectives = "Find Wavespeaker Valoren in the Nightmare Depths of Vashj'ir.", completion = "I sure am glad you're here!" }
WordHunterWoW_QuestEN[26057] = { title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", objectives = "Find Wavespeaker Valoren in the Nightmare Depths of Vashj'ir.", completion = "I sure am glad you're here!" }
WordHunterWoW_QuestEN[26058] = { title = "In Defense of Krom'gar Fortress", description = "There's no time left. Here they come! Take control of a heavy gun and shoot the gnomes out of the sky! If that bomb takes too many hits it will blow, taking us all with it!\n\nDefend the base, {name}! You're our only hope!\n\nIf we somehow make it out of this in one piece, report to Overlord Krom'gar.", objectives = "Destroy 15 Gnomish Flying Machines or Bombers and 25 Gnome Wing Commanders.", progress = "Our enemies surround us!", completion = "I have never seen such an act of bravery. You saved the base, sergeant - or should I say legionnaire! Lok'tar!" }
WordHunterWoW_QuestEN[26059] = { title = "Eyes and Ears: Malaka'jin", description = "Honor's Stand has been lost. The Horde's grip on the Barrens shattered along with the land itself. I now receive reports that we are at risk of losing Malaka'jin to a concerted attack by the Alliance and the Grimtotem. If Malaka'jin falls, half of Stonetalon falls with it!\n\nYou have proven yourself a capable soldier of the Horde. Will you be my eyes and ears at Malaka'jin? Witch Doctor Jin'Zil awaits your arrival.\n\nMalaka'jin is located far to the south.", objectives = "Report to Witch Doctor Jin'Zil at Malaka'jin in Stonetalon Mountains.", completion = "I see that Krom'gar has sent his best!\n\nGood, we have much work to do. The filth that is the Alliance have entered into a treaty with the Grimtotem. Now we fend off attacks from both forces.\n\nWe are spread thin across the Greatwood Vale and will soon fall beneath the concerted effort of our enemies. There is only one hope: VOODOO!" }
WordHunterWoW_QuestEN[26060] = { title = "Da Voodoo: Stormer Heart", description = "With voodoo, our troops might have a chance at beating back the Grimtotem assault. With that said, I need several ingredients if I am to invoke black magic.\n\nThe first ingredient on my list is a heart from a cliff stormer. The beasts have nearly been hunted to extinction, but a few still exist around these parts. Find one and recover its beating heart!", objectives = "Obtain a Cliff Stormer Heart.", progress = "I need the cliff stormer heart.", completion = "Excellent. Once I have everything I need I will mix it all together and unleash the voodoo! Woe unto our enemies!" }
WordHunterWoW_QuestEN[26061] = { title = "Da Voodoo: Ram Horns", description = "If I am to invoke voodoo, I will need several special reagents. Bring me horns from the Stonetalon rams of the region, {name}! Without the horns we are done for!", objectives = "Obtain 6 Stonetalon Ram Horns.", progress = "I need the Stonetalon ram horns!", completion = "Excellent. Once I have everything I need I will mix it all together and unleash the voodoo! Woe unto our enemies!" }
WordHunterWoW_QuestEN[26062] = { title = "Da Voodoo: Resonite Crystal", description = "The final ingredient for the voodoo ritual is a special type of crystal called resonite. It can only be found in the Boulderslide caverns, west of here. Beware the kobolds! They guard the resonite with their lives!", objectives = "Obtain 8 Resonite Crystals.", progress = "I need the resonite crystals!", completion = "Finally! Now I will create the charm that will hold the voodoo enchantment!" }
WordHunterWoW_QuestEN[26063] = { title = "The Queen and Her Court", description = "<Darn grunts.>\n\nHrmph.\n\nThings falling apart. Darn not happy. Now Darn's mate killed by spiders at Webwinder Hollow. Darn demands vengeance!\n\nHelp Darn? Kill Queen Silith and her little spiderlings? For Darn? For Darn's mate!\n\nWebwinder Hollow is northwest of here, up the path. Go!", objectives = "Kill Queen Silith and any 10 spiders in Webwinder Hollow.", progress = "Have you killed Silith for Darn?", completion = "Darn still not very happy, but Darn will reward you for what you have done." }
WordHunterWoW_QuestEN[26064] = { title = "Fight On Their Stomachs", description = "The troops are hungry, {name}. With our supply lines cut off, we're steadily running out of food. I can cook the soldiers a feast if you can get me some ingredients.\n\nHead into the woods west of here and look for Kalimdor eagle nests. Steal the eggs from the nests and bring them back to me.", objectives = "Collect 8 Kalimdor Eagle Eggs.", progress = "I need eggs!", completion = "Thank you, <name>. These eggs should get us through the week." }
WordHunterWoW_QuestEN[26065] = { title = "Free Wil'hai", description = "Those tentacle horrors rising from the depths have trapped that poor beast. Please, {name}, can you save it by destroying those things?\n\nWill you free Wil'hai?\n\nHere, take my totem and plant it near the tentacles. The cold it emanates will cause major shrinkage on those monsters and then you'll be able to destroy them.", objectives = "Slay all of the Tentacle Horrors to free Wil'hai.", progress = "Wil'hai is still trapped.", completion = "Thank you, <name>.\n\nThese nightmarish creatures that rise from below give me pause. I fear that our efforts will be for nothing." }
WordHunterWoW_QuestEN[26066] = { title = "Reinforcements...", description = "It would appear as if we are running out of big, stupid orcs to send at the enemy. This is a problem. Thankfully, I may have a solution.\n\nTake this whip and head west to Boulderslide Cavern. Within the cave you will find a filthy nest of kobolds. Use my whip to subdue the beasts. Once subdued they will do whatever we ask them to do.\n\nReturn to me when you have amassed a sizable army of kobolds.", objectives = "Use Subjugator Devo's Whip to Subdue 6 Boulderslide Kobolds.", completion = "In times of crisis, a desperate act may be all that is needed to secure victory. Sending a swarm of kobolds at the enemy may be the edge that we need to win." }
WordHunterWoW_QuestEN[26067] = { title = "Jin'Zil's Blessing", description = "Ah, it is done! Now to test it out.\n\nTravel to the main point of conflict within Greatwood Vale and use my voodoo stick on the Krom'gar marauders battling the Grimtotem. My voodoo magic should renew their vigor and allow them to crush our enemies!\n\nGo now, {name}!", objectives = "Use Jin'Zil's Voodoo Stick to infuse 12 Krom'gar Marauders with Voodoo.", completion = "Victory, at last! Though it stands to reason that without a stable supply line this victory will be short lived. Enjoy it while it lasts, <name>." }
WordHunterWoW_QuestEN[26068] = { title = "Kobold Fury!", description = "We now command the kobold armies of Stonetalon! It almost sounds impressive. Almost.\n\n<Devo sighs.>\n\nThe Alliance base camp north of here is tightly guarded. It is nigh impregnable, save for the entry point by the Unearthed Grounds, northeast of here. Take this kobold war horn and head towards the Unearthed Grounds. Enter from the east, {name}! Once there, head west until you arrive at the location I have marked upon your map. Use the horn there to unleash kobold fury upon the Alliance!", objectives = "Use the Kobold War Horn near the Horde Banner at the Unearthed Grounds to unleash the Kobold Army!", progress = "On my mark, unleash kobold hell!", completion = "<Devo laughs.>\n\nFascinating tale, friend. It would seem that our newfound kobold allies might be somewhat useful after all!" }
WordHunterWoW_QuestEN[26069] = { title = "Nura Pathfinder", description = "Southern Barrens is under attack by the Alliance. The tauren have sent out a call for help that we simply cannot ignore. All able bodied soldiers of the Horde should assist.\n\nIf you wish to help, take the path to the High Road, located in the village. Seek out Nura Pathfinder. ", objectives = "Report to Nura Pathfinder on the High Road in Southern Barrens.", completion = "The situation is grim, <race>. We need all of the help that we can get!" }
WordHunterWoW_QuestEN[26070] = { title = "Clearing the Defiled", description = "Our Earthen Ring friends here are wondering if we can lend them a hand. There are faceless down below in the Scalding Chasm that are defiling all of the wildlife.\n\nCan you take care of that for me?", objectives = "Slay any 8 Crushing Eels, Deep Remoras, or Chasm Stalkers.", completion = "Good enough for me.\n\nDon't get too complacent, <name>. The hard part's about to come." }
WordHunterWoW_QuestEN[26071] = { title = "Clearing the Defiled", description = "These Earthen Ring want us to do their killing for them. There are faceless down below in the Scalding Chasm that are defiling all of the wildlife.\n\nSwim down there and take care of it.", objectives = "Slay any 8 Crushing Eels, Deep Remoras, or Chasm Stalkers.", completion = "Well done.\n\nDon't get too full of yourself, <name>. The hard part's about to come." }
WordHunterWoW_QuestEN[26072] = { title = "Into the Totem", description = "You must take my totem down into the Scalding Chasm. Use it to capture the energies of the faceless as they die. The totem will keep them from returning from whence they came.\n\nWhen the totem is full, bring it back to me and we will use it to lure their leader up from deep down below.", objectives = "Slay 5 Faceless Defilers while they are within range of the Confinement Totem.", completion = "Yes, <race>, can you feel them seething with a desire to break free and destroy us?\n\nThis is good! They will be the perfect lure for their leader." }
WordHunterWoW_QuestEN[26073] = { title = "All's Quiet on the Southern Front", description = "Return now to Overlord Krom'gar, {name}. Inform him of our status and of what you have done to ensure that Malaka'jin does not fall.\n\nWe thank you for all that you have done. Perhaps some day soon you will have your own region to command.", objectives = "Report to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", completion = "Lok'tar ogar! You are the embodiment of what it means to be a Horde soldier, <name>. If only we had more like you, this war would be over and Kalimdor would belong to the Horde - UNCONTESTED!\n\nRise now as a champion of Krom'gar!" }
WordHunterWoW_QuestEN[26074] = { title = "Beginning of the End", description = "Champion, we have acquired a new target. Our scouts in Battlescar Valley report that the night elves are preparing their own weapon of mass destruction and hiding it within an ancient tree. They will never be given the chance to use their weapon against us.\n\nYou are to escort the bomb to the Sludgewerks for refueling and then to Cliffwalker Post, from which we will detonate the bomb and kill all of our enemies.\n\nGo now, {name}. Report to Jibbly Rakit when you arrive at the Sludgewerks. ", objectives = "Take the Krom'gar Hot Air Balloon to the Sludgewerks in Stonetalon Mountains.", completion = "Krom'gar has sent his champion! Well you haven't a thing to worry about, Champion. We'll get the balloon all fueled up in no time. How about you lend a hand around here while you wait?" }
WordHunterWoW_QuestEN[26075] = { title = "The Turd Problem", description = "We have a little problem...\n\n<Jibbly points to the large turds covering the base.>\n\nWe built the Sludgewerks near a wyvern habitat. Now our initial blueprints for the Sludgewerks were drawn up so as not to disturb the wyvern habitat as the beasts are apparently sacred to tauren and orcs. Do you know what's sacred to me? Not getting pooped on, that's what!\n\nBetween you, me and the wall, the wyvern must die!", objectives = "Kill any 6 Pridewing Wyvern.", progress = "Please help. The guards are getting a little uppity.", completion = "I sure hope you didn't miss any. I don't think I can take much more of this!" }
WordHunterWoW_QuestEN[26076] = { title = "Spy Infestation", description = "We've got another problem, {name}. Alliance spies are all over the place! You haven't seen any? That's because they're invisible! Cloaked! I have a solution, but I need muscle like you to go out there and follow through with my plan.\n\nUse this gas bomb on the cloaked spies and it will reveal them. Once revealed, send them back to their maker.\n\nYou'll know a cloaked spy by the effect they leave in the air. Look closely!", objectives = "Kill 8 Alliance Spies. Use Jibbly's Gas Bomb to uncloak the spies!", progress = "Have you dealt with the spy infestation?", completion = "And they called me crazy. I knew this place was crawling with spies. Poop too." }
WordHunterWoW_QuestEN[26077] = { title = "Final Delivery", description = "Overlord Krom'gar sends word from the base. You are to get back on the Krom'gar hot air balloon and take it to Cliffwalker Post. From there, the plan is to unleash the payload on the Alliance at Battlescar Valley.\n\nYou better get going, {name}. It's not wise to keep Krom'gar waiting.\n\nSpeak to General Grebo when you arrive at your destination. He'll be able to brief you on the next course of action.", objectives = "Take the Krom'gar Hot Air Balloon to Cliffwalker Post in Stonetalon Mountains.", completion = "Chieftain Cliffwalker and his tauren seek to commit treason against the Horde! They claim that the ancient tree at the heart of Battlescar Valley is merely a school for druids. They are blind to the fact that desperate measures are taken during war time. My scouts have assured me that the night elves hide a weapon of great power within that tree. We're going to end this now!" }
WordHunterWoW_QuestEN[26078] = { title = "Extinguish the Fires", description = "The Dark Iron attack took us by surprise. Their saboteurs managed to damage most of our aircraft, steam tanks, and supplies. We were only able to get a few of our bombers airborne.\n\nEvery technician, recruit, and guard I can spare is  scrambling to get the others repaired and flight-ready. Our infantry can only hold out for so long. Take this equipment and help extinguish the burning bombers.", objectives = "Using the Firefighting Equipment, extinguish 6 fires at the Ironforge Airfield.", progress = "We need to hurry and get those bombers airborne!", completion = "Well done! My men are working hard on getting our flying machines and steam tanks back into the fight." }
WordHunterWoW_QuestEN[26079] = { title = "Wanted!  Otto and Falconcrest", description = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.", objectives = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", progress = "Hello.  Do you have a report to submit?", completion = "Falconcrest and Otto?  Wonderful!\n\nHere is your reward, <name>.  I am happy to pay it." }
WordHunterWoW_QuestEN[26080] = { title = "One Last Favor", description = "{name}, I'm gonna need ya to bring this back to Captain Glovaal.  With my condition, it'll take me a week to get back to Darkbreak Cove, and we don't have any time to waste.", objectives = "Deliver Digsong's Fish and Tips to Captain Glovaal at Darkbreak Cove.", progress = "Have you found Oskar and Humphrey?", completion = "I see.  Yes, I am rememberink now... Humphrey and Oskar vere not the strongest svimmers.\n\nThe reconnaissance is helpful, and the extra fish look very tasty.  If you are seeink Mister Digsong before he returns, please send him my thanks." }
WordHunterWoW_QuestEN[26081] = { title = "Alina's Reward", description = "The tale of Trol'kalar ends here, then. It will be a weapon to bring death to the living, in the name of the Dark Lady.\n\nLeave me now, {name}. My job is once again to guard the blade. Tell Alina of your victory, I'm sure she will have a reward for you.", objectives = "Speak to Dark Ranger Alina.", completion = "The news of your victory satisfies me, <class>... a rare sensation. The Dark Lady herself has mused that our conquest of Lordaeron may be the only way the Forsaken can find true satisfaction, and pehaps even relief.\n\nBut it matters not. Our victory is inevitable. For your loyal service to the Forsaken, I award you in the name of Sylvanas." }
WordHunterWoW_QuestEN[26082] = { title = "To Battlescar!", description = "I will allow this old fool time to plead his case. He has assured me that he will bring back proof that the night elves do not harbor a weapon of mass destruction. We shall see.\n\nWhile we await this proof, you will assist our army in the valley. We have prepared a large number of siege tanks for this purpose. Our demolishers are poised for attack.\n\nTake the elevator down to the base of the outpost and take control of a Krom'gar demolisher. Use it to lay waste to our enemies in Battlescar Valley.", objectives = "Use the Krom'gar Demolisher to destroy 5 Darnassian Glaive Throwers and any 20 Alliance soldiers in Battlescar Valley.", progress = "Slay them all!", completion = "You possess quite a talent for destruction, <name>. Whatever Alliance remain after your rampage across Battlescar Valley will be dealt with by the bomb." }
WordHunterWoW_QuestEN[26083] = { title = "Hello Lolo", description = "Goutgut get sent scouting. Look at many things. Big adventure!\n\nGoutgut found secret pirate ship. Pirates all scared, run away. But ogre Lolo not run. Lolo make friend with Goutgut!\n\nGoutgut have to leave, but miss Lolo. You go say hello to Lolo for Goutgut.", objectives = "Find Lolo the Lookout at Faldir's Cove.", completion = "You friends with Goutgut! Him weird ogre. Smell funny." }
WordHunterWoW_QuestEN[26084] = { title = "Hammerfall", description = "You have served us well here, {name}. Now that we've made our mark, the next phase of our conquest will occur over months rather than minutes.\n\nThere is much work yet to be done, and I will spare you the tedium of waiting for our fortifications to trickle in. Travel to the east, to Hammerfall. The orcs there will no doubt have use of your aid.", objectives = "Report to Gor'mul at Hammerfall in Arathi Highlands.", completion = "Throm'ka, <class>. If your deeds for the undead are as great as you claim, I am honored to help you serve the Horde." }
WordHunterWoW_QuestEN[26085] = { title = "Rallying the Defenders", description = "While our engineers work on getting the bombers ready to fly again, our guards and mountaineers continue to fight the invaders.\n\nThey've been out there since the incursion began, without so much as a chance to catch some sleep or have a meal. Ironforge's defenders are among the best on Azeroth, but even they have limits.\n\nTake these banners and plant them in banks of loose snow. Remind the men what they are fighting for and help keep their morale high.", objectives = "Plant 8 Ironforge Banners in mounds of Loose Snow throughout the Ironforge Airfield.", progress = "We must do what little we can to keep the defenders' spirits high.", completion = "The men are finding hidden reserves of strength and courage to deal with the Dark Iron onslaught. The airfield will not fall on our watch!" }
WordHunterWoW_QuestEN[26086] = { title = "Orako", description = "<Captain Verne looks down at his watch.>\n\nWhere is that hunter?  I sent Orako to Underlight Canyon to prepare a recon report a week ago!  Sure, he's a handful, and I didn't mind getting him out of my hair, but I need his report.\n\nSay, what's your name?  {name}?  Would you be willing to go track him down?  It seems strange to send a {class} to find a hunter, but I'm running out of options.", objectives = "Report to Orako at Underlight Canyon in Vashj'ir.", completion = "Gah!  These fish are impossible to hit!\n\n<Orako looks at you.>\n\nMy wolf got eaten by a fish, and I'm not going back until I find her." }
WordHunterWoW_QuestEN[26087] = { title = "\"Glow-Juice\"", description = "Shooting fish in a barrel is easy.  Shooting fish in an ocean is a little harder.\n\nHave you seen the murlocs down in the canyon, {class}?  They don't shoot at all!  They have little balls full of glow-juice on their heads that make the fish come to THEM.  Hey, we should try that!\n\nGo south, and kill the crabs and groupers in the canyon.  They have lots of glow-juice in their skin.  I've seen it!", objectives = "Obtain 6 gobs of Glow-Juice from Pyreshell Scuttlers and Luxscale Groupers in Underlight Canyon.", progress = "We need lots and lots of glow-juice.", completion = "Hey, look at how glowy it is!\n\n<Orako looks wistfully off into the distance.>\n\nMy wolf loved things that were glowy..." }
WordHunterWoW_QuestEN[26088] = { title = "Here Fishie Fishie", description = "<Orako rolls the glow-juice into a ball, then attaches it to a device that he's clearly been working on for a long time.>\n\nHere, I got you this hat.  It has a light on it, and it will make fish follow you.  Just like the murlocs!\n\nThe murlocs like to hunt in the kelp and coral along the sides of the canyon.  If you put on this hat and swim in that kelp, you might catch some fish like they do.", objectives = "Put on the Fish Hat, then swim through the coral in Underlight Canyon to attract 30 Underlight Nibblers.", progress = "How many did you catch?", completion = "Hmm... you got a lot of fish, but none of these are the ones that ate my wolf.  I think it was probably a bigger fish." }
WordHunterWoW_QuestEN[26089] = { title = "Die Fishman Die", description = "A fish ate my wolf, and murlocs look like fish.  I'm going to make those murlocs pay!\n\nHead back down to the canyon and kill the fishmen!  My wolf will be avenged!", objectives = "Kill 4 Coldlight Hunters and 4 Coldlight Oracles.", completion = "I know, murlocs aren't fish.  I thought that killing them would make me feel better, but I still feel sad about my wolf.\n\n<Orako sighs.>" }
WordHunterWoW_QuestEN[26090] = { title = "I Brought You This Egg", description = "<This appears to be an egg from one of the devious great-eels that float up above the canyon.  You wonder whether or not Orako might be interested in something like this.>", objectives = "Deliver the Enormous Eel Egg to Orako at Underlight Canyon in Vashj'ir.", progress = "<Blam!>\n\nYou brought me something?", completion = "That is a big egg.\n\n<Orako sniffs it.>\n\nIt is big, and it smells like fish.  Maybe the big fish that made this egg is the big fish that ate my wolf!" }
WordHunterWoW_QuestEN[26091] = { title = "Here Fishie Fishie 2: Eel-Egg-Trick Boogaloo", description = "<Orako removes an explosive trap from his sack and shoves it through the egg's outer membrane.>\n\nThis will make the egg explode.  Place the egg down next to one of those giant eels, and wait for them to come close.  When the egg explodes, the big fish will be almost dead, and you can finish killing it.\n\nSave my wolf!  With this egg, you can do it.", objectives = "Use the Eel-splosive Device near a Devious Great-eel in Underlight Canyon, then defeat the Weakened Great-Eel.", progress = "Save my wolf, <name>.", completion = "<Orako is busy playing with Wolf.>\n\nOh, thank you, <name>!  I knew Wolf was alive!\n\nHere, take one of these.  I don't need them anymore." }
WordHunterWoW_QuestEN[26092] = { title = "Orako's Report", description = "<You remind Orako that he was supposed to send a report back to Captain Verne.>\n\nRight, a report.  All that I've seen here is fish.  Lots and lots of fish.\n\n<Orako looks over at the sack of fish that you brought for him.>\n\nBring this back to the captain.  This is my report.", objectives = "Deliver Orako's Report to Captain \"Jewels\" Verne in Tenebrous Cavern.", progress = "Where was he?  What happened?", completion = "This is his report?!  That idiot...\n\nI suppose we can use the food.  Thanks, <name>.  You've done as well as can be expected." }
WordHunterWoW_QuestEN[26093] = { title = "Northfold Manor", description = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nThough Southshore has fallen, we must not let any further ground be yielded to our enemies.\n\nGo to the Syndicate base in Northfold Manor and slay them. We must reclaim the land for ourselves before the Horde has a chance to creep further.", objectives = "Kill 10 Syndicate members at Northfold Manor.", completion = "Very good, <name>.  The last thing we need with the undead looming is a gang of common thieves distracting us." }
WordHunterWoW_QuestEN[26094] = { title = "Striking Back", description = "My chief engineer tells me that he's managed to get one of the bombers repaired and airworthy. Take these bombs with you, and look for the repaired bomber at the start of the runway.\n\nOnce you're airborne, use the bombs to do as much damage to the attacking Dark Iron dwarves as you can. I've heard rumors that they're preparing to deploy a new kind of war golem. Keep your eyes peeled for those golems and make them your highest priority targets.", objectives = "Board the Repaired Bomber and use the Iron Hammer Bomb to kill 30 Dark Iron attackers. You may kill any of the Dark Iron dwarves or their allies at the Ironforge Airfield.", progress = "At last, we finally have a chance to hurt the Dark Iron attackers.", completion = "The momentum is starting to shift, <name>, largely due to your efforts. Now, it is time to strike at the Dark Iron leadership." }
WordHunterWoW_QuestEN[26095] = { title = "Stromgarde Badges", description = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.", objectives = "Collect 7 Stromgarde Badges from Syndicate enemies in Stromgarde Keep.", progress = "Have you retrieved any Stromgarde Badges, <name>?  The Syndicate must learn they cannot profit from our dead.", completion = "Thank you, <name>.  We will inform the families of these fallen soldiers that they were killed in battle.\n\nIt will be grim news to bear, but it is better than the uncertainty of a missing loved one." }
WordHunterWoW_QuestEN[26096] = { title = "Scalding Shrooms", description = "We think that we have a use for the merciless ones that your friend from the cave delivered to us. But I need a preservative for it.\n\nDown below in the Scalding Chasm are some mushrooms with the properties that I need. Bring some back up to me and I'll see what I can do.", objectives = "Collect 5 Scalding Shrooms.", progress = "I heard that you had an unpleasant encounter with putting one of the demons on your head. I can assure you that they are now all quite dead.", completion = "I will use the mushrooms as a reagent to treat the corpses. We will have one ready for you soon." }
WordHunterWoW_QuestEN[26097] = { title = "Proof of Lies", description = "At the heart of Battlescar Valley stands an ancient tree - a tree that has withstood the force of ages and has served as a place of peace and learning for generations. My kin have studied druidism at the grove, alongside the night elves, for as long as I can recall. Now I am to believe that the tree holds within it an Alliance weapon of mass destruction?\n\nKrom'gar is wrong and I will prove it!\n\nI have sent my son, Orthus, to Thal'darah Grove in search of this weapon. Go there now and meet him.", objectives = "Find Orthus at Thal'darah Grove in Stonetalon Mountains.", completion = "Orthus is dead. He is clutching something in his hand." }
WordHunterWoW_QuestEN[26098] = { title = "Betrayal at the Grove", description = "Druid corpses litter the room. Something seems amiss, as you see no signs of a struggle.  Bloody drag marks lead in from the doorway.\n\nYou pry Orthus' death grip open to find something disturbing in his hand: a Krom'gar General's insignia.\n\nTake the Krom'gar General's insignia back to High Chieftain Cliffwalker.", objectives = "Take the Krom'gar General's Insignia back to High Chieftain Cliffwalker at Cliffwalker Post in Stonetalon Mountains.", progress = "He... My child is dead?", completion = "<High Chieftain Cliffwalker takes the insignia from you.>\n\n<High Chieftain Cliffwalker cries out in anger.>" }
WordHunterWoW_QuestEN[26099] = { title = "Is This Justice?", description = "He was a good boy, {name}. Young, loving. He would have never killed any of the young druids. They were his friends! No... Not Orthus.\n\nThe General must be called to answer for this crime. I will have justice!", objectives = "Defend yourself.", progress = "This is justice.", completion = "You saw with your own eyes, <name>. General Grebo attacked us!\n\n\n\nNow what will we do? Surely the Warchief will have us all executed for treason." }
WordHunterWoW_QuestEN[26100] = { title = "The General is Dead", description = "Perhaps if you spoke to Overlord Krom'gar, {name}. Maybe he would listen to what you had to say? You are a Champion in his army, after all. You saw everything. Please help us, {name}. We simply wish to be left alone - in peace.\n\nTalk to Overlord Krom'gar and try to help him see that we did not mean for any of this to happen.", objectives = "Speak to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", completion = "WHAT? My General has been killed by the tauren? This is treason! HIGH TREASON! They will pay for this grievous error." }
WordHunterWoW_QuestEN[26101] = { title = "Might Makes Right", description = "You have done well to report this crime. The perpetrators of this heinous act will be punished. There will be blood.\n\nI will need a new General now that Grebo is dead. You shall take his place.\n\nMeet me at Cliffwalker Post, General. Together we will end this nonsense.", objectives = "Meet Overlord Krom'gar at Cliffwalker Post in Stonetalon Mountains.", completion = "The traitorous tauren will now stand by as we destroy his precious grove and burn his village to the ground!" }
WordHunterWoW_QuestEN[26102] = { title = "Grimaxe's Demise", description = "With you leading the way, we've finally broken the momentum of the Dark Iron attack. General Grimaxe, the Dark Iron leader, is attempting to rally his troops from the center of their lines on the frozen lake to the south.\n\nHe stands atop one of their new dark iron golems, shouting orders to his men. If he succeeds in rallying them, they may still be able to overpower us. You must prevent that, {name}. Destroy the golem guarding him, then kill General Grimaxe himself. He is the key to our victory.", objectives = "Kill General Grimaxe at the Ironforge Airfield.", progress = "If we can defeat General Grimaxe, the Dark Iron forces won't be able to regroup.", completion = "We've done it! Without your help, Ironforge Airfield would surely be occupied by the enemy and the Dark Irons would have a clear road to Ironforge itself.\n\nThe Council of Three Hammers must be informed of what happened here." }
WordHunterWoW_QuestEN[26103] = { title = "Bio-Fuel", description = "Submarine fuel is expensive!\n\nThe powers-that-be in Gnomeregan were generous enough to deliver several fuel barrels, but we're burning through it faster than expected.  That means we're going to need to improvise.\n\nIt's a well-known fact that sea creatures are full of all kinds of interesting chemicals... like oil.  Take this device up to Kothrun's End and stick it into the corpses of terrapins, remoras, and hammerhead sharks.  If we don't get more submarine fuel, their oil might be our only hope.", objectives = "Use the Oil Extrusion Pump on the corpses of Seabrush Terrapins, Scourgut Remoras, and Spinescale Hammerheads in Kothrun's End to obtain 4 Terrapin Oil, 4 Remora Oil, and 4 Hammerhead Oil.", progress = "How did the device work, <name>?", completion = "<Engineer Hexascrub sticks a finger into each sample and sniffs it.>\n\nYes, I think this will do." }
WordHunterWoW_QuestEN[26104] = { title = "Our Aquatic Neigh-Bors", description = "Good fortune to you, comrade.\n\nThe reinforcements are here, and they are bringink food, and men, and fresh mounts.  The problem is that our mounts are highly immobile when placed under the water.\n\nDirectly above this cave, you vill find tall pillars with red, leafy kelp on their tops.  Seahorses hide in the kelp.  Throw this lasso into the kelp and catch us some mounts for usink in the water.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Seahorse Lasso near the kelp atop the pillars in Korthun's End to capture 5 Panicked Seahorses." }
WordHunterWoW_QuestEN[26105] = { title = "Claim Korthun's End", description = "The Horde has spies in this area?  Darkbreak Cove is nearby, and inside lies the Pincer X2!  The Horde must not be allowed anywhere nearby!\n\nSomeone in Darkbreak Cove will want to hear of this... after you finish slaying some more of these dirty Horde spies.", objectives = "Kill 7 Hellscream Seadogs in Korthun's End.", completion = "You did well, <name>.  We need to be especially wary of Horde attacks right now.  The Pincer X2 has plenty of firepower at sea, but in the back of this cave, she is exceptionally vulnerable." }
WordHunterWoW_QuestEN[26106] = { title = "Fuel-ology 101", description = "How much do you know about fuel, {name}?  Constructing the perfect fuel is a tricky job, as there's plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that's only naming a few.\n\nHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you're done.", objectives = "Use the Fuel Sampling Station in Darkbreak Cove to create the perfect bio-fuel.", progress = "We haven't found the right combination yet, <name>.  Keep at it!  I'm sure you can figure it out!", completion = "Have you considered a career in science, <name>?  If you ever get tired of this <class> nonsense, come see me!  I could use an assistant with your devotion to experimentation and the scientific method." }
WordHunterWoW_QuestEN[26107] = { title = "Raising Spirits", description = "Our race's gift of shamanism stirred me from a years-long lethargy. Now I provide for all here, crafting the same boons that gave me newfound strength.\n\nThe Highland raptors are cunning and fierce beasts. Their spirits can grant our warriors great strength. Bring me raptor eyes, so I may make the amulets as Tor'gan taught me.", objectives = "Collect 10 Highland Raptor Eyes from Highland Striders or Highland Thrashers.", progress = "The fierceness in the eyes of the raptors will be matched by those of our warriors.", completion = "The lethargy that overcame me even after the camps fell was so strong, I refused this gift when it was first given to me.\n\nNow, I am proud to do my part in the name of the Horde." }
WordHunterWoW_QuestEN[26108] = { title = "Guile of the Raptor", description = "The highland fleshstalkers to the south are even fiercer than the others of their kind. They possess not just strength, but true cunning.\n\nWhen I was trapped by lethargy, even the amulets of strength failed to move me. But Tor'gan used the hearts of the fleshstalkers to imbue me with spirits that conquered my doubt, freeing me.\n\nOur soldiers deserve the guile of the raptor. Collect the fleshstalker hearts for me, {name}.", objectives = "Collect 12 Raptor Hearts from Highland Fleshstalkers.", progress = "My preparations are made, all I need are the raptor hearts.", completion = "As Tor'gan taught me, I transfer the power and the spirit of the raptors into this orb. It will imbue our warriors with the fiery strength and intelligence of the raptor.\n\nThe guile of the raptor is yours now as well, <class>. Take it with pride, for the Horde!" }
WordHunterWoW_QuestEN[26109] = { title = "Land Ho!", description = "Lolo sees a tiny <race>! Always on the lookout, Lolo is!\n\nWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.\n\nBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!\n\nLolo suggests you talk to Captain O'Breen if you plan on sticking around here.Upon completion of this quest you will gain:", objectives = "Talk to Captain O'Breen at Faldir's Cove in Arathi Highlands.Lolo sees a tiny <race>! Always on the lookout, Lolo is!\n\nWelcome to Faldir's Cove. Captain O'Breen said we'd only be here for a few hours. Just long enough to gather the treasure and get back to Booty Bay.\n\nBut Lolo thinks we're going to be here a lot longer than that. We lost the other two ships from our formation. Poor Spirit of Silverpine and Maiden's Folly. On the bottom of the sea they rest now!\n\nLolo suggests you talk to Captain O'Breen if you plan on sticking around here.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26110] = { title = "Just Like Old Times", description = "It's funny. Kin and I have been through so much together, and here we find ourselves back in Arathi, like so many years ago.\n\nWe broke up a plot to create a new plague right here, her and I. It doesn't look like the Horde learned their lesson, because they're all over this farm yet again.\n\nTheir undead courier is shuffling around as obvious as daylight. If you want to help, find the courier and bring back whatever they're carrying.", objectives = "Collect the Sealed Folder from the Forsaken Courier.", progress = "We appreciate your help in looking for that courier, <name>.\n\nWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I'm confident that they're up to no good--I just need proof of it before we go off and do something rash.\n\nHave you had any luck yet?", completion = "Apothecaries yet again. You think they'd get the message. Let's see what it is this time..." }
WordHunterWoW_QuestEN[26111] = { title = "... It Will Come", description = "I now imbue you with the energies of the corrupting faceless.\n\nSwim down to my luring totem in the trench to the northeast. Release the energies through it. Bring back the brain of their leader.\n\nCall forth to Ick'thys the Unfathomable... it will come!", objectives = "Obtain the Brain of the Unfathomable.", progress = "Do you have it, <name>?\n\nWith the Unfathomable's brain, we still may yet be able to communicate with L'ghorek, the dying ancient one in front of us.", completion = "And now we will see if we can get you into L'ghorek to speak with it before it dies." }
WordHunterWoW_QuestEN[26112] = { title = "Demanding Answers", description = "So just how did all those Dark Iron warriors end up here, on the doorstep of Ironforge, on the verge of invading our city?\n\nDoes not 'Empress' Moira, a member of our esteemed Council of Three Hammers, rule the Dark Iron? This cannot have happened without her knowledge and consent. This was no ragtag band of rebel dwarves, but a well-organized and fully equipped invasion force.\n\nI have prepared a report on the battle for the airfield. Take it to Ironforge, to the High Seat and confront her!", objectives = "Take Stonebreaker's Report to Moira Thaurissan in Ironforge's High Seat.", progress = "What is the meaning of this intrusion?", completion = "And just what is this?\n\n<Moira takes the report and the color drains from her face as she reads.>\n\nThis is impossible!" }
WordHunterWoW_QuestEN[26113] = { title = "Quae and Kinelory", description = "The Horde have held Go'shek Farm to the east for a long time; it's never been of much concern compared to the rest of our problems here. But there's been reports of undead activity in the area.\n\nAnything more alarming than shuffling peons over there warrants investigation. This isn't the first time the undead have been up to no good at the farm, so I've sent my best scouts there to check it out. Report to Quae and Kinelory and they'll fill you in.", objectives = "Find Quae on the hill overlooking Go'shek Farm.", completion = "Refuge Pointe sent you? Good to know they're still there.\n\nWe've got some interesting things to check into here, <class>." }
WordHunterWoW_QuestEN[26114] = { title = "Quae Trusts You", description = "<Quae begins to go through the folder.>\n\nExpansion...control of territory... these undead aren't cooking up anything new, but they're planning to roll over all of Arathi. We need to disrupt their plans.\n\nI'll keep a lookout from up here. You go with Kin, and get those invasion plans. We're not going to let these walking corpses even know what day it is out here.\n\nAnd keep her safe, you hear me?", objectives = "Speak to Kinelory near Go'Shek Farm in Arathi Highlands.", completion = "The plague took our friends and family, but it was the Forsaken that took Phin. They're just as bad as the Scourge. I'll destroy every one of them with my own hands if I have to.\n\nWhen you're prepared, come let me know. We'll get started right away." }
WordHunterWoW_QuestEN[26115] = { title = "To Be Horde...", description = "Stand by me, {name}, and watch as our mighty weapon destroys our enemies!\n\nLearn what it means to be Horde!", objectives = "Learn what it means to be Horde.", progress = "Now do you understand?", completion = "Now you truly know what it means to be a member of the Horde, <name>." }
WordHunterWoW_QuestEN[26116] = { title = "Kinelory Strikes", description = "All right, {name}. I'm ready if you are.\n\nShall we?", objectives = "Protect Kinelory until she returns to Quae.", progress = "You'd best keep with Kinelory. I trust you, but if something happens to her, I won't be accountable for my actions.", completion = "You've done a great service for us, <name>. Thank you.\n\nI hope Kin wasn't too much of a handful down there. She's very friendly, but can be just as deadly when you're her enemy." }
WordHunterWoW_QuestEN[26117] = { title = "For Southshore", description = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nRefuge Pointe will want to know of our success. I'm going to stay here with Kin and let her catch her breath. Go on ahead without us.", objectives = "Return to Commander Amaren at Refuge Pointe.", completion = "I admit I'm impressed, <class>. It's a small comfort amidst all that's happened here.\n\nYou have fought the undead, struck back against the Horde, and honored the memory of the victims of Southshore. On behalf of the kingdom of Stromgarde, I present you with an official commendation, and this reward." }
WordHunterWoW_QuestEN[26118] = { title = "Seize the Ambassador", description = "The ambassador's betrayal will long haunt me. You must arrest him before he can do further harm, or worse, before he can escape and start planning the next attack. Ironforge is not safe with Ambassador Slaghammer free inside the city.\n\nTake these manacles and go to the Dark Iron embassy. It's just to the north of the High Seat, around the rim of the Great Forge. Arrest Ambassador Slaghammer and return with him.", objectives = "Go to the Dark Iron Embassy and use the Sturdy Manacles to arrest Ambassador Slaghammer.", progress = "We must stop the ambassador before he causes more harm.", completion = "The ambassador will trouble us no more. He is not the only Dark Iron <race> whose heart still belongs to Twilight's Hammer. We must remember that and remain vigilant against their schemes, else my son will inherit only ruins and ashes." }
WordHunterWoW_QuestEN[26119] = { title = "FLAG - Claim Our Stake Launched", description = "", objectives = "" }
WordHunterWoW_QuestEN[26120] = { title = "The Crazed Dragonmaw", description = "The Dragonmaw orcs nearby are fast becoming a nuisance. Their suicidal attacks on the grove are merely annoying, though they provide my sentinels with some needed practice.\n\nMy scouts, however, have seen them rounding up black dragon whelps in nets. The last thing these lands need is a crude revival of dragon-taming. Strike out to the east, {class}, and cut down the whelpstealers; make sure their folly does not come back to haunt us later.", objectives = "Kill 12 Dragonmaw Whelpstealers.", completion = "The orcs will know better than to press further west now. Well done." }
WordHunterWoW_QuestEN[26121] = { title = "Claim Korthun's End", description = "You are seeink spies up above?  This is not good... not good at all, comrade.\n\nReturn to Korthun's End and destroy them, my friend.", objectives = "Kill 7 Hellscream Seadogs in Korthun's End.", completion = "You did well, <name>.  We need to be especially wary of Horde attacks right now.  The Pincer X2 has plenty of firepower at sea, but in the back of this cave, she is exceptionally vulnerable." }
WordHunterWoW_QuestEN[26122] = { title = "Environmental Awareness", description = "Have you ever smelled submarine fuel, {name}?  It's nasty stuff.  Unfortunately, we need to burn huge amounts of it to get the Verne to move, and it's both bad-smelling AND deadly to the local wildlife.  We need to be more environmentally conscious.\n\nThe sea creatures nearby have particularly oily flesh.  Take this device up to Seabrush - just above this cave - and use it on the corpses of terrapins, remoras, and hammerhead sharks.  Their oil might save the lives of hundreds of other sea creatures.", objectives = "Use the Oil Extrusion Pump on the corpses of Seabrush Terrapins, Scourgut Remoras, and Spinescale Hammerheads in Seabrush to obtain 4 Terrapin Oil, 4 Remora Oil, and 4 Hammerhead Oil.", progress = "Please... don't tell the other goblins that I'm an environmentalist!  I don't think I can take the mocking!", completion = "<Fiasco sticks a finger into each sample and sniffs it.>\n\nYes, I think this will do." }
WordHunterWoW_QuestEN[26123] = { title = "When in Vashj'ir...", description = "Welcome, friend!\n\nReinforcements have arrived, and they've brought food, orcs, and fresh mounts.  Wait a minute... mounts?!\n\nHow are we supposed to get around underwater on WOLFBACK?!\n\n<Captain Verne sighs.>\n\nDirectly above this cave, in Seabrush, you will find tall pillars with red, leafy kelp on their tops.  Seahorses hide in the kelp.  Throw this lasso into the kelp and catch us some USEFUL mounts.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Seahorse Lasso near the kelp atop the pillars in Seabrush to capture 5 Panicked Seahorses." }
WordHunterWoW_QuestEN[26124] = { title = "Secure Seabrush", description = "The Alliance has spies in this area?  Tenebrous Cavern is nearby, and inside lies the Horde's new submarine, the Verne!  The Alliance must not be allowed anywhere nearby!\n\nSomeone in the cavern will want to hear of this incursion... after you finish slaying some more of these scheming Alliance spies.", objectives = "Kill 7 Alliance Sea-Scouts in Seabrush.", completion = "You did well, <name>.  We need to be especially wary of Alliance attacks right now.  The Verne's got plenty of firepower out at sea, but in the back of this cave, she's far too vulnerable." }
WordHunterWoW_QuestEN[26125] = { title = "Secure Seabrush", description = "You saw spies up above?  This is not good... I won't have it.\n\nReturn to Seabrush and get rid of them before they start trickling into our hideout.", objectives = "Kill 7 Alliance Sea-Scouts in Seabrush.", completion = "You did well, <name>.  We need to be especially wary of Alliance attacks right now.  The Verne's got plenty of firepower out at sea, but in the back of this cave, she's far too vulnerable." }
WordHunterWoW_QuestEN[26126] = { title = "The Perfect Fuel", description = "How much do you know about fuel, {name}?  Constructing the perfect fuel is a tricky job, as there's plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that's only naming a few.\n\nHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you're done.", objectives = "Use the Fuel Sampling Station in Tenebrous Cavern to create the perfect bio-fuel.", completion = "That's it.  Starting today, I'm shifting the Verne over to bio-fuel.  I'll send some men up to harvest more oil.\n\nThink of all the sea creatures that we've saved today, <name>!" }
WordHunterWoW_QuestEN[26127] = { title = "The Twilight's Hammer Revealed", description = "I and everyone else thought these fools were just Dark Iron up to no good, but these nutters are fullblown cultists!\n\nThe Twilight's Hammer wants nothing short of the destruction of the entire world. They've thrown their lot in with Deathwing and Ragnaros, and they've got a history with the Dark Iron.\n\nBut it doesn't matter who they are, what matters is they're in Dun Modr and they need to get out! I'll not let any past here. You get in there and crack some skulls!", objectives = "Kill 12 Twilight's Hammer members in Dun Modr.", progress = "I've got to hold the line here, lad. As much as I want to get in there and tear them up, I'm dead set on making sure not a one of the slimy curs escapes!", completion = "Good show, lad, but we've no time to celebrate. Thandol Span's in danger!" }
WordHunterWoW_QuestEN[26128] = { title = "The Battle of Thandol Span", description = "I've defended the Thandol Span from being destroyed before, against the Dark Iron themselves. And so did my father, and his father before him...\n\nThe only Dark Iron that managed to give me the slip ran straight for the bridge. Something's amiss, and I'm betting when we get there we'll be waltzing right into an ugly trap.\n\nI could use your help, {name}, for Ironforge. Are you with me?", objectives = "Defeat Calamoth Ashbeard at the Thandol Span.", progress = "There's no time to waste! Hurry to the Thandol Span!", completion = "And good riddance!\n\nThandol Span's safe thanks to you, <name>, and hopefully Calamoth is down for good this time." }
WordHunterWoW_QuestEN[26129] = { title = "Brothers In Arms", description = "Listen, {name}.  For the first time since the civil war I agree with Greymane.  Now is the time to put aside our quarrel.\n\nIt sure doesn't look like these beasts care much whether you're a rebel or a royal.\n\nSend word back to Greymane.  My men will join his.\n\nThere's a safehouse not far from here, in Josiah's cellar.  My lads stashed some heavy artillery there.\n\nTell our king that my arsenals are now at his disposal.", objectives = "Speak to King Genn Greymane at the Military District in Gilneas City.", completion = "Rebel arsenals?  In my own city?\n\nWhat in the bloody hell was Crowley up to?" }
WordHunterWoW_QuestEN[26130] = { title = "Unplug L'ghorek", description = "L'ghorek is the ancient that rests upon the shelf across from us. It is being controlled and its life energies slowly consumed by something immense beneath us.\n\nThere is a cave known as the Undershell down below L'ghorek. In that cave are three powerful ogre magi that are maintaining a ritual connecting the thing below with the ancient. You must kill these three to disconnect L'ghorek.", objectives = "Slay Ur'Goz, Sku'Bu, and Neph'Lahim.", completion = "Now that you have unplugged L'ghorek, we must attempt to make contact with it. I can sense that the ancient yet lives, but only barely." }
WordHunterWoW_QuestEN[26131] = { title = "Reinforcements for Loch Modan", description = "I've been waiting for the council to hear my plea for hours, and it's not looking good. Moira's greatest desire seems to be to paralyze the council.\n\nMeanwhile, Loch Modan suffers. Our enemies are many and our resources are few. Please, {name}, perhaps you will hear me if the council will not. Speak to Gryth Thurden, Ironforge's gryphon master. He's in the eastern part of the Great Forge. He'll provide a free flight to the South Gate Pass. Introduce yourself to Pilot Hammerfoot once you arrive.", objectives = "Speak to Gryth Thurden at the Great Forge for a flight to Loch Modan. Speak with Pilot Hammerfoot when you arrive.", completion = "You don't know how glad I am to see fresh faces from Ironforge. Perhaps sending Mountaineer Barleybrew wasn't a waste after all." }
WordHunterWoW_QuestEN[26132] = { title = "Fiends from the Netherworld", description = "The ogre magi within the Undershell have summoned protectors for themselves: fleshling fiends from the netherworld.\n\nWe cannot risk these aberrations from being later used against our forces. While you are in there, I want you to destroy as many of those things as you can.", objectives = "Slay 8 Nether Fiends.", completion = "The last thing we needed was a bunch of summoned creatures swarming our forces during the final assault." }
WordHunterWoW_QuestEN[26133] = { title = "Fiends from the Netherworld", description = "Those ogre magi inside the Undershell have summoned defenders: fleshling fiends from the netherworld.\n\nI do not want to see these aberrations used against our forces. While you are in there, destroy all of them!", objectives = "Slay 8 Nether Fiends.", completion = "That's one less thing we need to think about during the final assault." }
WordHunterWoW_QuestEN[26134] = { title = "Nothing Left for You Here", description = "There is nothing left for you here, {name}. As for me, I must lay Masha's body to rest. Once I have done that I will go to the bombing site and begin the process of regrowth. Perhaps one day a new grove will bloom - a grove infused with the spirit of my child and the fallen night elf youths.\n\nIf you wish to travel to Desolace, I hear word of a blood elf named Furien seeking adventuring partners. Perhaps you should seek him out.\n\nFarewell, friend, I will never forget you.", objectives = "Speak to Furien at Tethris Aran in Desolace.", completion = "<Furien groans.>" }
WordHunterWoW_QuestEN[26135] = { title = "Visions of the Past: Rise from the Deep", description = "What you told me of the naga before has been plaguing my mind. Who are these allies they're summoning? Do they really think they can defeat the Tidehunter?\n\nEscaping this cave brings a degree of relief, but our purpose here remains. I'm hoping you will be willing to seek answers from the Battlemaiden one last time.\n\nThere's only one place that I can think of where they would have taken the artifact - the temple atop the ruins. It's sure to be well guarded. Proceed carefully.", objectives = "Witness the concluding story of the Battlemaiden by using her broken blade somewhere in the Temple of Quel'Dormir.", completion = "Minions of the Old God? Two very potent foes have joined forces then. Their hope to defeat the Tidehunter may not be so foolish after all.\n\n<name>, we can't let that happen. If Azshara defeats the Tidehunter and takes his power for herself, I'm not sure any number of us could ever hope to oppose her on the seas.\n\nThe first step is clear at least - we need to hunt down the fiend that destroyed our ships. The navy was confident enough to bring in a new fleet, perhaps they have a plan." }
WordHunterWoW_QuestEN[26136] = { title = "FLAG - Rigor Mortis Removed", description = "", objectives = "" }
WordHunterWoW_QuestEN[26137] = { title = "Checking on the Boys", description = "I'm sure you've seen just how bad the damage to the Loch is by now. The damage spreads further than that, I'm afraid; all that water had to go somewhere, and it went down into the Wetlands.\n\nThere's a lot of fine dwarves down there trying to help out, and they need supplies. That's why I sent two of my mountaineers ahead with a cask of ale along the path into the Wetlands.\n\nI haven't heard back from them since they set off down the road to Dun Algaz. Would you mind checking up on them?", objectives = "Travel to the Wetlands and speak to Mountaineer Rharen near Dun Algaz.", completion = "Ah, well met, <class>.\n\nStormpike sent you? About the keg? Hoo boy..." }
WordHunterWoW_QuestEN[26138] = { title = "Ferilon Leafborn", description = "There's a group of night elves that call the wetlands home now. A bunch of them shipped in from Kalimdor to study the land here, look at the plants, that sort of stuff.\n\nOne of the druids by the name of Ferilon stopped by here a while back. He was nice enough to give us a hand with some raptors, and he mentioned something about needing more folk to help out with his duties.\n\nIf you've got the time, you'll find him at the place they call Greenwarden's Grove, to the northeast.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Ferilon Leafborn at Greenwarden's Grove.There's a group of night elves that call the wetlands home now. A bunch of them shipped in from Kalimdor to study the land here, look at the plants, that sort of stuff.\n\nOne of the druids by the name of Ferilon stopped by here a while back. He was nice enough to give us a hand with some raptors, and he mentioned something about needing more folk to help out with his duties.\n\nIf you've got the time, you'll find him at the place they call Greenwarden's Grove, to the northeast.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26139] = { title = "Into Arathi", description = "You should go on ahead and warn the other side of the span about this, {name}.\n\nOver the bridge to the north you'll find Refuge Pointe, the stronghold of the Alliance in Arathi. Tell Captain Nials to keep an eye out for these Twilight's Hammer curs.", objectives = "Travel to Arathi Highlands and speak with Captain Nials in Refuge Pointe.", completion = "I suppose I owe Thargas a favor for sending such a bold hero my way.\n\nOr perhaps he just wanted to keep all the clean-up for himself. Regardless, you'll find much to do here for the Alliance." }
WordHunterWoW_QuestEN[26140] = { title = "Communing with the Ancient", description = "Place the dead merciless one upon your head to pose as one of their slaves.\n\nEnter L'ghorek. Commune with the ancient.", objectives = "Deliver the Brain of the Unfathomable to L'ghorek in the Cerebrillum inside of L'ghorek in Vashj'ir.", progress = "I SENSE... SOMETHING. COME CLOSER....", completion = "WISE OF... YOUR ERUNAK TO... HAVE... YOU USE... THE FACELESS' BRAIN. I SEE... YOU NOW.\n\nI WILL DIE. THERE IS NO... STOPPING... THE INEVITABLE.\n\nBUT... YOU WILL HELP... ME DEAL WITH... THESE PARASITES FIRST." }
WordHunterWoW_QuestEN[26141] = { title = "Runestones of Binding", description = "ON THE OTHER... SIDE OF... MY CHAMBER THERE... ARE... CANDIDATES FOR ASCENSION.\n\nWE WILL NEED... THEIR... RUNESTONES OF BINDING... TO CREATE A... MEANS OF CONTROLLING... A BOUND ELEMENTAL.", objectives = "Collect 7 Runestones of Binding.", progress = "DO... YOU HAVE... ALL THAT IS... REQUIRED?", completion = "WE WILL USE... THESE... RUNESTONES TO ALLOW... YOU TO POSSESS... ONE OF... THE WATER ELEMENTALS." }
WordHunterWoW_QuestEN[26142] = { title = "Ascend No More!", description = "TO STOP... THEIR... RITUALS OF ASCENSION... YOU MUST DESTROY... THE ANCIENT CONDUITS.\n\nTHEY USE... THE CONDUITS TO... SIPHON... MY ENERGIES AWAY... AND MAKE... ASCENDANTS.\n\nA FIGHT WITH... NEPTULON IS IMMINENT. THE TWILIGHT'S HAMMER... MUST BE DENIED... THESE CREATURES.", objectives = "Destroy 5 Ancient Conduits.", completion = "THEY SHALL ASCEND... NO MORE!" }
WordHunterWoW_QuestEN[26143] = { title = "All that Rises", description = "<The voice of the ancient presses against your mind.>\n\nNOW THAT... YOU HAVE STOLEN... THE ENERGIES OF... THE FAITHFUL, ENTER... THE TEMPLE AND... DESTROY... HALLAZEAL THE ASCENDED!", objectives = "Slay Hallazeal the Ascended.", completion = "YOU HAVE DONE... MYSELF AND... THE TIDEHUNTER GREAT... SERVICE." }
WordHunterWoW_QuestEN[26144] = { title = "Prisoners", description = "The Twilight cultist dropped this key. Use it to free the Alliance prisoners in the cages inside of L'ghorek.\n\nHurry before the prisoners become sacrifices to whatever lurks below!", objectives = "Rescue 5 Alliance Prisoners." }
WordHunterWoW_QuestEN[26145] = { title = "The Trogg Threat", description = "{class}, you may or may not be aware of the trogg threat looming over dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we're left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the town here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned troggs lurking in the hills.  If you're up to the task, wage an assault on the troggs.  Bring me back eight trogg stone teeth as proof.", objectives = "Collect 8 Trogg Stone Teeth.", progress = "Do you have eight trogg stone teeth to show me?  If not, there is still work to be done, <name>.", completion = "I am quite impressed, <name>.  You have done the Dwarven race a great favor by defending our lands.  King Magni Bronzebeard himself would be proud!" }
WordHunterWoW_QuestEN[26146] = { title = "In Defense of the King's Lands", description = "We need to protect the Loch, {name}! With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front. Troggs are tunneling up from every crevice! The trogg infestation poses the largest threat to Ironforge.\n\nWe need you, brave adventurer, to venture forth and lay waste to the trogg threat. Slay twelve Stonesplinter troggs and venture back.", objectives = "Kill 12 Stonesplinter Troggs or Stonesplinter Scouts.", progress = "Loch Modan is under siege, <name>!  We need every able-bodied member of the Alliance to aid our cause.  Have you killed those troggs yet?", completion = "Well done, <name>!  You demonstrated uncanny courage on the battlefield.  Our war against the Troggs will be won with efforts such as yours.  You have served King Magni well." }
WordHunterWoW_QuestEN[26147] = { title = "Bigger and Uglier", description = "The Mountaineers tell me you are quite brave and capable, {name}.  We need a {race} like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned {class} here, let's see what you can do.\n\nGo out and kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers. You should find them in and around the caves in the southern mountains.\n\nLet's see if you live up to your reputation, Trogg-Slayer.", objectives = "Kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers.", completion = "I knew the second I laid eyes on you, <name>, that you would make Ironforge proud.  You have served our people well. I salute you, <name>." }
WordHunterWoW_QuestEN[26148] = { title = "A Decisive Strike", description = "It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug. He's the biggest of all the troggs here, lurking deep within the darkness of the caves to the north.\n\nIf you feel yourself worthy, {name}, I want you to lead the assassination mission on Grawmug.", objectives = "Kill Grawmug.", progress = "Your mission is not complete until Grawmug has been brought to death.  Khaz Modan is counting on you, <name>.", completion = "Most excellent, <name>! You have brought hope to Loch Modan. With Grawmug dead, we stand a better chance of seeing the Troggs eliminated from the land." }
WordHunterWoW_QuestEN[26149] = { title = "Prisoners", description = "The Twilight cultist dropped this key. Use it to free the Horde prisoners in the cages inside of L'ghorek.\n\nHurry before the prisoners become sacrifices to whatever lurks below!", objectives = "Rescue 5 Horde Prisoners." }
WordHunterWoW_QuestEN[26150] = { title = "A Visit With Maybell", description = "You seem like the helpful type, {name}. How about doing an old man a favor?\n\nThe last time I was over at the Maclure Vineyards I overheard Maybell crying in her cottage. Would you be so kind as to go check up on her? I'm a little worried.", objectives = "Speak to Maybell Maclure at the Maclure Vineyards in Elwynn Forest.", completion = "William sent you? Bless his soul. I... I'm ok... It's just... Well..." }
WordHunterWoW_QuestEN[26151] = { title = "Dark Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the insignia of the void - no doubt a message from our local warlock trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Read the Dark Letter and speak to Drusilla La Salle at the graveyard in Northshire Valley." }
WordHunterWoW_QuestEN[26152] = { title = "WANTED: James Clark", description = "By decree of the Stormwind Army, a bounty has been placed on the head of James Clark.\n\nClark is wanted for robbery, burglary, arson, and murder. He is also a suspect in the kidnapping and disappearance of the Brackwell's prized pig, Princess.\n\nJames Clark was last seen heading towards Eastvale Logging Camp.\n\nBring James Clark to justice and report to Marshal Patterson at Eastvale Logging Camp.", objectives = "Kill James Clark and take James Clark's Head.", progress = "Turning in a bounty?", completion = "And justice is served!" }
WordHunterWoW_QuestEN[26153] = { title = "Penny's Pumpkin Pancakes", description = "My daughter Penny loves pumpkin pancakes but we have had a shortage of pumpkins here in Elwynn from the frostbite last season.  I have heard of a new pumpkin patch north of Stormwind that might be ripe for the picking now though.  Head out and harvest a few of those ripe pumpkins for me and let's see what we can do.", objectives = "Obtain 6 Stormwind Pumpkins. Deliver them to Robby Flay in Stormwind City.", progress = "Have you finished collecting the pumpkins?", completion = "Nice job, <name>! Penny will be very excited for breakfast tomorrow!" }
WordHunterWoW_QuestEN[26154] = { title = "Twilight Extermination", description = "NOW, TAKE... THE ATTUNED RUNESTONE... AND USE... IT TO POSSESS... ONE OF... THE BOUND TORRENTS... AT... THE CENTRAL TEMPLE. THEY WILL IGNORE... YOU. YOU ARE BENEATH... THEIR NOTICE.\n\nUSE... THE ELEMENTAL'S POWERS... TO DESTROY... THE TWILIGHT DEVOTEES... AND... THEIR... FACELESS OVERSEERS.", objectives = "Possess a Bound Torrent and then slay 50 Twilight Devotees and 10 Faceless Overseers." }
WordHunterWoW_QuestEN[26155] = { title = "A Dark Threat, Remembered", description = "Years ago, the Dark Iron tried to destroy the Stonewrought Dam. Moira may be parked in Ironforge's fancy new senate, but I'm not about to forget the past, not when a whole field trip of them are milling about here in the Loch.\n\nI need you to get in there and find out what they're really up to. Find their real plans. They'll no doubt be in the center of their camp.\n\nTry not to be seen... but if you are, defend yourself, <name>. I'd hate to lose a good <race> out there.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain the Stonewrought Schematics from the Dark Iron in the center of The Loch.`" }
WordHunterWoW_QuestEN[26156] = { title = "All The King's Men", description = "The Stonewrought Dam may already be broken, <name>, but it holds back more than just water. The whole thing's hanging by a thread. With the land already destabilized, if they blow the remaining part of the dam...\n\n...half of Loch Modan could collapse! The damage would be even more catastrophic. We'll be standing on a giant sinkhole if we don't act fast.\n\nGet to the Stonewrought Dam and stop those Dark Iron Sappers. Make sure none of them get away!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 6 Dark Iron Sappers." }
WordHunterWoW_QuestEN[26157] = { title = "Kasim Sharim", description = "I need you to pass on a message for me.\n\nKasim Sharim is an old blood mage that knows a great deal about the demons of the Blasted Lands.  Though you wouldn't know from looking at him, he's quite old, and very powerful... if a little eccentric.  As of late, he spends his days in the back of the Serpent's Coil, a cave not far from where you killed those cultists.\n\nPlease, deliver this message to him.  He will know what it means.", objectives = "Report to Kasim Sharim in the back of the Serpent's Coil in the Blasted Lands.", progress = "I don't know you.", completion = "Hah!  You Nethergarde nincompoops are always two steps behind me, and I'm nowhere near as fast as I used to be.\n\nI don't need Mahar's note to know what's going on.  Why do you think I'm cooped up in the back of this cave?  What I do need, however, is a strong <race> like you." }
WordHunterWoW_QuestEN[26158] = { title = "Attune the Bloodstone", description = "Did you have fun fighting your way to the back of this cave?  I admit, I haven't picked the most... convenient of spots to perform my studies, especially for passing adventurers who wish to enter and leave at will.\n\nHowever, I can allow you to attune yourself to my bloodstone teleporters.  Simply place your hands on the stone in the back corner, and you will be teleported outside of the cave.  Then use the stone outside to teleport back!", objectives = "Attune yourself to the Bloodstone Teleporters in the Serpent's Coil.", progress = "The attunement process is simple, but will certainly come in handy down the line.", completion = "Excellent!  You've managed to complete the simplest of tasks without dying.  Now that that's out of the way..." }
WordHunterWoW_QuestEN[26159] = { title = "The First Step", description = "Like any good bloodmage, I perform my magic with blood.  All blood is different, and the Blasted Lands has several useful flavors, if you know where to look.\n\nFor our purposes?  Basilisks and hyenas, even amounts.  We're going to need plenty of it.  Head west, to the center of the Blasted Lands.  And don't forget... you can use that teleporter!", objectives = "Obtain 9 vials of Snickerfang Hyena Blood and 9 vials of Redstone Basilisk Blood.", progress = "Do you have it?", completion = "<Kasim eyes the blood hungrily.>\n\nMore than enough, and still warm!  Now, let's get this ritual started, shall we?" }
WordHunterWoW_QuestEN[26160] = { title = "Blood Ritual", description = "I suppose you want to know what we're doing.  Here's the short version - a version at which I happen to be an expert:\n\nThe Shadowsworn cultists wish to summon the demon, Razelikh, back to the Blasted Lands.  We cannot allow this to happen.  So we're going to summon him ourselves, and then kill him.  A task not as simple as it sounds...\n\nLet me know when you are ready to begin the blood ritual, and then stand back.", objectives = "Speak with Kasim Sharim to begin the blood ritual.", completion = "The blood ritual was a success; I can clearly see where we are going next.\n\nI'm sorry, I misspoke.  What I meant to say is, I can see where YOU are going next..." }
WordHunterWoW_QuestEN[26161] = { title = "Not Just Any Body", description = "We need Loramus Thalipedes, the demon hunter.  He knows Razelikh's true name, and as you know: if you know the name of the demon, you have power over it.  The problem is that Loramus has been killed, and his body torn apart.\n\nIf you bring me the pieces, we still have a recourse.  All three pieces are in the west... the Dreadmaul ogres hide them in their caves.  Move quickly, for much like Grimeo, Loramus also owes me a debt...", objectives = "Find Loramus' Head, Loramus' Torso, and Loramus' Legs.", progress = "Trust me... whatever happened to Loramus, we can fix.  The limits of blood magic are still undefined.", completion = "I see... yes, I can work with this.\n\n<Kasim looks at the night elf's head.>\n\nLoramus Thalipedes, demon hunter.  I look forward to our reunion." }
WordHunterWoW_QuestEN[26162] = { title = "The Altar of Storms", description = "Up on the bluffs to the west lies a powerful altar.  A powerful DEMONIC altar, guarded by cultists, but powerful nonetheless.  If you can reach it, you can use it to bring Loramus back to us.\n\nThe altar will likely resist your efforts, so you'll have to protect Loramus' body while the ritual completes.  Bring the demon hunter back to me afterwards.", objectives = "Bring Loramus' Body to the Altar of Storms, then protect it while the ritual completes.", completion = "You... you fool!  What have you done?" }
WordHunterWoW_QuestEN[26163] = { title = "Time is Short", description = "Razelikh plans to return to the Blasted Lands and overwhelm Azeroth with his demons.  Even now, he is preparing to summon his legions to eliminate us.  With these three amulets, we have the method to summon him... but no way to destroy him.\n\n<The gnome quickly draws a rune in the air, then hands it to you.>\n\nDeliver this to Grimeo at the Dark Portal, to the southeast.  He will guide you.  Quickly!  Time is short!  And so am I!", objectives = "Deliver the Discordant Rune to Watcher Grimeo at the Dark Portal in the Blasted Lands.", progress = "Do I know you, good <race>?", completion = "No, no, no... not Kasim again!  This is madness!\n\nPlease, remain quiet.  If my commander learns that I still work for the short one, do you know how quickly I will be removed from the watch?\n\n<Grimeo takes the rune from you, presses it to his chest, closes his eyes, and sighs.>\n\nI see you speak the truth.  Let us begin our business quickly, so that it may end even quicker." }
WordHunterWoW_QuestEN[26164] = { title = "The Charred Granite of the Dark Portal", description = "Kasim wants you to gather granite chips from these chunks of rock around the Dark Portal.  I don't know what he'd want rocks for, but I have my suspicions, and they're not pleasant ones.\n\nUse this pick and look for small outcroppings of rock along the edge of the portal's blast radius.", objectives = "Obtain 24 Charred Granite Chips.", progress = "Please, lower your voice.", completion = "I hope this is what the gnome wanted." }
WordHunterWoW_QuestEN[26165] = { title = "The Vile Blood of Demons", description = "Sharim wants demon blood.  Speaking personally, the stuff does not even seem like blood to me - more like liquid rot - but that is of no consequence.\n\nLuckily for you, the area around the Dark Portal is crawling with demons.  Infernals, felhounds, felguards... they've all got what you need, in copious, pustulent amounts.", objectives = "Obtain 7 bottles of Vile Demonic Blood.", progress = "Ugh, what's that smell?  Is that you, or the blood?", completion = "There is no doubt about it, you have found demon blood.\n\nKasim's requests aside, I am sure that my Watch Commander is thankful for your efforts.  They have been struggling to deal with these demon distractions for some time now." }
WordHunterWoW_QuestEN[26166] = { title = "Enhancing the Stone", description = "<Grimeo finishes packing the materials up in a neatly-wrapped package.>\n\nThat's all that the gnome asked of us.  When you see him, make sure you let him know that this task ends my debt.  I will not suffer his requests any longer.", objectives = "Bring Grimeo's Package to Kasim Sharim at the Serpent's Coil in the Blasted Lands.", progress = "You've returned, <class>.", completion = "This is sufficient.  If you see Grimeo again, you may tell him that he performed satisfactorily, but no... his debt is not yet cleared.  I will get to work on fashioning the stone knife of sealing.  There is no need for questions now.  All will be revealed in time.\n\nWhile I work, I have another task for you to complete.\n\nDon't look so upset!  This task will be fun... it involves collecting body parts." }
WordHunterWoW_QuestEN[26167] = { title = "The Amulet of Allistarj", description = "To summon our demon, we need three amulets, and the first is the Amulet of Allistarj.\n\nAllistarj himself is dead, but he locked his amulet up in a trove inside this very cave.  Along with the other amulets, this relic will give us access to Razelikh's perch.\n\n<Kasim concentrates for a moment.>\n\nThe amulet is close to the entrance.  I recommend using the teleporter.", objectives = "Obtain the Amulet of Allistarj from the Serpent's Coil in the Blasted Lands.", progress = "Allistarj left a piece of himself in that amulet.  Even now, I can sense his evil.", completion = "<Kasim examines the amulet.>\n\nHe was an archmage, I can feel it.  I will hold the amulet for you while you collect the rest." }
WordHunterWoW_QuestEN[26168] = { title = "The Amulet of Sevine", description = "The second amulet, Sevine's amulet, is in the hands of a murloc, far to the south, on a shelf that overlooks the Shattershore.  How it ended up in that murloc's possession, I cannot say, but I can state with certainty that you will find it there.\n\nBring her amulet to me, along with the rest.", objectives = "Obtain the Amulet of Sevine from Salt-Flop near the Shattershore in the Blasted Lands.", progress = "Sevine's amulet... along with the others, we can summon the Defiler.", completion = "<Kasim hefts the amulet.>\n\nA warlock... and a powerful one at that.  I will hold onto this until the time is right." }
WordHunterWoW_QuestEN[26169] = { title = "The Amulet of Grol", description = "Grol... the ogre.\n\n<Kasim laughs.>\n\nIt would seem that Grol's body no longer rests with the ogres.  His body, along with his amulet of power, is in a wrecked ship off the Shattershore, to the east.  His amulet is the last... once combined, the three will give us access to Razelikh, and therein lies our chance to stop his madness.", objectives = "Obtain Grol's Amulet from the Shattershore in the Blasted Lands.", progress = "The third amulet, from Razelikh's third lieutenant.", completion = "<Kasim clutches the third amulet.>\n\nHe was a powerful warrior, this one.  I will keep the amulet until we are ready to proceed." }
WordHunterWoW_QuestEN[26170] = { title = "The Final Ritual", description = "The knife is ready.  Loramus is present, and he knows what he must do.  I must now take the three amulets and use their enchantment to grant you access to Razelikh, the amulets' creator.\n\nI am prepared to perform the ritual on you and Loramus.  Speak with me when you are both ready.", objectives = "Speak with Kasim Sharim and participate in his ritual.", progress = "Quickly, friend.  This is but the calm before the storm.", completion = "It would seem that we are prepared to face our demon, <name>.  We have the amulet's blessing, we have the stone knife, and I alone know the demon's true name: Rakh'likh.  Together, this may be enough to defeat the Defiler." }
WordHunterWoW_QuestEN[26171] = { title = "You Are Rakh'likh, Demon", description = "Hero, listen well.\n\nFirst, we must travel to the Deathly Usher, who waits at the northern foot of the Rise of the Defiler, to our northwest.  The usher will take us to the top of the rise.  Once there, you will help me defeat Razelikh, for I fear I am not strong enough to defeat him alone.\n\nMost importantly, I need you to hold the stone knife, and do not use it until I tell you to.  The knife will trap Razelikh's soul within its new, eternal prison.\n\nIf we succeed, speak with Grimeo, the draenei.", objectives = "Speak with the Deathly Usher north of the Rise of the Defiler. Once atop the Rise, destroy Razelikh's body, then use the Stone Knife of Sealing to imprison his soul.", completion = "Loramus, resurrected!?  And then he trapped the demon inside his own body... by the Light...\n\nI see.  So this was Kasim's plan all along.  I suspected correctly, but I suppose I refused to believe it.\n\nAh, one last thing!  Kasim left one more instruction for me within his rune.  I did not understand it at first, but given the events that have taken place today, it now makes much more sense:\n\nHe asked me to let you choose from one of these." }
WordHunterWoW_QuestEN[26172] = { title = "A Bloodmage's Gotta Eat Too", description = "Contrary to popular belief, ancient and powerful bloodmages do NOT drink blood.  We eat normal food like everybody else - something which can be hard to come by in the recesses of a hostile cultist stronghold.\n\nThe ashmane boars in the central valley of the Blasted Lands are, if nothing else, convenient for eating, as their meat does not require any cooking.  Would you hunt these boars and help me replenish my ever-dwindling foodstores?", objectives = "Obtain 5 Ashmane Steaks from Ashmane Boars in the Blasted Lands.", progress = "I'm famished!  If you don't hurry, I might actually resort to drinking our reagents.", completion = "These are perfect, <name>.  I will eat well for the next several days." }
WordHunterWoW_QuestEN[26173] = { title = "Protecting Our Rear", description = "The only reason you see me standing aside Horde soldiers is because our duty outweighs our enmity... however slightly.  We have been charged with protecting the Dark Portal from unauthorized travel, and with the recent cataclysm, we are particularly susceptible to an attack.  We've already heard reports of black dragons in the area...\n\nWith my men focused on their duty, we need someone to keep the area demons in check.  Around the portal you will find three demon lieutenants.  Slay them.", objectives = "Kill Jarroc Torn-Wing, Shahandana, and Gomegaz.", progress = "You have not yet killed these demons.  <name>!  Get back to the field!", completion = "Your work is appreciated, soldier.\n\n<The commander leans in close, and whispers:>\n\n<race>... if you're still interested, I have one more small task for you..." }
WordHunterWoW_QuestEN[26174] = { title = "Watching Our Back", description = "<Watch Commander Relthorn Netherwane speaks in hushed tones.>\n\nI have orders from... higher up... that you would be suitable for.  I've seen the Horde periodically referring to a stack of papers on that barrel over there.  I'd like you to take a look at those papers and find out what it is that they're plotting.  My duty and station prevent me from such a questionable task, but a newcomer like you might be able to slip in unnoticed...", objectives = "Examine the Horde Plans at the Dark Portal without getting caught.", progress = "Did you get a look at those plans, <name>?", completion = "You're certain nobody saw you?  Good.\n\n<Netherwane listens to your recount of the information you saw.>\n\nHmph... fairly harmless stuff.  Either the Horde are foolish enough to NOT be planning something against us... or they're hiding their information better than I expected.  Either way, well done, soldier." }
WordHunterWoW_QuestEN[26175] = { title = "Surwich", description = "Other than what you've seen, the Portal's been surprisingly quiet.  There isn't much more work I can give to you, I'm afraid.\n\nIf you're looking for trouble, you might try the Gilnean fishing village to the southwest.  Surwich, I think it was.\n\nI know we're supposed to be friends with the Gilneans, but really?  Worgen?  I had enough trouble getting used to the draenei.", objectives = "Report to Mayor Charlton Connisport at Surwich in Blasted Lands.", completion = "Welcome to Surwich, <race>.  Please, have a look around." }
WordHunterWoW_QuestEN[26176] = { title = "Onward to Thelsamar", description = "You've helped us quite a bit here. If you're leaving, I'd ask you to take this status report up to Thelsamar.\n\nFollow the road just north, and you can't miss it. Mountaineer Kadrell will want the report.", objectives = "Deliver Captain Rugelfuss's Status Report to Mountaineer Kadrell in Thelsamar.", progress = "What can I do for you?", completion = "Glad to hear you've been clearing out the troggs. Let's have a look at this report, and...\n\n...Is that a beer stain?" }
WordHunterWoW_QuestEN[26177] = { title = "Feeling Crabby?", description = "Fresh crab legs have always been one of the King's favorite foods.  We have had good luck catching fresh crabs in the canals over the past few weeks.  Do you think you can lend me a hand and catch a few of them for me?  Be sure to catch them alive, they are no good to me dead, the King requires the freshest catch we can muster.", objectives = "Catch 6 Canal Crabs. Deliver them to Robby Flay in Stormwind City.", progress = "You must have fast hands!  I can't believe you caught all those crabs so quickly!", completion = "These crabs look great!  I will clean these up and make sure that the King hears about your contribution.  Thanks!" }
WordHunterWoW_QuestEN[26178] = { title = "Planning for the Future", description = "We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.\n\nThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.\n\nIf Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau'i at Moa'ki Harbor." }
WordHunterWoW_QuestEN[26179] = { title = "The Venture Co.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", objectives = "Kill 7 Venture Co. Workers for Morin Cloudstalker at Bloodhoof Village.", progress = "The Venture Co. was refused mining rights here in Mulgore, but it would seem that they do not take no for an answer. We tauren are not ones to mince words, however, and we have other ways of getting our message across.", completion = "I don't think there could be too much misinterpreting or ignoring of that signal, hm? The Venture Co. will know not to take the <race> lightly, or to be so arrogant as to believe we would allow them to steal the natural resources around us without protest." }
WordHunterWoW_QuestEN[26180] = { title = "Supervisor Fizsprocket", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", objectives = "Kill Supervisor Fizsprocket and collect Fizsprocket's Clipboard.", progress = "I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.", completion = "My anger is somewhat lessened at the news that the villain Fizsprocket is dead. I will go through his personal effects and see if there is any additional information about what the Venture Co. has planned for the future. Thank you for your efforts, <name>." }
WordHunterWoW_QuestEN[26181] = { title = "Back to Darkbreak Cove", description = "YOU MUST RETURN... TO... THE DARKBREAK COVE. ERUNAK STONESPEAKER AWAITS... YOU WITHIN.\n\nI DIE NOW....", objectives = "Speak with Erunak Stonespeaker at Darkbreak Cove in Vashj'ir.", completion = "Hello again, <class>.\n\nI felt L'ghorek die. A shame that such a magnificent being is gone.\n\nIf we do not assist Neptulon, we will all meet the same fate." }
WordHunterWoW_QuestEN[26182] = { title = "Back to the Tenebrous Cavern", description = "YOU MUST RETURN... TO... THE TENEBROUS CAVERN. ERUNAK STONESPEAKER AWAITS... YOU WITHIN.\n\nI DIE NOW....", objectives = "Speak with Erunak Stonespeaker at the Tenebrous Cavern in Vashj'ir.", completion = "Hello again, <class>.\n\nI felt L'ghorek die. A shame that such a magnificent being is gone.\n\nIf we do not assist Neptulon, we will all meet the same fate." }
WordHunterWoW_QuestEN[26183] = { title = "The King's Cider", description = "I am forever in debt to our King for all that he has done for us.  One thing I can do for him is make his favorite drink!  Lucky for us, the ingredients we need to make this wonderful drink are located right here in Stormwind City.  Apple trees can be found in every district of Stormwind.  These trees are too tall to pick the fruit from, but lucky for us the apples have fallen to the ground and are easy to retrieve.", objectives = "Obtain 12 Juicy Apples. Deliver the fruit to Robby Flay in Stormwind City.", progress = "Were you able to find enough Juicy Apples?", completion = "These will do nicely <name>.  I will get to work right away on the cider." }
WordHunterWoW_QuestEN[26184] = { title = "Wormthorn's Dream", description = "Not surprisingly, most of our citizens in Surwich did not come to the Blasted Lands for the pleasant atmosphere.  They came following the dream of an idealistic druid: Marl Wormthorn.  Wormthorn believed that the Tainted Scar could be healed, and attempted to grow it back.\n\nIt looks like he was wrong.  He grew his forest, but the land is still plagued by demons, and his great-tree is twisted and gnarled.\n\nI'm still hopeful.  Maybe if we head into the Tainted Forest and clear out some of the taint...", objectives = "Kill 5 Doomguard Destroyers, 5 Dreadlord Defilers, 5 Corrupted Darkwood Treants, and 3 Felspore Bog Lords in the Tainted Forest.", completion = "You say the demons were all worshipping the tree?\n\n<The mayor sighs.>\n\nIt is as I feared, then." }
WordHunterWoW_QuestEN[26185] = { title = "Advice from the Cenarion Circle", description = "I believe that the taint of the Blasted Lands has finally exerted its influence over my friend Wormthorn.  His experiment has failed, and his great-tree now only serves as a focus for the demons to rally around.\n\nThe tree must come down, and Wormthorn with it.  Speak with the Cenarion Observer on the other side of town; she should have some idea how to proceed.\n\n{name}: the act we are about to commit must not be made known to the townspeople of Surwich.  Morale is low enough as-is.", objectives = "Report to Cenarion Observer Shayana at the Surwich in the Blasted Lands.", completion = "While I'm surprised that Connisport is willing to go forward with his plan, I'm also relieved.  I've seen the demons rallying around Maldraz, and I share his fears." }
WordHunterWoW_QuestEN[26186] = { title = "Demoniac Vessel", description = "We need a way to get Wormthorn's attention.  Something to break him out of his trance.  Something that's guaranteed to work.\n\nThe few types of wildlife that managed to make a foothold in the Tainted Forest are, without a doubt, affected by the land's latent energies.  Your task is to collect their body parts and find a way to combine them into a vessel.  If Wormthorn's trance is druidic, or even if it is demonic, a large enough vessel of tainted animal flesh should be able to break it.", objectives = "Kill the Tainted Black Bears, Tainted Nightstalkers, and Tainted Screechers in the Tainted Forest, and try to assemble their parts into a Demoniac Vessel.", progress = "Shayana's plan is a good one.  Do you have the vessel, <name>?", completion = "<Mayor Charlton Connisport looks warily at the device you've assembled.>\n\nVery well, <name>.  We have what we need to break Marl's trance and put an end to both him and his experiment." }
WordHunterWoW_QuestEN[26187] = { title = "The Downfall of Marl Wormthorn", description = "When word gets out about what we've done... there's no saying what the citizens of Surwich will do.  They cling so closely to Wormthorn's dream...\n\n...but still, it must be done.  Take the demoniac vessel and use it on Marl Wormthorn to pull him from his trance.  Return to me when he is no more.", objectives = "Kill Marl Wormthorn at Maldraz in the Blasted Lands. You can use the Demoniac Vessel to pull him out of his trance.", progress = "Get back out there, before I change my mind.", completion = "Thank you, <name>.  I, and the people of Surwich, are in your debt.\n\nFeel free to take one of these.  While we haven't got much, we're happy to reward those that protect us." }
WordHunterWoW_QuestEN[26188] = { title = "Mazzranache", description = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I have gathered all the parts of the remedy I need to cure myself... except a flatland cougar femur.\n\nI grow weaker by the moment... please, help me.", objectives = "Bring a Flatland Cougar Femur to Maur Raincaller at Bloodhoof Village.", progress = "My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn't be able to handle a beast my grandfather was unable to defeat...\n\nDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.", completion = "Ah, thank you, <name>. Using the items you brought me, I will be able to create the remedy I need to stop the spread of the infection and, eventually, cure it completely. I owe you my life in thanks.\n\nBut I'll never forget that screeching call when Mazzranache came upon me, the blaze of color as its beak descended...\n\nBe wary on your travels." }
WordHunterWoW_QuestEN[26189] = { title = "The Angerfang Menace", description = "When we hauled up here to get away from the raptors, we put ourselves right next to a whole slew of Dragonmaw orcs!\n\nI've heard the stories in Menethil, how the Dragonmaw are even cruder barbarians than other orcs, how they strangle black dragons with their bare hands... I don't know how much of it's true, but I know we can't just let 'em sit up here in the hills.\n\nYou've got the chops for it, {name}. Head east to the Angerfang Encampment, take care of those orcs, and make sure you get their leader!", objectives = "Slay Gorfax Angerfang and 16 Dragonmaw Orcs in the Angerfang Encampment.", completion = "Good to see you back in one piece, <name>! You're quite a piece of work.\n\nI'll be tellin' Captain Stoutfist how you took care of those orcs!" }
WordHunterWoW_QuestEN[26190] = { title = "A Fisherman's Feast", description = "If there is one meal I know the King likes, it's fresh catfish.  Catfish are easy to prepare but hard to catch.  That's where you come in!  We have a good population of Gigantic Catfish here in the waters of Stormwind but the competition to catch them is intense to say the least.  I need you to figure out a way to \"acquire\" some of these fine catfish for our King.  You will find fisherman at the small canal docks around town.  You should be able to figure out the rest of the plan on your own.", objectives = "Obtain 5 Gigantic Catfish. Deliver the fish to Robby Flay in Stormwind City.", progress = "Were you able to steal the fish?", completion = "Thank you, <name>.  I will get to work scaling these for the King right away." }
WordHunterWoW_QuestEN[26191] = { title = "The Culmination of Our Efforts", description = "", objectives = "With every day, more warriors arrive at Azshara's command. Soon, Neptulon the Tidehunter will hear of our preparations, but too late to stop what we have set in motion. Our numbers will be too great and our allies too powerful. Victory is only a matter of time.\n\nIn Azshara's name." }
WordHunterWoW_QuestEN[26192] = { title = "Orphans Like Cookies Too!", description = "The orphans of Stormwind are often forgotten, but not today my friend.  The king has requested a special batch of cookies be baked and sent immediately over to the orphanage.  I was almost finished with the final batch when I ran out of confectioners' sugar.  Can you run out and get some more for me?  You should be able to find it at any of the general stores or inns inside of Stormwind.", objectives = "Obtain 4 sacks of Confectioners' Sugar. Deliver the sugar to Robby Flay in Stormwind City.", progress = "Were you able to find the Confectioner's Sugar?", completion = "These sacks look like just enough, <name>.  Can't wait to see the smiles on the orphans faces." }
WordHunterWoW_QuestEN[26193] = { title = "Defending the Rift", description = "The whispers of the elements are crowding my thoughts, {name}...\n\nThe Throne of Tides is under siege!\n\nI cannot stand idly by while the naga threaten Neptulon's realm. We must find a way to join forces with him.\n\nCaptain Taylor will escort me to the depths where I can commune directly with Neptulon.\n\nI must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides.\n\nMay the spirits see us through, {name}.", objectives = "Kill any 15 naga in the Abyssal Breach.", completion = "NO!\n\nThis is NOT over!" }
WordHunterWoW_QuestEN[26194] = { title = "Defending the Rift", description = "The whispers of the elements are crowding my thoughts, {name}...\n\nThe Throne of Tides is under siege!\n\nI cannot stand idly by while the naga threaten Neptulon's realm. We must find a way to join forces with him.\n\nNazgrim will escort me to the depths where I can commune directly with Neptulon.\n\nI must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides.\n\nMay the spirits see us through, {name}.", objectives = "Kill any 15 naga in the Abyssal Breach.", completion = "They may think they've won, but my axe and I have something to say about that!" }
WordHunterWoW_QuestEN[26195] = { title = "Who Wards The Greenwarden", description = "The greenwarden was a local legend. Many thought him a myth... the plant-man, protector of the wetlands. The night elves came here just to find him, and after they succeeded they ended up settling down to the east.\n\nThey've got a whole grove over there to watch over the greenwarden, and I've heard he's been acting up, enraged by the flooding and damage to the land.\n\nThe elves are good people. They could use the help of someone like you. If you get a chance, go tell the head druid what you've done here.", objectives = "Talk to Ferilon Leafborn at Greenwarden's Grove in the Wetlands.", completion = "Welcome to the Greenwarden's Grove, <class>. I am glad Whelgar has told you of us.\n\nIf you are able to lend us your assistance, I will be most grateful." }
WordHunterWoW_QuestEN[26196] = { title = "Longbraid the Grim", description = "The dwarves of Dun Modr fight day and night against the Dark Iron that have invaded their old home. While we cannot yet send our sentinels to risk their lives for them, we do send much needed supplies that they may sustain their vigil.\n\nIf you would, bring this package to Longbraid the Grim, north of here. His men must certainly need its contents.", objectives = "Take Ferilon's Care Package to Longbraid the Grim at Dun Modr.", progress = "Aye, what've ye got for me?", completion = "Supplies from Ferilon? Bless his heart.\n\nWe're good on food, but we're runnin' out of bullets!" }
WordHunterWoW_QuestEN[26197] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque has assembled a team of trainers to help you learn your arts.\n\nBipsi Frostflinger will help oversee your training and adjustment to life on the surface. She's waiting for you outside the tall building to the northeast.", objectives = "Meet with Bipsi Frostflinger in New Tinkertown.", completion = "<name>, isn't it? It's a pleasure to finally meet you. While you were getting cleaned up, Nevin's team told me about your escape from Gnomeregan." }
WordHunterWoW_QuestEN[26198] = { title = "The Arts of a Mage", description = "As you go on wild adventures and grow your power, you'll start to develop new connections to the arcane, granting you new spells.\n\nYou'll see. Go do it! Show me what you learn! I'll be here.", objectives = "Reach level 3 to learn Frost Nova. Once you've learned the spell, successfully cast it twice at a Training Dummy in New Tinkertown.", completion = "You picked that one up quickly. I can't wait to show you some of my other favorite tricks." }
WordHunterWoW_QuestEN[26199] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\n\"Doc\" Cogspin will help oversee your training and adjustment to life on the surface. She's waiting for you near the cluster of buildings to the north.", objectives = "Meet with \"Doc\" Cogspin in New Tinkertown.", completion = "It's good to meet you, <name>. I'm sure your time in Gnomeregan afforded you ample opportunity to practice your arts. Things are somewhat safer here, but your talents will never go to waste." }
WordHunterWoW_QuestEN[26200] = { title = "The Arts of a Priest", description = "You know, as you go out into this crazy world and get more powerful, you'll also start to discover new powers that you didn't know before.\n\nWhy don't you go out, get some more experience, and then come back and show me what you've learned!", objectives = "Reach level 3 to learn Shadow Word: Pain. Use it 5 times on training dummies in New Tinkertown.", completion = "Good work, <name>. You have a natural talent for our arts." }
WordHunterWoW_QuestEN[26201] = { title = "The Power of a Warlock", description = "I'm not at all surprised that a warlock like you fought your way out of Gnomeregan. Few people, even among the gnomes, truly understand the nature of the power we wield.\n\nAs you become more powerful, you're going to start hearing the fel voices revealing their secrets to you, teaching you new spells.\n\nI want you to go get some more experience. Once you learn something new, show me.", objectives = "Reach level 3 to learn Corruption, then cast it on a Training Dummy in New Tinkertown 5 times.", completion = "As you continue to gain power, return to me and I will teach you new spells and techniques." }
WordHunterWoW_QuestEN[26202] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. We're going to need all the help we can get to reclaim our home and rid ourselves of the troggs and irradiated gnomes. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your, uh, \"arts\".\n\nAlamar Grimm has taken up residence in the building just west of this one. He possesses powers similar to yours and can help you get adjusted.", objectives = "Meet with Alamar Grimm in New Tinkertown.", completion = "So, another one of Nevin's \"rescued\" survivors, eh? More than likely, you saved his life from the troggs down there. Did he stumble over his words when he mentioned me? The man has a healthy respect for the demonic powers we channel." }
WordHunterWoW_QuestEN[26203] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nDrill Sergeant Steamcrank will help oversee your training and adjustment to life on the surface. He's waiting for you on the small practice field across the road.", objectives = "Meet with Drill Sergeant Steamcrank in New Tinkertown.", completion = "For a <race> who has spent so much time inside Gnomeregan, you look positively fit and healthy, <name>. That's good. Before we can complete what Operation: Gnomeregan began, we're going to need more warriors like you." }
WordHunterWoW_QuestEN[26204] = { title = "The Arts of a Warrior", description = "Learning is the best way to improve. As you learn more, you'll start to discover you can do things you never realized!\n\nGo, get some more experience, and learn a new technique. Then, come back and demonstrate it on a training dummy.", objectives = "Reach level 3 to learn Charge. Locate a Training Dummy in New Tinkertown and use Charge on it.", completion = "Good work! Keep practicing your charge and you'll have an instant advantage at the start of battle." }
WordHunterWoW_QuestEN[26205] = { title = "A Job for the Multi-Bot", description = "If the multi-bot works, it will help us do all kinds of jobs that are unpleasant or dangerous for us gnomes!\n\nAfter Thermaplugg detonated his irradiator at the end of Operation: Gnomeregan, toxic clouds and ooze began bubbling up at the old airfield south of town.\n\nIf we don't get it under control, the contamination could spread to the rest of our lands. Take the multi-bot with you, and bring it close to the geysers in the green pools at the Toxic Airfield. Your bot should spring into action!", objectives = "Use the GS-9x Multi-Bot to clean up 5 Toxic Geysers at the Toxic Airfield. When you get close enough to a geyser, your GS-9x Multi-Bot will automatically begin its task.", completion = "Wow, I never expected it to work on the first trial!\n\nUh, I mean, we've succeeded! I wonder what other uses I we can find for this handy little guy." }
WordHunterWoW_QuestEN[26206] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nKelsey Steelspark, a key member of Gnomeregan Covert Ops, will help oversee your training and adjustment to life on the surface. She should be in the council tent to the northwest.", objectives = "Meet with Kelsey Steelspark in New Tinkertown.", completion = "It's good to meet you, <name>. Nevin tells me that you managed to survive the dangers in Gnomeregan by using your wits. That's exactly what we need up here. Clever minds and quick blades." }
WordHunterWoW_QuestEN[26207] = { title = "The Arts of a Rogue", description = "As you learn more and become a better rogue, you'll start to learn new abilities.\n\nOne of the most potent ones is to chain together moves in a combination, exploiting your enemy's weakness and opening up the opportunity to use stronger maneuvers.\n\nGo, get some more experience and figure out how to do it. Once you can, come back here and try it out.", objectives = "Reach level 3 to learn Eviscerate, then find a training dummy in New Tinkertown and practice using Eviscerate 3 times.", completion = "I'm not surprised to see you're such a quick study. I look forward to showing you more of our tricks of the trade." }
WordHunterWoW_QuestEN[26208] = { title = "The Fight Continues", description = "The dwarves of Ironforge kindly took us in when the trogg invasion and radiation forced us to leave Gnomeregan for the first time. But even the kindness of friends can't quell the longing for home.\n\nI sent out a call for brave gnomes and other members of the Alliance to help us regain control of Gnomeregan and defeat the usurper Thermaplugg once and for all.\n\nWe weren't able to achieve everything Operation: Gnomeregan set out to do, but Thermaplugg is on the run and we're closer to home than ever.", objectives = "Watch the holo-table in front of High Tinker Mekkatorque to learn about Operation: Gnomeregan.", progress = "Thermaplugg's defeat is a certainty, but that irradiator has bought him time to regroup.", completion = "Even now, only the S.A.F.E. teams dare to venture far into the city to search for survivors. Meanwhile, Thermaplugg has sent one of his followers, Crushcog, to distract us and buy time for him to dig in." }
WordHunterWoW_QuestEN[26209] = { title = "Murder Was The Case That They Gave Me", description = "Here's the deal, kid, we've got a full-blown murder on our hands. Double homicide... Single horse... icide.\n\nWorse yet, we're in Westfall. I could throw a rock behind me and hit a dozen hobos with motive enough to want to wipe these people (and horse) out.\n\nNow I don't know who did this and I sure don't appreciate having to come to this dump to investigate the deaths of a couple of squatters, but I'll be damned if I don't find the perp. You want to help? Go talk to some bums. The hobo... knows.", objectives = "Speak to the various homeless people occupying the Jansen Stead to gather clues about the Furlbrow murders.", progress = "Anything yet?", completion = "Gnolls and murlocs? Horse poopy, pal! Gnolls and murlocs didn't kill these people. I've seen what gnolls and murlocs do to people that they kill and this... isn't it. Too pretty. Too... perfect.\n\nFurthermore, the Furlbrow's had been squatting on this farm for 5 years. No, whoever wiped them out had a reason. This is murder, plain and simple and we're gonna get to the bottom of it..." }
WordHunterWoW_QuestEN[26210] = { title = "Gammerita, Mon!", description = "Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.\n\nMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.\n\nFind Gammerita and get my lure out of her stomach.", objectives = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.\n\nKatoom mentioned that Gammerita hangs out on the coast with the other turtles.", progress = "Did you get it yet?", completion = "MON! This is fantastic! With my best lure and the snapjaw population down, the fish will pile up." }
WordHunterWoW_QuestEN[26211] = { title = "Snapjaws, Mon!", description = "Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.\n\nDo me and the people of Revantusk Village a service and kill em, mon.\n\nKill the whole lot of em!", objectives = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 10 Saltwater Snapjaw turtles. Return to him when you have completed this task.", completion = "Oh, mon! I can't thank you enough! Hopefully this here fishing pole will be reward enough for the job." }
WordHunterWoW_QuestEN[26212] = { title = "Lard Lost His Lunch", description = "Lard was at secret special spot having picnic when ugly mean Vilebranch hit Lard wit da big stick. Lard run back to Revantusk but forget Lard lunch. Lard hungry. Maybe you go back to secret special spot and get Lard lunch? Lard scared. Go nort! Island der to da nort is da secret special spot.", objectives = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\n\nLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.", progress = "<Lard rubs his enormous belly.>\n\nLard so hungry.", completion = "<Lard takes the huge haunch of meat from you and stuffs it in his face.>\n\nDis hit da spot! Tanks little one.\n\nLard make you special picnic basket for help Lard." }
WordHunterWoW_QuestEN[26213] = { title = "Hot On the Trail: The Riverpaw Clan", description = "Seeing as how we have no other leads, we may as well chase down the information you got.\n\nThere are a couple of Riverpaw gnoll camps in the area. Track them down and search for clues. Bring back anything that you might find. Isolate your search to the Riverpaw gnolls and scouts.", objectives = "Recover the Riverpaw Gnoll Clue.", progress = "Find anything on the gnolls?", completion = "Is this supposed to be some kind of joke, because I'm not laughing. Bits and pieces of red cloth? What the hell is this supposed to mean?" }
WordHunterWoW_QuestEN[26214] = { title = "Hot On the Trail: Murlocs", description = "As pointless as I think that this is going to be, we need to investigate all of our leads.\n\nI need you to head out to the Longshore, west of here, on the coast, and shake up some murlocs. Try to find a clue or some info that can help shed some light on the murders.\n\nReturn to me if you get lucky, rookie.", objectives = "Recover the Murloc Clue.", progress = "How goes the murloc hunt?", completion = "Nice find, rookie. I think I have a stack of these on my desk back at the station. We're basically back to square one. What do we know? Someone that likes to write fiction about the past sent the Furlbrows a letter.\n\nLooks like we got ourselves a real history... mystery." }
WordHunterWoW_QuestEN[26215] = { title = "Meet Two-Shoed Lou", description = "Looks like we got ourselves a real \"whodunit\" here, rookie. Unfortunately, it looks like the locals aren't willing to talk and the clues you got off the gnolls and murlocs are damn near worthless. We're going to have to initiate plan... be on the lookout for Two-Shoed Lou.\n\nTwo-Shoed Lou is an old confidential informant of mine who, ironically, makes his home at the Furlbrow's old pumpkin farm. Head west to the farm and find out what Lou knows.\n\nIf he gives you any guff tell him that Horatio sent you.", objectives = "Speak to Two-Shoed Lou at the Furlbrow's Pumpkin Farm in Westfall.", completion = "Look, we ain't got no room for no more...\n\nHoratio sent you? Right then... um, how can I help you?\n\nHe's not here is he? Heh, he knows I wasn't hidin' from him, right? Was just tryin' to lay low and all that, ya know?" }
WordHunterWoW_QuestEN[26216] = { title = "Stoleways", description = "", objectives = "You will be able to choose one of these rewards:" }
WordHunterWoW_QuestEN[26217] = { title = "Overboard", description = "", objectives = "" }
WordHunterWoW_QuestEN[26218] = { title = "Long Shot", description = "", objectives = "" }
WordHunterWoW_QuestEN[26219] = { title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Darkbreak Cove, a giant underwater cavern bordering the abyss.\n\nThis time we're ready. The gnomes have been engineering a beauty for us back at Stormwind, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Pincer X2 pulls up to dock beside the ship, make your way on board and help out however you can. We'll be right behind you.", objectives = "Board the Pincer X2 from Voldrin's Hold and aid in securing Darkbreak Cove.", completion = "Vell done, Private <name>.\n\nThe cavern is ours, but the beast escaped. Should it raise it's ugly head again, ve vill make with blastink it out of the vater." }
WordHunterWoW_QuestEN[26220] = { title = "Everything Is Better with Bacon", description = "Feeding a hungry orc army is never an easy task.  Luckily for us, we have a good supply of mature swine meat from the pig farms and surrounding areas south of Orgrimmar.  Do me a favor and slaughter some of those pigs for their delicious belly meat.  I will slice it up and make bacon for the troops' breakfast.", objectives = "Slaughter Mature Swine south of Orgrimmar and bring me back 6 of their Swine Bellies. I will be waiting for you here in The Drag.", progress = "Have you finished slaughtering the swine?", completion = "Good work, <name>.  These will do nicely." }
WordHunterWoW_QuestEN[26221] = { title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Tenebrous Cavern, a giant underwater cave bordering the Abyssal Breach.\n\nThis time we're ready. The goblins have been proving their worth by making a vicious machine for us back at Bilgewater Harbor, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Verne pulls up to dock beside the ship, make your way on board and find a way to make yourself useful. We'll be right behind you.", objectives = "Board the Verne from The Stygian Bounty and aid in securing Tenebrous Cavern.", completion = "Well done, <class>.\n\nThat slippery beast got away! I'll be making a few upgrades. It won't be so lucky next time." }
WordHunterWoW_QuestEN[26222] = { title = "Scrounging for Parts", description = "There's just too much to do around here, and too few gnomes on their feet to help! The high tinker has asked me to start converting some of our old bots and parts from Operation: Gnomeregan. I hope to have a new line of multi-bots ready for a field test soon!\n\nI don't suppose you'd have some time to help, do you? There are all kinds of parts scattered around. Pick up anything you find and bring it back to me. You never know what could turn out to be useful!", objectives = "Bring 7 Spare Parts to Engineer Grindspark in New Tinkertown.", progress = "Did you get those parts?", completion = "These are fantastic! Let's see what we can put together. Would you be interested in testing out the prototype once I'm done?" }
WordHunterWoW_QuestEN[26223] = { title = "Stalking the Stalkers", description = "Many brave trolls have been lost to the harsh wilds of the Hinterlands, {race}. The Silvermane wolves are one of the biggest threats to our hunters. They lay in wait, hiding amongst the bushes and landscape, then strike out when the opportunity presents itself.\n\nThis type of ferocity will not go unchecked!\n\nYou must think like the Silvermane. Stalk the stalkers! Slay them all!", objectives = "Kill 8 Silvermane Stalkers.", completion = "A job well done, <race>. The Revantusk thank you for your contribution." }
WordHunterWoW_QuestEN[26224] = { title = "Hunt the Savages", description = "Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts.\n\nKill every savage owlbeast you see, {race}. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.", objectives = "Kill 10 Savage Owlbeasts.", completion = "You have proven a worthy ally to the Revantusk, <name>. Well done." }
WordHunterWoW_QuestEN[26225] = { title = "Pupellyverbos Port", description = "You there! Did you know that strewn across the northern beach are tens, if not hundreds, of bottles of fine wine?\n\n...well, now you do!\n\nI'd be out there gathering them by the armload, if those turtles weren't out to get me. They crave my blood, I swear.\n\nSo I'll pay you then. Bring me 12 bottles of Pupellyverbos Port and I'll \"purchase\" it from you, {class}.", objectives = "Collect 12 bottles of Pupellyverbos Port.", progress = "Do you have 12 bottles? I know how to count, you know!", completion = "Perfect! I don't know where I'd get this stuff if it wasn't for drunk humans repeatedly crashing their ships.\n\nNormally I'd settle down and get ready to haggle with you for an hour, but you're in luck; I'm too eager to crack these open. Cheers!" }
WordHunterWoW_QuestEN[26226] = { title = "Crawfish Creole", description = "There are a number of small lakes scattered around Orgrimmar.  These lakes fill up with crawfish every year.  That's where you come in, {name}.  I need you to catch some of those delicious crustaceans and return to me when you are done.  Assuming your catch is successful, our Horde army will feast tonight.", objectives = "Catch 10 Muddy Crawfish in Orgrimmar. Deliver the crustaceans to Marogg when you are done.", progress = "Were you able to dig up some crayfish?", completion = "Ugh, I never liked cooking these slimy things.  Thanks for the help <name>." }
WordHunterWoW_QuestEN[26227] = { title = "Careful, This Fruit Bites Back", description = "Sometimes the troops want something sweet to eat.  I don't always give them what they want but this time, I am going to make an exception.  I am sure you have seen the local cactus that grows here in Orgrimmar.  These cactus produce a tasty treat called prickly pear fruit.  The trouble is the fruit are covered in spines!  Watch your hands and bring me back a handful of that fruit.", objectives = "Retrieve 8 pieces of Prickly Pear Fruit. Deliver the fruit to Marogg in Orgrimmar.", progress = "Were you able to find enough fruit?", completion = "Let me see your hands... Aha!  Your not any better at collecting these wretched things than I am!" }
WordHunterWoW_QuestEN[26228] = { title = "Livin' the Life", description = "Listen, I really shouldn't be talkin' to you, but I owe Horatio a favor or two. I don't really know nothin' about what happened to the Furlbrows, but I might be able to point you in the right direction.\n\n<Lou hands you a large crate.>\n\nThat crate used to be my home before I struck it rich. Now I'm livin' the life every hobo dreams of!\n\nRight, so you take that there livin' crate and head to the Jangolode Mine, southwest of here. Head to the back of the mine and once there, hide in the crate. ", objectives = "Use Two-Shoed Lou's Old House at the back of the Jangolode Mine in Westfall.", completion = "<Lou puts his hands to his ears and starts talking loudly.>\n\nSTOP! STOP! STOP! I don't wanna hear it! I don't wanna know and I don't care! That kind of information is liable to get you killed 'round these parts.\n\nI got one more bit of information for you and then we're done!" }
WordHunterWoW_QuestEN[26229] = { title = "\"I TAKE Candle!\"", description = "Back before those damned kobolds gave me a permanent limp I used to be William Pestle's number one candle supplier. Hell, I even came up with the line \"I TAKE CANDLE!\" Yea, that was me. Kobold would say \"You no take candle!\" and I'd just respond \"I TAKE CANDLE!\" and then bash their brains in!\n\n<Jimb drifts off for a second.>\n\nGood times... The best times.\n\nNow? Can't even use the bathroom without assistance. You want to help me? Kill me some kobolds. You'll find a good load of 'em in the nearby mine.", objectives = "Kill 12 Kobold Diggers.", progress = "I just want those kobolds dead. Dead!", completion = "Oh SWEET justice! Killin' those kobolds won't make me walk like a normal person and it sure won't get me a job, but damn does it feel good.\n\n<Jimb reaches into a crusty old sack.>\n\nHere, I think I got somethin' for you from my kobold huntin' days. Maybe you can put it to good use." }
WordHunterWoW_QuestEN[26230] = { title = "Feast or Famine", description = "Life in Westfall's hard, sonny! Every day is a struggle. We can sometimes go weeks without a decent meal. That's why it's important that we all help each other out. Maybe you can lend a hand, eh? I'm making dirt pies and need some ingredients.\n\nGet me some fresh dirt from the pumpkin patch out front and a bundle of coyote tails. You'll find coyotes wandering around in the wilds of Westfall.\n\nGet moving! We got mouths to feed.", objectives = "Collect 6 Coyote Tails and 5 handfuls of Fresh Dirt.", progress = "Dirt pies don't make themselves - usually.", completion = "Just smellin' you comin' got my stomach rumblin'! We're gonna eat like kings tonight!" }
WordHunterWoW_QuestEN[26231] = { title = "Boarding Party", description = "", objectives = "You will be able to choose one of these rewards:" }
WordHunterWoW_QuestEN[26232] = { title = "Lou's Parting Thoughts", description = "A couple of thugs recently showed up at the farm, causin' all kinds of trouble. I don't know where they came from or who they're working for, but I KNOW they're bad news. I may have overheard 'em talkin' 'bout subjects that might interest you.\n\nIf you're interested, you'll find the thugs back behind the farmhouse. If you get caught or killed, I don't know you. Never seen ya!\n\nGood luck, kid.", objectives = "Eavesdrop on the Thugs out behind the farmhouse at Furlbrow's Pumpkin Farm in Westfall.", completion = "We're dealing with an organization here, rookie. You don't just off the richest bum in Westfall in broad daylight and leave no witnesses. Someone with a lot of power is behind these murders. What have you learned so far?" }
WordHunterWoW_QuestEN[26233] = { title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the trolls of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the trolls keep it stored in barrels near their structures.  Retrieve these barrels of Darkspear rice for me and I should be able to finish up. ", objectives = "Retrieve 6 Barrels of Darkspear Rice. Deliver the rice to Marogg in Orgrimmar.", progress = "Were you able to acquire the rice?", completion = "I see you are a skilled thief as well, <name>.  Don't worry, we will return the rice once we are done... or not." }
WordHunterWoW_QuestEN[26234] = { title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the goblins of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the goblins keep it stored in barrels near their structures.  Retrieve these barrels of Kezan rice for me and I should be able to finish up. ", objectives = "Retrieve 6 Barrels of Kezan Rice. Deliver the rice to Marogg in Orgrimmar.", progress = "Were you able to acquire the rice?", completion = "I see you are a skilled thief as well, <name>.  Don't worry, we will return the rice once we are done... or not." }
WordHunterWoW_QuestEN[26235] = { title = "Even Thieves Get Hungry", description = "We have had a problem with thieves stealing our infantry rations here in Orgrimmar for the last couple of weeks.  I recently received some intelligence of where these crimes are taking place.  Anywhere you see piles of crates and supplies, there are likely to be thieves nearby.  I need you to hunt these thieves down and recover the stolen rations.  Return to me when you are done.", objectives = "Recover 3 Horde Infantry Rations. Deliver them to Marogg in Orgrimmar.", progress = "Were you able to recover the rations?", completion = "Nice work <name>!  I will see that these rations are returned to the troops immediately." }
WordHunterWoW_QuestEN[26236] = { title = "Shakedown at the Saldean's", description = "So what do we know so far? We need to follow the clues.\n\nOver at the Jansen Stead you found a water-soaked letter and some scraps of red cloth. Here at the Furlbrow's you overheard a conversation between some shadowy figure and an ogre mage. You also got a confession to the murder from a bunch of thugs - whom you then killed.\n\nSomething isn't adding up, rookie.\n\nThere's an old couple, southeast of here, at the Saldean's Farm. Head over there and speak with Farmer Saldean. Find out what he knows.", objectives = "Speak with Farmer Saldean at Saldean's Farm in Westfall.", completion = "Horatio Laine? That man is a scumbag. Dirty as my underwear.\n\nListen, friend, I don't often give out advice like this, but you seem like a good man. GET OUT OF WESTFALL. You're already in way over your head. All you're doing now is putting your neck on the chopping block." }
WordHunterWoW_QuestEN[26237] = { title = "Times are Tough", description = "Times are tough, brother. With the downtrodden masses of Stormwind migrating into Westfall, resources are stretched as thin as they've ever been. The people are restless and in need of help.\n\nOur own farmhouse has been serving as a halfway house for years. Salma does the best that she can to keep our guests alive, but sometimes the watchers get 'em. Watchers are those twisted abominations roaming my fields - a little present left behind by the Defias, before they were driven off. Help us!", objectives = "Kill 10 Harvest Watchers.", completion = "Thank you, brother. You've done Salma and I a great service and I promise that it won't soon be forgotten. I don't have much money, but you're welcome to what I do have." }
WordHunterWoW_QuestEN[26238] = { title = "The Savage Dwarves", description = "The Horde has done much for us Revantusk, and we're no freeloaders. With the other forest troll tribes pushed back, we're striking out to claim more land in the name of the Horde.\n\nBut now the Wildhammer dwarves are getting in our way. If it's a war they want, it's a war they'll get... and I don't plan to lose a war to creatures half my height.\n\nGet out there and kill me some dwarves.", objectives = "Kill 10 Wildhammer Warriors or Wildhammer Shaman.", completion = "That will show the Wildhammer to stay away from our lands!\n\nCrazy dwarves should've stayed in the mountains..." }
WordHunterWoW_QuestEN[26239] = { title = "<PH>Wildhammer Totems", description = "", objectives = "" }
WordHunterWoW_QuestEN[26240] = { title = "Stomp To My Beat", description = "Our warriors are out there fightin' hard to kill them nasty Wildhammer dwarves, so we can be safe back here at the village. It's only right we do what we can to support them.\n\nA good beat's what every troll needs to do his best in a fight. The poundin' rhythm of the drums drivin' you to hit harder, callin' the spirits to watch over you. Take my drums to the battlefield wit' ya. Play 'em for our warriors, and let 'em show the Wildhammer who owns these lands!", objectives = "Use the Revantusk War Drums on 6 Revantusk Warriors.", completion = "Makes all the difference, doesn't it? That'll teach those dwarves a lesson." }
WordHunterWoW_QuestEN[26241] = { title = "Westfall Stew", description = "Hello, dear. Welcome to our home. Hmm, you don't look like you're homeless. Have you come to help us? If so, you're just in time! I'm planning dinner for the young ones and need a few simple ingredients.\n\nIf you could get me some okra, goretusk flanks and stringy fleshripper meat I can make my famous Westfall stew! You'll find all of the ingredients near our farm. Just be careful of the harvest watchers. They are merciless killers.", objectives = "Collect 6 Okra, 6 Stringy Fleshripper Meat and 6 Goretusk Flanks.", progress = "Food will be ready as soon as I have all of the ingredients! Hurry!", completion = "Bless your heart, dear. These poor orphans haven't had a hot meal in days.\n\nIt looks like we will have enough left over to help feed many more of the homeless of Westfall." }
WordHunterWoW_QuestEN[26242] = { title = "Deepholm, Plane of Earth", description = "", objectives = "" }
WordHunterWoW_QuestEN[26243] = { title = "The World Pillar", description = "The pillar in this room holds up more than just the Temple of Earth.\n\nThis entire plane of existence will soon collapse into our world if we fail to restore it.\n\nThe time to act will come soon, {name}.  But first you must listen to what I have to tell you.", objectives = "Ask Maruut Stonebinder about the World Pillar." }
WordHunterWoW_QuestEN[26244] = { title = "The Earth Claims All", description = "We're in the plane of earth, {name}.  Everything is absorbed by the land eventually.\n\nThe Storm's Fury will soon be turned to dust and we won't be able to gain any insight from its remains.\n\nGo and destroy the elementals that are dismantling the ship.  We're only delaying the inevitable, but we need to buy ourselves some time if we're to track down all the pieces of the World Pillar.", objectives = "Destroy 5 Deepstone Elementals.", completion = "You did what was necessary, <name>.  I can tell you're the sort of <class> I'll get along with well." }
WordHunterWoW_QuestEN[26245] = { title = "Gunship Down", description = "The Archstone was being transported inside a flying Horde gunship called the Storm's Fury.\n\nThe airship crashed south of here and our scrying has revealed the Archstone's no longer on it.\n\nSearch the ship for clues related to what might've happened.", objectives = "Search for clues at the Storm's Fury Wreckage in Deepholm.", completion = "The clues point to an obvious conclusion.  Too obvious perhaps." }
WordHunterWoW_QuestEN[26246] = { title = "Captain's Log", description = "<You leaf to the final, interrupted entry.>\n\n...approaching the Temple of Earth at 300 knots and commencing landing maneuvers according to new route.  We've made note of a low pressure system in the north and redrawn our...\n\nBLOOD AND THUNDER!  ALLIANCE SCUM APPROACH!!", objectives = "Bring the Captain's Log to Maruut Stonebinder at the Temple of Earth in Deepholm.", completion = "Why would the Alliance attack the Horde just as they're about to deliver a fragment of the World Pillar to us." }
WordHunterWoW_QuestEN[26247] = { title = "Diplomacy First", description = "The Earthen Ring is a neutral organization, {name}.  We cannot pick sides in the war between the Horde and the Alliance.\n\nLook around you -- our members come from all backgrounds.  Our mission would be compromised should racial tensions be put above our goal.  Let's try to keep this under wraps until we have more information.\n\nWe must not jump to conclusions just yet.  I'll send you and one of our new members to look for the Alliance gunship.\n\nFind out what you can without dragging us into the conflict.", objectives = "Meet Stormcaller Mylra aboard the Alliance Gunship.", completion = "Oi, <name>!  I was told I'd have company soon." }
WordHunterWoW_QuestEN[26248] = { title = "All Our Friends Are Dead", description = "Something's wrong here, {name}.\n\nThe ship's crew has been slain.  Yet there is no bloodshed or damage to the ship's structure.\n\nThis was not the Horde's doing.\n\nWe will find the answers we seek by speaking to the spirits of the dead.  They have not yet left this world.\n\nTake this totem and place it near the corpses of the fallen.  You will have a few seconds to listen to their last few thoughts.\n\nBeware, however!  There is no telling how the spirits of the dead will react to our prodding.", objectives = "Use the Spirit Totem on the corpses of 6 Slain Crew Members.", progress = "The spirits always have something to say to those who will listen.", completion = "We were bound to run into the Twilight's Hammer sooner or later, <name>.  If they're behind this, it's quite likely that the World Pillar fragment is in their possession." }
WordHunterWoW_QuestEN[26249] = { title = "The Admiral's Cabin", description = "It's possible we'll find further clues inside the admiral's cabin. You will find it directly below us.\n\nSee if there are any survivors or information that will lead us closer to the World Pillar fragment.  Be careful, {name}.  Whoever got the crew might still be out there.", objectives = "Look for clues in the admiral's cabin of the Alliance Gunship.", completion = "This ship is filled with rats..." }
WordHunterWoW_QuestEN[26250] = { title = "On Second Thought, Take One Prisoner", description = "It's not too late, {name}.  The cultists are probably still here.\n\nGo below decks, find out who's in charge and subdue them.\n\nWe will obtain answers to our questions, one way or another.", objectives = "Subdue Mor'norokk the Hateful at the Alliance Gunship in Deepholm.", completion = "Oi, this was a heavy one!  He nearly broke me gryphon's back!\n\nAre you ready to interrogate the ogre, <name>?" }
WordHunterWoW_QuestEN[26251] = { title = "Take No Prisoners", description = "It looks like the Twilight's Hammer's still on the ship.  Go below decks and take them out.\n\nBe careful, {name}.  I've a feeling they're not here for a spiritual retreat, if you know what I mean.", objectives = "Slay 6 Twilight Saboteurs.", completion = "Well done, <name>.  The Twilight's Hammer is an evil that we must fight anywhere we find them." }
WordHunterWoW_QuestEN[26252] = { title = "Heart of the Watcher", description = "You have found what appears to be the heart of a harvest watcher.\n\nFrom the sound being emitted by the device you can tell that it's still fully functional. Perhaps you should return it to Farmer Saldean.", objectives = "Return the Harvest Watcher Heart to Farmer Saldean at Saldean's Farm.", progress = "What have you got there, <name>?", completion = "Is that... Is that the heart of one of the watchers? I've heard stories about using one of these to power up a watcher for personal use. Of course I'm really in no shape to try such things myself." }
WordHunterWoW_QuestEN[26253] = { title = "Preserve the Evidence", description = "", objectives = "" }
WordHunterWoW_QuestEN[26254] = { title = "Some Spraining to Do", description = "Hop on, {name}.  Let's see what Mr. Ogreface has to say for himself.\n\nDon't be shy, Stormbeak's only ever dropped a passenger a couple of times before.", objectives = "Jump on Stormbeak and watch Mor'norokk's interrogation.", progress = "Yes, <name>?", completion = "We have our answers, <name>.  Let's report back." }
WordHunterWoW_QuestEN[26255] = { title = "Return to the Temple of Earth", description = "You must get word back to the others at the temple.  Chances are, the fragment is already getting moved to a more secure location.\n\nTell Maruut what you know.  I'm going to do a little investigating about this Twilight Council in the meantime.", objectives = "Speak to Maruut Stonebinder at the Temple of Earth in Deepholm.", completion = "We must investigate your findings further, but we must not lose track of the fragment." }
WordHunterWoW_QuestEN[26256] = { title = "Bleed the Bloodshaper", description = "The Twilight's Hammer are wielding foul magic here, {name}.  They animate and energize the remains of Deathwing's blood, so that instead of drying out and disappearing it thrives and becomes more abundant.\n\nTake out one of the bloodshapers, see if they have any clues as to where we can find this \"forgemaster.\"", objectives = "Obtain the Twilight Orders from one of the Twilight Bloodshapers at Deathwing's Fall.", progress = "We must make haste if we're to rebuild the World Pillar, <name>.", completion = "They're keeping slaves here?  We ought to free them regardless, but perhaps they might also aid us in finding the forgemaster." }
WordHunterWoW_QuestEN[26257] = { title = "It's Alive!", description = "From what I've heard, all you really need to do is find a suitable harvest golem and drop in the heart. Once you've done that you should be able to take full control of the creature.\n\nI think there's a whole field of overloaded harvest golems west of here, at the Molsen Farm. Look for the arcs of electricity.\n\nShould you manage to get it working, use the golem to destroy the energized harvest reapers at the old Molsen farm. Those monsters are much more destructive than the ones on our farm.", objectives = "Use the Harvest Watcher Heart on an Overloaded Harvest Golem and then use the Overloaded Harvest Golem to kill 25 Energized Harvest Reapers.", completion = "It actually worked? That's incredible, <name>. Hopefully that takes care of the harvest golem problem here in Westfall." }
WordHunterWoW_QuestEN[26258] = { title = "Deathwing's Fall", description = "The Twilight's Hammer involvement in the disappearance of the World Pillar fragment makes complete sense.  Let us hope that we can act swiftly enough to recover it.\n\n<Maruut places his hand on your shoulder.>\n\nI've established a spiritual bond with you.  We should be able to communicate while you remain in Deepholm.\n\nGo to Deathwing's Fall to the southeast and investigate the Twilight's Hammer operation there.", objectives = "Go to Deathwing's Fall in Deepholm.", completion = "This must be where the world pillar fragment was brought.  Let's have a closer look." }
WordHunterWoW_QuestEN[26259] = { title = "Blood of the Earthwarder", description = "When Deathwing escaped to Deepholm, his corruption was extreme, but perhaps not yet absolute.\n\nThe cultists at Deathwing's Fall harvest and shape the corrupted blood he left behind into living organisms to draw from their power.\n\nWhat if a trace of the Earthwarder's essence remains?  After all, Neltharion was the aspect of earth before he was the aspect of death.\n\nGather samples from the living blood the cultists have created and we'll see if any trace of the Earthwarder remains.", objectives = "Gather 5 samples of Blood of Neltharion from Living Blood at Deathwing's Fall.", progress = "You return, <name>.  Did you obtain the blood?", completion = "There is still great power present in his blood, <name>.  I can sense it even now.\n\nYet there is also much corruption.  I am not sure we can salvage the Earthwarder's essence from this." }
WordHunterWoW_QuestEN[26260] = { title = "The Forgemaster's Log", description = "Go to the tower the slave spoke of.  You should find it on the northeastern end of the camp.\n\nIf we can act fast enough we might be able to eavesdrop on the forgemaster's meeting.", objectives = "Find the Forgemaster's Log at Deathwing's Fall in Deepholm.", completion = "There is an entry for an upcoming meeting at the Upper Silvermarsh.\n\nThis must be where the Forgemaster is." }
WordHunterWoW_QuestEN[26261] = { title = "Question the Slaves", description = "According to the orders you found, there is a key inside the tent in the southeastern end of Deathwing's Fall.\n\nObtain it and free the slaves in the quarry to the south.", objectives = "Obtain the Twilight Slaver's Key and free 6 Enslaved Miners.", completion = "Let us find this journal.  We're getting close to the World Pillar fragment, I can sense it." }
WordHunterWoW_QuestEN[26262] = { title = "Twilight Armaments", description = "", objectives = "" }
WordHunterWoW_QuestEN[26263] = { title = "Thornar Thunderclash", description = "We've been trying to take out the commander of the Wildhammer encroaching on our lands, but we've had no luck.\n\nThornar Thunderclash sits in the safety of his command post, his voice booming across the battlefield to rally the dwarves. We're thinking he needs to be quieted.\n\nCut Thornar down and we can clean up the rest of this skirmish with no problem.", objectives = "Kill Thornar Thunderclash.", completion = "Well done, mon. A fine hero of the Horde you are." }
WordHunterWoW_QuestEN[26264] = { title = "What's Left Behind", description = "Most of us have seen the sickly and deranged gnomes suffering from exposure to the poisons and radiation of Gnomeregan. Eventually, they will devolve further, until they become mindless, but mostly harmless, puddles of toxic sludge.\n\nMy research suggests that we may even be able to restore them from this state. Go to the Toxic Airfield to the south, subdue the toxic sludge I told you about, and bring back the possessions of the gnomes they once were.", objectives = "Retrieve 6 Recovered Possessions from Toxic Sludges at the Toxic Airfield.", progress = "Were you able to recover the belongings of any of the irradiated gnomes?", completion = "I can't wait to give this new technology a try! We've lost more gnomes to radiation than we can count. It's time to turn that around!" }
WordHunterWoW_QuestEN[26265] = { title = "Dealing with the Fallout", description = "Tock Sprysprocket has some crazy theory about these toxic sludges being the last remnants of gnomes, so my men have orders not to engage them for now.\n\nHowever, the Toxic Airfield, just south of us, is teeming with living contamination. They are elementals composed of contaminated water and other toxic materials. Left unchecked, they'll overrun the town. Will you help us dispose of them?", objectives = "Destroy 6 Living Contaminations at the Toxic Airfield.", progress = "Were you able to clear away any of the contamination?", completion = "What a relief! Thank you for your help. I hope that gadget Engineer Grindspark was working on helps get the airfield cleaned up permanently." }
WordHunterWoW_QuestEN[26266] = { title = "Hope for the People", description = "About four years ago, in the dead of the night, a little girl walked right into our farmhouse and collapsed on the floor. Nobody had a clue as to her identity. The poor little thing had no recollection of who she was or where she came from - truly a lost soul.\n\nSoon after, we adopted the little girl and named her Hope - for that is what she represented.\n\nShe is now a young lady, caring for the destitute and homeless of Westfall. Take my Westfall stew to her at Sentinel Hill, south of here.", objectives = "Take the Westfall Stew to Hope Saldean at Sentinel Hill.", progress = "Good day sir. How may I serve you?", completion = "I smell Westfall stew! Mother sent you!?" }
WordHunterWoW_QuestEN[26267] = { title = "Skulk Rock Clean-Up", description = "Years ago, there used to be a Horde base deep within Skulk Rock. It's been abandoned since then, but it's still prime territory, worth reclaiming.\n\nThe problem is, it's full of oozes by now. They're nasty things... mindless, corrosive, eat anything they find.\n\nI need someone brave to go to Skulk Rock and get rid of those slimes. Are you brave enough, {name}?", objectives = "Kill 10 Jade Oozes.", completion = "It's good to see you back... and not missing any limbs, either." }
WordHunterWoW_QuestEN[26268] = { title = "Skulk Rock Supplies", description = "I was at Skulk Rock during the second war. I was young, years before I met my mate, and I still remember the chaos when the Alliance attacked us. We fled with the orcs, without any time to gather our belongings.\n\nIt was all left behind. Skulk Rock is still full of our old supplies. We could use them here at the village... and more importantly, the Wildhammer shouldn't get their filthy hands on them.", objectives = "Collect 5 Ooze-Coated Supply Crates.", progress = "How many crates did you find?", completion = "They're still intact! There's a lot of memories in these crate. Let's see what we've got in the first one...\n\nHey, banana bread! And it's still fresh!\n\nHere, mon, I'll take this and you can pick something else." }
WordHunterWoW_QuestEN[26269] = { title = "The Green Hills of Stranglethorn", description = "One page!  I only need one more page!\n\nMaster Nesingwary's novel ran into a bit of an... accident <Barnil shoots an accusing glance over at Spanks>... and we misplaced some of the pages.\n\nI've been asking your fellow adventurers to look for the missing pages, and they've been quite helpful, but one page still eludes me.\n\nI'm sure you're awfully busy with other matters, but while you're out in the jungle, would you mind looking for it?", objectives = "Find Page 14 of the Green Hills of Stranglethorn.", progress = "Have you found it?  I'd hate to return an almost-finished book back to Hemet.", completion = "You've certainly saved me a heap of trouble, <name>!  I can't thank you enough.  It shouldn't be long now until we see Master Nesingwary's book in libraries throughout the world!\n\nI'll leave a copy of the book right here, if you ever want to take a peek at the finished product.  Thanks again, <name>!" }
WordHunterWoW_QuestEN[26270] = { title = "You Have Our Thanks", description = "It's been many years since anyone has offered to lend us aid, {name}. Had you not come along, we might not have made it through the coming winter. You have proven yourself to be a selfless individual - a person that we can trust. I only wish we had something of value to offer you.\n\nWhile I have no information to assist you in your crusade to bring the Furlbrow's murderer to justice, perhaps my wife can help. Speak to Salma inside and she will tell you what you need to know before you leave.", objectives = "Speak with Salma Saldean at the Saldean's Farm in Westfall.", completion = "Of course, dear. Our little girl works at Sentinel Hill and is very close with the homeless of Westfall. Perhaps she has overheard something. Before you go, let me wrap up the Westfall Stew and tell you a little bit about our dear little girl." }
WordHunterWoW_QuestEN[26271] = { title = "Feeding the Hungry and the Hopeless", description = "Yes, I heard about the Furlbrow murders. It is very tragic, but such tragedy is a way of life in Westfall. There are many people here who simply no longer have the means or inclination to keep themselves fed. They have given up hope. Do you understand what it means to be left so hopeless as to stop caring about life? We must work together to show them that there is hope. That with the dawning day a better life comes.\n\nTake my mother's Westfall stew and help feed the homeless around Sentinel Hill.", objectives = "Use the Westfall Stew to feed 20 Homeless People around Sentinel Hill in Westfall.", completion = "You have a kind heart, <name>. You have done a good thing, today, and that act will reflect back upon you when judgment day comes." }
WordHunterWoW_QuestEN[26272] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Voldreka to the east.", objectives = "Meet with Voldreka in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have an intense look about ya though. Fiery eyes. You might have the makings of a real <class>.\n\nLets not waste anymore time 'den." }
WordHunterWoW_QuestEN[26273] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the dark arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", objectives = "Destroy 6 Tiki Targets.", progress = "Power stems from dis world and worlds you've not yet seen. Masterin' da power of one ain't gonna be enough ta make it outside of dese trainin' grounds - you gonna need to be pullin ya power from all of dem.", completion = "Not bad, mon. Ya have a deep power in ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go." }
WordHunterWoW_QuestEN[26274] = { title = "The Arts of a Warlock", description = "I tink I have something I should let ya know.\n\nAs ya' get more powahful, yo' gonna staht hearin' da voices - teachin' you new tings, new spells.\n\nGo, get some more experience, 'den come back an show me what ya learned.", objectives = "Reach Level 3 to Learn Corruption. Practice using Corruption 5 times against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya." }
WordHunterWoW_QuestEN[26275] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese." }
WordHunterWoW_QuestEN[26276] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day." }
WordHunterWoW_QuestEN[26277] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear." }
WordHunterWoW_QuestEN[26278] = { title = "The Defense of Grom'gol: Raptor Risk", description = "Throm'ka, {class}!\n\nYour arrival at Grom'gol is timely, indeed.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of eliminating the raptor population outside of Grom'gol, just to the north.  Don't worry about the raptors themselves... those wretched Nesingwary hunters will take care of them.\n\nI want you to destroy their eggs.", objectives = "Destroy 12 Lashtail Eggs.", completion = "Keep up the good work, <class>.  Hellscream's eyes are upon you." }
WordHunterWoW_QuestEN[26279] = { title = "The Defense of Grom'gol: Ogre Oppression", description = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.", objectives = "Kill 4 Mosh'ogg Brutes and 4 Mosh'ogg Witch Doctors.", completion = "I see you are good for more than simple egg-smashing duty.  Good.  The Horde can use a capable <race> like you." }
WordHunterWoW_QuestEN[26280] = { title = "The Defense of Grom'gol: Murloc Menace", description = "The Murkgill murlocs have been pushed out of the ocean by the Saltscale murlocs, so they make their refuge in the Kal'ai ruins to our northeast.  This was acceptable in the past, but no longer.\n\nSeparated from the sea, the Murkgill have grown restless, and they send their foragers to attack my supply caravans.  Send them a message: this behavior will NOT be tolerated by Hellscream's Horde.", objectives = "Slay 15 Murkgill murlocs.", completion = "Excellent work. Hopefully the raids will stop for now.\n\nI have one more task for you, <name>." }
WordHunterWoW_QuestEN[26281] = { title = "The Defense of Grom'gol: Trollish Thievery", description = "The trolls leave us well enough alone here in Grom'gol.  Most trolls know that the Horde can easily crush them when angered, and the trolls here in Stranglethorn are no exception.\n\nThe Bloodscalp have been more active lately, however.  As lately as last week, they sent a party into Grom'gol and stole several cases of rations.\n\nStealing food is the most forgivable type of theft, but I still can't let it happen under my watch.  Head north, to the Bal'lal ruins, and return our property.", objectives = "Obtain the Grom'gol Rations from the Bal'lal ruins.", progress = "Pity has no place under my command.  The trolls can find food elsewhere.  It's a big jungle.", completion = "<Aggro'gosh salutes you.>\n\nThe Horde thanks you, <name>.  Grom'gol is protected, if only for today." }
WordHunterWoW_QuestEN[26282] = { title = "The Favor of Akil'darah", description = "", objectives = "" }
WordHunterWoW_QuestEN[26283] = { title = "Prime Slime", description = "I've become very interested in the slimes inhabiting Skulk Rock. No matter how many times they're cleared out, they seem to return, yet it doesn't seem they're capable of reproducing from a single slime.\n\nI think something's growing in there. There's a source where all the slimes come from, and I want to study it. Find this source, and bring me back a sample.", objectives = "Collect a Direglob Sample from The Direglob.", progress = "Well? What did you find?", completion = "Fascinating... How large did you say it was? I wonder if others could be found intact...\n\nThis sample is excellent. I'll be sharing it with my fellow researchers." }
WordHunterWoW_QuestEN[26284] = { title = "Missing in Action", description = "Fer a job like this, I normally bring me whole crew o' demolitionists. With some help in settin' up th' powder, th' charges, and th' rest o' th' gear, the job gets done a lot faster.\n\nThose blasted troggs have me men caged all around Frostmane Hold. Now I'm 'ere all alone without th' personnel I need to finish th' job.\n\nYou look like a capable {class}, though. Would you find th' demolitionists th' troggs captured and break them out o' their cages?", objectives = "Free 6 Captured Demolitionists from their cages around Frostmane Hold.", completion = "You have me own thanks and th' thanks of th' men you rescued. I've already had th' boys start setting up the gear down inside the cave. It should be ready to go soon." }
WordHunterWoW_QuestEN[26285] = { title = "Get Me Explosives Back!", description = "It's gonna take a lot of powder ta collapse those caves. I don't know whether th' damnable troggs understood that when they stole me supplies and kidnapped me demolitionists! But th' outcome's th' same.\n\nAin't gonna be able ta blow nothin' up until I've got that powder back.\n\nGo south to Frostmane Hold and kill any o' those troggs you find. Any one o' 'em could be carryin' me kegs o' powder.", objectives = "Recover 7 Stolen Powder Kegs from Rockjaw Bonepickers or Rockjaw Marauders at Frostmane Hold.", progress = "Well, did you recover me missing supplies?", completion = "Well, now, that's more like it. We may get around to blowin' up somethin' after all." }
WordHunterWoW_QuestEN[26286] = { title = "In Defense of Westfall", description = "After my tour of duty was over in Grizzly Hills, I returned to Westfall, only to find the land in worse condition than when I left.\n\nThe price of our war left thousands of citizens homeless. They now migrate here and squat upon the deserted farmhouses and towns of the region.\n\nTo make matters worse, we are now under attack by the gnolls. The Westfall Brigade needs your help, {name}. Slay the attacking gnolls and recover their orders. Someone is pulling their strings and we need to find out whom!", objectives = "Recover the Gnoll Attack Orders.", progress = "Have you recovered the attack orders?", completion = "Helix? I've heard that name before. Recently as a matter of fact, but who is this admiral?" }
WordHunterWoW_QuestEN[26287] = { title = "The Westfall Brigade", description = "We were once known as the People's Militia. These days, though, we fight under the banner of Stormwind, with the full support of King Anduin Wrynn. Our goals here in Westfall are many: to clean up the mess left behind by the Defias, to expand the reach of the Alliance and to maintain order. So far we are failing on all fronts.\n\nTimes are worse now than when the Defias ran amok. Now with the indigenous gnolls of the region up in arms, we find ourselves backed into a corner. Help us, {name}!", objectives = "Slay any 12 Riverpaw Gnolls attacking Sentinel Hill.", progress = "Defend Sentinel Hill!", completion = "Well done, <name>. You have provided us a temporary reprieve from the onslaught of gnolls, but there is more work to be done." }
WordHunterWoW_QuestEN[26288] = { title = "Jango Spothide", description = "South of here is an area of Westfall known as the Dust Plains. From what we know the gnolls of the region have made the Dust Plains their unofficial capital. As with any capital, there exists a leader at the heart. If we are to put an end to these attacks, we must track down the gnoll in charge and end him.\n\nVenture forth into the Dust Plains, find the gnoll leader, Jango Spothide, and kill him. Take out any other gnolls that get in your way.", objectives = "Slay 5 Riverpaw Mystics, 5 Riverpaw Taskmasters and Jango Spothide.", completion = "Excellent work, <name>. It will take the Riverpaw weeks to recover from the blow you just dealt. Please take an item of your choosing as a reward for what you have done." }
WordHunterWoW_QuestEN[26289] = { title = "Find Agent Kearnen", description = "SI: 7 has been tracking Helix Gearbreaker since he entered Alliance territory two weeks ago. The letter I received from Mathias Shaw explained that he sent an agent by the name of Kearnen to Westfall to shadow Helix. Find Agent Kearnen and you'll find Helix Gearbreaker.\n\nKearnen came into town for supplies two days ago. She mentioned that she would be near Mortwake's Tower, southeast of here, on the Dust Plains.\n\nGet going, {name}.", objectives = "Find Agent Kearnen.", completion = "Helix is the one responsible for the gnoll attacks?\n\n<Kearnen nods at the tower.>\n\nHe's inside. He's been there for days. I've just been waiting for an excuse to bust him." }
WordHunterWoW_QuestEN[26290] = { title = "Secrets of the Tower", description = "Helix has got himself holed up inside Klaven Mortwake's old tower. I won't lie to you, {name}, it's heavily guarded. I count six armed mercenaries just on the outside. There's no way you're getting inside that tower by yourself. Lucky for you, Claire and I are here.\n\n<Kearnen pats her sniper rifle.>\n\nI'll cover your entry.\n\nTake this shrouding potion, you'll need it once you get inside. Use it as soon as you enter the tower and head upstairs. Find out what Helix is hiding up there!", objectives = "Enter Mortwake's Tower and find Helix Gearbreaker.", progress = "I won't let you down, <name>.", completion = "What could possibly be going on in Moonbrook? I don't like this one bit, <name>." }
WordHunterWoW_QuestEN[26291] = { title = "Big Trouble in Moonbrook", description = "I'll be filling out my report and heading back to Stormwind shortly. SI: 7 must be informed of the happenings in Westfall. I would recommend you do the same and report back to Gryan.", objectives = "Report your findings to Marshal Gryan Stoutmantle at Sentinel Hill in Westfall.", completion = "Who IS this Shadowy Figure? We have to get to Moonbrook." }
WordHunterWoW_QuestEN[26292] = { title = "To Moonbrook!", description = "We have had a camp near Moonbrook for quite some time now, {name}. One of my best soldiers works the area along with a company of Sentinel Hill troopers. Report to Captain Alpert now and find out if he has any news about the happenings in Moonbrook.\n\nAnother ally of mine is also at the Moonbrook camp. His name is Thoralius. I met Thoralius in Northrend during my time in Valgarde. He is a wise and powerful shaman. Perhaps his abilities could help us solve this mystery.", objectives = "Report to Captain Alpert at Moonbrook in Westfall.", completion = "The natives are restless, <name>. I don't know what's going on, but homeless activity in this area has quadrupled in the past two days. If I didn't know any better I'd say they were planning something..." }
WordHunterWoW_QuestEN[26293] = { title = "Machines of War", description = "Far to the east the \"Worldbreakers\" lay hidden in the Twilight Highlands. We must end their threat and we will do it with the most powerful army ever!\n\nOur new allies, the goblins, are making us new machines of war but I hear that there are problems with the quality. We can't fight with broken war machines. Speak to Foreman Glibbs and make sure our machines are ready for battle.", objectives = "Talk to Foreman Glibbs just inside the Orgrimmar Rear Gate in Orgrimmar.", completion = "Busy now. Go away.\n\nWait, what? Hellscream sent you? What - uh - what can I do for you? Him? Us?" }
WordHunterWoW_QuestEN[26294] = { title = "Weapons of Mass Dysfunction", description = "<Glibbs mops sweat from his brow with a greasy handkerchief.>\n\nSaurfang isn't happy with our work? This is very bad. My boys need to step it up.\n\nMaybe you can help set an example. A set of Hellscream Demolishers just rolled off the blocks and are ready for inspection. Give them a thorough going-over, and if you find any problems, give the Chief Engineer a good thrashing. Remind them that the Horde is depending upon them!", objectives = "Inspect Hellscream Demolishers until you find a faulty one, then teach its Chief Engineer a lesson.", progress = "You spoke with the Foreman?\n\nWell?", completion = "<Garrosh laughs.>\n\nInstilled a little discipline in them, did you? Good, good!\n\nEveryone pulls their weight in my Horde, from the smallest peon to the proudest warrior. I tolerate nothing less.\n\nOur preparations for the invasion are almost complete." }
WordHunterWoW_QuestEN[26295] = { title = "Propaganda", description = "We've noticed a rise in violent acts amongst the homeless of the area. Something or someone is getting them all riled up. Now whoever is behind all this is getting more organized. Just recently a group of thugs came through here handing out pamphlets.\n\nEnter Moonbrook and look for evidence. Propaganda, leaflets, whatever... Bring whatever you find back to me. Maybe we can find the source through the writings.", objectives = "Recover an Informational Pamphlet, Secret Journal, an Issue of the Moonbrook Times and Mysterious Propaganda.", progress = "Any luck?", completion = "V? The only V I know is VanCleef, but he died many years ago." }
WordHunterWoW_QuestEN[26296] = { title = "Evidence Collection", description = "The material of this bandana is identical to the material found at the Furlbrow murder scene. You should collect more red bandanas as evidence and return what you find to Captain Alpert.", objectives = "Collect 6 Red Bandanas.", progress = "Red bandanas?!", completion = "I haven't seen a red bandana in five years. Could this shadowy figure be attempting to reform the Defias Brotherhood?" }
WordHunterWoW_QuestEN[26297] = { title = "The Dawning of a New Day", description = "It looks like the meeting the shadowy figure spoke of is starting soon. The homeless are starting to mobilize. I need you to attend the rally and gather information, {name}.\n\nGo to the center of Moonbrook and listen in on the rally. Return to me with whatever you find out.", objectives = "Gather information from the Moonbrook Rally.", progress = "What happened?", completion = "I could hear the cheers from here. It seems as if we've got a huge problem on our hands, <name>.  We have to discover the identity of this shadowy menace before we enlist the aid of Stormwind. Perhaps there is another way..." }
WordHunterWoW_QuestEN[26298] = { title = "Hunt for Yenniku", description = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.", objectives = "Obtain 6 Bloodscalp Tusks from Bloodscalp trolls in the Bal'lal Ruins.", progress = "<class>.  Show me you have made prey of the Bloodscalp tribe.\n\nShow me your trophies.", completion = "These are good tusks, <name>.  You prove that you have the strength to hunt the Bloodscalps.\n\nAnd that is good, because you are not done hunting them." }
WordHunterWoW_QuestEN[26299] = { title = "Headhunting", description = "We must find if Yenniku is dead.\n\nSlay the Bloodscalps of Zuuldaia and take from them their shrunken heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, {name}.  You will find the heads at the ruins of Zuuldaia, along the coast to the north.", objectives = "Obtain 25 Shrunken Heads from Bloodscalp trolls at the Zuuldaia Ruins.", progress = "<name>.  I fear for our chief's son.  Do you have the shrunken heads so I may inspect them?", completion = "Thank you, <name>.  I will inspect these heads to ensure poor Yenniku was spared the headhunter's axe." }
WordHunterWoW_QuestEN[26300] = { title = "Nezzliok Will Know", description = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp witchdoctor will know it.  He is an enemy of the Darkspear tribe and will not speak freely, so we must force the truth from his dead lips!\n\nBring me the head of Nezzliok the Dire and place it within this cauldron.\n\nHe is deep within Zul'Kunda.  Bring his head...we will then make it talk.", objectives = "Obtain Nezzliok's Head from Nezzliok the Dire in Zul'Kunda.", progress = "The greenish broth within the cauldron bubbles.", completion = "You place the head of Nezzliok within the cauldron..." }
WordHunterWoW_QuestEN[26301] = { title = "Speaking with Nezzliok", description = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal two of their most-prized trophy skulls from the Skullsplitters across the river to the east.  Place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, the other from Ziata'jai.", objectives = "Obtain a Balia'mah Trophy and a Ziata'jai Trophy from the Skullsplitter ruins in Northern Stranglethorn.", progress = "I await the skulls...", completion = "Yes.  These will serve me well.  When my spirit is freed, I will enter the Nether with some fine servants indeed!\n\nYou are a credit to your <race> clan, and you have appeased me." }
WordHunterWoW_QuestEN[26302] = { title = "Chasing Yenniku's Fate", description = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, {class}.\n\nPerhaps your Darkspear allies at Bambala in the east can offer a hope of Yenniku's salvation.  But that, I doubt.", objectives = "Speak with Kin'weelay at Bambala.", completion = "Zanzil the Outcast??\n\nIf Yenniku is held by that troll, a vile and powerful witchdoctor, then I fear that only a faint hope remains.  Faint.  And tiny as the smallest insect.\n\nFortunately, I have some suspicions of my own.  Suspicions which may lead to Yenniku's salvation." }
WordHunterWoW_QuestEN[26303] = { title = "The Mind's Eye", description = "The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the south.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.", objectives = "Obtain the Mind's Eye from Mai'Zoth.", progress = "Greetings, <name>.  The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai'Zoth.\n\nDo you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, <name>!\n\nAnd in getting the Eye, you must have defeated Mai'Zoth and sent him to the Nether.  That is why the spirits would not mention him before.\n\nIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.\n\nBut that is a worry for another time." }
WordHunterWoW_QuestEN[26304] = { title = "Nighttime in the Jungle", description = "One year ago, my mother - that is, the troll who took care of me - was taken by the Skullsplitters of Zul'Mamwe.  Young and headstrong, I ran in after her, only to see her being pushed toward a burning brazier by a dozen of their warriors.  I hid behind a tree and watched as they grabbed her and... and...\n\n<Kil'karil looks away.>\n\nAt nighttime, the lights from their braziers reflect off the treetops and keep me awake.  Please, {name}... travel south into Zul'Mamwe and put them out.", objectives = "Put out 8 Zul'Mamwe Braziers at Zul'Mamwe in Northern Stranglethorn.", progress = "Please, <name>... put out the awful fires.", completion = "My mother's spirit rests well tonight, <name>.\n\nAs will I." }
WordHunterWoW_QuestEN[26305] = { title = "Saving Yenniku", description = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nMy suspicions that I spoke of earlier were correct: the spirits tell me that Yenniku dwells not with Zanzil the Outcast, but within the Ruins of Zul'Mamwe, to the southwest.  Once you have freed Yenniku's spirit, return to Nimboya at Grom'gol.", objectives = "Bring the Filled Soul Gem to Nimboya.", progress = "<name>.  Kin'weelay told me you set out to capture Yenniku.\n\nIs it true?  Do you have him?", completion = "You've done it!  You freed Yenniku from the will of Zanzil and the tyranny of the Skullsplitter, and completed the mission I had thought was so hopeless.  Zanzil still looms a threat in the Cape of Stranglethorn, but for now, I at least know that the soul of my chief's son is free.\n\nOur tribe will remember your name in songs, <name>, and we will etch your tale in stone so that it will live forever." }
WordHunterWoW_QuestEN[26306] = { title = "Start Taking Back", description = "Today we make the first strike at the heart of the savage Vilebranch tribe. Show no mercy, {name}; this is no longer just a spat between trolls. Every victory of the Revantusk is a victory for the Horde!\n\nThe Vilebranch headhunters and witch doctors will be the first to go. Make your strike against the lower terraces and report back to me with blood on your weapons.", objectives = "Kill 5 Vilebranch Witch Doctors and 5 Vilebranch Headhunters in Jintha'Alor.", completion = "Well done, <name>! Let the Vilebranch flee in terror from the sight of you!" }
WordHunterWoW_QuestEN[26307] = { title = "Death to the Vilebranch", description = "We won't give them a chance to react. You must re-enter Jintha'Alor and charge all the way to the upper tiers.\n\nThe Vilebranch berserkers and shadowcasters are dangerous enemies, {name}. When the others see their bodies thrown across the walls, they'll know we mean business.\n\nDon't leave any Vilebranch hearts beating!", objectives = "Kill 5 Vilebranch Berserkers and 5 Vilebranch Shadowcasters in Jintha'Alor.", completion = "It won't be long until we're the only trolls left breathing on these walls." }
WordHunterWoW_QuestEN[26308] = { title = "It's Ours Now", description = "Only the strongest and foulest Vilebranch are left now. The soul eaters and blood drinkers, foul worshippers of the evil god Hakkar.\n\nThey are FOOLS! They cling to old, defeated beliefs. I won't tolerate their crimes against the Revantusk any longer.\n\nStrike the final blow. Claim Jintha'Alor for the Revantusk... claim it for the Horde!", objectives = "Kill 5 Vilebranch Blood Drinkers and 5 Vilebranch Soul Eaters in Jintha'Alor.", completion = "There are none left to oppose the Revantusk! Any stragglers will be quickly taken care of.\n\nYou've done my people a great honor, <name>." }
WordHunterWoW_QuestEN[26309] = { title = "Dark Vessels", description = "The Vilebranch trolls here used to drink the corrupted blood of the god Hakkar himself for power. They boiled it in crude pots before drinking, dark vessels full of unholy strength.\n\nHakkar was killed long ago, of course. But the interesting thing... I still see some cauldrons bubbling up there. Bring me back a few and we'll see just what they've got cooking.", objectives = "Collect 5 Vessels of Tainted Blood from Jintha'alor.", progress = "Be careful near those cauldrons, <class>. The Vilebranch won't let you take their treats without a fight.", completion = "First the spiders and now this. I can smell the venom in this blood... it's the same as the skitterlings, but stronger.\n\nThe Vilebranch and spiders... there's some potential here." }
WordHunterWoW_QuestEN[26310] = { title = "All That Skitters", description = "A moment if you're going up there, {class}...\n\nI've got a few brokers quite interested in potent toxins. I couldn't help but notice the spiders scurrying around near here... not giant ones, about the size of your hand.\n\nThe skitterlings are a hue I've never seen before in this area. Could you collect a few for me and bring them back?", objectives = "Collect 8 Skittering Spiderlings in Jintha'Alor.", progress = "How many did you get?", completion = "Oh yes... I was wise to ask you to get these. How fascinating.\n\nCome here, my pretties. Into the bag you go." }
WordHunterWoW_QuestEN[26311] = { title = "Unfamiliar Waters", description = "The Warchief has designs to launch an all-out assault on the Twilight Highlands. Once there we hope to ally with the Dragonmaw orcs.\n\nThrough my own sources I've discovered that a Dragonmaw orc resides here, in Orgrimmar. He is known as Herezegor Flametusk, and once he commanded legions of their warriors.\n\nHis insider knowledge is precious to us. Find Flametusk and obtain for us a chart of the Twilight Highlands waterways.\n\nLast I hear, Flametusk was washed up at a bar in the Valley of Honor...", objectives = "Locate Herezegor Flametusk at the Wyvern's Tail inn within the Valley of Honor in Orgrimmar, and obtain a Twilight Highlands Coastal Chart.", progress = "<Sauranok is surprised to see you back so soon.>\n\nAh, <class>, you return. What have you discovered?", completion = "<Sauranok seems uninterested in the map as you relate your story.>\n\nTwilight Assassins followed you to the bar? Here, in Orgrimmar?\n\nThe Warchief won't be happy about this.\n\nContinue your preparations for the invasion and I will investigate." }
WordHunterWoW_QuestEN[26312] = { title = "Crumbling Defenses", description = "When da attack started, we pushed out to take da field as quickly as we could. Dere forces were deep and endless... we underestimated dem. Now some of our best shaman be stranded out dere, exhausted, far from our defenses.\n\nMake your way out and take da pressure off of our stranded brothas. Even a small break in battle be a chance to get much needed room ta breathe.\n\nBe swift, {class}.", objectives = "Relieve Tawn Winterbluff, Stormcaller Mylra, and Hargoth Dimblaze by helping them to defeat their opponents.", completion = "Thank you, <class>. Many Earthen Ring owe dere lives to ya dis day." }
WordHunterWoW_QuestEN[26313] = { title = "Core of Our Troubles", description = "Elementals are chaotic by nature, but dis kind of organized aggression is out of character. More so down here where dere deaths be a bit more permanent. I suspect dis is Therazane the Stonemother's doin', but I have to be sure.\n\nDestroy da Irestone Rumblers and bring me their cores. We'll be settlin' here and now if dis is da Stonemother's hatred brought down on us.", objectives = "Collect 6 Irestone Cores.", progress = "We've never been claimin' a great friendship with da  Elemental Lords, but we still be trustin' in a bit of security in da chaos. As long as dey be remainin' unorganized, we've been havin' little to fear.\n\nIf the Stonemother is truly rallyin' da earth against us, we be havin' a great deal more to be fearin'.", completion = "Dese are in surprisingly good condition - good work, mon." }
WordHunterWoW_QuestEN[26314] = { title = "On Even Ground", description = "We're fortunate dat those giants be havin' such bad aim. Luck is sure to be favorin' dem eventually though.\n\nWe need to get dem off da battlefield, but I don't tink takin' dem head on would be very smart.\n\nTake dis grapplin' line, get a good hold on one of their ankles and pull their legs out from under dem. Once dey are on da ground, dey should be easy ta be finishin' off.", objectives = "Use the Elementium Grapple Line to pull 3 Servants of Therazane off of their feet.", completion = "Dat will slow their assault a bit while Norsala be findin' a way to calm'm. We've no desire ta be remainin' enemies of Therazane the Stonemother." }
WordHunterWoW_QuestEN[26315] = { title = "Imposing Confrontation", description = "Have ya seen the looming giant in the distance to the northeast? Dat is Boden the Imposing, one of Therazane the Stonemother's Stone Lords.\n\nWe be knowin' little of da Stone Lords, but Boden is not known ta be very level-headed. Sadly, he seems to be da one leadin' dis assault, so he's the one we must be confrontin'.\n\nTake dis proclamation to him and read it aloud on behalf of da Earthen Ring. I know it be a bit of a stretch to think words will settle dis, but we have to try. Be cautious.", objectives = "Read the Earthen Ring Proclamation to Boden the Imposing.", progress = "Did ya confront Boden yet?", completion = "Yeah, mon... dat's about the reaction we were expectin'.\n\nHe mentioned Diamant though? If da two don't get along, perhaps this Diamant be a bit less brash den Boden. At least it's somethin'.\n\nLet me see if I can get da earth to tell me where we might be findin' dis Diamant." }
WordHunterWoW_QuestEN[26316] = { title = "What's Keeping Kharmarn?", description = "The cataclysm tore open deep caves beneath Frostmane Hold and troggs flooded out of their warrens. They succeeded in displacing the trolls who used to live there and they stand to drive us out if we do not act.\n\nHigh Tinker Mekkatorque hired the renowned demolitionist, Kharmarn Palegrip, to close the caves and stem the trogg advance. We've received no word about whether he was able to stop the troggs. Would you look for him at his camp near Frostmane Hold, to the south beyond the Toxic Airfield?", objectives = "Find Kharmarn Palegrip at his camp in Frostmane Hold.", completion = "It won't be tough to collapse th' tunnel, but I'm goin' to need my team an' my equipment 'afore I can get to th' task." }
WordHunterWoW_QuestEN[26317] = { title = "A Lashtail Hatchling", description = "Upon dealing the final blow to the lashtail eggs, you look down to see a newborn hatchling looking back up at you.  You can see it studying you, learning your features and following your movements.\n\nThe lashtail hatchling has formed a bond with you.\n\nYour original assignment was to thin out the raptors, but you have fulfilled your egg quota, and this one is an innocent newborn.  Perhaps someone back at Grom'gol Base Camp will know what to do with a raptor hatchling.", objectives = "Bring the Lashtail Hatchling to Far Seer Mok'thardin at Grom'gol Base Camp.\n\nProvided item:", completion = "Yes, the little one seems to have taken a liking to you.  I suppose that one raptor alone and raised among orcs is much less deadly than a whole pack of them.  Keep her, <name>... she may come in handy.\n\nIn fact..." }
WordHunterWoW_QuestEN[26318] = { title = "Finishin' the Job", description = "My team has finished settin' up th' powder kegs and th' detonator at the bottom o' th' cave in th' western part of Frostmane Hold. All you need to do is venture down there and activate th' detonator to explode the powder and collapse those tunnels.\n\nThat'll stop th' flow of troggs from th' deep parts of th' earth. Mekkatorque'll have an easier time of dealin' with the remainin' troggs if you can take out their leader, who calls 'imself Boss Bruggor. Good luck, {name}.", objectives = "At the bottom of the cave in Frostmane Hold, kill Boss Bruggor and activate the Detonator to detonate the trogg tunnels.", progress = "Well, is th' job done?", completion = "I could feel th' explosion way up here! My boys did a fine job riggin' up that blast, but it wouldn't have happened without your help. It's only fair that I split my contract payment with you for helpin' me finish th' job." }
WordHunterWoW_QuestEN[26319] = { title = "Secrets Revealed", description = "There is a shaman here, Thoralius, who might be able to aid us. He is a friend of Gryan's who has recently come to Westfall to study the elemental devastation that has befallen us.\n\nSpeak to Thoralius and see if there is something that he can do to shed some light on the identity of this shadowy figure.", objectives = "Speak with Thoralius the Wise at Moonbrook in Westfall.", completion = "Hmm, yes, perhaps I could be of some assistance. When I was in Northrend I helped the people of Valgarde uncover some of the mysteries of the vrykul by delving into the spirit world. Perhaps the same could be done here." }
WordHunterWoW_QuestEN[26320] = { title = "A Vision of the Past", description = "This incense will put your body and mind in a deep meditative state. Once the trance begins you will be pulled into the spirit world. Do not fight the trance once it has begun, {name}. Allow the spirits to show you what they know.\n\nYou must leave now. Go to the Deadmines, a place which I am told holds great significance in the history of Westfall. Once inside, use the incense.\n\nYou may enter the Deadmines through the old farmhouse south of here. Follow the homeless. \n\nReturn to Gryan with your discovery.", objectives = "Enter the Defias Hideout and follow the trail of homeless to the Deadmines dungeon. Enter the Deadmines dungeon and use the Incense Burner to see into the past.", completion = "WHAT? VanCleef had a daughter?" }
WordHunterWoW_QuestEN[26321] = { title = "I Think She's Hungry", description = "It looks like your young raptor is hungry.  If you're looking to keep her, why don't you find something for her to eat?  The lashtail often attack the camp of the Murkgill murlocs, just to our north.\n\nShe probably isn't strong enough to hunt on her own yet, but I'm sure she will eat freshly killed murloc meat.", objectives = "Kill Murkgill murlocs in Northern Stranglethorn, and let your Lashtail Raptor eat 40 bites of their meat.", completion = "She looks bigger already!  You can see, these raptors grow quickly.  You are lucky to have found such a strong companion.\n\nKeep her by your side as long as you can, <name>.  I'm sure she will prove to be an asset in the future." }
WordHunterWoW_QuestEN[26322] = { title = "Rise of the Brotherhood", description = "I had no idea that VanCleef had a daughter, {name}. If there was one thing that man was exceptionally skilled at, it was keeping secrets.\n\nHow tragic. Poor thing witnessed a horrible act. Had I only known.\n\nWhat was that? Did you hear something? It seems as if the gnolls are pulling back... where are my guards?\n\nON GUARD, {name}!", objectives = "Bear witness to the rise of the Brotherhood.", completion = "I will deploy a battalion of soldiers to Westfall at once! With the Defias Brotherhood reborn, an old threat to the kingdom is renewed." }
WordHunterWoW_QuestEN[26323] = { title = "Favored Skull", description = "Your pet raptor seems to have found a new toy: a skull, from a nearby troll skull pile.\n\nWhat sets this skull apart from the rest is beyond you, but for some reason, she won't put it down.\n\nNimboya at Grom'gol Base Camp seems to be somewhat of a skull expert, judging by the skull piles he keeps.  Maybe he'll have some idea what makes this one so special.", objectives = "Return to Nimboya at Grom'gol Base Camp and show him your Lashtail Hatchling's new skull.\n\nProvided item:", completion = "What do we have here?  A young raptor, and her pet <race>.  Hah!\n\nMore importantly, what is that skull you have there?  This was no ordinary troll.  He was big...\n\n\n\n... and strong, too.  Let's see what we can do with this one.\n\nDon't go anywhere." }
WordHunterWoW_QuestEN[26324] = { title = "Where Is My Warfleet?", description = "The Highlands are the home of the Dragonmaw orcs. If we show them our might they would ally with us against the Twilight's Hammer. I am certain!\n\nThe fleet is gathering at Bilgewater Port in Azshara but there are reports of delays.\nYou did good getting the goblins to work, I need your skills here too.\nFind Warlord Krogg in Azshara and see what is taking so long.", objectives = "Speak with Warlord Krogg at Bilgewater Port in Azshara.", completion = "What, another message from Hellscream? His patience is thinner than calf's hide.\n\nHave you ever worked with goblins before? Everywhere is another hidden cost! Our ships lie half-assembled and the air fleet is scattered to the winds.\n\nIf this invasion is going to happen, I'm going to need your help." }
WordHunterWoW_QuestEN[26325] = { title = "A Nose for This Sort of Thing", description = "<The skull speaks to you.>\n\nI live?  No, I do not... but I can.\n\nThat raptor you have is wise to have found my skull among what must have been so many.  In life, I was strong, powerful, a lord among trolls.  With your help, I can be a lord once more.\n\nThe Bloodscalps at Zuuldaia hoard magical fetishes that can help me return.  They hide these artifacts under the sand.  Use your hatchling to find these artifacts, {name}... then throw them in the pot.", objectives = "Use your Lashtail Hatchling to sniff out 8 Zuuldaian Fetishes.", progress = "<The large troll skull bubbles to the surface.>\n\nHow many did you find?", completion = "<You drop the fetishes into the pot.>\n\nYes... yesss...\n\nMy spirit is strong again, <race>, and I am ready to return to the world.  Now I need a body." }
WordHunterWoW_QuestEN[26326] = { title = "The Very Earth Beneath Our Feet", description = "Only one piece of the World Pillar remains, and it is in the hands of the Stonemother herself. Worse, the temple has come under siege by elementals and giants. It's not a terrible leap of logic to assume they're acting by her will.\n\nGo out and meet the elementals in battle to the northwest. Work with Torunscar and Norsala to find a way to communicate with their leaders and seek out the World Pillar. We would prefer such be done peacefully, but we will do whatever we must to seal the rift.", objectives = "Find Earthcaller Torunscar just northwest of the Temple of Earth, in the Jagged Wastes.", completion = "Hey, mon! Thank ya for comin'.\n\nWe weren't ready for dis kind of attack. We been expectin' da Twilight Cult, but not elementals... we've got no idea what upset dem so much that dey would turn on us like dis.\n\nYou haven't been out dere killin' them, have you?" }
WordHunterWoW_QuestEN[26327] = { title = "Anvilmar the Hero", description = "You don't want to waste your time talking to me right now, lad. Thargas Anvilmar himself is just on the other side of these wagons.\n\nSurely you've heard of him? He fought to defend the Thandol Span from the Dark Iron alongside the King of Stormwind! He's one of the finest heroes of Ironforge.\n\nRight now though, he's in the thick of it! Go out there and let him know you're ready to help. Just keep a good distance, he swings wide.", objectives = "Talk to Thargas Anvilmar.", completion = "Well met! If you've got a weapon on you, I'll take any help I can get clearing out these crazed fools!" }
WordHunterWoW_QuestEN[26328] = { title = "Rocky Relations", description = "<Norsala reaches to the ground in an attempt to discern Diamant's location, but jumps back in shock after a moment's contact.>\n\nMy! Dat was unexpected. Diamant ain't far at all. When I reached out ta him, he spoke back wit me and told me where we could be finin' him. Head towards tha northeastern edge of the Jagged Wastes - Diamant will be expectin' ya.\n\n{name}, be careful. It may be unlike an earth bein' to lay an ambush, but it was unlike dem to siege the temple in da first place.", objectives = "Find Diamant the Patient at the northeast edge of the Jagged Wastes.", completion = "Ah... you must be the <race> that I was expecting.\n\nYou have come on behalf of the Earthen Ring then?" }
WordHunterWoW_QuestEN[26329] = { title = "One More Thing", description = "Well, it's time to start packin' up and movin' on to the next job. There's always somethin' else to blow up out there. Somewhere, there's a mountain needs movin' or a gorge that needs carvin', and I'll be there to do it.\n\nI don't suppose you'd do me one more favor? Would you take this report back to High Tinker Mekkatorque in New Tinkertown? He needs to know that th' troggs won't be botherin' his people again anytime soon.", objectives = "Bring Kharmarn's Report to High Tinker Mekkatorque in New Tinkertown.", progress = "Welcome back, <name>.", completion = "<The high tinker reads Jessup's report.>\n\nSplendid news! With the troggs taken care of, we should be able to turn our attention to Crushcog's troublemaking." }
WordHunterWoW_QuestEN[26330] = { title = "Who's a Big Troll?", description = "<The skull speaks once more.>\n\nMy soul is ready, but my body is not.  The Bloodscalps desecrated my old body long ago.  The horrors that they inflicted upon me... my spirit watched on while they tore my body apart and, and... I can't go on.\n\nTheir chief, Gan'zulah, presided over the gruesome acts.  In fact, if memory serves, he was a strong, powerful troll... about the same size as I was.  What a fine coincidence.\n\nYou know what to do, {race}.  Make it quick.", objectives = "Obtain Gan'zulah's Body from Zul'Kunda.", progress = "<You hear the skull's voice:>\n\nGan'zulah...", completion = "You have done well, <race>.  Only one more step remains before I may return." }
WordHunterWoW_QuestEN[26331] = { title = "Crushcog's Minions", description = "Our old enemy, Thermaplugg, is doing his best to keep us from rebuilding and finishing our reclamation of Gnomeregan. He's sent one of his most loyal henchmen, Razlo Crushcog, and a force of irradiated gnomes to harry us.\n\nThey've taken over an old arsenal up the road to the north, and Crushcog's technicians are repairing those weapons. We have to stop them before they're able to get those mechano-tanks back online. Go to Crushcog's Arsenal and eliminate as many of the technicians as you can.", objectives = "Kill 8 of Crushcog's Minions at Crushcog's Arsenal. You may kill Irradiated Technicians or Crushcog's Battle Suits.", completion = "That should set back Crushcog's plans a bit, but we can't rest until he is defeated and Chill Breeze Valley is secure." }
WordHunterWoW_QuestEN[26332] = { title = "Skullsplitter Mojo", description = "<The skull speaks again.>\n\nI have my body, thanks to you, your raptor, and Gan'zulah.  Now, if I remember correctly, you and your witch doctor friend will need some mojo to complete this ritual.\n\nThe Bloodscalps keep mojo in Zul'Kunda, but it is weak.  Your Darkspears' mojo will not work either.  No... you want to take from the Skullsplitter trolls, across the river to the east.\n\nHurry back, {race}.  I will be watching...", objectives = "Obtain 6 Skullsplitter Mojos from Skullsplitter trolls in the Ziata'jai Ruins and the Balia'mah Ruins.", progress = "<The large troll skull floats around within the cauldron.>", completion = "<You throw the mojo into the pot.>\n\nExcellent work, <race>.  You and your raptor have done a great thing.  Hakkar would be most pleased..." }
WordHunterWoW_QuestEN[26333] = { title = "No Tanks!", description = "We've lost more than a couple scouts trying to find out what exactly Razlo Crushcog plans to do with all those mechano-tanks his irradiated technicians are repairing.\n\nWe can't afford to take it slowly anymore. We must act before Crushcog turns his followers and his weapons on us.\n\nThis techno-grenade packs enough explosive power to destroy the mechano-tanks and deny Crushcog their use. Take it north with you along the road to Crushcog's Arsenal and take out those tanks!", objectives = "Use the Techno-Grenade to destroy 5 Repaired Mechano-Tanks at Crushcog's Arsenal.", progress = "Have you managed to take out any of those mechano-tanks Crushcog's men are working on?", completion = "Mekkatorque will be pleased to hear that you've ruined Crushcog's plans to use our old weapons for his followers. Without the mechano-tanks under his command, he'll be weak and vulnerable." }
WordHunterWoW_QuestEN[26334] = { title = "Bloodlord Mandokir", description = "{race}.  {race}, {race}, {race}... you didn't think I was a friend, did you, {race}?  Ah, ha ha haaaa!\n\nYou've served your purpose.  I've returned to the realm of the living, and it's all thanks to you.  So, instead of killing you, I'm going to make you a deal instead.\n\nGive me the raptor.\n\nYou must already know that she's no normal raptor, and I need a replacement for Ohgan.  Do it, or both you and the witch doctor will taste my rage.", objectives = "Deliver the Lashtail Raptor Egg Fragment to Bloodlord Mandokir in Grom'gol Base Camp.", progress = "All I ask is the raptor, <race>.  Give it to me, and the troll lives.", completion = "I'm glad to see you've come to your senses.\n\nCome and visit us in Zul'Gurub sometime, <race>.  I'll be watching..." }
WordHunterWoW_QuestEN[26335] = { title = "Ready the Navy", description = "Hellscream expects an armada of ships for his invasion, but the docks here are weeks behind schedule. Costs are rampant and quality is poor. Corruption is the problem, {name}! And I need you to root it out.\n\nThe Foebreaker, a warship berthed at the northwest pier, should have been outfitted days ago. Something reeks. Go there and oversee the construction yourself.\n\nFind out who's disrupting our naval preparations and deal with them!", objectives = "Investigate the Hull of the Foebreaker.", completion = "<Here, in excruciating detail, are the blueprints for the Foebreaker.>\n\n<You twist the documents every which way, trying to make sense of the incomprehensible scribbles, notes, and corrections.>" }
WordHunterWoW_QuestEN[26336] = { title = "Shakes O'Breen", description = "You're all right, {name}. It's not every day you come across a so-called hero that has a clue what they're doing once they get this far from home, so I'll let you in on some more work.\n\nI've a friend by the name of Shakes O'Breen. He's the captain of a crew of pirates, the Blackwater Raiders; good men, respectable as pirates go. They dock at Faldir's Cove, hidden along the southern shore.\n\nI'm sure O'Breen will have lucrative jobs for you if you're interested.", objectives = "Find Shakes O'Breen at Faldir's Cove in Arathi Highlands.", completion = "Ahoy, <class>. Any friend of Skuerto is a friend of mine.\n\nYou'll find plenty of work needs doin' around here. We're not sittin' in this cove twiddlin' our thumbs by choice." }
WordHunterWoW_QuestEN[26337] = { title = "Beating the Market", description = "<It's not hard to see why the Foebreaker is behind schedule. Every other day, a foreman comes in and changes the blueprints.>\n\n<Most troubling are the recent alterations. The workers have been ordered to remove rivets to save on costs!>\n\n<You'd better track down one of the Bilgewater foremen responsible for this and make an example out of him, before any Horde lives are lost in a faulty ship.>", objectives = "Track down a Bilgewater Foreman somewhere in Bilgewater Harbor and knock him around a little.", completion = "So they were trying to skimp on production costs? Unacceptable!\n\nI'm glad you knocked some sense into them. If that foreman makes good on his word, our fleet will be ship-shape in time for the invasion." }
WordHunterWoW_QuestEN[26338] = { title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", objectives = "Slay 7 Bloodscalp Mystics, 7 Bloodscalp Hunters, 7 Bloodscalp Scouts, and 1 Bloodscalp Beastmaster.", completion = "Balance is restored - for now.  We may call on you again in the future, <name>." }
WordHunterWoW_QuestEN[26339] = { title = "Staging in Brewnall", description = "While High Tinker Mekkatorque, his military advisors, and I finalize the plans for the attack on Razlo Crushcog, I've sent my assistant ahead to Brewnall Village to begin preparations.\n\nTo get to Brewnall Village, follow the road southeast out of town. Once you arrive, find Jarvi Shadowstep and see if he needs any help. Our dwarven cousins have dispatched a cadre of mountaineers from Ironforge to join us in the fight against Crushcog.", objectives = "Speak with Jarvi Shadowstep at Brewnall Village.", completion = "Ah, yes, Kelsey told me to expect you. There's still much to do before we can take on Crushcog." }
WordHunterWoW_QuestEN[26340] = { title = "The Hunt", description = "Of all the places to end up across Azeroth, I'm stuck here in Grom'gol.  With the marauding wildlife, the caravan raids, and the constant threat of troll attacks, I'm surprised I've survived for this long.\n\nCould be worse, I suppose.  At least here in Grom'gol we have walls and guards.  There's a group of hunters up north that set up camp right in the middle of the jungle!\n\nI see people heading there all the time.  If you're looking for trouble, feel free to head up there.  I'll stick with my Grom'gol.", objectives = "Report to Barnil Stonepot at Nesingwary's Expedition in Northern Stranglethorn.", completion = "Hmm?  Barnil's the name.  And you are...?" }
WordHunterWoW_QuestEN[26341] = { title = "The Stone Shards", description = "I've scouted all over these highlands, {name}, and there's one thing I've found I haven't been able to explain.\n\nTo the northeast of here, there's a circle of stones, like the others you'll find everywhere in Arathi... but the largest and most imposing of them, built into the mountainside itself.\n\nJust between you and me, I heard voices while I was there. Whispers of the earth. If you're the curious type, you could go see for yourself...", objectives = "Investigate the Shards of Myzrael.", completion = "<The shards pulse softly, and a whisper slowly echoes through your head.>\n\nHelp..." }
WordHunterWoW_QuestEN[26342] = { title = "Paint it Black", description = "We have reliable intelligence that Razlo Crushcog has taken up a defensive position on the island in the middle of frozen Iceflow Lake. To make matters worse, he's surrounded himself with a network of sentry-bots that will detect any possible attackers.\n\nIf we're to take on Crushcog, we'll need to take out those sentries. This device launches a dark, sticky paint that will coat the optical sensors of Crushcog's sentry-bots. Use it to take out his early warning system.", objectives = "Use the Paintinator to blind 5 of Crushcog's Sentry-Bots.", progress = "Were you able to blind Crushcog's sentries?", completion = "You've given us just the opening we'll need to get the drop on Crushcog. Excellent work, <name>." }
WordHunterWoW_QuestEN[26343] = { title = "Supply and Demand", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in Northern Stranglethorn.", objectives = "Bring 2 Large River Crocolisk Skins to Drizzlik at Nesingwary's Expedition.", progress = "My equipment is all ready to go, <name>, I just need those skins. We don't want to keep Riddlevox waiting, that's for sure.\n\nIt's not a good idea for anyone to keep the chief inventor of the Tinkers' Union unsatisfied.", completion = "These skins should do. Their quality isn't too important, given that they'll make up the inside layer of the boots, but it's still important that they're comfortable.\n\nIf they're a bit too rigid, I'll use some tiger blood to soften it up. Tricks o' the trade, you know?" }
WordHunterWoW_QuestEN[26344] = { title = "Some Assembly Required", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", objectives = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik at Nesingwary's Expedition.", progress = "Drizzlik's Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocolisk skin boots. None finer!\n\nCan't beat a glowing description like that, can you?\n\nExcept, maybe, if you have those skins for me?", completion = "My boots... they're like sausages, <name>. Look great, taste great. I tell you they're filled with nothing but the finest ingredients and meats, and you eat it, and you love it.\n\nIt's safer--and more enjoyable--if you just trust me, and don't ask too carefully what's really inside." }
WordHunterWoW_QuestEN[26345] = { title = "Excelsior", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder snapjaw crocolisk.  Find them to the south, near the border with the cape.", objectives = "Bring an Elder Crocolisk Skin to Drizzlik at Nesingwary's Expedition.", progress = "I read somewhere that the elder crocolisks are slowly dying out... bad news for my business, isn't it?\n\nAnyways, I hope you have that elder snapjaw crocolisk skin for me!", completion = "Great! Thanks to your help I'll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!\n\nFor all your hard work, here, I made some extras, so take a pair. It's on Drizzlik.\n\nAnd remember, there's no boot so fine as one of Drizzlik's Excelsior line!" }
WordHunterWoW_QuestEN[26346] = { title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Skuerto of what you've done so far.", objectives = "Return to Skuerto at Refuge Pointe in Arathi Highlands.", completion = "Say no more, <name>. I followed up with an... \"old friend\" while you were gone. I should've known better than to send you to those shards.\n\nWe've both made a grave mistake in involving ourselves in this. Luckily, I \"persuaded\" my boy Gerrig to tell me what to do if this happened." }
WordHunterWoW_QuestEN[26347] = { title = "Keeper of the Flame", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me chasm ooze from the slimes in the Raging Chasm to the northeast.", objectives = "Bring 5 Chasm Oozes to Captain Grayson at the Westfall Lighthouse.", progress = "The flame will not burn for long without ooze, <name>. We used to use oil back in the day, but it was hard to come by!", completion = "Praise you, brave <class>.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.\n\nI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny." }
WordHunterWoW_QuestEN[26348] = { title = "The Coast Isn't Clear", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill murloc tidehunters and oracles and I will see to it that you are rewarded.", objectives = "Kill 7 Murloc Tidehunters and 7 Murloc Oracles.", completion = "Well done, <name>.  You have quite a knack for combat.  Thanks to you the Coast of Westfall is a safer place." }
WordHunterWoW_QuestEN[26349] = { title = "The Coastal Menace", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", objectives = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.", progress = "Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.\n\nReturn to me when the foul beast is dead.", completion = "So the foul heathen, Murk-Eye is dead.  Well done, <name>.  By your hands one life was laid to rest but perhaps many more were saved.  The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics." }
WordHunterWoW_QuestEN[26350] = { title = "Priestess Hu'rala", description = "Thank you, {name}.  I know you didn't have to save my life, and... well, I am thankful.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe trolls at Bambala in the east may know more.  Speak with their priestess.", objectives = "Speak with Priestess Hu'rala at Bambala in Northern Stranglethorn.", completion = "Mandokir is alive, yes.\n\nYou are responsible, yes.\n\nYou may be able to stop him still, yes." }
WordHunterWoW_QuestEN[26351] = { title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go west, and you will find the feathers, yes.", objectives = "Obtain 5 Jungle Stalker Feathers from Jungle Stalkers in Northern Stranglethorn.", progress = "Raptor named Ohgan'aka, still your friend.", completion = "You bring feathers, yes.\n\nYou can follow directions, yes." }
WordHunterWoW_QuestEN[26352] = { title = "Cozzle's Plan", description = "I may be of Darkspear birth, but I spent my childhood here, in Stranglethorn Vale.  I've seen everything there is to see here in Stranglethorn, but the most offensive is the devastation that the Venture Company has done to the riverbed.\n\nTo make things worse, Foreman Cozzle and his crew have been increasing their activity, and I suspect they have some new plan.  Succeed where I failed, {name}: Kill Cozzle, obtain his key, and steal the blueprints from his apartment.", objectives = "Obtain Cozzle's Key from Foreman Cozzle, then obtain the Fuel Regulator Blueprints.", progress = "The Venture Company's acts against Stranglethorn cannot be forgiven.", completion = "A fuel regulator?  This seems important.  At least, I hope it is.\n\nWe may not have ended the Venture Company's operations, but we at least slowed them down.  Thank you, <name>." }
WordHunterWoW_QuestEN[26353] = { title = "Captain Sanders' Hidden Treasure", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", objectives = "Find Captain Sanders' footlocker and search it for the next clue.", completion = "The footlocker slowly creaks open.  Sand and water seem to be its only contents. But wait!  A small crab scurries out with a clue to the treasure in his claws!" }
WordHunterWoW_QuestEN[26354] = { title = "Captain Sanders' Hidden Treasure", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", objectives = "Find the old barrel near the ruined chimney and search it for your next clue.", progress = "This looks like the right barrel.", completion = "Good work, treasure hunter!" }
WordHunterWoW_QuestEN[26355] = { title = "Captain Sanders' Hidden Treasure", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", objectives = "Search the empty jug next to the windmill for the next clue.", progress = "There's a clue sticking out of the empty jug.", completion = "You're on your way to the jackpot, treasure seeker!" }
WordHunterWoW_QuestEN[26356] = { title = "Captain Sanders' Hidden Treasure", description = "Sure enough, deep within the Old Jug there is another clue to Sanders' treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", objectives = "Locate Captain Sanders' chest and open it for your reward.", progress = "The lost treasure of Captain Sanders awaits!", completion = "The hinges on the old chest are rusty but they still work.  You force the chest open and take the booty.\n\nCongratulations!" }
WordHunterWoW_QuestEN[26357] = { title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. The spirits not gonna be watchin' over them much longer.\n\nTake this torch with ya as ya fight through the Vilebranch, {class}. Set fire to their tiki masks. I'll be watchin' from here as their wards and hexes fade away, an' their heretical dark voodoo goes up in smoke.", objectives = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor.", completion = "Such a pretty site ta see the enemy's hopes burnin'..." }
WordHunterWoW_QuestEN[26358] = { title = "Ready the Air Force", description = "I gave Hellscream my personal guarantee that I'd have his airfleet ready this week, but our flagship - The Spear of Durotar - still doesn't have its primary engines installed.\n\nFleep promised me a dangerously shiny new engine last week. Go to her junkyard behind the bank and find out what the holdup is.\n\nThe airfleet is waiting on us, {name}!", objectives = "Look for Fleep at her junkyard within Bilgewater Harbor in Azshara.", completion = "<Fleep wipes her face, plastering an enormous grease smear across her cheek.>\n\nWhat? The Captain said WHAT?\n\n<She shakes her pipe wrench threateningly.>\n\nIt's HIS fault this big beast of an engine is delayed." }
WordHunterWoW_QuestEN[26359] = { title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", objectives = "Speak with Priestess Hu'rala at Bambala to participate in the Mind Vision ritual.", progress = "Your vision not Ohgan'aka's, no.\n\nYou are not ready.", completion = "What did Priestess tell you?\n\nThe raptor is daughter of Ohgan, heir to Mandokir's seat.\n\nHah!" }
WordHunterWoW_QuestEN[26360] = { title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", objectives = "Obtain Braddok's Big Brain from Braddok in Zul'Mamwe.", progress = "Extra-big spells need extra-big brains, yes.", completion = "Hold on, next part is tough, yes.\n\nLots of chances to fail, yes.\n\nBut <name> and <name>'aka going to be reunited... yes they will." }
WordHunterWoW_QuestEN[26361] = { title = "Smoot's Samophlange", description = "It was the Captain who insisted his new engines use an induction samophlange.\n\nThose things hadn't even been invented yet!\n\nI tasked Smoot with creating one based on some stolen Venture Company schematics, and he's finally built a working model.\n\nNow that he's got his samophlange, he's drunk with power. He's running all over town with it like a goblin possessed.\n\nSmack Smoot and snag my samophlange, {name}.", objectives = "Find Smoot somewhere in Bilgewater Harbor. Tackle him and get the Induction Samophlange.", progress = "Smoot's a good engineer.\n\nA samophlange can kill from thirty yards if you misalign the reduction caliphracts.", completion = "Excellent! I should have this here engine samophlanginated within the hour." }
WordHunterWoW_QuestEN[26362] = { title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", objectives = "Speak with Priestess Hu'rala, then help the Captured Lashtail Hatchling escape from Zul'Gurub.", progress = "Where is <name>'aka?", completion = "What a shame, yes.\n\nThis is what the spirits wanted, yes.\n\nMaybe when you are stronger, you will go into Zul'Gurub and take back your <name>'aka from Mandokir, yes.\n\nFor now, Priestess give you this." }
WordHunterWoW_QuestEN[26363] = { title = "Summit of Fate", description = "You've done well cleaving through their warriors, {name}. I'd like you to investigate the summit of Jintha'Alor.\n\nWe were prepared for our fiercest battle there, to storm their dark altar, but it's too quiet. Not a sound. It could be a terrible trap, and someone strong should look into it first instead of all of us rushing in.\n\nAnd if it's not a trap... I'm very interested in finding out what happened up there. Bring me back any clues you can find.", objectives = "Collect 8 Spider Idols from the Vilebranch at the summit of Jintha'Alor.", progress = "What did you find?", completion = "Dead? All of them, around the altar? And you found these spider idols on them...\n\nA mass sacrifice. They threw their lives to Shadra." }
WordHunterWoW_QuestEN[26364] = { title = "Down with Crushcog!", description = "Our cousins, the dwarves of Ironforge, have agreed to help us in the battle against Razlo Crushcog. Mountaineer Stonegrind is a veteran who knows Dun Morogh well. He and High Tinker Mekkatorque stand ready on a small snow-covered island in Iceflow Lake to the north. Meet up with them there and let the high tinker know when you are ready to face the traitor Crushcog.\n\nTake this orbital targeting device and use it during the battle. It will help guide the high tinker's special weapons.", objectives = "Defeat Razlo Crushcog. Speak to High Tinker Mekkatorque at Iceflow Lake when you are ready to begin the battle.", progress = "Did you face Crushcog? What happened?", completion = "We're finally free of Razlo Crushcog and his interference! With the defeat of Crushcog and his forces, Thermaplugg can't afford to send any more of his followers to the surface. I can't wait for the day when we defeat him for good!" }
WordHunterWoW_QuestEN[26365] = { title = "Hero's Call: Redridge Mountains!", description = "While the situation here is dire, other parts of the region are literally quaking from the great upheaval.\n\nI have here a report from Watch Captain Parker of Redridge Mountains, one of our territories east of Elwynn Forest. He is asking for a hero to come to their aid.\n\nWe are spread so thin here that I don't know how we can afford to send anymore military. Would you check on Parker and see what he needs? You will find Watch Captain Parker atop the tower at Three Corners.", objectives = "Report to Watch Captain Parker at Tower Watch in Redridge Mountains.", completion = "Heard Westfall was in some deep doody.\n\n<Parker doesn't even turn to face you.>\n\nWell, we got our own set of problems here. See them gnolls out there? Looks like they're actin' up again. I don't like it. Don't like it one bit." }
WordHunterWoW_QuestEN[26366] = { title = "Heads Up", description = "Umboda of the Vilebranch is one of their strongest warriors, and a sick butcher.\n\nHe takes the heads of all he slays as trinkets, rewards...even weapons!  It's his turn to be taken.\n\nFind Umboda \"Three-Heads\", slay him, and bring me HIS head! We'll see how the Vilebranch fight when we throw it back over their walls!", objectives = "Defeat Umboda Three-Heads and collect his head.", progress = "Let's see it!", completion = "The look of fear and confusion on his face... this is what he deserved! Let's make sure all the Vilebranch wear the same look." }
WordHunterWoW_QuestEN[26367] = { title = "Ongo'longo's Revenge", description = "Ongo'longo was one of us. What outsiders called a Dire Troll, but he was a Revantusk, and a proud warrior like all of us!\n\nThen the Vilebranch took him. They keep him chained up in a pit at the top of Jintha'Alor, made to dance for their sick amusement.\n\nNo chains can hold Ongo'longo. All you need to do is raise his temper, {name}. Fight him until he's enraged enough to remember his true spirit and break free... and then get out of the way!", objectives = "Fight Ongo'longo until he breaks free.", completion = "I wish I could have been there to see it, <name>! I'll have to hear the story from Ongo'longo himself when this is over." }
WordHunterWoW_QuestEN[26368] = { title = "Venomous Secrets", description = "There's more of this curious venom to be had if Shadra's being summoned.\n\nDon't look so surprised... the Forsaken have studied these lands before, and we've encountered the venom queen at least once. Her toxins have proven quite useful in the past.\n\nThey'll prove useful to the Horde once more, too. Be a dear and fetch me as much poison as you can from the spawn of Shadra that lurk in the cave on the summit... I'm sure you'll be covered in it anyway.", objectives = "Collect 6 Shadra-Spawn Venom Samples from the Spawn of Shadra in Jintha'Alor.", progress = "Have you the venom...?", completion = "Mmm, yes... that old nostalgic smell.\n\nYou've done well for the Forsaken, and the Horde." }
WordHunterWoW_QuestEN[26369] = { title = "Hunt the Keeper", description = "Kotonga has told me of Shadra. She is the venom queen, the loa of spiders, worshipped in darkness. If the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", objectives = "Kill Morta'gya the Keeper and obtain the Tablet of Shadra.", progress = "Be sure you search her body. I don't want any traps laid by the Vilebranch to be hidden by their deaths.", completion = "The parts scattered, the keepers separated... I see.\n\nThis is a ritual to summon Shadra. They must not have gotten far. It should be destroyed..." }
WordHunterWoW_QuestEN[26370] = { title = "Return to Sentinel Hill", description = "The Defias Brotherhood are not a force to be taken lightly, {name}. What you witnessed was the birth of a ruthless organization of criminals that will stop at nothing to see Stormwind turned to rubble.\n\nI need you to return to Sentinel Hill and let Gryan know that we are sending him troops. I hope it's not too late.", objectives = "Report to Marshal Gryan Stoutmantle at Sentinel Hill in Westfall.", completion = "Five years of work burned to the ground in five minutes. Damn the Defias!\n\nAnd this is only the beginning, <name>! We have a long, hard road ahead of us." }
WordHunterWoW_QuestEN[26371] = { title = "The Legend of Captain Grayson", description = "Have you heard of Captain Grayson? Some say that he's the figment of a drunken sailor's imagination, but anyone in Westfall will tell you that Grayson is real! He's a ghost that haunts the Westfall Lighthouse far to the west, off the coast of the Longshore.\n\nDo you dare investigate?", objectives = "Find Captain Grayson at the Westfall Lighthouse in Westfall.", completion = "Aye... I used to be flesh and blood, just like you, lad. That is, until that fateful day when the murlocs attacked the lighthouse..." }
WordHunterWoW_QuestEN[26372] = { title = "Pre-Flight Checklist", description = "This new engine is extremely fast. And dangerous. I'd use the word \"volatile.\"\n\nThat's the way the Captain likes it.\n\nRun back up the hill and let him know that I'll install this bad boy right now and that he should meet me at the construction site.", objectives = "Talk to Captain Krazz at Bilgewater Harbor in Azshara.", completion = "My airship has engines? At last!\n\nNow we can rip the heavens a new one!\n\nOnce the ground and naval forces are ready, we're going to light up the skies over the Twilight Highlands." }
WordHunterWoW_QuestEN[26373] = { title = "On to Kharanos", description = "Some of the mountaineers under Stonegrind's command were telling me about the situation out at Kharanos. When the troggs took over Frostmane Hold, it sounds like the surviving trolls fled westward, deep into the heart of the dwarven homeland.\n\nNow, they threaten the dwarven town of Kharanos. It sounds like they're going to need all the help they can get. You should go to Kharanos and introduce yourself to Captain Tharran. Just follow the road east out of Brewnall and keep going until you see the town.", objectives = "Speak with Captain Tharran in Kharanos.", completion = "If Gnomeregan Covert Operations is recommending you, then you must have made quite an impression. Your help will be most welcome here, as we've a wealth of enemies and few enough mountaineers to face them." }
WordHunterWoW_QuestEN[26374] = { title = "Ready the Ground Troops", description = "It was a bad idea to muster the troops in this festering goblin metropolis. Every vice that coin can buy is within arm's reach. Our mighty veterans are running rampant, blowing years of Northrend back-pay in a city-wide debacle.\n\nCan you make a sweep through the city and gather up any stragglers that have gone AWOL?\n\nMy axebite warriors are unmatched on the battlefield, but I won't have them disgrace their uniforms while on shore leave.", objectives = "Search Bilgewater Harbor and convince 12 AWOL Grunts to report for duty.", progress = "Have you found my missing troops?\n\nBe sure to search every filthy back-alley. If there's trouble, they'll find it.", completion = "Thank you, <name>! Most of my soldiers have already reported for duty, some a little worse for the wear.\n\nOne night in Bilgewater makes a hard orc humble.\n\nStill, fresh fighting in the Twilight Highlands should restore discipline." }
WordHunterWoW_QuestEN[26375] = { title = "Loose Stones", description = "The Twilight Cultists are taking my rocklings among them.  They drain them and torture them.  Strip them of the very essence that animates them from the stone.\n\nPlease, {race}, free my rocklings. Neither Diamant nor I have the delicacy to smash their chains without hurting them as well.  But we do have a tool you might use.\n\nUse this. Break their chains and set them free.", objectives = "Use the Delicate Chain Smasher to release 6 Quartz Rocklings.", progress = "It is unbearable to watch. They know no mercy. They should be offered none.", completion = "You are a generous <race>. You give back to the earth that offers you so much. You have my respect. You shall surely have the respect of the Stone Lords with time." }
WordHunterWoW_QuestEN[26376] = { title = "Hatred Runs Deep", description = "I would apologize for Boden, but stone is stubborn.\n\nIt does not sway from its ways without the wear of time.\n\nThe Stone Lords, Boden and I among them, are charged with retrieving the World Pillar.\n\nIn that, we are at odds.\n\nI would extend my patience upon you, {race}.\n\nProve that you are no ally of the Twilight Cult or Deathwing...\n\nCarry our hatred upon them.\n\nStrike swiftly where we cannot.\n\nSucceed and I will listen.", objectives = "Kill Dragul Giantbutcher and 12 Twilight Cultists at Lorthuna's Gate.", completion = "I have observed you, <race>\n\nYou do not fear shedding Twilight blood.\n\nIn this, I am willing to extend you some degree of trust.\n\nIt is a start.\n\nAll things in time." }
WordHunterWoW_QuestEN[26377] = { title = "Unsolid Ground", description = "The Twilight Cult are mining jade crystals near their camp.\n\nFoolish...\n\nReckless...\n\nGather the mined crystals. Take them to the center of their camp. Shatter them against the ground.\n\nThe reverberations and the powered crystal will bring the tunnelers upon them.\n\nThey will learn respect for the earth...\n\nPiece by piece...\n\nRock by rock...\n\n...with time.", objectives = "Gather 6 Jade Crystal Clusters, combine them, and shatter them within the Lorthuna's Gate encampment.", completion = "Time brings respect to all.\n\nThe smallest pebble.\n\nThe largest mountain.\n\nThe most stubborn cultist." }
WordHunterWoW_QuestEN[26378] = { title = "Hero's Call: Westfall!", description = "Westfall has fallen to hard times, friend. With the threat of the Defias extinguished, the region has become a haven for the homeless and downtrodden. The crime rate of the area has skyrocketed as people fight for shelter and food. Now I hear tale of murder!\n\nIf you are interested in helping the people of the Alliance, Westfall would be a great place to start. Report to Lieutenant Horatio Laine at the Jansen Stead. You'll find Westfall directly west of Elwynn Forest.", objectives = "Report to Lieutenant Horatio Laine at the Jansen Stead in Westfall.", completion = "Murder, rookie. That's what you're looking at on the ground in front of us." }
WordHunterWoW_QuestEN[26379] = { title = "In Aid of the Refugees", description = "You're come to help, I hope? You have no idea what I'm talking about, do you...\n\nI don't have time to fill you in on all of the details, but we had a town in Darkshore, Auberdine, that took some of the worst of the Cataclysm. We're in the process of rescuing some of the survivors, but I need someone with a bit more experience--someone like you--to check in on a refugee camp that we heard about in the south.\n\nLeave things to us up north. Head straight down there and help the refugees however you can.", objectives = "Sentinel Lendra at Lor'danel wants you to speak to Priestess Alinya at the Refugee Camp.You're come to help, I hope? You have no idea what I'm talking about, do you...\n\nI don't have time to fill you in on all of the details, but we had a town in Darkshore, Auberdine, that took some of the worst of the Cataclysm. We're in the process of rescuing some of the survivors, but I need someone with a bit more experience--someone like you--to check in on a refugee camp that we heard about in the south.\n\nLeave things to us up north. Head straight down there and help the refugees however you can.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26380] = { title = "Bound for Kharanos", description = "I was supposed to be bringing these casks of ale to the inn in Kharanos. They contain a mysterious new ale produced by an upstart brewery based in Brewnall Village. As I was leaving town, I was attacked by a Frostmane troll raiding party. It's going to take me days to repair the wagon!\n\nI don't suppose you'd be willing to do me a favor, will you? These big kegs aren't going anywhere, but I have some smaller sample casks. Would you bring them to Kharanos for me? Just follow the road to the southeast.", objectives = "Bring the Sample Casks to Innkeeper Belm at the Thunderbrew Distillery in Kharanos.", progress = "Welcome, visitor. Have you come to the inn to rest, or do you need a new hearthstone?", completion = "These look promising. I've heard great things about the Short and Stout Brewery, but I haven't had the chance to try their ale until now.\n\nWhile you're here, relax a little. If you need a spare hearthstone or wish to make Kharanos your home, just speak to me and I'll be happy to help." }
WordHunterWoW_QuestEN[26381] = { title = "The Eye of Shadra", description = "Shadra must be summoned, for certain. To allow an opportunity like this to pass us by would be foolish. While the apothecaries can make fine use of the god's venom, they are relatively inexperienced in ritual magic.\n\nFortunately, I am quite familiar with preparing dark convocations. You will bring the scattered parts of Shadra to me, and I will help you bring her to this plane to be taken out.\n\nThe first part is the eye of Shadra, guarded in Agol'watha to the north.", objectives = "Recover the Eye of Shadra from Agol'watha.", progress = "If the tablet was a ruse, I will not be pleased. Did you find the eye?", completion = "I'm pleased, <name>. That was quicker than I expected." }
WordHunterWoW_QuestEN[26382] = { title = "Can't Make An Omelette Without...", description = "Marnal has been pestering me about this Shadra plot for days. I'm almost upset he actually found the tablet; I was ready for him to shut up about it.\n\nDespite his high talk of ritual magic, he's still going to need my help as much as I need his. I've got to whip up a base medium with similar...\n\n...You know what, I'm not going to bother rambling about the details. Just bring me the Shadraspawn eggs from Agol'watha. There should be quite a few, guarded by the Vilebranch trolls.", objectives = "Collect 5 Shadraspawn Eggs from Agol'watha.", progress = "I hope you brought enough.", completion = "Good, good. Just put them over there, I've got my hands full." }
WordHunterWoW_QuestEN[26383] = { title = "Breaking Waves of Change", description = "You! You look able. And perhaps willing to help?\n\nAuberdine has finally fallen. Though many of its inhabitants departed long ago when the city first suffered the brunt of the Cataclysm, many of the more stubborn residents are yet unaccounted for. And it now appears that the city may have been overrun by water elementals.\n\nMy sisters need help rescuing the survivors. Please, {class}, use the western tree to reach Rut'theran, then speak to Vesprystus to secure a flight to Lor'danel. Be swift!", objectives = "Use the teleportation tree in western Darnassus to reach Rut'theran Village, then speak to Vesprystus to secure a ride to Lor'danel.", completion = "Did the sentinels send you? Thank Elune. We need everyone we can get." }
WordHunterWoW_QuestEN[26384] = { title = "Darkcleric Marnal", description = "We can't toss that tablet aside just yet, {name}. We can use it...\n\nYou see, I'm quite taken with the venom of the spiders here. It's clearly magical, probably related to that spider-god the trolls are involved with. And if that tablet will allow someone to summon it...\n\nWell, you can see where this is going. The Horde can't pass up this opportunity. Take the tablet to my fellow Forsaken. They're to the west, at the research station in the Hiri'watha ruins.", objectives = "Bring the Tablet of Shadra to Darkcleric Marnal.\n\nProvided item:", completion = "Ah, what have we here...\n\nFascinating. Quite fascinating." }
WordHunterWoW_QuestEN[26385] = { title = "Breaking Waves of Change", description = "It seems you have your first charge. You must travel back down to Rut'theran Village, where we first arrived, and speak to Vesprystus to secure a ride to Lor'danel.\n\nOnce in Lor'danel, aid the night elves in any way that you are able. I am trusting you to treat them with the reverence that they deserve in light of all that they have done for us.\n\nI must travel to the distant city of Stormwind to meet with King Anduin. I hope to see your face again very soon, {name}. Until then, a fond farewell.", objectives = "Speak to Vesprystus in Rut'theran Village to secure a ride to Lor'danel.", completion = "Our allies have come to our aid? Thank Elune. Tyrande was wise to extend open arms to your people.\n\nWe need help.  We need everyone we can get." }
WordHunterWoW_QuestEN[26386] = { title = "Surkhan", description = "Priestess is not very good at speaking Orcish, no.\n\nMaybe you go speak with Surkhan, upstairs.\n\nTell him about what you've seen inside Zul'Gurub, yes.", objectives = "Report to Surkhan at Bambala in Northern Stranglethorn.", completion = "<You explain to Surkhan what has happened up to this point.>\n\nIt would seem that Jin'do has survived, and he is rallying his brothers to once again summon Hakkar into this world.  It was good of you to come to speak with me.\n\nThere is not much we can do now but to wait, and watch.  Jin'do is weak, and prime for striking, but I must wait for word from Rastakhan before issuing orders.  Until then, you and your raptor will have to wait." }
WordHunterWoW_QuestEN[26387] = { title = "Starvation Diet", description = "The spiders infesting the Creeping Ruin to the east are useless. We're calling them shadraspawn now, and it's clear they're related to the spider god, but that doesn't change the fact that they're more trouble than they're worth. I'd much rather just wipe the little pests out.\n\nWhen you head to the creeping ruin, destroy any cocoons you find. They feed off the bodies inside for days, so depriving them of their meal will be much more effective than trying to squash them all.", objectives = "Destroy 6 Cocooned Victims at the Creeping Ruins.", completion = "Now we've got a win-win situation. The spiders are going to either starve off, or find some dwarves and elves to replenish their larder, since my colleagues and I would make a poor meal." }
WordHunterWoW_QuestEN[26388] = { title = "Twilight Skies", description = "Okay, you're all checked in. Wait here for Captain Krazz to bring the zeppelin around, then get on board and accompany the air fleet. Admiral Stonefist will be waiting for you outside of Dragonmaw Port!", objectives = "Accompany the Horde air fleet to Twilight Highlands. Catch your zeppelin from the tower at the Southern Rocketway Terminus in Azshara.", completion = "This is a disaster, <name>!\n\nOur air fleet was decimated. And reports are coming in that our navy was attacked - unprovoked - by the Alliance in open water.\n\nAnd what of Hellscream? Is the Warchief dead?" }
WordHunterWoW_QuestEN[26389] = { title = "Blackrock Invasion", description = "The orcs have begun burning down the forest, {name}! They have taken over the vineyard to the east and are planning their final assault against us! They must be stopped!\n\nHead east, across the river, and kill the rampaging Blackrock orcs. Collect their weapons as proof of their demise and return to me.\n\nYou're our only hope, {name}!", objectives = "Recover 8 Blackrock Orc Weapons.", progress = "Have you killed the rampaging orc hordes?", completion = "The Blackrock orcs will surely fall now that their main force has been defeated! Only one task remains." }
WordHunterWoW_QuestEN[26390] = { title = "Ending the Invasion!", description = "The rampaging orc horde is led by a savage beast known as Kurtok the Slayer! Kurtok is responsible for the recent invasion and must be killed if we are to have peace in the valley.\n\nVenture back east, across the river and through the vineyard, and look for the passage leading into the mountains. Kurtok will be there, preparing for another assault. Kill him and return to me.", objectives = "Kill Kurtok the Slayer.", progress = "Have you found Kurtok?", completion = "With Kurtok slain we are safe once again from the orcish hordes. I will send peasants to the pass in an attempt to seal the passage so that no more orcs may come through into our territory.\n\nYou have the thanks of Stormwind and of the Alliance, hero!" }
WordHunterWoW_QuestEN[26391] = { title = "Extinguishing Hope", description = "Times like these make me long for when the Defias were still around. The cataclysm has opened a pathway from the Burning Steppes and now Blackrock orcs pour into Northshire Valley! They have taken over my vineyard and are burning it to the ground! TO THE GROUND!\n\nPlease, {name}, that vineyard is all I have. Take my fire extinguisher and extinguish the flames at the vineyard. There still might be hope for that land!", objectives = "Use Milly's Extinguisher to put out 8 Vineyard Fires.", progress = "Have you put out the fires?", completion = "Bless your heart, <name>. You truly are a hero of the Alliance! Though the land is completely incinerated and there is nothing left of the vineyard but ash and debris, I still might be able to recover. Right? How bad can it be?" }
WordHunterWoW_QuestEN[26392] = { title = "Voucher of Bravery", description = "You've driven off the Blackrock orcs, and for that we are grateful! Though the vineyards have been burned to the ground, the rest of Northshire is safe, thanks to you.\n\nPlease accept this voucher outlining your bravery and deliver it to Marshal McBride. He is responsible for the safety of Northshire and he will be happy to hear about what you have done.You will receive:", objectives = "Deliver the Voucher of Bravery to Marshal McBride at Northshire Valley in Elwynn Forest." }
WordHunterWoW_QuestEN[26393] = { title = "A Swift Message", description = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Bartlett the Brave, our gryphon master.  He's just outside of the smithy; bring him my note, and then take a gryphon to Stormwind.", objectives = "Bring Argus' Note to Bartlett the Brave the gryphon master.", progress = "You look like you're in a hurry.  Well, then you came to the right place!", completion = "You have to get this note to Stormwind?  That's not a problem, you can take one of my gryphons!" }
WordHunterWoW_QuestEN[26394] = { title = "Continue to Stormwind", description = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Argus' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!", objectives = "Buy a gryphon ride from the gryphon master Bartlett the Brave, then bring Argus' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.", progress = "You've been traveling, eh?  Have you been anywhere interesting?", completion = "Ah, a note from Smith Argus?  I'm not surprised he needs more gear.  There are so many new recruits these days.\n\nWell thank you, <name>.  Here's some money to cover your travel costs." }
WordHunterWoW_QuestEN[26395] = { title = "Dungar Longdrink", description = "{name}, I gathered into this crate everything Argus asked for.  Can you take it to him?\n\nIf you've already spoken to Bartlett at Goldshire, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Argus as fast as you can.  We don't want our fighting men and women in Goldshire to go without fresh equipment!", objectives = "Bring Osric's Crate to Dungar Longdrink the gryphon master.", progress = "Is that sweat on your brow, lad?  You've been running too much.  Next time, take a gryphon!", completion = "A crate for Goldshire, eh?  People sure are getting lazy. Have you been to Goldshire before?  If so, then it's no problem, my friend.  I have plenty of gryphons trained to fly that route!" }
WordHunterWoW_QuestEN[26396] = { title = "Return to Argus", description = "The gryphon master in Goldshire is Bartlett.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Bartlett, so just speak with me again when you're ready to take a gryphon to Goldshire.  Once there, you can deliver Osric's Crate to Smith Argus.", objectives = "Buy a gryphon ride to Goldshire from the gryphon master Dungar Longdrink, then take Osric's Crate to Smith Argus at Goldshire.", progress = "You're back from Stormwind?  Did Osric send the armor?", completion = "Great, you brought the armor!  We'll get this divvied to those who need it immediately.\n\nThank you, <name>.  Your efforts have been a great help to us.  And now that you're no stranger to gryphons, I hope you'll come and lend your aid to Goldshire often!" }
WordHunterWoW_QuestEN[26397] = { title = "Walk With The Earth Mother", description = "Much has changed outside of Mulgore, {name}. The world is torn, and our Horde allies have turned down dark paths. We must guide them. Even in the darkest hour, we will bravely hold our heads high, and honor the Earth Mother in all we do.\n\nYou must go, {name}, and be this example. Go to Orgrimmar. Tell Saurfang how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, and never forget your people.", objectives = "Take the Mark of Bloodhoof to High Overlord Saurfang, located in Grommash Hold in Orgrimmar.\n\nYou may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin.", progress = "What makes you seek the Warchief of the Horde, <race>?", completion = "The Grimtotem forced from Mulgore... if Baine speaks for this, you are indeed a fierce warrior.\n\nFrom this day, your strength is no longer your own. It belongs to me, and the Horde, as a weapon of war.\n\nHellscream's eyes are upon you, <name>. Victory or death!" }
WordHunterWoW_QuestEN[26398] = { title = "Walk With The Earth Mother", description = "You have fought bravely alongside me, {name}, and done much for my people. If every {race} could be as noble, the future of the Horde might not disturb me so much.\n\nI would ask you to ease my worries further. Go to Orgrimmar. Tell High Overlord Saurfang how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, friend.", objectives = "Take the Mark of Bloodhoof to High Overlord Saurfang, located in Grommash Hold in Orgrimmar.\n\nYou may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin." }
WordHunterWoW_QuestEN[26399] = { title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that some {race} schmuck in a ridiculous {class} getup found this ogre hand, and...\n\n<Skeezy trails off as he looks you over.>\n\nWhat was I just saying?  Oh yes... some SWASHBUCKLING HERO found this ogre hand, and Mok'thardin thinks it means that the ogres have some special artifact.  I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Skeezy struggles fruitlessly to open the box.>\n\nThose ogres really know how to close a treasure chest, I'll tell you what.  A box is useless to me, hero.  We're going to need to find a way into this crate." }
WordHunterWoW_QuestEN[26400] = { title = "The Universal Key", description = "We're going to need something even stronger than those beefy {race} hands of yours to open this.  And the Venture Company schlubs to the northwest might have just the thing.\n\nLast time I was over there, I saw shredders walking around with giant rotating blades on their hands.  That's one way to open a box!\n\nIf you can't find any shredders, you might also try the giant sawblade in their lumber mill, by the lake.", objectives = "Open the Mosh'Ogg Bounty by fighting a Venture Co. Shredder or by using the sawblade in the Venture Company lumber mill.", progress = "You get that chest open yet?  I can't wait to see what's inside.", completion = "<The goblin peers inside.>\n\nWhaaaaaa?!?\n\nI'm... I'm going to have to send this to... to Flem... in the south.  He'll know what to do with it." }
WordHunterWoW_QuestEN[26401] = { title = "Return to Vestia", description = "The soft glow from the pedestal brightens, and you can see a simple chain left behind. Is this what the apprentice was searching for?", objectives = "Bring the Darkmist Amulet to Vestia Moonspear at the Tower of Estulan.", progress = "You're back... and without him...", completion = "How horrible... for someone so young and full of promise to fall to demons!\n\nI beg your forgiveness for sending you into danger as well, <name>. I hope you don't cross paths with that demoness again..." }
WordHunterWoW_QuestEN[26402] = { title = "General Shandris Feathermoon", description = "We druids do not keep very close company with the Sentinel army, but we are always willing to work together to defend our lands. Now that you have assisted me, I would be remiss in not requesting you assist them as well.\n\nShandris Feathermoon, general of the Sentinels, commands the war effort for all of Kalimdor from the newly built Feathermoon Stronghold to the south. Tell her I sent you; I am sure she will have need of your skills.", objectives = "Speak with Shandris Feathermoon at Feathermoon Stronghold in Feralas.", completion = "Telaron has already sent word of you, <name>. I'm interested in seeing if you're half as skilled as he claims.\n\nI am fighting a war on multiple fronts, while keeping our currently held areas properly defended, as well as overseeing the instruction of our youngest sentinels. If you're a decent fighter, there will be plenty for you to do." }
WordHunterWoW_QuestEN[26403] = { title = "Venture Company Mining", description = "Man, I hate the Venture Company.  They have a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti to the northwest are deeply interested in those strange blue crystals they have been finding in the mines.  Bring me samples of the stone from their geologists.  I don't care what you have to do to get them. ", objectives = "Bring 5 Tumbled Crystals to Skeezy Whillzap at Bambala in Northern Stranglethorn.", progress = "Do you have those crystals??  I need them!!\n\nI mean...I need to know the evil Venture Company is losing ground in Stranglethorn.  Because, you know, we honest folk have to make a living!", completion = "Great!  Wonderful!  I can get a bundle for these!!\n\nThat Venture Company sure picked the wrong jungle to mine in, didn't they?  We'd all be in better shape if they moved out of here." }
WordHunterWoW_QuestEN[26404] = { title = "Above My Pay Grade", description = "Hey, have you been to Hardwrench Hideaway yet?  Oh, you've GOT to see it.  It's everything a goblin could ever hope for.\n\nTell you what... you look like a stand-up {class}.  Raskha in the vest and the skirt over here can give you a ride, if you don't already know the way.\n\nThe flight's on me.", objectives = "Report to Sassy Hardwrench at Hardwrench Hideaway in the Cape of Stranglethorn.", completion = "Skeezy sent you to the right place.  Welcome to Hardwrench Hideaway!" }
WordHunterWoW_QuestEN[26405] = { title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel south to Zul'Mamwe and cull their wayward tribe.", objectives = "Kill 16 Skullsplitter Trolls within Zul'Mamwe.", completion = "As promised, your reward.  You do the troll nation proud." }
WordHunterWoW_QuestEN[26406] = { title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn.  Their venom is strong, {name}... don't get careless.", objectives = "Collect the Fang of Shadra from the Creeping Ruins.", progress = "Have you got the fang?", completion = "There it is... only one left." }
WordHunterWoW_QuestEN[26407] = { title = "Mosh'Ogg Handiwork", description = "This ogre was carrying an unusual item: the severed hand of another ogre, tied to a piece of string, and worn around the neck.  The hand itself is marked heavily with scars that glow a faint purple.\n\nA scar that glows after death is highly unusual, and to find such an item on an ogre is even stranger.  Perhaps someone back at Grom'gol will know what to do with this oddity.", objectives = "Bring the Disfigured Mosh'Ogg Hand to Far Seer Mok'thardin at Grom'Gol Base Camp in Northern Stranglethorn.", progress = "A hand, you say?", completion = "<The Far Seer makes sure to hold the item by the string, carefully avoiding the dead ogre's fist.>\n\nStrange indeed.  I will pass this on to my contacts in the east, near the Mosh'Ogg's main camp.  I have a feeling that they'll be interested in these strange scars.\n\nYou have my thanks, <race>." }
WordHunterWoW_QuestEN[26408] = { title = "Ashes in Ashenvale", description = "Darkshore may be battered and broken, but thanks to you, we've achieved some amount of safety here. Some amount of peace. We've much rebuilding to do.\n\nYou should continue on, friend. Garrosh has pressed the full might of his Horde against us in Ashenvale. They will kill all of us and chop the forest clear if we don't step forward to stop them.\n\nIf we are to have any hope of not losing those forests entirely, we'll need your help. Follow the road to the south and find Sentinel Shyela.", objectives = "Speak to Sentinel Shyela at Orendil's Retreat in Ashenvale.", completion = "Good to see a new face around here!\n\nThe forest crawls with Horde, but my assignment requires that I keep this outpost safe. I could really use someone who might be up for a good fight." }
WordHunterWoW_QuestEN[26409] = { title = "Where's Goldmine?", description = "My goblin initiate has been gone for quite some time. His name is Goldmine.\n\nI sent him out to observe the local rock flayers southwest at the Quartzite Basin. Perhaps you would be willing to find him? When you do, please ask him to come back to the temple.", objectives = "Find Initiate Goldmine at the Quartzite Basin in Deepholm.", completion = "Hiya! Lend a hand, would ya, bub?" }
WordHunterWoW_QuestEN[26410] = { title = "Explosive Bonding Compound", description = "This guy's the son of the Earthen leader! He almost made it to the temple when he got ambushed by more rock flayers than I can count!\n\nWe know that the Earthen Stonefather has the middle fragment of the World Pillar. Maybe if we were to heal his son, the Stonefather would give us the fragment?\n\nMy heals won't work on Flint here. But if we were to get some of the quartzite resin off of these monsters, I think I can make an explosive compound that will bond and cauterize his wounds.", objectives = "Collect 5 Quartzite Resin.", progress = "It won't take much resin. Those rock flayers are pretty dangerous though.", completion = "Good thing that I just happen to be a grand master of all things explosively alchemical.\n\nThis won't ignite on its own, though." }
WordHunterWoW_QuestEN[26411] = { title = "Apply and Flash Dry", description = "Alright, take this and apply it to his wounds. If the cauterizing effect of the flash dry explosion doesn't crack him wide open, it should completely heal him.\n\nI think.", objectives = "Use the Explosive Bonding Compound on Flint Oremantle.", progress = "Don't yap at me. Use the explosive bonding compound on Flint.", completion = "Looks like that did it. He should come to any moment now.\n\nI told you I was a grand master of alchemy!\n\nI've got some extra resin leftover. I can make it into all kinds of explosively wonderful stuff. What do you want?" }
WordHunterWoW_QuestEN[26412] = { title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that they're hiding some special, magical artifact in their cave.  Skeezy knows better, though.  I can smell money from a Mulgore mile away, and I'll bet that ogre doodad's worth a fortune.\n\nHere's a hint: I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound." }
WordHunterWoW_QuestEN[26413] = { title = "Take Him to the Earthcaller", description = "He still looks a little loopy to me. His head must still be ringing.\n\nBest get him inside the temple and see what the Earthcaller wants to do with him.\n\nI think I'm going to stay out here a little while longer and \"observe\" these rock flayers.", objectives = "Introduce Flint Oremantle to Earthcaller Yevaa at the Temple of Earth.", progress = "One of the Earthen? This is an unexpected and fortuitous surprise, <name>.", completion = "We are honored by Flint Oremantle's presence. I am given to understand that the Stonefather is in possession of a fragment of the World Pillar.\n\nIt is imperative that we recover all of the fragments. The instability between worlds is increasing. Soon it may become too great even for mighty Thrall to hold at bay." }
WordHunterWoW_QuestEN[26414] = { title = "Hitting a Walleye", description = "Sometimes, I fish for fun.  Other times to relax, but sometimes I want a challenge.  That's where the hardened walleye comes into the picture.  This prized fish is not caught for us to eat, but for the challenge.  You can find the walleye in Stormwind Lake just north of the city.  Think you are up to the challenge?", objectives = "Catherine Leland in Stormwind City wants you to bring her 8 Hardened Walleye.", progress = "Was the challenge too much for you?", completion = "Nice work <name>!  I see you are quite the fisherman these days.  Might just have to take you out on the boat soon and see what you can really do!" }
WordHunterWoW_QuestEN[26415] = { title = "Questflag for Captain's Log", description = "", objectives = "" }
WordHunterWoW_QuestEN[26416] = { title = "Well, Come to the Jungle", description = "My commander has sent me to scout for potential recruits to assist in the defense of Grom'gol Base Camp in Northern Stranglethorn.  Are you familiar with Stranglethorn?  It's a long way away... across the Great Sea, on the southern tip of the Eastern Kingdoms.  You fit the build he was looking for... interested in leaving Kalimdor for a while?\n\nIf so, then go talk to my cohort Bort in Orgrimmar.  He'll help you board the zeppelin.\n\nAnd tell him I said \"Woozle wozzle.\"  He'll know what it means.", objectives = "Report to Bort in Orgrimmar.", completion = "Hah!  That Cromula cracks me up.\n\nOh, right, Stranglethorn.  You're really going?" }
WordHunterWoW_QuestEN[26417] = { title = "Northern Stranglethorn: The Fallen Empire", description = "Commander Aggro'gosh is looking for devoted members of the Horde to assist him and his mission in Grom'gol.  If you're interested, just hop on up to the top of that zeppelin tower and board the Grom'gol zeppelin.  It's that easy!\n\nSeriously, Stranglethorn is the place to be right now... there's plenty of action to be found, and not nearly as much cataclysmic damage as, say... Stonetalon Mountains.  I wish I could go with you.", objectives = "Report to Commander Aggro'gosh at Grom'gol Base Camp in Northern Stranglethorn.", completion = "Glad you could make it!  Let's get to work, shall we?" }
WordHunterWoW_QuestEN[26418] = { title = "The Shell of Shadra", description = "We've one last part to collect, and then we'll have everything we need.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nSimple enough, no? Get up the steps of the altar and send her head rolling back down them. Bring the shell to me and we will have Shadra at last.", objectives = "Kill Qiaga the Keeper and collect the Shell of Shadra.", progress = "Do you have it?", completion = "Yes... it's finally time. Shadra will be ours!" }
WordHunterWoW_QuestEN[26419] = { title = "Shadra the Venom Queen", description = "<The ground rumbles as the idol sits on the altar, and the lake below roils! Shadra is emerging!>", objectives = "Kill Shadra the Venom Queen.", completion = "Excellently done. You have served the Dark Lady well today, <name>.\n\nThis virulent blood will supply our armies with all manner of powerful weapons against the disgusting Alliance. We will wipe them from these lands.\n\nFor the Horde, of course... and all thanks to you." }
WordHunterWoW_QuestEN[26420] = { title = "Diggin' For Worms", description = "Hey there, Angler!  Arnold here tells me that you have been looking for a new fishing spot and I think I know just the place.  North of Stormwind there is a great little spot called Olivia's Pond.\n\nThe pond is stocked with crystal bass every year but they are hard to catch.  They only bite on a very specific type of bait... overgrown earthworms.  If you search the shore around the pond, you should find plenty of worms to use as bait.", objectives = "Find an Overgrown Earthworm near Olivia's Pond and use it as bait to catch a Crystal Bass. Crystal Bass can be found in Olivia's Pond, north of Stormwind.", progress = "Did the bait work?", completion = "Those look like some nice bass, <name>.  Let's fry em' up and see how they taste!" }
WordHunterWoW_QuestEN[26421] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, <name>. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge." }
WordHunterWoW_QuestEN[26422] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, <name>. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge." }
WordHunterWoW_QuestEN[26423] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, <name>. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge." }
WordHunterWoW_QuestEN[26424] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, <name>. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge." }
WordHunterWoW_QuestEN[26425] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, <name>. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge." }
WordHunterWoW_QuestEN[26426] = { title = "Violent Gale", description = "There is a task that I can set before you.\n\nIt is a dangerous task. Completing it will help impress the more stubborn Stone Lords.\n\nTo the northwest is the Scoured Reach. Severe winds batter the rock and hide the true living threat underneath.\n\nWithin the Scoured Reach are Gyreworms. They devour rock and move through it as if it were water. They do the same thing to our rocky skin.\n\nFind Felsen the Enduring. Have him direct you to the Crumbling Depths. I will speak to you once you get that far.", objectives = "Find Felsen the Enduring and follow his instruction towards the entrance to the Crumbling Depths.", completion = "<The ground rumbles slightly as you approach the cave. This looks to be the entrance that Diamant and Felsen spoke of.>" }
WordHunterWoW_QuestEN[26427] = { title = "Without a Captain or Crew", description = "Not sure who you're with, but you don't look like one of... them.\n\nI'm not sure what happened.  I slept through supper and woke up to a ship full of dead people and murderers.\n\nNot sure if you want to kill me or not, but I'll spare you the trouble.\n\n<Moody points to a wound in his stomach.  His insides are not where they should be.>\n\nI can keep steering the ship for a while longer.  You don't die from a gut wound immediately.  Just bring me some rope and some rum... no, whiskey.", objectives = "Bring First Mate Moody a Bottle of Whiskey and a Spool of Rope.", progress = "You have what I asked for?", completion = "All right, help me get tied to the wheel.\n\n<Moody sips from the bottle.>" }
WordHunterWoW_QuestEN[26428] = { title = "To Steal From Thieves", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, she and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", objectives = "Take the heads of Kenata Dabyrie, Fardel Dabyrie, and Marcel Dabyrie.", progress = "Kill them all and bring me their heads!", completion = "You stand before me as a figure of vengeance, and I bow down before you in thanks.\n\nWith that cow's death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off." }
WordHunterWoW_QuestEN[26429] = { title = "Crush the Witherbark", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", objectives = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors.", completion = "The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed." }
WordHunterWoW_QuestEN[26430] = { title = "Revantusk Village", description = "Not all forest trolls are foul nuisances like the Witherbark. North of here in the Hinterlands is Revantusk Village, home to the only forest troll tribe still allied with the Horde.\n\nEven they cannot escape the cruelty of their brethren. The Vilebranch tribe wars with them, distracting them from our battle with the Alliance.\n\nYou have fought well here. Speak with Urda if you wish to fly to Revantusk. Their village will have use of your strength.", objectives = "Travel to Revantusk Village in The Hinterlands and speak with Elder Torntusk.", completion = "Welcome to Revantusk, <class>. I hope fighting the Witherbark hasn't exhausted you; the Vilebranch are even worse." }
WordHunterWoW_QuestEN[26431] = { title = "Archaeology", description = "Accept this quest to find archaeology points on your map!", objectives = "Accept this quest to find archaeology points on your map!" }
WordHunterWoW_QuestEN[26432] = { title = "The Fall of Jintha'Alor", description = "We've got more to deal with than just dwarves, mon. While I watch the village, my mate Primal Torntusk has gone to lead our warriors against the wicked Vilebranch tribe.\n\nThey've killed our brothers, and I was even taken prisoner by them once. No more! This time, the city of Jintha'Alor falls to us.\n\nGo to Jintha'Alor and speak with my mate. She's captured a camp near the entrance to the city.", objectives = "Find Primal Torntusk at Jintha'Alor in The Hinterlands.", completion = "Welcome, <class>. We're gonna make the Vilebranch regret ever crossin' us." }
WordHunterWoW_QuestEN[26433] = { title = "The Holy Water of Clarity", description = "Skeezy said you'd be coming.  Let's identify this... thing.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  The nagas to our southeast maintain a hallowed shrine that dispenses a water so clean, so fresh, and so mouthwateringly pure, that when the imbiber quaffs but a mouthful of the sacred stuff, their mind is cleansed and their best path made clear.\n\nSounds good, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", objectives = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", progress = "<Flem's ears perk up as you approach.>\n\nThe Holy Water of Clarity?  Is it here!?", completion = "<The goblin downs the water in one gulp.>\n\nAhh... do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nOh, right... your artifact, and clarity.  Clarity...\n\nI've got it!" }
WordHunterWoW_QuestEN[26434] = { title = "Primal Reagents of Power", description = "I see clearly now... the key to identifying this mysterious talisman revolves around obtaining some rare and precious items.  These Primal Reagents of Power, when properly combined, will reveal to us the origin of our treasure.\n\nTravel north, to the western side of the Gurubashi Arena, and hunt the cats that roam the jungle.  Their fleecy furs will lead us to the truth!", objectives = "Obtain 4 Supple Tiger Furs and 4 Velvety Panther Furs.", progress = "Make sure the reagents are extra-cushy, <name>.  A scratchy reagent simply won't do.", completion = "<Flem feels the hides and smiles to himself.>\n\nExcellent work, <name>!  These reagents will serve perfectly." }
WordHunterWoW_QuestEN[26435] = { title = "I'm A Huge Liar and a Fraud", description = "I have no idea what this artifact is.  I have no idea where I would even START finding out what it is.\n\nIn fact, I have no idea why anybody expected ME to be able to identify it in the first place.\n\nI asked for water because I was thirsty.  I asked for the jewelry and furs for... well, they're for my girlfriend.\n\nHopefully I can at least point you in the right direction.  Garley Lightrider in Booty Bay is a member of the Reliquary, and might be of more use than me.\n\nSorry.", objectives = "Bring the Opened Mosh'ogg Bounty to Garley Lightrider at Booty Bay in the Cape of Stranglethorn.", progress = "Yes, <race>?  I'm quite busy.", completion = "Fascinating!\n\nI'll need some time to study this.  Why don't you have a look around Booty Bay and come back later?" }
WordHunterWoW_QuestEN[26436] = { title = "Entrenched", description = "Your intentions appear true.\n\nI will impress upon the other Stone Lords my wary trust.\n\nWith this, they should speak to you.\n\nMore importantly, they should listen.\n\nEarning their favor may take time. Earning the Stonemother's favor may take more time. Time is a potent offering, so be generous with it.\n\nAmong the Shuddering Spires far to the northwest, you shall find Kor the Immovable. He is evenly tempered. His situation lends itself well to seeking outside aid.\n\nGo to him.", objectives = "Seek out Kor the Immovable among the Shuddering Spires.", completion = "Diamant says you are to be trusted. Diamant is patient and wise, so I shall allow you to prove yourself.\n\nAs it happens, I could use hands that are more... mobile." }
WordHunterWoW_QuestEN[26437] = { title = "Making Things Crystal Clear", description = "Among the Shuddering Spires are crystals. White, chalky crystals. We can absorb these crystals into our skin. To cleanse us. Purify us.\n\nI do not stride among the stones any longer. I am one with the earth. This carries many boons, but I can no longer retrieve the crystals for myself.\n\nBring me the crystals that I might be stronger. Carry them away from the flayers. Away from my sons. This honor should be mine.", objectives = "Collect 8 Chalky Crystal Formations.", progress = "Have you done this favor that I asked of you? Did you bring the crystals?", completion = "Ahh... invigorating. Thank you, fleshling." }
WordHunterWoW_QuestEN[26438] = { title = "Intervention", description = "The flayers have gone crazy with hunger. Their digging was once tempered and moderate. Now their hunger cannot be quenched. They grow murderously violent.\n\nThe flayers have turned on my sons. They overwhelm them. Kill them. It must stop.\n\nKill the flayers. They serve no purpose to the earth. Their passing will not be missed. Save my sons. Slaughter any flayers you find.", objectives = "Kill 12 Jaspertip rockflayers.", completion = "You've proven useful, <race>." }
WordHunterWoW_QuestEN[26439] = { title = "Putting the Pieces Together", description = "{race}. If you act in the service of the Stone Lords, there are those that might aid you.\n\nWatch for the Stonebound. They lie dormant all around the Shuddering Spires. It should not take much prompting to rebind them to service against the flayers.", objectives = "Aid 6 Dormant Stonebound Elementals in reforming.", progress = "<Berracite grumbles, and you feel the reverberations gradually roll by under your feet.>", completion = "Thank you, <race>." }
WordHunterWoW_QuestEN[26440] = { title = "Clingy", description = "<A miniscule elemental seems to have taken a liking to you.>\n\nCaris... carstr... crystal? <Pebble looks up at you expectantly.>\n\n<You did notice a very large crystal formation towards the middle of the Shuddering Spires. Perhaps you should take him there?>", objectives = "Bring Pebble to the large crystal formation in the Shuddering Spires.", progress = "<Pebble looks up at you expectantly.>", completion = "<The stones in Pebble's body bounce up and down happily. He seems very appreciative.>" }
WordHunterWoW_QuestEN[26441] = { title = "So Big, So Round...", description = "<Pebble looks around, excited by something. After a few seconds of confusion, he stops and stares up at you with big, glowy gem eyes.>\n\nHug-nery... hungry...\n\n<Try as you might, there's no resisting those eyes. Maybe Kor knows what mini-mentals like to eat?>", objectives = "Speak to Kor to find out what kind of food Pebble might like.<Pebble looks around, excited by something. After a few seconds of confusion, he stops and stares up at you with big, glowy gem eyes.>\n\nHug-nery... hungry...\n\n<Try as you might, there's no resisting those eyes. Maybe Kor knows what mini-mentals like to eat?>", completion = "You've made a friend, have you?\n\nAre you certain you want to feed him? He might become attached." }
WordHunterWoW_QuestEN[26442] = { title = "Rock Lobster", description = "If I could choose my last meal, it would definitely be fresh lobster tail.  Something about that tasty crustacean is just irresistible!  We recently started trapping lobsters here in Stormwind.  Would you mind heading out and checking the traps for me?\n\nOne more thing, watch out for the sharks.  They can be vicious down there.", objectives = "Collect 6 Rock Lobsters from the cages below the docks in Stormwind Harbor. Watch out for sharks!", progress = "Looks like you were able to avoid the sharks.  Were there any lobsters in the traps?", completion = "Looks like the traps are working!  Thanks <name>!" }
WordHunterWoW_QuestEN[26443] = { title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Forest Song to the north, the location where a new draenei settlement is being established.\n\nPerhaps Vindicator Vedaar at the Warsong Lumber Camp would be interested in these?", objectives = "Deliver the Diabolical Plans to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.", progress = "What do you have there, sir?", completion = "By the Seven Crystals of Ata'mal, this cannot be! They plan to attack Forest Song?!\n\nNot on my watch!\n\n<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>\n\nNo. We will not allow this to happen!" }
WordHunterWoW_QuestEN[26444] = { title = "Destroy the Legion", description = "I will not tolerate their existence on this world! The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world. Then they came again and we retreated, over and over.\n\nNo more!\n\nThere is a remnant of the Legion to the south and west in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge. They are what is leftover from a force that once long ago invaded this world.\n\nGo and destroy as many as you can before it is too late!", objectives = "Slay any 15 demons at Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge.", completion = "You have my respect and thanks, <class>. Perhaps we'll be able to create a new home here without having to worry about the Burning Legion yet again." }
WordHunterWoW_QuestEN[26445] = { title = "Never Again!", description = "{name}, it falls to you to see that this attack by the Burning Legion never comes to pass. You must go and slay their leaders.  Without them the demons will be mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge. To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.\n\nBring me their weapons.", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", progress = "Our night elf scouts report that preparations for the attack are almost complete. Those dreadlords must die soon, <name>!", completion = "Never again will the Burning Legion threaten Ashenvale! You have delivered us from a fight we very likely would have lost, <class>.\n\nI give you thanks, <name>, and the deepest gratitude of the Hand of Argus. It honors me to have you at our side!" }
WordHunterWoW_QuestEN[26446] = { title = "Reclaiming Felfire Hill", description = "Little one, to the southwest is an area of Nightsong Woods that has in recent times come to be called Felfire Hill. It is very sad to see the demons crawling over it, spreading their corruption.\n\nWould you do something to help take back the land?\n\nI have a number of seeds that I have been saving for such a purpose. Take them to Felfire Hill and plant them in the fertile dirt mounds.", objectives = "Plant 8 Tree Seedlings in the Fertile Dirt Mounds.", completion = "Good. Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against all of the enemies of Ashenvale." }
WordHunterWoW_QuestEN[26447] = { title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.\n\nYou're certain that Valusha at Splintertree Post would be interested in these.", objectives = "Deliver the Diabolical Plans to Valusha at Splintertree Post in Ashenvale.", progress = "What do you have there, scout?", completion = "Dreadlords!  They plan to attack us here at Splintertree Post?!\n\nNot while I still draw breath!\n\n<Valusha crumples the demon-scrawled plans in her fist.>\n\nNo.  We will not allow this to happen!  They are a blight upon our world!" }
WordHunterWoW_QuestEN[26448] = { title = "Destroy the Legion", description = "The remains of the demonic Burning Legion have been a thorn in our side for far too long!\n\nNo more!\n\nThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.\n\nGo and destroy as many as you can to bring glory to both yourself and the Horde!", objectives = "Slay 15 of any demon type at Felfire Hill, Demon Fall Canyon, or Demon Fall Ridge.", completion = "That's better!  There's nothing quite like ridding our world of a demon.  And they make for worthy opponents as well, unlike the weak races of the Alliance." }
WordHunterWoW_QuestEN[26449] = { title = "Never Again!", description = "{name}, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.\n\nReturn to me with their weapons as proof of your deeds.", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", progress = "Those dreadlords must die soon, <name>!", completion = "Never again will the Burning Legion make slaves of the orcs, or any other race of the Horde!\n\nBravely fought, <class>!  You have the true heart of the Horde beating inside of you!  You give us much honor!" }
WordHunterWoW_QuestEN[26450] = { title = "If They're Just Going to Leave Them Lying Around...", description = "I was just thinking about something, {name}.  Those naga have more than just reeds down there.  They tend to keep little statues lying around on their shrines, in the sand, under their trees.  They don't seem to be USING them.\n\nI could use those statues!  I could... put 'em around the camp, make it feel a little more homey.  Anything's better than a bloody dinosaur corpsepump.  I could sell them as souvenirs.\n\nI could sell them back to the naga!\n\nWhy don't you go grab a couple while I figure this out.", objectives = "Obtain 6 Naga Icons from the Southern Savage Coast in the Cape of Stranglethorn.", progress = "Let's see 'em!", completion = "Nice work, <name>.  Now I've just got to decide what to do with all of these..." }
WordHunterWoW_QuestEN[26451] = { title = "Gurubashi Challenge: Free-For-All Arena Combat", description = "The arena is a place of battle unlike any other.  Inside, you have no friends.  Alliances that do form are fleeting, as your allies can turn on you in the blink of an eye.  Horde vs. Alliance, Alliance vs. Alliance, Horde vs. Horde... anything goes.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", objectives = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger.", progress = "Why don't you get a little bit more blood on your armor before you speak with me again?", completion = "Well done, <race>!  Did you feel it?  The rush of the melee?  The true risk of free-for-all combat?\n\nAs today is your first day here, I'll let you perform in one more competition for another reward.  If you return in the future, you may compete again, once a day.  Your rewards will, of course, improve as you become stronger." }
WordHunterWoW_QuestEN[26452] = { title = "Gurubashi Challenge", description = "You've returned, {race}.  That means you've felt the call of the arena once more.  Very well.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", objectives = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger.", progress = "Why don't you get a little bit more blood on your armor before you speak with me again?", completion = "Well done, <race>!  I look forward to seeing you fight again soon." }
WordHunterWoW_QuestEN[26453] = { title = "A Helping Hand", description = "Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.\n\nThe task of building won't be easy, {name}, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested men his way.\n\nSpeak to me again and I will arrange for fast transport for you to their location.", objectives = "Speak with Architect Nemos at Forest Song in Ashenvale.\n\nVindicator Palanaar can offer you a ride to get you there more swiftly.", completion = "It's good to see another new arrival here at Forest Song.\n\nVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.\n\nTake a look around, <class>. It may not be much now, but with time and help from our night elf allies, we'll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome." }
WordHunterWoW_QuestEN[26454] = { title = "A Shameful Waste", description = "Welcome to Forest Song, {class}. Where you see tents, there will one day be buildings, but such ambition requires a steady stream of materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the west have no such reverence for the forest.\n\nWe shall reclaim the tainted wood from Satyrnaar to the west. Take the wood to Gnarl at the Warsong Lumber Camp. He is an Ancient who will purify it for our use.", objectives = "Collect 5 Satyrnaar Fel Wood.", progress = "<The ancient creaks as it turns toward you.>\n\nArchitect Nemos said that you might be bringing wood salvaged from befouled Satyrnaar.", completion = "Wood warped by foul demonic magic is of no use to the draenei at Forest Song. Nothing sound can be built with it, but I shall purify it and return it in good time to Architect Nemos and his people for their use.\n\nSome good will come from this tragedy, after all." }
WordHunterWoW_QuestEN[26455] = { title = "The Lost Chalice", description = "The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.\n\nThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, {name}.", objectives = "Obtain the Chalice of Elune.", progress = "Can you feel it, <name>, the touch of corruption upon the wind? If we do nothing, it will continue to advance. That is why I seek the Chalice of Elune. Were you able to find it?", completion = "Excellent work, <name>. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim.\n\nDo you see how it still shines, after all these years?" }
WordHunterWoW_QuestEN[26456] = { title = "Report from the Northern Front", description = "The battle against the Horde isn't being waged from Raynewood Tower alone, {name}. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southeast, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.\n\nI'm a bit late in sending my latest report to her, but also hesitant to leave the tower unattended.\n\nI am in dire need of your help in getting this report to her as soon as possible!", objectives = "Deliver Sentinel Melyria's report to Sentinel Farsong at Silverwing Grove in Ashenvale.", progress = "What's that you have there, <class>?", completion = "Thank you for delivering this report, <class>. From what Sentinel Melyria writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.\n\nWe can't afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I'm certain we could triumph.\n\nWill you join our fight? A new front has just opened in Warsong Gulch to the south." }
WordHunterWoW_QuestEN[26457] = { title = "Agents of Destruction", description = "The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!\n\nNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, {name}, and we will show them that we'll not suffer further destruction of our lands!\n\nGo, and do not rest until Overseer Gorthak and his minions are dead!", objectives = "Slay Overseer Gorthak and any other 12 Horde at the Warsong Lumber Camp.", completion = "At last we have sent a message that the orcs won't dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!\n\nWe must press our advantage, <name>, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground.\n\nNow what was this about explosives...?" }
WordHunterWoW_QuestEN[26458] = { title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps to the west.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.You will receive:", objectives = "Bring 10 Twilight Pendants to Sentinel Aluwyn at the Blackfathom Camp." }
WordHunterWoW_QuestEN[26459] = { title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the sin'dorei are headed toward. In Blackfathom Deeps, just to the west, you will find both satyr and naga.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Relwyn Shadestar at the Blackfathom Camp wants 8 Corrupt Brain stems." }
WordHunterWoW_QuestEN[26460] = { title = "In Search of Thaelrid", description = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps to the west.\n\nMy role here is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been days now since I sent a scout to check on the activity inside Blackfathom Deeps. Scout Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out Thaelrid for me, <name>.Upon completion of this quest you will gain:", objectives = "Seek out Scout Thaelrid inside Blackfathom Deeps.Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps to the west.\n\nMy role here is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been days now since I sent a scout to check on the activity inside Blackfathom Deeps. Scout Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out Thaelrid for me, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26461] = { title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, <name>, please.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp." }
WordHunterWoW_QuestEN[26462] = { title = "The Wicked Revantusk", description = "These Revantusk trolls think they're special for bein' in the Horde. Makes me laugh!\n\nSee, the funny part is, it doesn't matter if they're part of the Horde, or some kinda troll empire, or the bloody Burning Legion for that matter. We've fought trolls in these lands for a few centuries now.\n\nIn fact, I'll be kind enough to let you lend a hand, lad! Grab a weapon and head out to the battlefield and help our boys to the east.", objectives = "Kill 10 Revantusk Stalkers or Revantusk Hexxers.", completion = "Not bad for a city-dwellin' <race>. Good show, aye!" }
WordHunterWoW_QuestEN[26463] = { title = "Finding Teronis", description = "A friend of mine from Astranaar, Raene Wolfrunner, asked me to send a scout west to Lake Falathim. Teronis left days ago, just before the Horde attacked.\n\nHe was searching for an item he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left, he mentioned a gem for the rod. Unfortunately, we know that the lake has been invaded by some evil force.\n\nPlease, {name}, find my friend.\n", objectives = "Find Teronis at Lake Falathim in Ashenvale.", completion = "Teronis' body lies broken atop the small rise next to the Keeper.\n\nDeep slashes crisscross his corpse." }
WordHunterWoW_QuestEN[26464] = { title = "The Lost Gem", description = "As you rummage through Teronis' belongings, you find a water-damaged journal.\n\nQuickly flipping through the last legible pages, you read that Teronis makes mention of finding the gem, but then of having lost it in the Falathim area.\n\nThe only thing left to do is find it. Perhaps the tendrils have it...?", objectives = "Find the Glowing Gem.", progress = "Ah, welcome back, <name>.", completion = "This is terrible, <name>. Teronis is dead?!\n\nThe time for mourning will come, but for now we must focus our efforts. I will send some of the Sentinels to recover Teronis' body and to assist the keeper.\n\nYou have the gem that Teronis was seeking? It must be delivered to Astranaar." }
WordHunterWoW_QuestEN[26465] = { title = "The Ancient Statuettes", description = "I would charge you with a task, {class}.\n\nI was on my boat, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws! I fled and the rest, as they say, is history.\n\nI am an archaeologist of sorts, and I am attempting to recover artifacts of the lost city.\n\nWill you head out onto the Zoram Strand to the southwest and recover any ancient statuettes you come across? They are the reason I have braved the dangers of the Zoram Strand.", objectives = "Collect 10 Ancient Statuettes.", progress = "Have you found many statuettes, <name>?", completion = "That's quite a few that you have found! Thank you, <name>!\n\nThe old city of Zoram holds many secrets, and these statuettes may be the key to many of them." }
WordHunterWoW_QuestEN[26466] = { title = "Ruuzel", description = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to their ancient locks.\n\nThat key is a ring, the Ring of Zoram. It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on her isle on the northern edge of the Zoram Strand. Please, {name}, retrieve the ring for me!", objectives = "Obtain the Ring of Zoram.", progress = "It is said that the Ring of Zoram is the key to any lock within the city. Do you have it, <name>?", completion = "You found the ring! Thank you, <name>.\n\nPlease take this as payment, and know that your deeds today will remain forever in my memory." }
WordHunterWoW_QuestEN[26467] = { title = "Vile Satyr! Dryads in Danger!", description = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n{name}, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", objectives = "Find Anilia at Xavian in Ashenvale.", completion = "Judging by the gaping wound in her side, Anilia is on the verge of death." }
WordHunterWoW_QuestEN[26468] = { title = "The Branch of Cenarius", description = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.", objectives = "Obtain the Branch of Cenarius.", progress = "Have you found them? What did Anilia say? Where is she?", completion = "Anilia died? No... that can't be! It was just yesterday that we were running and playing together in the woods.\n\nI guess those days are over..." }
WordHunterWoW_QuestEN[26469] = { title = "Satyr Slaying!", description = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.", objectives = "Obtain 16 Satyr Horns.", progress = "Please, help me avenge Anilia's death.", completion = "Thank you, kind <race>. My sister's spirit is gladdened by your efforts." }
WordHunterWoW_QuestEN[26470] = { title = "Retaking Mystral Lake", description = "We could easily have held Silverwind Refuge from the Horde had they not taken control of our water elemental defenders on Mystral Lake.\n\nOne of their shaman summoned in Tideress, an old and angry water spirit of the forest who befouled our elementals and turned them against us. With the lake and the Horde pressing in on us, we had no choice but to retreat to the spire here.\n\nGo east. Take the lake back so that we will have a chance to retake the refuge some day.", objectives = "Slay 12 Befouled Water Elementals and Tideress.", completion = "Well done, <name>! With the befouled elemental numbers thinned and Tideress put back into the lake, we should be able to launch a counter-offensive on Silverwind Refuge.\n\n\n\nJust as soon as we're done with defending the spire...." }
WordHunterWoW_QuestEN[26471] = { title = "Knowledge in the Deeps", description = "It is my duty to collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that could awaken more of Those Who Sleep if it is mishandled.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in to the west. That place is the old dwelling of our long-dead ancestors. They held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript. Do this, and I will not forget it. Not even in these end days.You will receive:", objectives = "Bring the Lorgalis Manuscript to Sentinel-trainee Issara at the Blackfathom Camp." }
WordHunterWoW_QuestEN[26472] = { title = "Insane Druids", description = "The druids are dead, killed by their leaders who were driven insane by the Horde tainting the Forest Heart! I can feel the corruption even from here and I dare go no further.\n\nWhile I am too well attuned to Ashenvale and the Forest Heart, you... you could descend into the barrow den and do what must be done. I've laid down breadcrumbs for you in there.\n\nThough it tears me apart, I must ask that you put to rest the druids' once great leaders: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", objectives = "Slay the insane druids: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", completion = "Rest in peace, my friends.\n\n<You can see the sorrow in the druid cat's eyes.>\n\nI felt the anguish of the Dor'danil Barrows lessen, and knew that you had completed your task.\n\nIt was grim work that you did, <name>, for the spirits you destroyed were merely victims of the Horde's evil. But with their destruction, let us hope the maddened spirits will finally find peace." }
WordHunterWoW_QuestEN[26473] = { title = "Bathran's Hair", description = "There is a plant that grows in the old ruins of Bathran's Haunt across the road to the east. The plant is called Bathran's Hair and is known to cure ailments of the spirit.\n\nNow the Horde are there harvesting the plant for their own evil schemes.\n\nThere is a sick child in Astranaar, and we believe that her illness is more than just physical. I promised my master that I would help seek a cure, but I am no fighter.\n\nWill you go to Bathran's Haunt and gather the plants?", objectives = "Collect 8 Bathran's Hair.", progress = "Have you gathered the Bathran's Hair, <name>?  The child's health grows weaker by the hour....", completion = "Ah, you have the hair! This is a good first step. There are other ingredients that we will need, but the hair of the fallen Ancient could well be the most important.\n\nI only hope that whatever the Forsaken are devising from the plant will not be turned into a weapon. We simply do not have the numbers to remove them right now, especially with Maestra's Post under attack!" }
WordHunterWoW_QuestEN[26474] = { title = "Orendil's Cure", description = "{name}, now that it has been bathed in Elune's blessed light, I believe that the concoction will help the afflicted child. Please, take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south and then east. However, if you'd like to get there more swiftly, speak with Sentinel Avana.", objectives = "Bring Orendil's Cure to Pelturas Whitemoon at Astranaar in Ashenvale.", progress = "I must apologize, for I have no time to speak. My child, Relara, is deathly ill!", completion = "This is from Orendil?\n\nHis skill with herbs and healing is great! This cure gives me hope, when before I had little...." }
WordHunterWoW_QuestEN[26475] = { title = "Elune's Tear", description = "I'd hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through her. We must find more powerful medicine! Thankfully, Orendil spoke to me of further remedies should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the remains of Iris Lake, destroyed by the eruption of Thunder Peak, northeast of Astranaar. Orendil said the stone will wash away corruption.\n\nPlease, {name}, bring me Elune's Tear and pray it will end my child's sickness!", objectives = "Collect Elune's Tear.", progress = "<name>, did you find the remains of the lake?  Do you have the Tear?", completion = "Oh, you found it! Odd... it looks tarnished somehow. I will place the tear in a stew, and pray that it will cure her.\n\nThank you! Thank you, <name>!" }
WordHunterWoW_QuestEN[26476] = { title = "Dryad Delivery", description = "Ah, there you are, {name}. I've pored over the notes Teronis has made and it sounds like your next course of action is to find the other pieces of Dartol's rod.\n\nI would start by heading east along the road to Raynewood Tower.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.", objectives = "Deliver the Glowing Gem to Shael'dryn at Raynewood Tower in Ashenvale.", progress = "Hello. How are you?", completion = "Oh, Raene sent you? It must be serious indeed.\n\nWhat can I help you with?" }
WordHunterWoW_QuestEN[26477] = { title = "Search the Bole", description = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nTo find the next piece of the rod, you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here near the Felwood border, at the Howling Vale. Once you have it, look for a small glade through the tunnel at the vale. The chest should be hidden around there.", objectives = "Find the Wooden Key and use it to obtain the Iron Shaft portion of Dartol's Rod.", progress = "It upsets me so that the treants have become corrupt. I wish I could do more to help them.", completion = "I'm pleased to see you're back, <name>." }
WordHunterWoW_QuestEN[26478] = { title = "Playing Possum", description = "The last piece of the rod is held by druids of the claw. I asked their leader, Oso Bramblescar, to give it to me, but he and his guardians nearly killed me! Clearly they too were affected by the Horde's corruption of the Forest Heart.\n\nBut, I have an idea for how you can get into Oso's cave and grab the pommel.\n\nEver since I was a faun, I've been pretty good at playing possum. It works great against bears! I can teach you! Go east to the Shady Nook, and if they try to get you, just use my technique.\n", objectives = "Obtain the final piece of Dartol's Rod, the Iron Pommel.", progress = "Did you find the final piece of the rod, <name>? How did my technique work?", completion = "You got it? Wonderful for you... and for Raene!\n\nI guess we'll have to see about reassembling it, won't we?" }
WordHunterWoW_QuestEN[26479] = { title = "Return to Raene", description = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nBe careful... I sense a great deal of power within it for both good and ill. I hope that you and Raene know what you are doing.\n\nGood luck, {name}.", objectives = "Deliver Dartol's Rod to Raene Wolfrunner at Astranaar in Ashenvale.", progress = "Yes, <name>? How go your efforts?", completion = "You've recreated the rod Teronis had set out to find? That's wonderful to hear.\n\nShael'dryn has been indispensible in her assistance. Teronis would be proud to see his quest is continuing even after his tragic passing.\n\n<Raene looks over the reconstructed rod with a look of approval and thoughts racing behind her eyes.>\n\nNow it is time for us to make use of its power to eliminate the enemies of Ashenvale!" }
WordHunterWoW_QuestEN[26480] = { title = "Dartol's Rod", description = "I'm not completely certain what Teronis had in mind next, but if what he said was true about the rod's power, then it will allow you to take on another form altogether, presumably that of a furbolg.\n\nPerhaps he meant to use its powers to get closer to them, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was uncorrupted.\n\nI would start with one known as Krolg. Seek his hut southeast of Mystral Lake.", objectives = "Use Dartol's Rod to be able to communicate with Krolg at Krolg's Hut in Ashenvale.\n\nProvided item:", completion = "Yes, yes... you appear as one of my kind, but I care not what you truly are if you can help the furbolg.\n\nThe night elves and now the orcs have visited many atrocities upon my people.\n\nCorruption runs through our veins, corruption brought down upon us by the prideful night elves and the warlike orcs. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.\n\nAt night I can still see the campfires burning in the darkness." }
WordHunterWoW_QuestEN[26481] = { title = "A New Adornment", description = "I'm certain that the long-dead wizard, Dartol, intended to use his rod to subjugate and destroy us just as the night elves and orcs have, but I think now we'll put that thing to an unintended use.\n\nRan Bloodtooth is the king of all of the Ashenvale furbolg. His tribe, the Bloodtooth, are the most powerful and keep themselves secluded in a camp just to the east.\n\nKill them all and bring back his skull. Let us see if we can put it to good use.", objectives = "Obtain Ran Bloodtooth's Skull and Dartol's Rod.", progress = "Have you slain Ran yet, my friend? We must have his skull if you're to deliver my people from bondage.", completion = "You have done well, my friend.\n\nNow quickly, hand me Ran's skull. While his essence yet taints it, we shall fashion it upon Dartol's Rod giving you the power to influence my brethren and deliver them from evil!" }
WordHunterWoW_QuestEN[26482] = { title = "True Power of the Rod", description = "Now, take the rod and while using its power, speak with my brother, Ota Wen.\n\nOta is amongst the other furbolg that the orcs have captured and have penned in the giant cage on the north side of Silverwind Refuge. The rod will allow you to convince Ota and the other furbolg to rise up and attack the Horde.\n\nThen you may go wherever your path leads you. Just know that you have found a new friend for that which you have done.", objectives = "Use Dartol's Rod and speak with Ota Wen. Convince him to rise up against his Horde oppressors. Then, deliver Dartol's Rod to Raene Wolfrunner.", progress = "You return, <name>. What's that affixed to the top of the rod? A skull?", completion = "So, you used the skull of the furbolg king to modify the power of Dartol's Rod? You then used that power to convince the captured furbolg to rise up and attack the Horde at Silverwind Refuge?\n\nI am more than pleased and impressed with your abilities, <name>. The Sentinels cannot thank you enough. It should be a simple matter for us to sweep away the orcs and retake the refuge now!\n\nTeronis would be proud. You have my deepest respect." }
WordHunterWoW_QuestEN[26483] = { title = "Gan'dranda", description = "As fun as it is to butt heads with these trolls, we've got other things to do down here. It'd be nice to get this battle over with, aye?\n\nTheir commander, Gan'dranda, sits in the ruined walls to the southeast of the battlefield. Our boys have most of their forces locked up, so I want you to slip in there and take out Gan'dranda. When they see a {race} standin' over the corpse of their biggest hero it should take some of the fight out of 'em!", objectives = "Kill Gan'dranda.", completion = "Now that's what I like to hear! Good on ya." }
WordHunterWoW_QuestEN[26484] = { title = "To Stonehearth's Aid", description = "The earthen and the stone troggs somehow found their way to Deepholm through Uldum more than fifteen thousand years ago. They've been warring ever since.\n\nIf we're to recover the middle fragment of the World Pillar, the Stonefather must be rescued.\n\nPlease go to Stonehearth and do everything that you can to aid the Earthen in their war against the stone troggs.\n\nYou're our best hope, {name}.", objectives = "Speak with Crag Rockcrusher at Stonehearth in Deepholm.", completion = "The Stonefather's son, Flint, sent you? No time to talk.\n\nWe must prevent a second front from opening up on the war!" }
WordHunterWoW_QuestEN[26485] = { title = "Snapjaws, Lad!", description = "I've got plans to brew up somethin' special for those pesky trolls. Aye, I said for them... a brew they won't ever forget! A brew that'll have them pickin' their tusks out of the hillsides!\n\nI've got a few ingredients steepin' already, but I could use a hand gatherin' more. At the bottom of the Overlook Cliffs to the east, near the shore, is a whole mess o' snapjaws. I need fresh, whole gizzards from them for my blastbrew.", objectives = "Collect 8 Snapjaw Gizzards from Saltwater Snapjaws.", progress = "Got those gizzards?", completion = "Ah, nice an' fresh. I'll get those going while you fetch me some more goods then..." }
WordHunterWoW_QuestEN[26486] = { title = "99 Bottles of Booze on the Beach", description = "Now, I know we've got a little battle ragin' and all that, but down at the overlook cliffs are some nice lookin' bottles strewn all over the place. I don't want good drink to fall into the hands o' the Horde!\n\nIf you're down that way, collect the bottles for me and bring 'em back here. I'll pay in full for it as if you bottled 'em yourself.", objectives = "Collect 12 bottles of Pupellyverbos Port.", progress = "About 12 should do the trick, aye?", completion = "That's the stuff! Wouldn't want any trolls or goblins gettin' pleasure out of these, now would we!\n\nMaybe I can work a bit of this into my next brew..." }
WordHunterWoW_QuestEN[26487] = { title = "Akiris by the Bundle", description = "It's not easy running a combination 5-star exotic resort/jungle resource salvaging plant!  That is, it wouldn't be easy, if I didn't have the organizational skills of a trade prince's personal assistant!\n\nThe first trick is multitasking.  For example: the naga explorers to our south carry a valuable ocean reed - Akiris reeds.  We can sell these reeds to our clients overseas, and we can also stuff our visitors' mattresses with them!  Come to think of it, we could probably use some more of that stuff.", objectives = "Obtain 6 Akiris Reeds from Naga Explorers.", progress = "Let's see... we're going to need some shotguns for our nature hikes, rowboats for the oil rig day trip, and...\n\nOh, you're back already?", completion = "Hey hey!  Not bad, not bad at all!  You may have a future in resource acquisition.  Or hotel management." }
WordHunterWoW_QuestEN[26488] = { title = "Big Gulp", description = "Arnold and I used to relax down at the moat in the Valley of Heroes.  One day, I lost my locket in the lake and I have never been able to find it.  Rumor has it that huge royal monkfish live in that moat and that they eat anything!  I know it's a long shot, but do you think you could catch a few monkfish and look for my locket?\n\nPlease let me know right away if you find it, it's very precious to me.", objectives = "Fish up a Royal Monkfish from the moat in the Valley of Heroes district of Stormwind. Once you catch a monkfish, fillet it and check if it swallowed the locket.", progress = "Were you able to find my locket?", completion = "You found it!  I can't believe it was down there all those years!  You have no idea how much this means to me <name>." }
WordHunterWoW_QuestEN[26489] = { title = "It's You!!", description = "Yes, can I help...\n\n<Sassy's jaw drops to the floor.>\n\n{name}!  Is it really you?!  Look how big and strong you've gotten!  Let me feel that bicep!\n\nMe?  I've been trying to make my gold here in the jungle.  We're mainly in resource acquisition, but we also do tourism.\n\nI know, genius, right?\n\nHey, listen.  I was thinking... the naga explorers to the south carry Akiris reeds, which we could sell, and use to stuff visitor mattresses.  You interested in killing some naga?  It'll be just like old times!", objectives = "Obtain 6 Akiris Reeds from Naga Explorers.", progress = "Let's see... we're going to need some shotguns for our nature hikes, rowboats for the oil rig day trip, and...\n\nOh, hey Boss <name>.  You're back already?", completion = "I knew you had it in you, boss-man.  You know what they say: You can take the <race> out of the islands, but you can't take the murderous tendencies out of <name>." }
WordHunterWoW_QuestEN[26490] = { title = "Prime Slime", description = "Not many dwarves know this, but to get a REAL kick out of my brew I add a wee bit of the oozes around here. Aye, the giant green dwarf-eatin' oozes, those ones.\n\nThis brew's gonna have a HUGE kick to it though, so we need a huge slime! There's one lurkin' down in Skulk Rock that's the mother o' them all, absolutely huge...the Direglob, we call it.\n\nIf you've got what it takes, head down there and take a chunk out of the Direglob for me!", objectives = "Collect a Direglob Sample from The Direglob.", progress = "Aye, do ya have it?", completion = "Look at it! That'll put some oomph into the mix!" }
WordHunterWoW_QuestEN[26491] = { title = "Skulk Rock Clean-Up", description = "Years ago, there used to be a Horde base deep within Skulk Rock. It's been abandoned since then, but it's still prime territory, worth takin' for our allies!\n\nProblem is, it's full of dwarf-eating slimes and oozes. Those things are slightly less disgustin' than trolls, but they'll still give us a hassle.\n\nWith our boys tied up fightin' the Revantusk, I need you to go to Skulk Rock and clear the place out for me.", objectives = "Kill 10 Jade Oozes.", completion = "It's good to see you back... and not missing any limbs, either." }
WordHunterWoW_QuestEN[26492] = { title = "Skulk Rock Supplies", description = "I had a cousin in the second war! He used to tell me all about when they led a raid on Skulk Rock. Swept in there and drove the trolls out like rats from a nest. They chased right after 'em all the way to Alterac!\n\nThe slimes moved in right quick after that, and there's still cratefuls of old Horde goods sittin' in there. I say we don't let the trolls get it back!\n\nBring me back a few crates from Skulk Rock to the northwest.", objectives = "Collect 5 Ooze-Coated Supply Crates.", progress = "You got the crates?", completion = "Looks like it's still good inside! Huh... is that banana bread? Still fresh!\n\nHere, lad, take your share of goods." }
WordHunterWoW_QuestEN[26493] = { title = "There's Somebody Out There Who Wants It", description = "So, while you're already all sweaty from doing all that other stuff, I was thinking I might grab you for one more task.  You don't mind, do you?\n\nThe latest Science and Explosions journal just came in from Bilgewater Harbor, and there's this article about this hot new reagent.  Prices on the reagent are skyrocketing, and we're in prime position to capitalize!\n\n<Sassy leans over and whispers the details into your ear.>\n\nYou got that?  Good.  You can find the basilisks in a cave, far to the east.", objectives = "Obtain 7 of Sassy's Secret Ingredient from Thrashtail and Ironjaw Basilisks in the Crystalvein Mine.", progress = "I hope you used the extraction procedure we discussed.", completion = "Great!  These look... disgusting.  But probably pretty valuable.  Let's get to splitting these up.  Some for me, some for Jasper, some for Chabal..." }
WordHunterWoW_QuestEN[26494] = { title = "Mixmaster Jasper", description = "Mind giving some of this stuff to Jasper, over by the luxury suites?  I'm sure he can find some use for it.\n\nThanks, {name}!", objectives = "Bring Sassy's Samples to Mixmaster Jasper in Hardwrench Hideaway.", progress = "Hey, is that the stuff?  From the magazine?", completion = "I'll file these away for now.  Maybe we can experiment later.\n\n<Jasper looks over at you.>\n\nYeah, you'll do." }
WordHunterWoW_QuestEN[26495] = { title = "Chabal", description = "Chabal, that troll over by the botanical gardens/biological weapons lab, is a special guest.  He's a representative of the Zandalari trolls, and has traveled quite far to stay with us.\n\n<Sassy places some of the items you've collected in a small parcel and hands it to you.>\n\nHere, give this to him.  Tell him that the Zandalari are always welcome at Hardwrench Hideaway!  And mention that referrals are key to maintaining our business!", objectives = "Bring Sassy's Largesse to Chabal in Hardwrench Hideaway.", progress = "Care to explain yourself, <class>?", completion = "<The troll looks into the package.>\n\nYou have my thanks.\n\nI have been waiting for you to approach me, <race>.  I have identified you as the most promising <race> here in this strange town.  I have a task for you, if you would be willing to take it." }
WordHunterWoW_QuestEN[26496] = { title = "Down with the Vilebranch", description = "The Revantusk isn't the only tribe of foul trolls we're here to take care of! The Vilebranch have corrupted this land for years from their stronghold of Jintha'Alor.\n\nWe're done sittin' by in Aerie Peak twiddlin' our thumbs, if you haven't noticed. Doran Steelwing leads the charge against the Vilebranch from a camp the boys took just to the south. Speak with him and join the fight!", objectives = "Find Doran Steelwing at Jintha'Alor in The Hinterlands.", completion = "Well met, <name>! We've got a lot of trolls to kill and only so many hands to do it with!" }
WordHunterWoW_QuestEN[26497] = { title = "Vilebranch Scum", description = "The Vilebranch are a different tribe from the Revantusk, but the difference is academic. Far as we're concerned the only good troll is a dead troll!\n\nBut make no mistake, the Vilebranch are just as nasty even without the Horde's chain around their neck. They'll poison this whole land unless we take this stand and get rid of them\n\nYou can start with their witchdoctors and headhunters on the lower tier. Let me know when you've killed a fair share of 'em.", objectives = "Kill 5 Vilebranch Witch Doctors and 5 Vilebranch Headhunters in Jintha'Alor.", completion = "Aye, we'll have these trolls cleared out yet." }
WordHunterWoW_QuestEN[26498] = { title = "Death to the Vilebranch", description = "We're makin' good progress. Keep pressing on, and don't falter!\n\nThe Vilebranch berserkers fight like savage animals, whipped into a blood frenzy. Their shadowcasters summon foul spirits from beyond this world! This is why we're getting rid of these depraved creatures, {name}, never forget that.\n\nHead to the middle tier and kill the berserkers and shadowcasters!", objectives = "Kill 5 Vilebranch Berserkers and 5 Vilebranch Shadowcasters in Jintha'Alor.", completion = "It won't be long until we're the only dwarves left breathing on these walls." }
WordHunterWoW_QuestEN[26499] = { title = "Stonefather's Boon", description = "With the Stonefather taken prisoner, our forces are demoralized. Normally any one of mine could take five times his number of stone troggs. But now....\n\nI want you to head out into the field surrounding the town. Plant Stonefather Oremantle's banner near my defenders. Grant them his boon and remind them of that for which they fight.", objectives = "Grant the Stonefather's Boon to 12 Earthen Defenders.", progress = "Rally more of our troops, <name>.", completion = "You have my thanks, <name>. You've made all the difference, and the fate of these cowardly stone trogg ambushers is set in stone.\n\nNow we must get about the business of retaking Stonehearth." }
WordHunterWoW_QuestEN[26500] = { title = "We're Surrounded", description = "Our war has been waged for longer than your kind counts time. Let us see if you can make a difference, {race}.\n\nThe stone troggs are a mistake of the titans. On your world they have succumbed to the Curse of Flesh. But here, in Deepholm, you see them in their true form.\n\nWe're surrounded. Maybe you could go out there and break a few troggs down for us. See what they're really made of?", objectives = "Slay 12 Stone Trogg Ambushers.", progress = "Are you going to pull your fleshy weight, <race>?", completion = "Not a bad start, though you'll have to destroy more of them than that if you're going to rescue the Stonefather.\n\nA lot more." }
WordHunterWoW_QuestEN[26501] = { title = "Sealing the Way", description = "The stone troggs have found a way to burrow up from underneath our homes!\n\nI've sent our geomancers to seal all of the buildings, but they need these reagents and enough time out of battle to properly cast their rockslide rituals.\n\nWhen you're done, report to, Gravel Longslab, just to the north on the Fractured Front.", objectives = "Help the Earthen Geomancers to get out of combat and then give them the Rockslide Reagents so that they can seal the Armory, Inn, Barracks, and Shrine.", completion = "This is good. We no longer need to worry about stone trogg attacks from the rear.\n\nLet's see what you can do for us on the front." }
WordHunterWoW_QuestEN[26502] = { title = "Thunder Stones", description = "To the north lies the Fractured Front. That is where most of the heavy fighting is happening.\n\nGo into Stonehearth proper and grab all of the thunder stones that you can. Our engineers need them for the catapults.\n\nWhen you have enough, take them to Clay Mudaxle. Don't mind his tongue. He's old and cranky, and should have gone back into the earth thousands of years ago.", objectives = "Collect 12 Thunder Stones.", progress = "<The older Earthen has cracks where the others do not, clearly ancient.>\n\nWhat are you supposed to be? Some kind of fleshy mistake? Cursed is what you are!\n\n<Clay spits dust.>\n\nMake yourself useful or get off of my front!", completion = "<Clay grumbles to himself.>\n\nThose'll do. Just put them down over there.\n\n<The Earthen looks you up and down with one eye and then spits dust onto the ground.>\n\nI'm going to have something for you to do in a moment. Maybe." }
WordHunterWoW_QuestEN[26503] = { title = "Still Assessing the Threat", description = "Damned worthless gnolls are up to no good. I can feel it in my bones. Gnoll activity in the area has tripled in the past two weeks. I fear they might be mounting up to make an assault on Lakeshire.\n\nI need you to head to each of the gnoll camps of this area and gather any information that you come across. Check the camps directly north of here, east of here and southeast of here. Bring back whatever you find.", objectives = "Steal the Gnoll Battle Plans, Gnoll Orders and Gnoll Strategy Guide.", progress = "Did you find the gnoll plans?", completion = "I knew it! Looks like Yowler is behind this uprising - which is incredible, because we keep killing gnolls named Yowler. I don't know how many sons the original Yowler had, but it's got to be close to a hundred.\n\nWell, looks like we got ourselves another Yowler to kill.\n\nMagistrate Solomon must be notified." }
WordHunterWoW_QuestEN[26504] = { title = "WANTED: Redridge Gnolls", description = "By order of the Stormwind Royal Guard, all gnolls of the region known as Three Corners in the southwestern corner of Redridge Mountains, are wanted dead.\n\nShould you dispatch of the gnolls of the region, report your victory to Watch Captain Parker at Tower Watch.", objectives = "Kill any 15 Redridge Gnolls in the Three Corners region of Redridge Mountains.", progress = "Come to collect on a bounty?", completion = "A job well done deserves a reward, wouldn't you say?\n\nDon't spend this all in one place, <class>. Better to spread it around, if you catch my drift." }
WordHunterWoW_QuestEN[26505] = { title = "Parker's Report", description = "<Watch Captain Parker hands you a report.>\n\nHere it is, {name}. Take my report to Lakeshire, located north of this tower, and deliver it to Magistrate Solomon. Inform him that we need a more comprehensive solution for dealing with the gnolls. Suggest explosives. Lots of explosives.\n\nAnd stick to the road if you know what's good for you.\n\nWhat's good for you is staying alive, by the way. In case you didn't know what was good for you. You now know... Oh never mind!", objectives = "Deliver Parker's Report to Magistrate Solomon at Lakeshire in Redridge.", progress = "Where did I put my monocle?! Conacher is that you?", completion = "<Magistrate Solomon puts on his monocle.>\n\nOh, you're not Conacher. What have you got there?\n\n<Magistrate Solomon takes Parker's report from you.>\n\nOh for pity's sake. Yowler? AGAIN?" }
WordHunterWoW_QuestEN[26506] = { title = "Franks and Beans", description = "I need your help, {race}! Our rations have run out and the guards are getting hungry. They're clamoring for my world famous franks and beans, but I have no ingredients on hand. Would you be a darling and help me out?\n\nI need some goretusk kidneys, condor giblets, and tarantula eyes. You'll find goretusks, condors and tarantulas near this tower. Just look around!", objectives = "Collect 4 Tarantula Eyes, 4 Condor Giblets and 4 Goretusk Kidneys.", progress = "Have you gotten my ingredients?", completion = "PERFECT! I'll put these in the pot right away. Dinner should be ready in a few hours.\n\nThank you, darling!" }
WordHunterWoW_QuestEN[26507] = { title = "Petrified Delicacies", description = "Petrified bats.\n\nElementals of that size are picky. You're not likely to find anything better easily.\n\nTo the east are basilisks. They petrify stone bats that fly too close and snack on them when they grow hungry. You may find bats scattered around their territory.\n\nI must warn you... if you show that little elemental too much attention, you're unlikely to be rid of it. It can be very... needy.", objectives = "Gather 12 Petrified Stone Bats for Pebble.", progress = "<Pebble starts to look up at you, eyes glowing faintly, growing rounder and larger every moment.>", completion = "<Pebble leaps upon the pile of petrified bats and rolls around in them, seeming to forget that you exist entirely. Perhaps for the best, if Kor's warnings are to be trusted.>" }
WordHunterWoW_QuestEN[26508] = { title = "Nida's Necklace", description = "My friend Nida lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", objectives = "Find Nida's Necklace.", progress = "Hi.  I miss my necklace.  My daddy got it for me.  Daddy says that there are monsters in the lake.  Did you beat up any monsters?", completion = "Thank you for finding my necklace mister <class>... you are very kind!  My kitty thanks you too - isn't that right Effsee?" }
WordHunterWoW_QuestEN[26509] = { title = "An Unwelcome Guest", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", objectives = "Kill Bellygrub and take Bellygrub's Tusk.", progress = "Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?", completion = "Finally the menace is laid to rest!  Thank you, <name>, you have done me a great service.  The garden shall be in full bloom this season!" }
WordHunterWoW_QuestEN[26510] = { title = "We Must Prepare!", description = "More of our citizens go missing every day. We think the gnolls are responsible, but we have no idea where they are taking them! If you are to help us defeat the gnolls and find our people, you must be properly equipped. Unfortunately, we are all out of gnomecorders. Without a gnomecorder, there is no way for us to communicate with you when you are in the field.\n\nOur last good gnomecorder was stolen by marauding murlocs last week. You will have to go to Lake Everstill, east of here, and recover it!", objectives = "Recover the Gnomecorder.", progress = "Have you recovered the gnomecorder?", completion = "Excellent! Let me make a few adjustments here and we should be good to go." }
WordHunterWoW_QuestEN[26511] = { title = "Lake Everstill Clean Up", description = "Headed out to Lake Everstill? You'll be happy to know that we currently have a bounty on murlocs. Kill as many as you can and be rewarded! Any murloc will do. All you need to do is kill indiscriminately.\n\nYou'll find Lake Everstill directly east of Lakeshire. It's the lake. Has water in it... Any of this ring a bell?", objectives = "Kill any 10 Murlocs in Lake Everstill.", progress = "Have you killed all the murlocs?", completion = "That ought to teach those murlocs a lesson. Hopefully the next time they decide to raid our town they'll think twice.\n\nWe both know that won't happen." }
WordHunterWoW_QuestEN[26512] = { title = "Tuning the Gnomecorder", description = "The gnomecorder looks to be in working order. I've got you all hooked up, now we just need to tune the gnomecorder for reception.\n\nHead north out of Lakeshire and follow the road up to the graveyard. Once you reach the graveyard I'll attempt to transmit.", objectives = "Go to the Lakeshire Graveyard to tune the Gnomecorder.", completion = "<The gnomecorder crackles and pops.>\n\nCan you hear me, <name>? Is this thing on? Ah, yes, I see you there now.\n\nLet's get to work!" }
WordHunterWoW_QuestEN[26513] = { title = "Like a Fart in the Wind", description = "We were raided last night, or perhaps it was the night before. I'm not really sure when it was as I haven't had a wink of sleep in three days. I'm probably delusional at this point.\n\nListen, gnolls raided our supply stores and took off with everything! Just like a fart in the wind, they were in and they were OUT! My soldiers saw them running back towards the canyons, northwest of here. Recover our supplies, {class}!", objectives = "Recover 8 Redridge Supply Crates.", progress = "Did you recover the supplies?", completion = "Thank you, citizen. Without you, we would have starved or worse, been forced to go out and get food for ourselves." }
WordHunterWoW_QuestEN[26514] = { title = "Canyon Romp", description = "<The gnomecorder hums.>\n\nThe first order of business is a romp through the Redridge Canyons, directly north of Lakeshire. Kill every gnome that you see... woops, did I say gnome? I meant gnoll. Kill every GNOLL that you see and take their collars as proof of deed.\n\nI must warn you, {name}; while you are out there, watch out for ettins. My scouts have reported seeing huge, bloodthirsty ettins roaming the canyons lately. Stay out of their way if you want to remain alive.\n\nSolomon out. I'll be in touch.", objectives = "Collect 10 Redridge Gnoll Collars.", progress = "Did you recover those collars?", completion = "<The gnomecorder crackles and pops.>\n\nGood work, <name>. I've just been handed some important information. It would appear that our most hated enemy, the Blackrock orcs, have wised up...\n\n\n\nI've transferred a few silver over to you for the gnome, erm, gnoll kills." }
WordHunterWoW_QuestEN[26515] = { title = "Ongo'longo's Revenge", description = "I've got a plan to pit troll against troll.\n\nThe Vilebranch have a big ol' dire troll locked up in a pit with some flimsy-lookin' chains. I've seen those things fight, and there's no way those'll hold if that big brute gets swingin' mad!\n\nI want you to find the dire troll and fight him, {name}. Don't kill him... just smack him around til' he's seein' red, then let him break free and get out of his way! He'll be a big pain for the Vilebranch.", objectives = "Fight Ongo'longo until he breaks free.", completion = "Ain't that a hoot! Wish I could've seen it myself." }
WordHunterWoW_QuestEN[26516] = { title = "It's Ours Now", description = "Only the strongest and foulest Vilebranch are left now. The soul eaters and blood drinkers, foul worshippers of the evil god Hakkar.\n\nDon't forget you're not just fighting trolls here, {name}. You're fighting dark and evil forces that'll churn this land into ash if we let them live!\n\nShow no mercy!", objectives = "Kill 5 Vilebranch Blood Drinkers and 5 Vilebranch Soul Eaters in Jintha'Alor.", completion = "We've cleared straight through 'em! Jintha'Alor is as good as wiped out!" }
WordHunterWoW_QuestEN[26517] = { title = "Summit of Fate", description = "You have to go to the summit now, {name}. Our warriors won't go past the final gates. They say it's still as a tomb; not a sound, not a breath, not a hint of motion.\n\nThey think it's a trap, but based on what you've brought me, I'm worried it's something even more sinister. Go to the altar, investigate what happened... and bring me back ANY sort of mystical object or dark idol you find! Do you hear me?", objectives = "Collect 8 Spider Idols from the Vilebranch at the summit of Jintha'Alor.", progress = "What did you find?", completion = "Dead? All of them, around the altar? And you found these spider idols on them...\n\nIt's Shadra. The Spider Loa! They're trying to tap her power!" }
WordHunterWoW_QuestEN[26518] = { title = "Heads Up", description = "Umboda Three-Heads is one o' the biggest trolls you'll see around. He's a savage butcher, takin' heads for his own collection, dwarf and troll alike! It's time he got what he deserved.\n\nLook for the big brute on the lower terraces, and you take his own head right back here!", objectives = "Defeat Umboda Three-Heads and collect his head.", progress = "Let's see it!", completion = "That's one ugly mug. Maybe he was takin' other heads tryin' to find a prettier one!" }
WordHunterWoW_QuestEN[26519] = { title = "He Who Controls the Ettins", description = "You've stumbled upon a gnoll document. The gnoll that wrote this propaganda is semi-literate:\n\nBROTHERS OF YOWLER, HEAR DIRTPAW! DIRTPAW GIVEN ORB FROM ORCS! DIRTPAW CONTROL ETTIN THINGS! DIRTPAW CRUSH HUMIES! COME GET DIRTPAW PAW-O-GRAPH IN RETHBAN CAVE. CAVE IS WEST, HIDDEN IN CANYON!\n\n<There's a paw print as the signature.>\n\n<There also appears to be a bite taken out of the scroll.>\n\nYou should probably investigate.", objectives = "Kill Ardo Dirtpaw.", progress = "<The orb emanates powerful magic.>", completion = "<The orb hisses as you touch it.>" }
WordHunterWoW_QuestEN[26520] = { title = "Saving Foreman Oslow", description = "<Upon touching the orb you hear a faint click.>\n\n<You remove the orb from the pedestal.>\n\n<You now control the orb, therefore you now control the ettins. Maybe you can use an ettin to remove the huge boulder currently crushing Foreman Oslow over at Lakeshire. Find an ettin and use the orb on the ettin. Then head over to Lakeshire.>", objectives = "Use the Ettin Control Orb to control an Ettin and then use the Ettin Control Orb on your Subdued Canyon Ettin to lift the Huge Boulder off of Foreman Oslow at Lakeshire.", completion = "You used an ettin to remove the boulder that was crushing Foreman Oslow? Incredible work, <name>! Oslow will be grateful once he regains his composure." }
WordHunterWoW_QuestEN[26521] = { title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. We won't tolerate their foul hexes and dark magic.\n\nIt's time to send a message, and tear down their defenses, all at once! Take this torch, {class}. Set fire to their tiki masks and watch 'em burn. They'll know the Wildhammer want them gone when they see their dark idols consumed!", objectives = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor.", completion = "The elements dance, and fire consumes. Let the flame show 'em the cost of their wickedness!" }
WordHunterWoW_QuestEN[26522] = { title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. The spirits not gonna be watchin' over them much longer.\n\nTake this torch with ya as ya fight through the Vilebranch, <class>. Set fire to their tiki masks. I'll be watchin' from here as their wards and hexes fade away, an' their heretical dark voodoo goes up in smoke.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor." }
WordHunterWoW_QuestEN[26523] = { title = "All That Skitters", description = "There's somethin' I've noticed up there... Jintha'Alor's full of spiders. Small ones about as big as yer hand. Not an unusual sight for the Hinterlands, but somethin's amiss.\n\nTo be honest, I don't trust the trolls to keep pets. They're up to somethin'. I need you to bring me some of those spiders. Keep 'em alive if you can, and we'll see what the spirits tell me...", objectives = "Collect 8 Skittering Spiderlings in Jintha'Alor.", progress = "Let's see what you've got.", completion = "By Kurdan's beard... these don't look like any spiders I've seen before. Dark magic's at work here." }
WordHunterWoW_QuestEN[26524] = { title = "Dark Vessels", description = "The Vilebranch trolls here were always worshippers of the foul god Hakkar, the loa of blood. He was a sick and twisted entity that nearly broke through to our world, but he was defeated long ago.\n\nThe Vilebranch are still stirring their dark cauldrons, ones they filled with blood years before. They're either holding onto hope for a long-dead spirit, or they're up to something new and just as sinister.\n\nGet me those vessels, {name}. We need to examine them with the spiders and see just what's going on here!", objectives = "Collect 5 Vessels of Tainted Blood from Jintha'alor.", progress = "Be careful near those cauldrons, <class>. The Vilebranch won't give them up easily!", completion = "This isn't just blood... it's venom!\n\nSpiders... venom... I hope I'm wrong about my hunches here, <name>." }
WordHunterWoW_QuestEN[26525] = { title = "Venomous Secrets", description = "If the sacrifice has already been made, Shadra's presence is going to start creepin' into this realm. That cave's probably full of her spawn by now.\n\nDon't let them escape, {name}. Slay any of those vile spiders you find!", objectives = "Kill 8 Spawn of Shadra.", completion = "Good riddance. May those horrid things never walk these lands again." }
WordHunterWoW_QuestEN[26526] = { title = "Hunt the Keeper", description = "Shadra the spider loa... the venom queen, a spirit of darkness and death! If there's been a sacrifice, they're trying to bring her forth as a last-ditch effort.\n\nIf the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", objectives = "Kill Morta'gya the Keeper and obtain the Tablet of Shadra.", progress = "Be sure you search her body. I don't want any traps laid by the Vilebranch to be hidden by their deaths.", completion = "A tablet! If I can read this... this is a ritual to summon Shadra herself into this world, and a list of the idols needed.\n\nYou've done a good job slaying the keeper and getting ahold of this, <name>." }
WordHunterWoW_QuestEN[26527] = { title = "Gryphon Master Talonaxe", description = "I'd smash this tablet to bits if I had the right, but that's not for me to decide. Gryphonmaster Talonaxe needs to see this.\n\nYou've got to return to Aerie Peak with the tablet. Gryphon Master Talonaxe is in the aviary, tending to the gryphons.\n\nBe swift... and don't let that tablet leave your grasp for a moment!", objectives = "Deliver the Tablet of Shadra to Gryphon Master Talonaxe.I'd smash this tablet to bits if I had the right, but that's not for me to decide. Gryphonmaster Talonaxe needs to see this.\n\nYou've got to return to Aerie Peak with the tablet. Gryphon Master Talonaxe is in the aviary, tending to the gryphons.\n\nBe swift... and don't let that tablet leave your grasp for a moment!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26528] = { title = "The Eye of Shadra", description = "Gryphon Master Talonaxe has sent me here to deal with Shadra, the Venom Queen. The conquest of Jintha'Alor isn't enough... the trolls could regroup and summon this creature later, when we're not expecting it.\n\nWe'll gather the artifacts first, pull Shadra into this world on our own terms, and put our hammers to that foul creature. I'll need you to help find the artifacts, and put a hurt on the rest of the trolls while you're at it.\n\nWe first need the Eye of Shadra, guarded in Agol'watha to the north.", objectives = "Recover the Eye of Shadra from Agol'watha.", progress = "Was the tablet right? Did you find the eye?", completion = "Well done, <name>. We'll be knockin' on this bug's door in no time." }
WordHunterWoW_QuestEN[26529] = { title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn. Hideous spiders the size of a dwarf, and twice as strong. Their venom is strong, {name}... don't get careless.", objectives = "Collect the Fang of Shadra from the Creeping Ruins.", progress = "Have you got the fang?", completion = "There it is... only one left, lad." }
WordHunterWoW_QuestEN[26530] = { title = "The Shell of Shadra", description = "The final piece is all we need to burn Shadra out for good.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nYou've got to climb that altar to the top and take her out! She'll have the Shell in her possession. Bring it back here.", objectives = "Kill Qiaga the Keeper and collect the Shell of Shadra.", progress = "Do you have it?", completion = "This is it, lad! We're ready!" }
WordHunterWoW_QuestEN[26531] = { title = "Summoning Shadra", description = "Our best fighters are ready, we've got the idol assembled... it's time, {name}.\n\nHere's what we're gonna do. You'll travel southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples, fighting through the trolls guardin' them.\n\nWhen you do that, Shadra will emerge into our world, and we'll be right there waiting for her with fury in our hearts. Talk to my boys on the scene as soon as you've performed the ritual!", objectives = "Use the Idol of Shadra at the Northwestern, Southwestern, and Eastern Temples in Shadra'Alor.", progress = "Are y'ready?", completion = "Talonaxe and the boys are right behind. Let's do this!" }
WordHunterWoW_QuestEN[26532] = { title = "Shadra the Venom Queen", description = "No time to waste, {name}! She's comin' out of the water right now!\n\nGryphon Master Talonaxe is comin' right now with the boys, let's show that bug what for!", objectives = "Kill Shadra the Venom Queen.", completion = "You've done a great thing for the Wildhammer today, <name>. I wish Falstad could've been here for that.\n\nOn behalf of the whole clan, I'd like to repay you for keeping these lands free from that foul shadow. You've earned this reward." }
WordHunterWoW_QuestEN[26533] = { title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI'd like to get my hands on some, {race}.  Check the zombies to the southeast.", objectives = "Obtain 5 vials of Zanzil's Mixture.", progress = "Excellent... you're not a zombie yet.  That's good.\n\nOh, umm... nothing.  It's just that... that was a potential risk.  Did I forget to warn you?", completion = "<Jasper carefully analyzes the strange compound.>\n\nThis mixture is... I don't understand it.  Perhaps we need to run some clinical trials." }
WordHunterWoW_QuestEN[26534] = { title = "Let's See What You've Got, Zanzil", description = "Visitors to Hardwrench Hideaway sign a number of waivers upon arrival, one of which allows us to perform basic tests on them.  I'd say it's about time we invoked that clause again.\n\nActually, let's avoid poisoning our customers this time.  Better for business.\n\n<Jasper fills a pitcher with Zanzil's Mixture and some crushed ice.>\n\nThe Hideaway's southeastern tower serves as a temporary jail.  \"Hardwrench Hoosegow,\" we call it.  Anyways, give the prisoners a drink and tell me what happens.", objectives = "Offer Jasper's Jungle Cooler to Gmurgl, Orgus, and Captain Bartholomew Softbeard.", completion = "You don't say!  Well, that certainly is interesting.  In that case...\n\nForget understanding how the stuff works!  I gotta get my hands on that recipe!" }
WordHunterWoW_QuestEN[26535] = { title = "Recipe for Disaster", description = "I need Zanzil's recipe, now more than ever.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the other coast of the Cape, and snatch it for me!", objectives = "Obtain Zanzil's Formulation from one of Zanzil's followers in the Ruins of Aboraz.", progress = "Did he use shimmerweed?  I'm guessing he used shimmerweed.\n\nNo wait... amberseeds!  It's gotta be amberseeds.", completion = "This is fascinating!  Just think of all the applications!\n\nJust so we're clear, I'm not thinking about using this to make an army of slaves or anything like that.  No, no... I'm much more interested in the ogre explosions!" }
WordHunterWoW_QuestEN[26536] = { title = "Thunder Falls", description = "Arnold and I have been fishing in and around Stormwind for years now.  That's the kind of time it takes to find a good fishing spot.  One of my favorites is called Thunder Falls.\n\nIt's just south of Stormwind in Elwynn Forest.  Best part about Thunder Falls is the violet perch.  I have never seen them anywhere else, only up there at the falls.  It's a bit of hike for me and Arnold to get out there these days though, do you think you could head up there and fetch some of those perch for us?", objectives = "Catch 4 Violet Perch from Thunder Falls, south of Stormwind. Return to Catherine Leland with your catch once you are done.", progress = "Were you able to find the falls?", completion = "These perch look great <name>.  Why don't you join us for a fish fry tonight?" }
WordHunterWoW_QuestEN[26537] = { title = "Shatter Them!", description = "I want you to go out there and I want you to finish them.\n\nBerserkers, Earthrenders, Deathriders... I don't care! I want those stone troggs shattered!", objectives = "Slay any 12 stone troggs on the Fractured Front.", completion = "That's a good dent, but it's clear to me that we're going to have to handle this a slightly different way." }
WordHunterWoW_QuestEN[26538] = { title = "Emergency Aid", description = "Many of our warriors didn't survive the Twilight attack on our air fleet. Those that did are swimming to the remains of the fleet, bleeding and badly burned. I need support from the shore to keep my men alive!\n\nThere should be some sort of doctor or medicine man inside of Dragonmaw Port who would be willing to help his fellow orcs out. Go ashore and see if you can bring some medical supplies back to the fleet!", objectives = "Seek out a Medicine Man in Dragonmaw Port, somewhere near the shore.", completion = "<Gregor bows respectfully to Zaela.>\n\nIf it is Zaela's wish, then you shall have your supplies. Just don't tell the Dragonmaw Warchief..." }
WordHunterWoW_QuestEN[26539] = { title = "Stalled Negotiations", description = "The Warchief's whereabouts are unknown! But we have to keep his plan moving forward. {name}, you look like you can get things done.\n\nOur negotiations with the Dragonmaw have stalled. Their Warchief is... not what we expected. I need you to go in there and get negotiations back on track.\n\nMeet with Ornak on the shore, he'll fill you in.\n\nTalk to Horzog on deck here for quick transportation to the shore.", objectives = "Speak with Ornak in Dragonmaw Port. Horzog can provide you with quick transportation to the shore.", completion = "I'm glad you're here, <class>. Perhaps a seasoned veteran of the Horde's campaigns in Northrend and elsewhere can talk some sense into the Dragonmaw leadership..." }
WordHunterWoW_QuestEN[26540] = { title = "Dangerous Compassion", description = "The red dragonflight represents the aspect of life. As such, their blood has healing properties.\n\nThis crate of bandages has been soaked in red dragon blood. It is the last of my supply. May it bring a speedy recovery to your warriors.\n\nWhatever the outcome of your negotiations here, do not forget that you have friends among the Dragonmaw.", objectives = "Bring the Crate of Dragonmaw Bandages back to Warlord Krogg off the coast of Dragonmaw Port.", progress = "Do you bring any hope for our wounded?", completion = "Dragon's Blood!? We best not tell our red dragon allies that we've used these.\n\nStill, it's powerful magic... We'll have our fighting force back in no time." }
WordHunterWoW_QuestEN[26542] = { title = "Hero's Call: The Hinterlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Gryphon Master Talonaxe at the aviary in Aerie Peak.\n\nOur new brothers in the Alliance need your help to fend off the aggressive Horde offensive in their beloved homeland. Travel north from the Arathi Highlands, through the dwarven mountain pass and follow the road northwest to Aerie Peak.\n\nFor the glory and honor of the Alliance!", objectives = "Travel to Aerie Peak in The Hinterlands and speak with Gryphon Master Talonaxe.", completion = "Welcome to Aerie Peak, <name>. On behalf of High Thane Falstad, I thank ye for comin' to help us." }
WordHunterWoW_QuestEN[26543] = { title = "Clammy Hands", description = "Nothing tastes like fresh monstrous clam meat, {name}.  I have been so busy with work these past few weeks that I have not been able to make it out to the local clam spawning grounds.  Think you could run down there and gather some of those tasty treats for me?\n\nThe clams can be found near the shoreline on the eastern coast of Durotar.  Should be plenty right around the Orgrimmar docks.", objectives = "Collect 10 Monstrous Clam Meat from the clams near the eastern shoreline, just south of Orgrimmar. Return to Razgar once you are done.", progress = "Were you able to find the clams?", completion = "Looks like you found the clams, <name>.  These will do nicely." }
WordHunterWoW_QuestEN[26544] = { title = "They've Wised Up...", description = "<The gnomecorder crackles and pops.>\n\nIt would appear that the Blackrock orcs have finally wised up. I'm getting reports that they're joining forces with the gnolls and planning an attack. I want details, {name}!\n\nI need you to check out Rethban Caverns, located in the western region of Redridge Canyons. Look for orcs with dark skin. Kill any that you encounter and search their corpses for information.\n\nSolomon, out.", objectives = "Recover the Blackrock Orc Missive.", progress = "What have you found out?", completion = "<The gnomecorder buzzes and whirs.>\n\nJust put the missive in the little compartment and I'll read it. I am fluent in orcish.\n\n<You hear a distraught yell in the background.>\n\nIt looks like these orcs are here under the direct command of Yowler. That means Yowler must have the orc invasion plan." }
WordHunterWoW_QuestEN[26545] = { title = "Yowler Must Die!", description = "<The gnomecorder hums.>\n\nYou need to find Yowler, {name}. He'll be located somewhere in the northern region of Redridge Canyons. Kill that mongrel and search his corpse for the Blackrock invasion plans. Should you succeed, bring the plans to me over at the town hall in Lakeshire.\n\nSolomon, out.", objectives = "Kill Yowler and recover the Blackrock Invasion Plans.", progress = "Do you have the Blackrock invasion plans?", completion = "<Magistrate Solomon takes the plans from you and begins reading.>\n\nShadowhide army!? Damn those orcs to hell! These invasion plans speak of a massive build up of orcish and gnoll forces in the east. Looks like Gath'Ilzogg, the Blackrock general, is preparing to march his armies across Lakeshire and attack Stormwind directly!" }
WordHunterWoW_QuestEN[26546] = { title = "Razorbeak Friends", description = "Our clan reveres the gryphon as a sacred animal. They're majestic creatures of the skies, and more than just beasts; they're intelligent and cunning.\n\nSome say we keep them, but it's more of a friendship. If you want to befriend the Wildhammer here, first befriend our gryphons! Take this bag o' chow, it's nice and fresh. Our trained razorbeak gryphons wander the forests to the south of the aviary. Go on and feed a few of 'em for me, aye?", objectives = "Use Gryphon Chow to feed 7 Trained Razorbeak gryphons.", completion = "Treat them with respect, and they'll treat you with it as well.\n\nGive 'em guff and you'll be out an eye!" }
WordHunterWoW_QuestEN[26547] = { title = "A Mangy Threat", description = "We do everything we can to protect our kin and our gryphons. That includes chasin' off predators, whether they be from the forest or from the Horde.\n\nI won't ask you to save us from two-legged monsters just yet. Mangy silvermane prowl the woods to the south where our gryphons range, and they're known to get 'em if they stray too low. Hunt a few of the silvermane and make sure they know our gryphons aren't food.", objectives = "Kill 8 Mangy Silvermanes.", completion = "Much appreciated, <name>." }
WordHunterWoW_QuestEN[26548] = { title = "Out to the Front", description = "We need your help with somethin' more pressin', {name}.\n\nThe Horde's been gettin' bolder out here. They've moved in on our territory and started attackin' us outright. The Revantusk forest trolls are attackin' Stormfeather Outpost in broad daylight!\n\nI need you to help out. Talk to Guthrum Thunderfist just outside. He'll put you on a gryphon to Stormfeather Outpost. Kerr Ironsight will fill you in when you get there.", objectives = "Speak with Kerr Ironsight at Stormfeather Outpost.", completion = "Good to see you out here! Let's get to it." }
WordHunterWoW_QuestEN[26549] = { title = "Madness", description = "Our last two negotiators haven't returned from speaking with the Dragonmaw Warchief. I think we might need to flex a little bit of muscle.\n\nThis time, I want YOU to accompany the negotiator. Their Warchief might think twice once he realizes the Horde is full of battle-hardened heroes like yourself.\n\nSimply escort our negotiator into the main hold in the center of Dragonmaw Port and look menacing. ", objectives = "Escort the Horde Negotiator to the main hall in Dragonmaw Port to meet with Warchief Mor'ghor of the Dragonmaw. Speak with Ornak on the coast if you lose your Negotiator.", progress = "<name>, I understand you're going to speak with our \"Warchief\" about joining your Horde.\n\nBe careful, <class>.\n\nSee me afterwards...", completion = "Wake up, <name>! We don't have much time.\n\nI rescued your gear for you.\n\nAt least now you've seen the foolishness of our leader first-hand. His blood is contaminated, his rage is unquenchable -- and he'll destroy us all trying to defeat the Horde!" }
WordHunterWoW_QuestEN[26550] = { title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the east.  Hir'eek will guide you from there.", objectives = "Place the Gurubashi Incense in front of the Totem of Hir'eek, then listen to Zanzil's plot.", completion = "It is as I suspected.  Zanzil is too haughty to interfere with the squabbles between the Bloodscalps and the Skullsplitters.  No, he is playing a part in a grander scheme... Jin'do the Hexxer is using him to help bring Hakkar back to Zul'Gurub.\n\nIt's good that we found this out now, because it offers us a simple solution." }
WordHunterWoW_QuestEN[26551] = { title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return swiftly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", objectives = "Travel to the Ruins of Aboraz in the Cape of Stranglethorn and deal with Zanzil the Outcast." }
WordHunterWoW_QuestEN[26552] = { title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Chabal entrusted this task to you.\n\nThe portal lies in wait in front of you.", objectives = "Use Zanzil's Portal and enter Zul'Gurub.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway." }
WordHunterWoW_QuestEN[26553] = { title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", objectives = "Destroy High Priestess Jeklik's body before Zanzil can resurrect her.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway." }
WordHunterWoW_QuestEN[26554] = { title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", objectives = "Pass through Zanzil's Portal.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway." }
WordHunterWoW_QuestEN[26555] = { title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", objectives = "Deal with Zanzil the Outcast and High Priest Venoxis.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", completion = "I ask you to slay Zanzil the Outcast, a lowly, hermetic exile of the Gurubashi, and what do you do?  You dash headfirst into the Gurubashi capital and eliminate one of their High Priests!  Very nearly two!  Only one word suffices to explain such a rash and foolhardy endeavor:\n\nHeroism.\n\nJin'do the Hexxer still walks within Zul'Gurub's walls, but he lost one of his legs when you crushed Jeklik.  Today's battle is ours." }
WordHunterWoW_QuestEN[26556] = { title = "No Dumping Allowed", description = "Ever since those goblins took up refuge in Orgrimmar, they have been dumping all of their waste in our water supply.\n\nI have no idea what effect this is having on our local fishing supply, but I don't think it's good.  I have heard reports of a new mutated fish species spawning in that toxic pool near their camp.  A few specimens would really help me figure out what exactly is going on.\n\nCan you help me out?", objectives = "Fish up 6 Toxic Puddlefish and return them to Razgar in the Valley of Honor once you are done.", progress = "Were you able to fish up a few specimens?", completion = "Nice work <name>.  These samples will help us figure out what is going on in that toxic soup over there." }
WordHunterWoW_QuestEN[26557] = { title = "A Staggering Effort", description = "I've fished sandy carp in Orgrimmar's local waters for years now.  Recently, I have noticed my bait is not working as well as it used to.  I suspect it has something to do with all the tauren that moved into the Valley of Wisdom.\n\nI spoke with one of their local fisherman and it just turns out their appetite has changed.  They are biting on stag eyes these days.  You should be able to find plenty of stags north of Orgrimmar, just outside the northern gate.", objectives = "Slaughter a Stag north of Orgrimmar and use its eye as bait to catch a Sandy Carp in the Valley of Wisdom. Return to Razgar in the Valley of Honor once you are done.", progress = "Did the eye work as bait?", completion = "Outstanding!  Those sandy carp are picky eaters aren't they?" }
WordHunterWoW_QuestEN[26558] = { title = "Summoning Shadra", description = "The idol is prepared, {name}. I trust that you are as well?\n\nYou will go southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples.\n\nWhen you do that, Shadra will be summoned to this realm. The Deathstalkers and I will be along shortly to subdue and harvest her body. Speak with the lookout I've sent ahead once you've performed the ritual, and await my arrival.", objectives = "Use the Idol of Shadra at the Northwestern, Southwestern, and Eastern Temples in Shadra'Alor.", completion = "Marnal draws close... and Shadra even closer. Prepare for bloodshed." }
WordHunterWoW_QuestEN[26560] = { title = "Jorgensen", description = "I don't know where Krakauer or Danforth are, but Jorgensen was being held at Render's Camp, northwest of here. I was in the same crap filled cage with him before they relocated me to Alther's Mill.\n\nIf we're gonna get him out we'll need the key. A stone cold witch from hell known as Utroka the Keymistress holds on tight to that thing. We'll have to kill her if we're going to get Jorgensen's cage key. She's up north in the valley leading to the Burning Steppes.\n\nLet's go, kid.", objectives = "Retrieve Jorgensen's Cage Key.", progress = "Messner! Damn, it's good to see a friendly face. Get me out of here!", completion = "I know where they're holding Krakauer and Danforth. We gotta hurry. They were prepping those two for a sacrifice!" }
WordHunterWoW_QuestEN[26561] = { title = "Krakauer", description = "Krakauer is up on the chopping block as we speak! The orcs brought in a Gurubashi witch doctor to perform a dark ritual on him. We need to kill that troll to free Krakauer!\n\nLet's go! He's just inside the cave here. Hang a right at the first fork.", objectives = "Kill Ritualist Tarak.", progress = "<Krakauer groans.>", completion = "Wha... Where am I? What happened? Messner? Jorgensen?\n\nOH MY GOSH! We have to get to Danforth! It might already be too late!" }
WordHunterWoW_QuestEN[26562] = { title = "And Last But Not Least... Danforth", description = "Danforth's being tortured on the other side of the cave. There's no telling what state he's in by now! We need to get over there and save him!\n\nOverlord Barbarius has the key to the lever holding Danforth up. We work together as a team and we can kill that bastard, Barbarius. Once Barbarius is dead, we use his key to get Danforth down and get out of here!\n\nReady?", objectives = "Kill Overlord Barbarius and recover the Blackrock Lever Key. Use the Blackrock Lever Key to free Danforth.", progress = "Well look at that! The team's all here... everyone but Keeshan.", completion = "About damn time you sissies showed up. My arms were gettin' tired." }
WordHunterWoW_QuestEN[26563] = { title = "Return of the Bravo Company", description = "I don't know who you are, mister, but you've earned the respect and admiration of the Bravo Company. You've managed to save all our hides and kill a boatload of orcs in the process. Now we return the favor.\n\nGet back to Lakeshire and report to Colonel Troteman. We'll find Johnny and deliver the good news in person. With the Bravo Company back in action, these orcs don't stand a chance.", objectives = "Report to Colonel Troteman at Lakeshire in Redridge.", completion = "<Colonel Troteman salutes.>\n\nUnbelievable work, <name>. You've managed to rescue the entire Bravo Company from the clutches of the Blackrock orcs? With Keeshan's team rescued and Keeshan's belongings returned, there's no way Keeshan could refuse us." }
WordHunterWoW_QuestEN[26564] = { title = "Fixer Upper", description = "<Clay sneers at you and makes a sound much like two stones rubbing against each other.>\n\nThey've smashed all of our catapults. I've been trying to get this one working, but no luck so far.\n\nMaybe you'd like to make yourself useful. Head out onto the front and grab me any spare parts you come across.\n\nYou think you can handle that, flesh bag?", objectives = "Collect 6 Catapult Parts.", progress = "Well? I don't have all day.", completion = "Well then. Maybe you're okay after all.\n\nAlright, alright... don't get all bent out of shape. Just give me a few moments with these parts." }
WordHunterWoW_QuestEN[26565] = { title = "A Furious Catch (REMOVED)", description = "Are you up for a challenge, <name>?  Good, I was hoping you would be.  The southfury river flows just west of Orgrimmar and your challenge can be found within it's mighty flow.\n\nWe are looking for a furious pike.  This mighty fish used to be prevalent in these areas but ever since the floods hit, they have been much harder to find.  Head out to the river and let's see just how good of an angler you really are.You will receive:", objectives = "Catch a Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar's western gate. Return to Razgar in the Valley of Honor once you are done." }
WordHunterWoW_QuestEN[26566] = { title = "A Triumph of Gnomish Ingenuity", description = "We will need all the weapons, inventions, and soldiers we can get in order to defeat Razlo Crushcog and his followers.\n\nOver to the northeast, you'll find Engineer Grindspark, one of a new generation of brilliant gnomish minds. Why, he hasn't had an explosion in over three prototypes!\n\nBut enough bragging. Engineer Grindspark is working on a bot that he says will help clean up the toxic airfield. You should introduce yourself to him and see if he needs any help testing it.", objectives = "Speak with Engineer Grindspark in New Tinkertown.", completion = "So the high tinker himself has heard of my little project? Splendid! I've almost finished my latest prototype, but maybe you can help me chase down those last few parts." }
WordHunterWoW_QuestEN[26567] = { title = "John J. Keeshan", description = "You ever heard of John Keeshan, {name}? I was his commanding officer throughout all three great wars. Let me tell you, that man has killed more orcs than any man alive. If anyone can stop the Blackrock orc invasion, it's JOHN J. KEESHAN. We need to get him to help us or Lakeshire will be nothing more than a mound of rubble and ash after that massive Blackrock army marches through to Elwynn.\n\nI heard he was fighting in the underground fight club at the Lakeshire inn. Find him and tell him everything you know.", objectives = "Enlist the help of John J. Keeshan at the Lakeshire Inn in Lakeshire.", completion = "Help you? Help these people? These people that would rather spit on me than crack a smile?" }
WordHunterWoW_QuestEN[26568] = { title = "This Ain't My War", description = "They asked me to fight in those wars. I didn't ask them! I did what I had to do to win. So I end up getting captured by those filthy, crap-swilling, maggot orcs and for five long years they used me as a toilet. Finally I break out and head back to my hometown and what do I get? People spitting on me, protesting me, calling me a baby orc killer and all kinds of vile crap!\n\nNo, I don't think I'll be helping you. You go back to Troteman and you tell him that this ain't my war.", objectives = "Return to Colonel Troteman.", completion = "<Troteman sighs.>\n\nI'm not giving up on him, <name>, and I'm not giving up on Redridge. We need to boost his spirits... Rouse the slumbering monster within him!" }
WordHunterWoW_QuestEN[26569] = { title = "Surveying Equipment", description = "Ah, my savior! I've heard that you're on a mission to save Lakeshire... and my bridge. Yep, worked too damned long on that thing to let it get destroyed by an army of marauding orc monsters!\n\nListen, if you're headed up north towards Render's Camp, would you do me a solid and get me some spyglasses from the Blackrock trackers up there? I could sure use 'em for my new surveying gear.", objectives = "Recover 5 Blackrock Spyglasses.", progress = "Did you recover the spyglasses?", completion = "Fantastic work, <name>! These will come in handy for our next project, the Lakeshire SUPER BRIDGE, meant to traverse the length of Lake Everstill. It should be done in 20 or so years. Give or take a decade or two." }
WordHunterWoW_QuestEN[26570] = { title = "Render's Army", description = "Heading up north, eh? How about you wage your own little war against those Blackrock monsters? What do you say, {name}?\n\nKill any Blackrock orc that you see at Alther's Mill or Render's Camp. Kill until your skin turns red from their blood splatter and then come back to me and I'll pay you handsomely.\n\nIt might not stop the Blackrock invasion, but it'll be sure to put a kink in their plans.", objectives = "Kill any 25 Blackrock Orcs in Alther's Mill or Render's Camp.", completion = "You've probably bought us another day, maybe two. Nice work, <name>." }
WordHunterWoW_QuestEN[26571] = { title = "Weapons of War", description = "What I'm about to ask of you isn't going to be easy to accomplish, {name}. Keeshan left everything back there in that orc prison, and I'm not just talking about his soul or his will to live.\n\nIf we're going to get Johnny ready for war, we need to recover his prized possessions. The orcs now hold Keeshan's bow and his survival knife.\n\nHead to Alther's Mill, east of here and look for two orc lieutenants, Murdunk and Homurk. They've got Keeshan's gear. Get it back.\n\nI'll be in touch via gnomecorder.", objectives = "Recover Keeshan's Bow and Keeshan's Survival Knife.", progress = "Did you terminate Murdunk and Homurk?", completion = "<The gnomecorder buzzes with energy.>\n\nCome in, <name>. Do you copy? Troteman here! Great job on getting Keeshan's weapons back! Now there's one final mission you have to run. Are you up to the challenge?" }
WordHunterWoW_QuestEN[26572] = { title = "A Golden Opportunity", description = "You heard of the golden stonefish, {name}?  The thing with these fish is that they can't be caught by normal means.  They have jaws so strong that they snap right through any hooks or lures you try to use on 'em.\n\nYou can find a number of them in Thunder Ridge, south of Orgrimmar.  That ridge used to be full of thunder lizards, but they all drowned in the flood.\n\nTake my knife, swim down there and cut off their tails.  You should be able to use the tail to zap any stonefish you find.", objectives = "Use Razgar's Fillet Knife to cut off a Drowned Thunder lizard Tail in Thunder Ridge, south of Orgrimmar. Once you have the tail, use it near a Golden Stonefish to kill it. Return to Razgar in the Valley of Honor once you are done.", progress = "How did it go down there?  Any luck with the tails and the stonefish?", completion = "Nice one, <name>!  I tell ya, golden stonefish are not easy to come by so this is a nice treat." }
WordHunterWoW_QuestEN[26573] = { title = "His Heart Must Be In It", description = "<The gnomecorder clicks.>\n\nHis gear alone won't be enough, {name}. His heart must also be in this battle. To capture that, we need items of sentimental value. The Blackrock orcs of Render's Camp, located in the north, hold two such items that belong to Keeshan.\n\nGet up there and search their coffers for Keeshan's headband and a jade amulet left to him by his wife - who was brutally killed during a Blackrock orc invasion.\n\nBring them back to me should you succeed.", objectives = "Recover Keeshan's Red Headband and Keeshan's Jade Amulet.", progress = "Did you locate the headband and amulet?", completion = "I hope with these items and with his crew all rescued he'll have a change of heart. We can't do this without Keeshan." }
WordHunterWoW_QuestEN[26574] = { title = "Adella's Covert Camp", description = "Lady Shandris has already asked for you to assist us further.\n\nAdella has struck out to the east, among the woodpaw gnolls, and established a foothold south of Camp Mojache. You are to report to her if you wish to assist Lady Shandris and the Alliance further.\n\nDon't stray too close to Camp Mojache... the Horde will not hesitate to attack. Keep to the south and look for our banners.", objectives = "Report to Adella at Shadebough in Feralas.", completion = "Welcome to Shadebough, <name>. Lady Shandris sent word of you." }
WordHunterWoW_QuestEN[26575] = { title = "Rock Bottom", description = "I've one more favor to ask, fleshling.\n\nThere is a basilisk, much larger and much older than the rest. Though we normally fear nothing from their kind, this one has become so potent as to petrify some of my sons. This shall not be abided.\n\nFind Gorgonite to the east and slay him. He has lived much longer than necessary.", objectives = "Kill Gorgonite.", completion = "Thank you, <race>. You've done all that I can ask of you. I shall impart my favor for you to the Stonemother.\n\nMay the stone beneath your feet hold you steady during your quest for the World Pillar." }
WordHunterWoW_QuestEN[26576] = { title = "Steady Hand", description = "Nearby to the north, you will find Terrath the Steady. He has taken upon the task of pulling the stone dragons back into the fold. We find ourselves repeating this trial every few hundred years... the stone dragons are fickle, and bend only to strength.\n\nTerrath is balanced and reasonable, but his goals may not be easily accomplished. Go to him. Appeal to the more balanced side of the Stonemother.", objectives = "Speak to Terrath the Steady at the Pale Roost.", completion = "Greetings, <race>. I have been told of your coming. If you wish to aid me, then perhaps I can be of aid to you as well." }
WordHunterWoW_QuestEN[26577] = { title = "Rocky Upheaval", description = "To the east, on the Crimson Expanse, you will find Gorsik. He embodies the more unstable and violent nature of our kind. He is neither friendly, nor trusting, but his word carries weight.\n\nProving yourself to Gorsik will go a long way towards proving yourself to the Stonemother.", objectives = "Speak to Gorsik the Tumultuous upon the Crimson Expanse.", completion = "You are Diamant's chosen.\n\nSo small. So fragile.\n\nDo you realize that your actions shall be the basis by which your entire, \"Earthen Ring\" is judged? You truly think you can stand for so many?\n\nYou are a fool. A confident fool. We shall see if you are a capable fool as well." }
WordHunterWoW_QuestEN[26578] = { title = "Doomshrooms", description = "The rift to your world has poisoned our home. Corrupted it. Polluted it.\n\nThis expanse festers and grows. It becomes difficult to even see the purity of the rock beneath this filth.\n\nIf you are here to lend your aid, then go about cleansing this overgrowth. Look for the brightly glowing mushrooms that are growing faster than the others. They are the worst of the offenders.", objectives = "Destroy 10 Doomshrooms.", completion = "You have appealed to Diamant. He is patient. Trusting. Perhaps too much so. You have much to prove if you wish my favor, <race>.\n\nStill, this is a start." }
WordHunterWoW_QuestEN[26579] = { title = "Gone Soft", description = "The fungal behemoths that surround us have succumbed to a weakness very similar to that that affects your kind. Their skin has grown soft. They no longer belong with the stone.\n\nKill them. We do not wish to see this infection spread.", objectives = "Kill 8 Fungal Behemoths.", completion = "You carry with you a certain degree of potency. I can find some respect for such strength, especially in your kind.\n\nMy concerns are not yet abated. Not for the source of the overgrowth, and not for you." }
WordHunterWoW_QuestEN[26580] = { title = "Familiar Intruders", description = "Fleshling. Some of your kind skitter among the rocks. Too cowardly to approach, too swift to be crushed.\n\nIf you wish my favor, deal with them. I tire of these games.", objectives = "Speak to the \"fleshling\" intruders in the Crimson Expanse.", completion = "It is good to see you again, brother. I see that your efforts go well. The Stone Lords appear to be showing you some degree of trust.\n\nWe've come to help. We might be of some aid in tracking down the source of this sudden growth. I highly suspect your giant friend's aggressions are focused in the wrong direction." }
WordHunterWoW_QuestEN[26581] = { title = "A Head Full of Wind", description = "I'm no druid, but some of these mushrooms do not look to be naturally occurring. I know that our Stone Lord friend over there is eager to blame this on exposure to Azeroth, but I suspect more domestic causes.\n\nI saw some clouds of red mist to the northeast, near the water's edge. They seemed to be spurring new growth in their wake. Take one of my wind-devils with you and get me a sample from those clouds. You may have to stay close to the ground to spot them.", objectives = "Bring Lorvarius' wind-devil to the clouds of red mist in the Crimson Expanse, near the water, and then return with a sample.", completion = "You let the mist touch your skin? I hope there weren't any adverse affects." }
WordHunterWoW_QuestEN[26582] = { title = "Unnatural Causes", description = "This is most definitely magic in origin. Not even druidic. I suspect one among the stone troggs to the north.\n\nGo to Gorsik and point him in their direction. Hopefully this will help earn his favor.", objectives = "Speak to Gorsik the Tumultuous in the Crimson Expanse.", completion = "The stone troggs? And I am to trust you at your word?\n\nI have no love for the Verlok anyway. Suspicion is more than enough reason to lay waste to them. We shall see if your word is true." }
WordHunterWoW_QuestEN[26583] = { title = "Wrath of the Fungalmancer", description = "Their leader hides within his hole ahead. He is the one that has brought the plague upon the crimson expanse.\n\nHe must be killed.\n\nOne of your Earthen Ring companions is already inside. You should speak with her.", objectives = "Speak to Earthmender Norsala, then kill Fungalmancer Glop.", progress = "I cannot fit inside. Our elementals are not up to the task.\n\nYou must see this done.", completion = "Well done, <race>.\n\nGorsik shall hear of your deed. Therazane shall hear of your deed.\n\nYou are quite vicious for one so small... and so soft." }
WordHunterWoW_QuestEN[26584] = { title = "Shaken and Stirred", description = "I have sent my brothers to assault the Verlok village from below. The Verlok will gather on their rocky ledges, as they always do to avoid our ire. When they do, we shall make the earth itself shake them until they fall at our feet below.\n\nThat is where you prove your use. When they fall to the ground amongst my brothers, make sure that they do not rise again.", objectives = "Kill 8 Verlok Pillartumblers in the lower section of Verlok Stand.", completion = "Well done fleshling. Your presence complimented my brothers well." }
WordHunterWoW_QuestEN[26585] = { title = "Corruption Destruction", description = "If this disgusting growth is truly brought on by the Verlok, then their supplies will be in their village to the north. Bring them to me so that I can verify your claims.", objectives = "Retrieve 8 bags of Verlok Miracle-Grow.", progress = "I await your proof, <race>...", completion = "So your words prove true. You have my gratitude, <race>." }
WordHunterWoW_QuestEN[26586] = { title = "In Search of Bravo Company", description = "If you and Keeshan are going to defend Lakeshire, we're going to need to find his old battalion. Last I heard all of 'em - Messner, Jorgensen, Krakauer and Danforth - were captured by the Blackrock orcs. Now I don't know where they could possibly be or if they're even alive, but I'd be a damned fool if I didn't ask you to try and find 'em.\n\nSearch Alther's Mill, east of here, for any clues.", objectives = "Search Alther's Mill for a member of the Bravo Company.", completion = "Keeshan? You mean JOHNNY'S ALIVE? You bet your sweet behind I'll help, but first you gotta get me out of this damned cage." }
WordHunterWoW_QuestEN[26587] = { title = "Breaking Out is Hard to Do", description = "The key to this cage is stored in a pouch over at the worg den, just north of our location. The problem is that the pouch is resting safely atop a tree stump amidst a sea of bloodthirsty man-killing worgs.\n\nYou've got one shot to get that key without waking up any of those sleeping worgs. Head to the worg den and find a way into the center. Tread carefully and watch out for the Blackrock worg captain. Get the key and return to me.\n\nIf you got a pet, I'd recommend telling it to stay back!", objectives = "Retrieve Messner's Cage Key.", progress = "Did you get the cage key?", completion = "IT'S PAYBACK TIME!" }
WordHunterWoW_QuestEN[26588] = { title = "A Furious Catch", description = "Are you up for a challenge, {name}?  Good, I was hoping you would be.  The Southfury River flows just west of Orgrimmar and your challenge can be found within its mighty flow.\n\nWe are looking for a giant furious pike.  This esteemed fish used to be prevalent in these areas but ever since the floods hit, the big ones have been much harder to find.  Head out to the river and let's see just how good of an angler you really are.", objectives = "Catch a Giant Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar's western gate. Return to Razgar in the Valley of Honor once you are done.", progress = "Were you able to catch a giant pike?", completion = "<name>, you got one!  It's a rare day that I get to see such a strong, beautiful fish." }
WordHunterWoW_QuestEN[26589] = { title = "The Wilds of Feralas", description = "You are truly brave to help us protect these lands, hero. If you wish to do more for the wilds, there are others in need of your aid.\n\nThe verdant forests of Feralas lie to the south. There, in the shade of the mighty Twin Colossals, you must seek out Konu Runetotem. He has found signs of a disturbing illness.\n\nFollow the road west around the Twin Colossals to find Camp Ataya. Go in peace, {name}, and walk with the Earth Mother.", objectives = "Travel to Feralas and speak with Konu Runetotem at Camp Ataya.", completion = "Peace, friend. I wish we could have met under less troubling circumstances." }
WordHunterWoW_QuestEN[26590] = { title = "The Holy Water of Clarity", description = "Hey, listen.  You don't look like any old tourist, and I'm in a bit of a pickle.  My cousin up north sent me this weird artifact, and I need your help to... ah... identify it.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  Rumor has it that whoever drinks from this spring is given a vision of clarity.\n\nSounds pretty promising, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", objectives = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", progress = "<Flem's ears perk up as you approach.>\n\nThe Holy Water of Clarity?  Is it here!?", completion = "<The goblin downs the water in one gulp.>\n\nAhh... do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nOh, right... that artifact.  Clarity...\n\nI've got it!" }
WordHunterWoW_QuestEN[26591] = { title = "Battlefront Triage", description = "You seem quick on your feet, {race}. I need someone to go out into the chaos of the front and patch up our injured.\n\nTake my kit. It's simple enough to use.\n\nHeal them before the stone troggs finish them off for good.", objectives = "Patch up 10 Injured Earthen.", completion = "If you ever get tired of your being a <class>, come look me up. You seem very good with those fleshy hands of yours." }
WordHunterWoW_QuestEN[26592] = { title = "Diffractory Chromascope", description = "To properly identify this artifact, I will need tools for analysis.  A diffractory chromascope should suffice, I think.\n\nI already have the mithril casing, which surprisingly, is the hardest part to find.  We simply need two other pieces: a ruby and a sapphire.\n\nThere's pirates nearby, just to our south, and a bit farther to the east.  Pirates love treasure... why don't you see if you can find some gems for me?", objectives = "Obtain a Bloodsail Ruby and a Bloodsail Sapphire.", progress = "<Flem's eyes sparkle.>\n\nAre those gems I see?", completion = "<Flem weighs the gems in his hands and nods in approval.>\n\nYes, these will do.  Now to perform the analysis...\n\n<The goblin clacks the gems together for a while, then looks up at you.>\n\nOh, you're still here?  You don't think I'm a fraud or something, do you?" }
WordHunterWoW_QuestEN[26593] = { title = "Scaring Shaky", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me.  Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt elder mistvale gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", objectives = "Obtain 5 Mistvale Giblets from Elder Mistvale Gorillas.", progress = "Hey!  I don't like the look you're giving me, mister.", completion = "Ack!  Where'd you get these?  No, don't tell me. I don't want to know!\n\nWho sent you?  Sea Wolf?" }
WordHunterWoW_QuestEN[26594] = { title = "Return to MacKinley", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", objectives = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.", progress = "Here here, <name>.  Did you get Shaky's payment?", completion = "Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?\n\nHah!  He's so easy to read, when I play cards with him I can't help but win!\n\nThanks for your help, <name>.  Now it's your turn to get paid..." }
WordHunterWoW_QuestEN[26595] = { title = "Kill-Collect", description = "There's three phases to debt collecting: asking nicely, asking forcefully, and something I like to call \"Phase Three\".\n\nUnfortunately, collecting during Phase Three is something that this old dog can't do any more.  That's why I employ so many cronies, stooges, mooks, goons, and noble adventurers like yourself!\n\nJuntz Fitztittle, Ephram Moonfall, and Maury Wilkins are hiding out on the eastern coast.  You should have no problem visiting them all in one trip... and bringing back their valuables.  ", objectives = "Obtain Maury's Clubbed Foot, Fitztittle's Ratcheting Torque Wrench, and Ephram's Jeweled Mirror.", progress = "<name>, did you find those debtors?", completion = "Great!  I can get a good price for these, especially for what's inside Maury's foot!  Thanks much, <name>!\n\nI hope those three learned their lesson: don't bet something you can't afford to lose.\n\nAnd maybe it's too late for them, but...they should be careful of who they gamble with." }
WordHunterWoW_QuestEN[26596] = { title = "The Call of Kalimdor", description = "I've been sent by the good people of Theramore to find loyal members of the Alliance who are willing to help Lady Jaina with some problems in Dustwallow.\n\nYou weren't really here working for the goblins, were you?\n\nThe path back to Dustwallow will take you through Ratchet.  Wait on the end of this pier for the next boat.  Once you get to Ratchet, speak with Gazlowe.  He'll point you in the right direction from there.\n\nUgh, I think I stepped on a fish!  And it flopped!", objectives = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe.", completion = "Yeah?  Whaddya need?" }
WordHunterWoW_QuestEN[26597] = { title = "Stranglethorn Fever", description = "Sick...so...very s-s-sick... have contracted Stranglethorn Fever....\n\n...technically... CAPE of Stranglethorn Fever....\n\n...deadly v-v-virus....\n\n...only cure... is... is... to eat the heart of M-m-m-m-mokk the Savage... elusive white beast....\n\n...Witch Doctor Unbagwa... only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape....\n\n...hurry... dying... dying....", objectives = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", progress = "....mother?\n\n...so cold...\n\n...heading into the Twisting Nether...h-h-h-hold me mother....", completion = "...feel strength returning....\n\nWhere might I be?  Booty Bay?  Oh my!  I had the strangest dream...\n\n...the weakness has not completely left me...." }
WordHunterWoW_QuestEN[26598] = { title = "The Heart of Mokk", description = "", objectives = "Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!\n\nMe speak with spirits and make he come, I do.\n\nBut other gorilla-beast like spirit talkin' too.  You protect Witch Doctor Unbagwa and I make he come to you.\n\nWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!", progress = "Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!\n\nMe speak with spirits and make he come, I do.\n\nBut other gorilla-beast like spirit talkin' too.  You protect Witch Doctor Unbagwa and I make he come to you.\n\nWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!", completion = "Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.\n\nYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!" }
WordHunterWoW_QuestEN[26599] = { title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  I will not rest until their corpses pepper the ocean floor!\n\nOne of the giants, Gorlash, stole my captain's chest.  I hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", objectives = "Obtain Smotts' Chest from Gorlash in the Cape of Stranglethorn.", progress = "Ahoy, <name>!  Did you find Gorlash?  That chest was my favorite, and it has a hidden compartment that held my greatest treasures!", completion = "You found it!  What a glorious day for ol' Hecklebury, this is.  Getting back my chest cools some of the fire in me.\n\nBut my revenge isn't complete..." }
WordHunterWoW_QuestEN[26600] = { title = "A Giant's Feast", description = "The next giant on my list is called Negolash.  I remember vividly how he leapt from the seafoam and plucked poor Poop-Deck Paul from the crow's nest.\n\nSwallowed him in one gulp, he did.  And snapped my mizzenmast in two on the way down.\n\nNo man on my crew deserves such a heinous death.  So we're going to use Negolash's appetite against him.  Kelsey Yance should be able to sell you some meat, and Whiskey Slim has enough booze to knock out... well, a sea giant.  You'll find both of them in town.", objectives = "Purchase a Crate of Grade-E Meat from Kelsey Yance and a Crate of Pupellyverbos Port from Whiskey Slim.", progress = "We're going to need a lot of food, <name>.  Quantity over quality is the goal here.", completion = "This wasn't expensive, was it?  Well, here's some pieces of eight to reimburse you.\n\nNow let's get onto this revenge, shall we?" }
WordHunterWoW_QuestEN[26601] = { title = "Mok'rash the Cleaver", description = "Mok'rash the Cleaver is the last of the lot.  And the largest, by my memory.  Taller than a wave in a windstorm, with a beard like a kelp forest and a hammer like an oak tree.\n\nHe taunts me from Janeiro's Point, the island right off the end of this very pier.  It's because of him that I'm still trapped here, living this lamentable landlubber's life.\n\nIf you can swim, then head out to Janeiro's Point and slay Mok'rash.\n\nTake care, {name}.  Mok'rash will not lay down as easily as his brothers.", objectives = "Kill Mok'rash the Cleaver at Janeiro's Point.", progress = "I've been waiting for this moment, <name>.", completion = "Mok'rash... Negolash... Gorlash... they're all gone.\n\nI suppose I have no excuses now.  I can return to the high seas and a life of pillage and booty!  And it's all thanks to you.\n\nNow I just need to get myself a ship..." }
WordHunterWoW_QuestEN[26602] = { title = "A Dish Best Served Huge", description = "Take this food, and put it in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come running!\n\nAnd when he does, there will be a stouthearted {class} ready to knock his corpse back into the briny deep.", objectives = "Bring the Giant Crate of Giant Food to Captain Smotts' lifeboat, then use it to summon and kill Negolash.", progress = "Is it done, <race>?", completion = "I can't believe my fortune, <name>!  Meeting you has turned my luck to the better, make no mistake there!\n\nIf I ever get a new ship and you're looking to sail the seas, you would be my honored guest." }
WordHunterWoW_QuestEN[26603] = { title = "Message in a Bottle", description = "Inside the bottle you find a note which reads, in fairly good handwriting:\n\n<To any that can aid me->\n\n<Please, my need for help is dire. A great beast holds me captive on an island in the South Seas.>\n\n<The stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see shoreline to the northwest, and what seem to be large sailing ships to the southwest.>\n\n<I beg of you, my would-be savior, please help me.>", objectives = "Find the author of the message at Jaguero Isle in the Cape of Stranglethorn.", completion = "Have you come to free me?" }
WordHunterWoW_QuestEN[26604] = { title = "Protecting Her Royal Highness Poobah", description = "These vicious jungle cats have been circling me for some time now.  I watch them as closely as I can, but they seem to just... disappear into the grass.\n\nHow they snarl and hiss!\n\nDon't get me wrong... I still want you to rescue me, but first, clear out some of these cats.  I won't need to be rescued if I end up someone's dinner.", objectives = "Slay 5 Jaguero Stalkers.", progress = "Please, my hero, dispose of the stalking panthers!", completion = "It's about time you returned.  I was beginning to worry that I was going to be eaten while you hunted.\n\nA cat eating a princess... wouldn't that be a fancy feast?" }
WordHunterWoW_QuestEN[26605] = { title = "Grubby Little Paws", description = "I understand that you're anxious to rescue me, but the time is not yet right.  First I'm going to need some of my things.\n\nThe gorillas and the monkeys on the other side of the island have taken most of my possessions.  I'll need my tiara, my scepter, my slippers, and my diary before I'm ready to leave.\n\nWhat?  Stop looking at me like I'm some sort of insane person.  You don't know what it's like being a princess.", objectives = "Obtain Poobah's Tiara, Poobah's Scepter, Poobah's Slippers, and Poobah's Diary from the apes on Jaguero Isle.", progress = "I shudder to think what Mukla plans to do with me.", completion = "<Poobah surveys her belongings.>\n\nLooks like it's all here.  Alright, I think I'm ready to be rescued now." }
WordHunterWoW_QuestEN[26606] = { title = "Mukla's Demise", description = "{name}, I now put my faith in you to help free me.  The great Skymane King Mukla is my captor.  He commands the beasts of this island, and they keep me here against my will with the aid of this chain.  If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", objectives = "Slay King Mukla obtain the Shackle Key.", progress = "I thank my ancestors someone has come to aid me. Do you have the key that will free me?", completion = "<name>, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown." }
WordHunterWoW_QuestEN[26607] = { title = "They Drew First Blood", description = "Take this bundle of Keeshan's possessions and head back to the Lakeshire inn basement. Bravo Company is already there, talking to Keeshan. Remind him of who drew first blood, {name}. Lakeshire needs Keeshan. The Alliance needs Keeshan.\n\nDismissed, soldier!", objectives = "Deliver Keeshan's Possessions to John J. Keeshan at the Lakeshire Inn in Redridge.", progress = "You again?", completion = "<Keeshan takes the bundle from you and opens it.>\n\nMy bow... and knife! Where did you...\n\nJade's amulet... My darling Jade.\n\n<Keeshan picks up his red headband.>\n\nWe got orcs to kill." }
WordHunterWoW_QuestEN[26608] = { title = "Negotiations Terminated", description = "Go now, go back to your fleet. Tell them what kind of a monster claims authority over the Dragonmaw.\n\nOur \"Warchief\" is a traitor to his blood. Since his return from Outland he reeks of demon and leads what remains of our clan to ruin.\n\nHelp rid the Dragonmaw of Mor'ghor, and those of us with pure blood will be your allies forever. This I can promise.", objectives = "Return to Admiral Stonefist off the shore of Dragonmaw Hold in Twilight Highlands.", completion = "The Fel Orcs from Outland have laid claim to the Dragonmaw? Obscene!\n\nIf Hellscream knew what was happening here, he'd raze their city to the ground..." }
WordHunterWoW_QuestEN[26609] = { title = "The Bloodsail Buccaneers", description = "You sure seem eager to work, matey.  Not sure why some land-loving {race} {class} is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nWe've made Booty Bay our happy home away from the high seas, but word has it that the Bloodsail have some new plan cooked up.  All me boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", objectives = "First Mate Crazz wants you to check the cove north of Booty Bay.", completion = "On top of the barrel, you discover a map with some hastily written text on it, along with some coins." }
WordHunterWoW_QuestEN[26610] = { title = "Bloodsail Treachery", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"Set up your command post here, and bide your time.  The Fleet Master will send out word when it's time to make your move.\"\n\n\"I'm placing Lieutenant Bruce in charge here.  This time will be different.  This time we take Booty Bay once and for all.\"\n\nThe map is held in place with a dagger, placed right through the location of Booty Bay.", objectives = "Report your findings to First Mate Crazz in Booty Bay.", completion = "Sure, I remember you, <class>.  Back from scouting I see...." }
WordHunterWoW_QuestEN[26611] = { title = "The Baron Must Be Told", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Baron Revilgaz at once!  You'll find him here in Booty Bay.", objectives = "Report the planned Bloodsail attack to Baron Revilgaz.", completion = "Bloodsail Buccaneers attacking Booty Bay?  This isn't the first time that those blaggards have tried something.  Booty Bay is impenetrable!\n\nSounds like they might be changing their strategies up, though.  Wouldn't put it past Firallon to try something crazy.  Very well, let's see what else they're up to." }
WordHunterWoW_QuestEN[26612] = { title = "Details of the Attack", description = "I want to know details, {name}.  Our supremacy over the Bloodsail is due largely in part to our stronghold here in Booty Bay, but intelligence also plays a critical role.\n\nThe Bloodsail maintain a few meager camps to the south which they call their \"Southern Command.\"  Well, you're going to raid their excuse for a southern command, find their plans, and slaughter their men.  Return with whatever information you can find.", objectives = "Kill 8 Bloodsail Sea Dogs and 8 Bloodsail Elder Magi, and bring back the Bloodsail Charts and the Bloodsail Orders.", progress = "Ahoy, <name>.  What word do you bring of the Bloodsail encampment to the south?", completion = "Perfect, <name>.  Now that we know their plan, it's just a matter of time.\n\nAnd to think the fools have dropped anchor just off the cape...." }
WordHunterWoW_QuestEN[26613] = { title = "Up to Snuff", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless {class} like you could convince 'em to share the goods, eh?", objectives = "Deeg in Booty Bay wants you to bring him 15 tiny heaps of Snuff.", progress = "Any luck finding the goods, matey?", completion = "Good show, <name>!  And just before I need to ship out too!  Can't thank you enough, old friend." }
WordHunterWoW_QuestEN[26614] = { title = "Keep An Eye Out", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", objectives = "Retrieve Dizzy's Eye from the Bloodsail Buccaneers.", progress = "Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.\n\nCould really use me eye back.  Captain's going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.\n\nWhat good is a lookout who can't see?  The crow's nest used to be me home...without me deadlights I'd be lucky to scrub the bilge.", completion = "Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let's see if she still fits.\n\n<Kshhh-thunk>\n\n<name> ho!  Blimey, I can see!!" }
WordHunterWoW_QuestEN[26616] = { title = "It's Never Over", description = "Those Blackrock orcs are gonna need an army to handle the Bravo Company and you, {name}. When you're ready to go, meet us at the dock facing Lake Everstill and we'll set off on my riverboat for Camp Everstill on the other side of the lake.\n\nSee you there, {name}.", objectives = "Take Keeshan's Riverboat to Camp Everstill in Redridge.", completion = "It's orc killin' time." }
WordHunterWoW_QuestEN[26617] = { title = "An Old Sea Dog", description = "This old, weathered coin was found on the body of the pirate \"Good-Boy\" Bruce.  Its front side bears the image of a large, unfamiliar pirate ship; on its back side, the term \"Brashtide Crew\".\n\nSomeone who has been in the piracy business for some time might know what this coin is, or what it means.", objectives = "Bring the Weather-Beaten Coin to Fleet Master Seahorn in Booty Bay.", progress = "What's that you've got there, <race>?  Let me see it.", completion = "That coin!  Where did you get it?\n\nBruce... yes, I see.  He was one of the Blackwater Raiders once.  One of us, before Greymane closed the Gilneas ports and held his crew captive.\n\nI know that what happened in Gilneas changed the people there, but I never expected them to change their loyalties.  Especially not Bruce.\n\nIf you wouldn't mind, could I keep the coin?  I'll pay its worth in gold." }
WordHunterWoW_QuestEN[26618] = { title = "Wolves at Our Heels", description = "The dire wolves are the most common threat to the townsfolk here. They lurk in the forests on all sides of us, though most are along the north bank of the river.\n\nThese aren't the runt dogs you see in Elwynn, or wherever you come from. They're big as a man and twice as vicious.\n\nIf you wish to assist the people of Darkshire, hunt the dire wolves so our streets can be safer.", objectives = "Kill 12 Dire Wolves.", completion = "Don't go thinking that was too easy. Far greater dangers lurk deeper in the woods." }
WordHunterWoW_QuestEN[26619] = { title = "You Say You Want a Revolution", description = "If what you say is true, {name}, then we have friends within the Dragonmaw Clan. We can support an insurgency from within their ranks and avoid a lot of bloodshed on both sides.\n\nI can help, but the most dangerous part is up to you.\n\nMy Axebite Warriors will launch an offensive on the shores. During the confusion, I need you to slip behind the lines and speak with your revolutionary contact, Zaela.\n\nWe'll arm the Dragonmaw and overthrow their fel masters! ", objectives = "Slip through the front lines at Dragonmaw Port and speak with Zaela.", completion = "<name>, what are your people doing? Are you attacking the Dragonmaw or are you here to rid us of Mor'ghor's corruption?\n\n\n\nAh, I see now. I like the way you think. Warchief Mor'ghor won't even know what hit him.\n\nLet's do this!" }
WordHunterWoW_QuestEN[26620] = { title = "Seasoned Wolf Kabobs", description = "Seasoned wolf kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.\n\nBring me five wolf skirt steaks.  The dire wolves near the river north of town are good to hunt; I wouldn't stray too far into the woods if I were you.", objectives = "Gather 5 Wolf Skirt Steaks from Dire Wolves.", progress = "Were you able to find five wolf skirt steaks yet?", completion = "Mmm-mmm! The skirtsteak's the best part. It's not an efficient way to cook, though.\n\nHere, have this recipe. It's a little different, but flank meat's easier to come by when you really need a meal." }
WordHunterWoW_QuestEN[26621] = { title = "Insurrection", description = "The weapons the Horde has supplied us with will be more than enough. The four of us should split up and arm as many Dragonmaw workers and merchants as we can.\n\nDon't underestimate us, {name}. You'll find even our tradesmen are ferocious in battle.\n\nLet's do as much damage as possible. Arm a squad of Dragonmaw and lay waste to the fel enforcers and warlocks that have intimidated my people for so long. Then meet back here to launch our final strike!", objectives = "Arm 3 Dragonmaw Workers or Merchants, then slay 10 Dragonmaw Enforcers and 4 Dragonmaw Warlocks.", progress = "Revolution, at last!\n\nThe Dragonmaw are finally undoing the shackles of the filth who have held us back!", completion = "We've lost a lot of good orcs, but the fight is going our way, <name>.\n\nMor'ghor's regime is collapsing. All that remains is to destroy the beast himself." }
WordHunterWoW_QuestEN[26622] = { title = "Death to Mor'ghor", description = "The time has come. Mor'ghor dies today.\n\nBe warned, {class}. Demon blood courses through his wretched veins, and he channels unnatural power. He will be destroyed, yes. But it will not be an easy fight.\n\nYou remember where Mor'ghor resides, at the top of the camp. I will meet you there. Finish him!\n\nBe sure to recruit 3 Dragonmaw followers if you are short - you will need our help.", objectives = "Slay Warchief Mor'ghor in Dragonmaw Port. You can still recruit Dragonmaw Merchants and Workers to help you.", completion = "Well done, <name>! You have done the Horde proud in my absence.\n\nThe Dragonmaw have joined us, with Zaela as their new leader. Blood was shed, but casualties were low, and we have their complete loyalty.\n\nOur Horde grows stronger!" }
WordHunterWoW_QuestEN[26623] = { title = "Dusky Crab Cakes", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider meat!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!\n\nIf you want to try some still, I'm afraid I'm out of meat. I need some lump meat to whip up a few more cakes.\n\nVenom Web Spiders are a good source - they nest to the north, between the foothills and the river.", objectives = "Gather 6 Dusky Lumps from Venom Web Spiders.", progress = "Hail, <name>.  Did you get that lump meat for me?", completion = "Ah yes, a nice lump you have there!  Let me just get this seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...\n\nAnd, although Dusky Crab Cakes are my specialty and I won't give out the recipe, here's the recipe for a dish that's almost as good." }
WordHunterWoW_QuestEN[26624] = { title = "Getting In With the Bloodsail", description = "These plans are... interesting.  Firallon, you're smarter than this!\n\nLook, he has all three ships devoted to cannon fire, and only a few men coming in through the tunnel.  He can never take Booty Bay with three ships and a dozen footmen.  And he knows that.\n\nNo, they've got something else planned... and you're going to find out what it is.  Speak to Yancey Grillsen, the Bloodsail Recruiter, just to the north of town.\n\nThat's right, {name}.  You'd better hope that they don't recognize your face.", objectives = "Report to Yancey Grillsen at the waterfall north of Booty Bay.", completion = "Yarr, ya made a good decision, lad." }
WordHunterWoW_QuestEN[26625] = { title = "Troggzor the Earthinator", description = "You have to put an end to this now!\n\nGo back northwest onto the front and kill their battle leader, Troggzor the Earthinator. Bring me his cudgel as proof.", objectives = "Obtain the Earthinator's Cudgel.", progress = "Is he dead? Do you have the cudgel?", completion = "<Gravel solemnly nods his head.>\n\nFinally, we can move forward and rescue the Stonefather." }
WordHunterWoW_QuestEN[26626] = { title = "We Have a Situation", description = "One of Clay's catapult teams is broken down on the front. I need you to get some parts from him and get that catapult back in the fight, <name>.You will receive:", objectives = "Speak with Clay Mudaxle on the Fractured Front in Deepholm.One of Clay's catapult teams is broken down on the front. I need you to get some parts from him and get that catapult back in the fight, <name>.You will receive:" }
WordHunterWoW_QuestEN[26627] = { title = "The Hermit", description = "I've been told there's signs of activity at Beggar's Haunt. People have reported seeing lights in the tower to the east of town.\n\nFew would be bold enough to stay that close to Deadwind Pass. You're the first to report since I've learned about this; go check it out and make sure whatever's in there is human.", objectives = "Find the denizen of the tower at Beggar's Haunt.", completion = "Ah, welcome, stranger. I'd offer you something, but there's not much here...\n\nCould I beg you to run some errands for a poor old hermit?" }
WordHunterWoW_QuestEN[26628] = { title = "Death From Below", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, {name}?", objectives = "Protect Shakes O'Breen during the attack.", completion = "We survived the attack!\n\nWe could not have done it without you, <name>.\n\nWe'll be heading out as soon as the tide rises. If you weren't such a promising hero I'd offer you a place on my crew. But I can tell you have bigger fish to fry.\n\nEven if you are a puny <race>...." }
WordHunterWoW_QuestEN[26629] = { title = "Seeing Where Your Loyalties Lie", description = "Thar be just one thing...\n\nYancey hears things.  A few o' me hearties were pretty deep in their cups when they told me about some {race} {class} that came a-rollin' through the Southern Command lookin' for charts and orders.  Even ran a couple o' good pirates through, he did.\n\nLike I said, they were up to their eyeballs in grog, but still... a buccaneer's gotta trust his ears.  So I've just got one small task for ye, one sent down from Firallon hisself...\n\nBring me the head of Fleet Master Seahorn.", objectives = "Obtain the Head of Fleet Master Seahorn in Booty Bay.", progress = "Firallon special-ordered this one himself.  Said the tauren's too much of a risk.", completion = "Well blow me down!  Now there's something ya don't see too often.\n\n<Yancey reaches out and shakes your hand.>\n\nWelcome aboard, <name>.  Plunder and booty await ye." }
WordHunterWoW_QuestEN[26630] = { title = "Looks Like a Tauren Pirate to Me", description = "Firallon wants MY head?  Now that's interesting.  But it's nothing we can't work around.\n\nThis Yancey character probably doesn't know my face too well.  Most non-tauren find us tauren indistinguishable from one another.  In fact... most non-tauren find us indistinguishable from... a certain four-legged farm creature.\n\nRikqiz the leatherworker keeps one of these creatures here in Booty Bay, and Narkk is my chief supplier for pirate hats.  Get a replacement head and a hat, then return with both.", objectives = "Obtain a Cow Head and an Oversized Pirate Hat, then bring them back to Fleet Master Seahorn.", progress = "You should know that most tauren would find this shameful.  I find it... amusing.", completion = "That should fool that Bloodsail dimwit.\n\nThis was fun, <name>." }
WordHunterWoW_QuestEN[26631] = { title = "Your First Day as a Pirate", description = "Ye may be a slayer of Fleet Masters, but rules is rules and orders is orders.  And MY orders say that all new pirates start out as swabbies.  It's the rule.\n\nYou're to be working for Captain Keelhaul, the commander of the Riptide.  It's the westernmost ship in the fleet, which is parked south of the tip o' the cape.\n\nFind him in his captain's chambers, and bring yer papers.", objectives = "Bring Yer Papers to Captain Keelhaul.", progress = "I trust y'got yer papers, swabbie.  I'd hate t'send ye all the way back to Yancey.", completion = "Yes... yes... I see... well, everything appears to be in order.\n\nSlayer of the great Seahorn, eh?  That doesn't matter on MY ship.  Only thing you're gonna be slaying is deck stains.  Grab a mop." }
WordHunterWoW_QuestEN[26632] = { title = "Close Escort", description = "Alright, I think I've got it working again. You've got to get the catapult to the stone trogg town, Needlerock Slag, just to the north of the front.\n\nThe driver will go with you. I'll head back and let Gravel know.\n\nThere's no doubt that the stone troggs will try to stop you. You just keep them off of the catapult. It packs a big punch.\n\nLet me know when you're ready, {name}.", objectives = "Escort the Earthen Catapult safely to Needlerock Slag.", completion = "<The catapult chief gives you an appraising look.>\n\nWord of your prowess has spread ahead of you, <race>. Let's see if you can help us keep these fungal horrors off of the front." }
WordHunterWoW_QuestEN[26633] = { title = "Swabbing Duty", description = "I want the surface of the Riptide t'shine like a star ruby, Swabbie {name}.  I keep a tight ship around here, and it's swabbies like you that make it happen!\n\nWell, what're y'waitin' for, y'cockle-brained bilgerat?  Head updecks and start swabbin'!", objectives = "Pick up a Swabbie's Mop on the deck of the Riptide, then keep the deck clean for 2 minutes.", completion = "I heard the most furious mopping sounds from down here, mate.  That's EXACTLY what your Captain likes to hear." }
WordHunterWoW_QuestEN[26634] = { title = "The Bane of Many A Pirate", description = "Gum disease.  It's a real problem, {race}.\n\nI know you're new and all, and probably haven't ever needed your gums cut, but the rest of us pirates have to deal with a little thing called SCURVY.  It's why we keep so many limes around here.\n\nWell... we used to keep limes around here.  Someone made off with our last shipment, but they can't have gone far - maybe to the nearby islands?  Bring them back, and maybe I'll see what I can do to get you promoted from swabbie.", objectives = "Obtain 5 Bushels of Limes.", progress = "I've seen too many good men die to such a preventable disease, <race>.  We need those limes.", completion = "I'll distribute these right away, <race>.  And I'll see what I can do to put in the good word for you." }
WordHunterWoW_QuestEN[26635] = { title = "Cannonball Swim", description = "Help out a fellow swabbie?\n\nKeelhaul asked me to gather up some cannonballs at the bottom of the ocean.  Let me tell you why this doesn't work for me.\n\n- One: I have tiny arms.  Look at them!  Do you really think I can pick up a cannonball, even underwater?\n\n- Two: I have a weak respiratory system.  I start to white out after holding my breath for more than ten seconds.\n\n- Three: There are sharks.\n\nYou gotta help me, {name}!  I've been demoted as far as I can... I don't want to see what comes next!", objectives = "Obtain 6 Bloodsail Cannonballs from the water beneath the Riptide.", progress = "I wasn't always a swabbie, you know.", completion = "Thanks, <name>.  I'd been hearing whispers about \"Pretty Boy\" and a \"boo-box\".  I don't think I want to go in the boo-box." }
WordHunterWoW_QuestEN[26636] = { title = "Bravo Company Field Kit: Camouflage", description = "We're gonna need some supplies before we take out the Blackrock army and save Redridge. That's where you come in, rookie.\n\nKeeshan put me in charge of getting camouflage together for the Bravo Company field kit. What I need you to do is head south and do a little \"gardening.\" There are two parts to this little adventure that you should know about: (1) Leaves and (2) Fox poop. We need 'em both.\n\nWhat did you think camo was made of?\n\nHead south and gather what I asked for, pal.", objectives = "Gather 5 Piles of Leaves and 5 pieces of Fox Poop.", progress = "Leaves and poop - that's what I need.", completion = "Nice job, rookie. I'm gonna go ahead and put the camo in the box. We should be ready soon." }
WordHunterWoW_QuestEN[26637] = { title = "Bravo Company Field Kit: Chloroform", description = "The first part of this mission is all covert ops, {name}. To that end, we need to be able to incapacitate the enemy without making any sounds. To do that we're going to need chloroform.\n\nThe muckdwellers at the bottom of Lake Everstill hold chloroform in their glands. I'm going to need you to go underwater and recover muckdweller glands. Think you can handle it?\n\nCome back to me once you've recovered enough glands.\n\nWhere's the lake you ask? Open your eyes, dummy. Directly west.", objectives = "Collect 8 Muckdweller Glands.", progress = "Did you recover the glands?", completion = "Perfect. Those orcs won't know what hit 'em - literally. I'll need a few minutes to get these in working order and then I'll put them in the Bravo Company field kit." }
WordHunterWoW_QuestEN[26638] = { title = "Hunting the Hunters", description = "Just south of here on the Lakeridge Highway are a group of Blackrock orcs that stalk the forests under cover of darkness and ambush the uninitiated. That group is the first line of defense for the Blackrock army. They're scouts, reporting everything they see back to their central command. They need to be taken OUT or our mission here could be compromised.\n\nHead south and kill every Blackrock hunter that you see.", objectives = "Kill 8 Blackrock Hunters.", completion = "Great work, <name>. We need to move quickly before they send for reinforcements." }
WordHunterWoW_QuestEN[26639] = { title = "Point of Contact: Brubaker", description = "Before we do a damned thing we need to get a field kit together. You'll help with that, {name}. There's also a matter of scouting. Thankfully for that we got some help from Stormwind. An old war buddy of mine, Brubaker, was sent here by SI:7 to scout around for us. You're to meet him in the field, just south of here.\n\nMeet up with Brubaker and find out what he knows.", objectives = "Find Brubaker.", completion = "Brubaker is dead. It looks like the orcs are attempting to send a message with this grisly display. Upon closer examination you notice something in Brubaker's pouch." }
WordHunterWoW_QuestEN[26640] = { title = "Unspeakable Atrocities", description = "<You unfold the note and begin reading.>\n\nKeeshan, if you're reading this note, I'm dead. Likely that my position was compromised.\n\nOrcs are committing unspeakable atrocities against their prisoners. Yes, prisoners, Keeshan. They've got cages full of P.O.W's. If you're gonna blow up this valley, you'll need to free the prisoners first.\n\nTell my wife I love her and to take out the damned trash.\n\n-Brubaker\n\nPS - They've got black dragons.\n\nTake Brubaker's report back to Keeshan.", objectives = "Deliver Brubaker's Report to John J. Keeshan at Camp Everstill in Redridge.", progress = "They got Brubaker?", completion = "<Keeshan reads the report.>\n\nDAMN IT! This just got complicated. We've got prisoners of war to rescue before we can blow up the valley. Not to mention the orcs have black dragons on their side.\n\nAre you ready, <name>?" }
WordHunterWoW_QuestEN[26641] = { title = "Can't Make An Omelette Without...", description = "The Vilebranch broodguards to the northeast tend the eggs of Shadra's brood. Even if we kill the Vilebranch, those eggs will still sit there, waiting to hatch and release those horrible creatures further into the wilds.\n\nWe need to take care of this properly. Tear any eggs you see out of the egg sacks and bring them to me. Don't try to destroy them on your own; you might let the little ones out.\n\nWhen you get them back here, I'll see that they're properly disposed of!", objectives = "Collect 5 Shadraspawn Eggs from Agol'watha.", progress = "Do you have the eggs?", completion = "I'll see these are burnt to ash right away, and scattered to the winds for good measure." }
WordHunterWoW_QuestEN[26642] = { title = "Preserving the Barrens", description = "For years, the Barrens have been the heart of the Horde presence on Kalimdor, a vital link between the orcs of Durotar and the tauren settlements in Mulgore.\n\nIn the chaos of the cataclysm, floods, earthquakes, and even a quilboar invasion threaten to separate us from this vital grassland.\n\nYou look ready for a challenge. Report to Kargal Battlescar at Far Watch Post and ensure the route to the Barrens remains clear! Head west from nearby Razor Hill and cross the Southfury River to find him.", objectives = "Report to Kargal Battlescar at Far Watch Post in Northern Barrens.", completion = "A fresh recruit from Orgrimmar is it?\n\n<Kargal sizes you up.>\n\nI'll take what I can get. Keeping the roads open has been a nightmare." }
WordHunterWoW_QuestEN[26643] = { title = "Starvation Diet", description = "The Creeping Ruin to the east is crawling with fully-grown Shadraspawn spiders. They're large enough to drag off an entire dwarf in the night, and you'll see evidence enough of that when you get there... bodies are cocooned all through the ruins.\n\nThey don't keep them alive for long, {name}, but they feed off the bodies for days. It's too late to save the victims, but we can't let those spiders grow fat and thrive. Make sure you get rid of those cocoons.", objectives = "Destroy 6 Cocooned Victims at the Creeping Ruins.", completion = "A grim task for sure, <name>, but it'll keep the spiders left alive from recovering. I thank you." }
WordHunterWoW_QuestEN[26644] = { title = "Attracting Attention", description = "Swabbie {name}!  This is a sad day fer ol' Cap'n Keelhaul.  Today I lose m'best swabbie.\n\nA letter's come in from Fleet Master Firallon.  Apparently he's heard about the excellent swabbin' y'been doin', and he wants t'take ye aboard the Crimson Veil as his Jack o' Swords and third mate.  She's moored just next t'the Riptide.\n\nPiracy career-wise, this's a big step fer ye, Swabbie {name}.  I recommend y'take his offer.\n\nDismissed!", objectives = "Report to Fleet Master Firallon within the Crimson Veil in the Cape of Stranglethorn.", completion = "So ye be the one that did ol' Seahorn?  Yancey sent word, but I wanted to make sure he hadn't been telling his tall tales again.\n\nI'll make it brief.  Ye did well on Keelhaul's crew, but I expect ye to do even better on mine.  I've got an entire fleet to attend to, so you'll be helpin' to run the day-to-day of me ship.\n\nWelcome aboard the Crimson Veil, sailor." }
WordHunterWoW_QuestEN[26645] = { title = "The Night Watch", description = "I'm afraid you're all I've got to help here, {name}. Stormwind's forces are so taxed by greater evils that they can't spare a single footman to protect Darkshire. It's up to me and the rest of the Night Watch to keep our homes safe.\n\nThere's more threats here than just wolves, unfortunately. Rotting horrors roam near Blind Mary's Haunt, on the southeast outskirts. If they're not kept in check, they'll be visiting our homes in the night.\n\nDeal with the undead and report back to me for your bounty.", objectives = "Kill 8 Rotting Horrors near Blind Mary's Haunt, southeast of Darkshire.", progress = "I don't have authority to order you around, <name>. But at least think of the citizens here who'll be suffering if those undead are allowed to lurk.", completion = "Splendid, <name>.  For your service to the people of Darkshire you shall be rewarded." }
WordHunterWoW_QuestEN[26646] = { title = "Prisoners of War", description = "The Bravo Company field kit is ready, {name}. I'm gonna equip you with it and you're gonna enter Render's Valley, southeast of here, and free our P.O.W.s.  I'm sending Jorgensen with you to watch your back.\n\nNow the prisoners are being held on the northeast side of the valley in a large cage, but the key to the cage is in a cave on the south side of the valley. You'll have to steal the key, create a distraction, and free the citizens.\n\nGood luck, {name}! I'll be in touch through the field kit.", objectives = "Free the Prisoners of War locked up in the prison at Render's Valley.", completion = "<The radio on the Bravo Company field kit crackles.>\n\nLooks like the P.O.W.s are free. Time to initiate Operation: End All." }
WordHunterWoW_QuestEN[26647] = { title = "Ol' Blasty", description = "We've got some work to do.  How much experience have you got with cannons?  Hmm... really?  Well, how about with ancient, fallin'-apart pirate cannons?\n\nWe've got a few cannons updecks that work the old-fashioned way: you load one cannonball in at a time, aim, lock it into place, and fire.  Works well if you're tryin' to hit the side of a three-sailer... not so well for rowboats and the like.\n\nWhy don't you head upstairs and lob a few shots at Smilin' Timmy Sticks?", objectives = "Practice using the cannon by hitting Smilin' Timmy Sticks 5 times with cannonballs from Ol' Blasty.", progress = "You look a little green, <name>.  You feelin' alright?", completion = "I like the cut of your gib, <name>." }
WordHunterWoW_QuestEN[26648] = { title = "Our Mortal Enemies", description = "Hey, new guy, take a look at this.\n\n<The dwarf flips up his eyepatch to reveal a living, functional eyeball.>\n\nI don't wear this patch because of any lost eye.  I wear it because this OTHER eye is so strong, the normal one was just weighin' it down.\n\nThis eye's good for seein' all kinds of things, like those masked hooligans that follow us around.  Fleet Master says that they've been spotted over on Jaguero Isle.  Once you get there, fire this flare gun, and I'll help you spot 'em.", objectives = "Kill 15 Ninjas on Jaguero Isle.", completion = "Excellent work, <name>.  The eternal battle wages on, but we've tipped the scales in favor of the pirates today.  Firallon will be happy to hear the news." }
WordHunterWoW_QuestEN[26649] = { title = "Drive-By Piracy", description = "Now that you know how to handle our cannons, it's time to hit some real targets!\n\nThe Venture Company has found gold to the north of here... a rare type they call \"Black Gold\".  More like a Black Spot if you ask me.\n\nWe're going to take that gold, but first, we need to get rid of those Venture Company goons.  I've got an oarsman who will take you out there.  Head off the ship down the gangplank and speak with him on the islet's northern shore.", objectives = "Speak with the Bloodsail Oarsman outside the Crimson Veil, then use the cannon to kill 75 Venture Co. Oil Workers.", progress = "Those goblins will learn the fury of the Bloodsail!", completion = "Ahahaha!  Blasted 'em clear off their rigging!  I'll drink to that!\n\nYou've got a bright future, kid." }
WordHunterWoW_QuestEN[26650] = { title = "The Damsel's Luck", description = "I know ye just arrived here on the Crimson Veil, but I need to send ye off on another task.  The Damsel's Luck is the third ship in me fleet, moored over to the east.  Her skipper - Captain Stillwater - is no longer with us.\n\nDamn those masked hoodlums!\n\nAnyhow, Ironpatch told me about yer heroics at sea, and I be runnin' low on quality brigands.  I think yer more than capable for this new duty.\n\nCongratulations, matey.  Ye be the new captain of the Damsel's Luck.", objectives = "Report to your Captain's Chambers within the Damsel's Luck in the Cape of Stranglethorn.", completion = "You see a set of plans unrolled on the table.  They explain everything!\n\nThese are the details of the impending attack on Booty Bay.  Battle formations, plans of attack, and something about a group called the \"Brashtide Crew\"." }
WordHunterWoW_QuestEN[26651] = { title = "To Win a War, You Gotta Become War", description = "<The Bravo Company radio beeps.>\n\nDo you understand yet, {name}? Do you now see what we gotta do to win a war against these monsters? YOU GOTTA BECOME WAR! NO MERCY!\n\nWith the P.O.W.s freed you're clear to plant the seaforium. Carefully make your way into each of the structures out there and plant a charge.\n\nPlant a seaforium charge at the Blackrock munitions hut and the Blackrock tower. Once you're done meet up with me and the rest of Bravo Company at Shalewind Canyon, east of Render's Valley.", objectives = "Use the Bravo Company Field Kit to plant a Seaforium Charge at the Blackrock Tower and Blackrock Munitions Hut.", completion = "And now, we blow the whole damned thing up." }
WordHunterWoW_QuestEN[26652] = { title = "Ghost Hair Thread", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", objectives = "Bring the Spectral Comb to Blind Mary.", progress = "<Sob> Oh please, don't look at me!  I tore out these eyes with my own hands, but I can still feel your gaze!\n\nI'm hideous!  Hideous!  Please, look away!!", completion = "What is this?  A comb?  It's lovely!  And it glides through my hair as if it weren't the stiff, stringy horror that it is.\n\nOh, if only I had a mirror..." }
WordHunterWoW_QuestEN[26653] = { title = "Supplies from Darkshire", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some ghost hair thread?  You can get it from Madame Eva at her home on the Darkshire square.", objectives = "Speak with Madame Eva in Darkshire.", completion = "Ah, ghost hair thread is what you need, is it?  I'm afraid I have none in stock, but I can make some for you...if you can supply the ghost hair." }
WordHunterWoW_QuestEN[26654] = { title = "Return the Comb", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", objectives = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", progress = "I sense that you have seen Blind Mary.  You have my comb...?", completion = "I can make a spool of ghost hair thread with this, and have a few strands to spare.  Here are some coins for those extra strands." }
WordHunterWoW_QuestEN[26655] = { title = "Deliver the Thread", description = "Here is your thread, {name}.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", objectives = "Bring the Ghost Hair Thread to Abercrombie in his tower at Beggar's Haunt.", progress = "I need to string the ghost hair thread along my door and my windows to keep out unwanted spirits.  Did you get it for me?", completion = "Delightful!  This will do splendidly...\n\nHere, good <name>, take this as payment for your honorable deed." }
WordHunterWoW_QuestEN[26656] = { title = "Don't. Stop. Moving.", description = "When Deathwing came, the Stone Dragons flocked to him. In his absence, they are again without purpose. They swarm and feed upon our kin.\n\nI have bound dozens of Opalescent Guardians, but am unable to lead them from the safety of cover. I need someone more swift, as I suspect you might be.\n\nLead them by ground towards Therazane's Throne to the east. Surely, some will not make it, but as long as you keep moving, you should be able to bring several to join our forces there.", objectives = "Rush at least 5 Opalescent Guardians east by ground, out of the Pale Roost, to the stone circle near Therazane's Throne.", progress = "Did they make it, <class>?", completion = "Well done. Of my main strengths, speed is not one." }
WordHunterWoW_QuestEN[26657] = { title = "Hard Falls", description = "Stone Dragons bow only to strength. When we have punished them enough, they will bend back to our will.\n\nI have sent many of my strongest giants onto the fields in the west. They will bring the drakes to the ground. You will see to it that they do not take wing again after they fall.", objectives = "Kill 6 Stone Drakes.", completion = "Not just fast it seems. You have some bite in you.\n\nWell done, <class>." }
WordHunterWoW_QuestEN[26658] = { title = "Fragile Values", description = "It is now time to draw the Broodmother's attention. To do so, we will need a mallet that the troggs use when making offerings to her.\n\nSeek out the Stone Trogg Beast Tamers that are attempting to tame basilisks in the southern portions of the Pale Roost. You will find a mallet on one of their corpses.", objectives = "Retrieve a Stonework Mallet.", progress = "Did you find a mallet?", completion = "Glorious.\n\nNow we will deal a blow to the stone dragons that they will remember for the next hundred years." }
WordHunterWoW_QuestEN[26659] = { title = "Resonating Blow", description = "On the western edge of the Pale Roost, you will find a resonating crystal. Strike it with the mallet and the broodmother will come.\n\nBe ready for battle. I will be there to aid you, but she will not be easily overcome.", objectives = "Defeat Aeosera.", completion = "Impressive, fleshling. You are far more capable than I initially assumed.\n\nI will extend that sentiment to the Stonemother as well." }
WordHunterWoW_QuestEN[26660] = { title = "Zombie Juice", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, {name}.  These nights get cold, and I need that drink to put fire in my veins again!", objectives = "Speak with Tavernkeep Smitts.", completion = "You need some Zombie Juice, do you?  Hmm...that's some strong stuff - I don't usually get requests for it." }
WordHunterWoW_QuestEN[26661] = { title = "Gather Rot Blossoms", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nRot blossoms grow in strange places.  They tend to flourish on dead things, and Duskwood has its fair share of those!\n\nI've seen a few of them growing at Tranquil Gardens Cemetery lately. Check near the graves... but mind the dead that are walking about near there.", objectives = "Gather 5 Rot Blossoms from Tranquil Gardens Cemetery.", progress = "Hi, <name>.  Do you have those rot blossoms for me yet?", completion = "Good,  you got the rot blossoms.\n\nI'll whip up the zombie juice... it's strong stuff, I warn you." }
WordHunterWoW_QuestEN[26662] = { title = "The Brashtide Crew", description = "The charts mention a group called the Brashtide Crew.  This name is new to you, though you've heard about a few other newcomers to the Buccaneers.\n\nMaybe it's time you paid them a visit and found out what they know.", objectives = "Speak with Long John Copper on the Damsel's Luck, Enormous Shawn Stooker on the Crimson Veil, and Wailing Mary Smitts on the Riptide.", completion = "The Brashtide Crew aren't just pirates... they're worgen pirates!  And they're joining in on the attack!\n\nRevilgaz is definitely going to want to know about this." }
WordHunterWoW_QuestEN[26663] = { title = "Sinking From Within", description = "The attack on Booty Bay is looming.  You'll have to return to Booty Bay quickly and inform the Baron.\n\nFirst, however, it might be a good idea to sabotage some of the pirates' supplies while you're still in their favor.  The pirates keep most of their supplies belowdecks, spread out across the entire fleet.", objectives = "Sabotage the Barrel of Grog, the Barrel of Gunpowder, and the Crate of Cannonballs.", completion = "You've set the pirates back several days' work.  Hopefully this will delay their attack." }
WordHunterWoW_QuestEN[26664] = { title = "Making Mutiny", description = "Before returning to Booty Bay, you should do everything you can to weaken the Bloodsail Buccaneers.  Unfortunately, even as captain, you're prohibited from killing other buccaneers in cold blood.  Only a Fleet Master can do that.\n\nYou can, however, put mutineers to the sword... and mutiny can be awfully hard to disprove.\n\nSpeaking of which, those Bloodsail corsairs that hang out on the lowest level of the ships have been acting awfully suspicious...", objectives = "Accuse 9 Bloodsail Corsairs of mutiny, then kill them.", completion = "The fewer Bloodsail Buccaneers that Booty Bay has to fight, the better.  However, it might be best to stop slaughtering your supposed allies before you draw suspicion to yourself." }
WordHunterWoW_QuestEN[26665] = { title = "Call of Booty", description = "You feel like you've done just about enough damage, and you know the Bloodsail's battle plans.  You've done everything that Baron Revilgaz has asked of you.\n\nIt's time to hang up the pirate hat and return to Booty Bay.  The battle looms near.", objectives = "Report to Baron Revilgaz at Booty Bay in the Cape of Stranglethorn.", completion = "The Brashtide!?  I thought they were dead and gone YEARS ago!\n\n<Revilgaz listens intently as you relay the information you gathered.>\n\nNo, that absolutely makes sense.  And it's not good news either.  The Brashtide are formidable foes, and if their numbers are anywhere near what they were before they disappeared, we're in for a nasty battle." }
WordHunterWoW_QuestEN[26666] = { title = "The Legend of Stalvan", description = "I'm here because I received a letter from my brother Stalvan, who I haven't seen in years. On arriving here, I was told he was dead...\n\nThe entire town refuses to offer any further explanation. Any mention of his name is met with terror and suspicion. As if I didn't have enough of that myself!\n\nI'm afraid of what will happen if my frustration and anger grows any further. I beg you, help me get to the bottom of this. Implore Clerk Daltry for any information he may have on my brother.", objectives = "Seek out Clerk Daltry in the Darkshire Town Hall.", completion = "Can I help you?" }
WordHunterWoW_QuestEN[26667] = { title = "The Stolen Letters", description = "You want to know about Stalvan...\n\nYou're not the first, you know. We get outsiders coming through asking about him every so often. Always outsiders. Everyone who lives here knows better.\n\nYou're out of luck, anyway. I'm missing half the archives. Feral worgen broke into the town hall not a few nights ago and tore the place to shreds.\n\nThe documents you'll want are probably strewn all across Brightwood Grove by now, deep in the woods to the west. Not worth it if you ask me.", objectives = "Collect the Bundle of Shredded Letters from Brightwood Grove.", progress = "Look, sir, I really don't want any trouble...", completion = "By the Light... you actually went and got it?\n\nI'm shocked. I suppose I owe you thanks for returning it to the archives." }
WordHunterWoW_QuestEN[26668] = { title = "Detonation", description = "Those explosives you planted were high yield, {name}. When I push this button on the Bravo Company field kit, that whole valley is gonna be consumed by a massive fireball of death.\n\nYou know, I think you should do the honors. You did all the hard work, after all.\n\nReady?", objectives = "Blow up Render's Valley.", completion = "Did you see those orcs explode? THAT'S HOW WE DO IT IN BRAVO COMPANY! Now to clean up the rest of these jackasses." }
WordHunterWoW_QuestEN[26669] = { title = "In A Dark Corner", description = "If you're that serious about this, I'll help you, {name}. I know where the other documents must be. I'm just too terrified to do anything about it.\n\nThere's only a few places that those horrible Nightbane beasts gather when they're not prowling the forest. One of them's the Rotting Orchard to the south. They use the buildings there as their dens, so if they haven't just eaten the other documents, you might find one there... but you'll have to search their lairs thoroughly, I wager.", objectives = "Search the Rotting Orchard for the Torn Journal Page.", progress = "You're back in one piece, I see.", completion = "This was all you found?\n\nThat's bad news, I'm afraid..." }
WordHunterWoW_QuestEN[26670] = { title = "Roland's Doom", description = "This isn't all of it...\n\nYou should let it go, {name}. The only place left to look is Roland's Doom. That's the mine south of town, and the largest lair of worgen in Duskwood. Nobody in Darkshire has ever made it back from that place alive. In fact, some of the records I have here imply that's where the monsters first came from... who knows what evil's lurking in there?\n\nPlease, {name}, just give it up. Let's just forget about this whole thing, and never speak of it again.", objectives = "Search Roland's Doom for the remaining pages of Stalvan's Journal.", progress = "I told you, <name>, it's not worth pursuing...", completion = "You actually went and got it?!\n\nI don't know whether to call you brave or insane. But once again, my archives thank you." }
WordHunterWoW_QuestEN[26671] = { title = "The Fate of Stalvan Mistmantle", description = "You've recovered everything. Everything except the last page...\n\n...which I've got right here. Don't look at me like that. You'll understand when you read it. Some even say it's cursed, you know. In fact, I was relieved when the worgen broke in and made off with these!\n\nTake it. Take all of it, in fact. I thank you for recovering my archives, but I don't want anything to do with this ever again. Please, just leave me be.", objectives = "Take The Legend of Stalvan back to Tobias Mistmantle.", progress = "You're back! Did you find anything about my brother?", completion = "I can't thank you enough... I had hoped for this to be a joyous reunion, but the more I learn, the less glad I am to have asked.\n\nBut I must know." }
WordHunterWoW_QuestEN[26672] = { title = "Clawing at the Truth", description = "This can't be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...\n\n<Tobias brings a hand to his face, averting his gaze.>\n\nI must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.\n\nI need to know why...\n\nTake my ring, {name}. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I'll try anything at this point.", objectives = "Bring the Mistmantle Family Ring to Madame Eva.", progress = "What dark whispers guide you to my door, <class>?", completion = "How interesting. It's been quite a while since I've seen such a ring..." }
WordHunterWoW_QuestEN[26673] = { title = "REUSE - BREADCRUMB", description = "This can't be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...\n\n<Tobias brings a hand to his face, averting his gaze.>I must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.\n\nI need to know why...\n\nTake my ring, <name>. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I'll try anything at this point.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Mistmantle Family Ring to Madame Eva." }
WordHunterWoW_QuestEN[26674] = { title = "Mistmantle's Revenge", description = "I'm afraid I cannot give Tobias the answers he seeks. But I can help you find the only person who can...\n\nStalvan Mistmantle.\n\nTake the ring into the woods to the north, to Manor Mistmantle, where Stalvan's body was buried. Enter, and hold the ring before you. Let the waning moon pour its light through the ring, and the spirits will answer your call.\n\nTake heed, {name}. The questions of the living can offer more comfort than the answers of the dead.", objectives = "Use the Mistmantle Family Ring at Manor Mistmantle, north of town.", completion = "Master Harris may have been right. I would have been better to leave the past behind.\n\nI've got a new life now. Whether it's that of a monster or a man is up to me.\n\nAs for you, I cannot thank you enough for your assistance, regardless of the outcome. Please, take this with my thanks." }
WordHunterWoW_QuestEN[26675] = { title = "The Value of Trust", description = "The troubles of this world seem to never fade. They shift, change, and reform, but they are ever-present.\n\nThe wind brought us whispers of a traitor in our midst. We sent one of our best sentinels to investigate, and now she has turned up dead. I did her disservice in assuming that the traitor would not be aware of our movements... I was brash, and she paid for my folly.\n\nI need a new face to pick up the trail. Someone the people of the city won't know. This is a dangerous request. Will you help me?", objectives = "The troubles of this world seem to never fade. They shift, change, and reform, but they are ever-present.\n\nThe wind brought us whispers of a traitor in our midst. We sent one of our best sentinels to investigate, and now she has turned up dead. I did her disservice in assuming that the traitor would not be aware of our movements... I was brash, and she paid for my folly.\n\nI need a new face to pick up the trail. Someone the people of the city won't know. This is a dangerous request. Will you help me?" }
WordHunterWoW_QuestEN[26676] = { title = "Juice Delivery", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", objectives = "Bring the Zombie Juice to Abercrombie at Beggar's Haunt.", progress = "I need that Zombie Juice to keep me warm on these cold, dark nights.  Did you get it for me?", completion = "A thousand thanks, <name>.  You warm an old man's heart with your foolish-...I mean...with your kindness!\n\nHere you are, friend.  Take this as a token of my gratitude." }
WordHunterWoW_QuestEN[26677] = { title = "Ghoulish Effigy", description = "Out here on the outskirts of town, it's a wonder the walking dead haven't eaten me!  In fact, just yesterday a pack of ghouls was pounding on the walls of my tower!\n\nI want to make an effigy - a kind of \"scarecrow\" for ghouls.  To do that I need some ghoul ribs.  You can find plenty of them on the fetid corpses wandering Manor Mistmantle's grounds, north of Darkshire...\n\nGet the ribs for me, and I will repay you with some coin.", objectives = "Gather 7 Ghoul Ribs from Fetid Corpses at Manor Mistmantle.", progress = "I'm sure you could find plenty of ribs in Raven Hill as well, but you might not want to wander so far at night...", completion = "Ah, thanks.  These will do just the trick!" }
WordHunterWoW_QuestEN[26678] = { title = "Doublerum", description = "<Baron Revilgaz sighs.>  Even with all my suspicions about Firallon's plot, we aren't prepared for a full two-front attack between the Bloodsail and the Brashtide.  It's going to take a small miracle to hold Booty Bay today.\n\nI've got a barrel of Doublerum in my chambers.  Take the stairs down three flights, and check the first door on your right.  You can ignore the warnings on the barrel... those should be the least of your worries.", objectives = "Find Baron Revilgaz's Barrel of Doublerum within Booty Bay.", completion = "This must be the doublerum.  You pour a glass for Revilgaz, then consider pouring one for yourself..." }
WordHunterWoW_QuestEN[26679] = { title = "Return to Revilgaz", description = "Something is happening outside.  Could the Bloodsail already be here?\n\nYou'd better get Revilgaz his doublerum.  Quickly.", objectives = "Bring the Doublerum to Baron Revilgaz at Booty Bay.", progress = "Guess who showed up while you were gone?", completion = "<The Baron quickly empties his cup.>\n\nAH!  Much better, <name>.  Now, let's get down to business.  I believe that you and I have a town to save." }
WordHunterWoW_QuestEN[26680] = { title = "Ogre Thieves", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, {name}, retrieve this crate for me for I miss it sorely.", objectives = "Return Abercrombie's Crate to Abercrombie.", progress = "Do you have my crate?  If so, then please...give it to me quickly!", completion = "Thank the Nec-...well, thank YOU, <name>!  You have more than earned your reward.\n\nAha!  Happy!  Happy nights ahead!!" }
WordHunterWoW_QuestEN[26681] = { title = "Note to the Mayor", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", objectives = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", progress = "A letter? What's this all about?", completion = "<Ello looks at the letter, and immediately pales.>\n\nYou fool! You've doomed us all!" }
WordHunterWoW_QuestEN[26682] = { title = "A Shambling Threat", description = "Dustwallow is Horde territory, {name}. The humans may have their little island and their precious sand bar, but the marsh belongs to us.\n\nIn time, we will surely win this stalemate with the humans. For now, we must master our own territory. The withervine bog beasts to the north rise from the marsh itself to attack any living thing that approaches. If we own this marsh, we must not let our own land fight back against us!\n\nSlay the bog beasts, if you wish to serve the Horde. You will be rewarded.", objectives = "Slay 7 Withervine Creepers or Withervine Ragers in the marsh north of Brackenwall Village.", completion = "Well done, <name>. We'll be able to focus on greater threats here now." }
WordHunterWoW_QuestEN[26683] = { title = "Look To The Stars", description = "My gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars. According to Cog's blueprint, what I need first is a way to reflect light.\n\nI remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", objectives = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.", completion = "Why yes, I used to own a looking glass." }
WordHunterWoW_QuestEN[26684] = { title = "The Insane Ghoul", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an insane ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", objectives = "Retrieve Mary's Looking Glass from the Insane Ghoul.", progress = "I showed Cog the beginnings of our star-viewing machine.  He was impressed.  Did you happen to find a reflective device?", completion = "Most superb!  This will work perfectly.  Many thanks!" }
WordHunterWoW_QuestEN[26685] = { title = "Classy Glass", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", objectives = "Kill Zzarc'Vul in the southern ogre mound in Duskwood and collect the Ogre Monocle.", progress = "Were you able to convince Zzarc'Vul to lend us his monocle for our experiment?", completion = "At last!  The stargazing device is complete!  Thank you, <name>.  Now I can continue my research. . ." }
WordHunterWoW_QuestEN[26686] = { title = "Bones That Walk", description = "There's even fouler undead left to deal with, {name}.\n\nTranquil Gardens Cemetery, further south of town, is a place you don't want to be caught in at night. The bones that rise from the ground there are cunning enough to remember how to swing an axe or cast a spell.\n\nI shouldn't need to explain how dangerous that makes them. Proceed with caution, but remember the people of Darkshire that will suffer if you falter.", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 5 Skeletal Warriors and 5 Skeletal Mages.", completion = "The people of Darkshire thank you, <name>.  You have proven yourself to be a great ally of The Night Watch." }
WordHunterWoW_QuestEN[26687] = { title = "Reinforcements From Theramore", description = "Hawthorne dead... my own son murdered... the situation in the Barrens is out of control, {name}.\n\nI'm going to take charge of Fort Triumph and try to lock things down. To do that, I'm going to need reinforcements. Reinforcements that were promised from Theramore weeks ago!\n\nTravel to Theramore in Dustwallow Marsh and give Captain Garran Vimes an earful. What good is that blasted road through the swamp if the men and materiel aren't rolling in?", objectives = "Travel to Theramore Isle in Dustwallow Marsh and talk to Captain Garran Vimes in the main barracks.", completion = "What now, soldier?\n\nReinforcements? For the Barrens? We've been bleeding supplies and men there for months!\n\nDoes someone need to remind Twinbraid of the attack on Northwatch? Our losses at Honor's Stand? What happened to the men I sent to Fort Triumph? We've nothing to spare!\n\nListen <name>, if you want to help out our cause, you'll focus your efforts here in Dustwallow. Between the deserters and the Horde encroachment... we could use a hand." }
WordHunterWoW_QuestEN[26688] = { title = "Worgen in the Woods", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane worgen in Brightwood Grove. We'll see if you have what it takes to hunt these monsters.", objectives = "Kill 7 Nightbane Worgen in Brightwood Grove.", completion = "Impressive, <name>. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities." }
WordHunterWoW_QuestEN[26689] = { title = "The Rotting Orchard", description = "The worgen infestation stretches further than Brightwood Grove. To the south, on the very edges of Darkshire itself, the Rotting Orchard is host to even more of the savage beasts.\n\nThe worgen there are more cunning, {name}, but just as savage and evil. They conjure foul shadows to tear their enemies apart from a distance. Go to the Rotting Orchard, and slay the Shadow Weavers to keep the town safe!", objectives = "Kill 10 Nightbane Shadow Weavers at the Rotting Orchard.", progress = "Back so soon, <name>? I hope you haven't come to tell me you've given up.", completion = "You performed well against the Shadow Weavers, <name>. But even now, years after their first arrival, there seem to be so many to replace the ones we kill.\n\nI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem." }
WordHunterWoW_QuestEN[26690] = { title = "Vile and Tainted", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", objectives = "Kill 8 Nightbane Vile Fangs and 8 Nightbane Tainted Ones in Roland's Doom.", progress = "Intimidating beasts aren't they? But have no fear, <name>, those who stand for the Light will never fall!", completion = "<name>, to be honest with you, I did not believe that you would get this far, but you are clearly a <class> to be reckoned with. In fact, if you wish to formally join Master Carevin's struggle, I will gladly write for you a letter of recommendation." }
WordHunterWoW_QuestEN[26691] = { title = "Worgen in the Woods", description = "Here you go, {name}. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", objectives = "Bring Calor's note to Jonathan Carevin.", progress = "Yes, what is it? Make it quick, I've pressing matters to attend to.", completion = "Excuse me for my cold reception, <name>, but as I'm sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.\n\nThere are unsavory types afoot, <name>, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.\n\nGlory under the Light." }
WordHunterWoW_QuestEN[26692] = { title = "Shadowhide Extinction", description = "Now that every Blackrock orc south of Lake Everstill is nothing more than ash and cinder, we can turn our attention to the Shadowhide gnoll army of Galardell Valley, directly north of here.\n\nI want you to head out there and kill 'em all, {name}! Initiate Operation: Extinction, soldier. For Bravo Company and for the Alliance!", objectives = "Kill any 20 Shadowhide Gnolls.", completion = "We're closing in on the Blackrock high command. There's nowhere left for those dogs to run." }
WordHunterWoW_QuestEN[26693] = { title = "The Dark Tower", description = "We got lucky with some vital intelligence from the locals of this valley. Those two behind us, the Ranthals, have informed me that the gnolls in Galardell Valley are being controlled by a powerful magus in the tower of Ilgalar. The problem is that the tower is sealed by a magical force field.\n\nThe first thing we need to do is get the key that will get you inside. The gnoll general, Fangore, has your ticket inside. Kill General Fangore and get the key.\n\nI'll be in touch.", objectives = "Recover the Key of Ilgalar.", progress = "I hear you loud and clear, <name>.", completion = "<Keeshan comes in over the Bravo Company field kit.>\n\nNow that the easy part is over, it's time for phase two." }
WordHunterWoW_QuestEN[26694] = { title = "The Grand Magus Doane", description = "<The Bravo Company field kit vibrates.>\n\nGood work, kid. I've got some vital intel for you. The magus in the tower is a human named Doane. Damned traitor is working for the Blackrock orcs. I want him dead.\n\nUse the key of Ilgalar and get inside that tower. Work your way to the top and show Doane what Bravo Company does with traitors.\n\nRendezvous back at Shalewind Canyon when the deed is done.\n\nKeeshan, over and out.", objectives = "Kill Grand Magus Doane.", progress = "I hear you loud and clear, <name>.", completion = "He teleported away? Mentioned Darkblaze? What the hell is going on here.\n\nLooks like it's time to strap in and finish this nonsense." }
WordHunterWoW_QuestEN[26695] = { title = "Prepare for Takeoff", description = "I've got an idea, but it's going to involve some footwork on your part.  As a goblin cartel, the Blackwater Raiders have a lot of explosives on hand.  In fact, I know for a fact that our old friend Narkk keeps a case in the back of his shop, in the Old Port Authority.\n\nGo grab them and bring them here, if they haven't already exploded.", objectives = "Obtain Narkk's Handbombs from the Old Port Authority inside Booty Bay.", progress = "You're still alive?", completion = "You brought them!  I'm beginning to think the tide is turning in our favor, <name>." }
WordHunterWoW_QuestEN[26696] = { title = "The Call of Kalimdor", description = "Say, you haven't seen a fish about this long?  Short fins?  Responds to the name Steve?  He's blue?\n\nNever mind, I'll keep looking.\n\nActually... there was another reason I came here to Booty Bay.  Boss Krog, over in Dustwallow, is looking for new blood.  Someone to help us Stonemaul from getting overrun.  You look strong enough.\n\nWait on the edge of the pier for the next ship, then ride to Ratchet.  Gazlowe should be able to help you from there.\n\nSteve?  Steve!", objectives = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe.", completion = "Yeah?  What can I do for ya?" }
WordHunterWoW_QuestEN[26697] = { title = "The Final Voyage of the Brashtide", description = "We'll never survive this attack with all these worgen pirates pouring into the harbor from the north.  Luckily, it looks like they're not armed with cannons, so if we can get you out of the harbor, you can attack from the skies.\n\nKebok, the Horde flight master's assistant, is right around the corner.  Talk to him and let him know that you're going to need his bravest wind rider.\n\nBring a couple armloads of handbombs with you.  You'll need all of them to stop those attack boats!", objectives = "Speak with Kebok in Booty Bay to board a Bold Wind Rider. Then use the handbombs to kill 85 Brashtide Crewmen and destroy 6 Brashtide Attack Boats.", progress = "We're still overwhelmed, matey.  Get back out there and protect my town!", completion = "I hope those mongrels know how to doggy paddle!\n\nActually, I take that back." }
WordHunterWoW_QuestEN[26698] = { title = "Seeking Seahorn", description = "When the Brashtide pulled in, Seahorn grabbed the nearest weapon he could find and jumped off the ledge here.  You'll find him down below, probably pounding new holes into those worgen's skulls.\n\nHelp him out down there.  I can handle the motivation from up here.", objectives = "Report to Fleet Master Seahorn in Booty Bay.", completion = "I should have known these Brashtide were alive and up to no good.  I'd written them off years ago." }
WordHunterWoW_QuestEN[26699] = { title = "Turning the Brashtide", description = "The Brashtide are everywhere!  The Baron's Booty Bay Bruisers are no match for their sheer numbers, I'm afraid.\n\nWhile you're down here in the fray, why don't you help me get rid of a few of them?\n\nWhen you're done, don't bother coming back here.  I'll probably be pretty busy.", objectives = "Kill 10 Brashtide Raiders in Booty Bay.", completion = "We need to keep moving, <name>.  Booty Bay won't hold out for much longer." }
WordHunterWoW_QuestEN[26700] = { title = "The Damsel's (Bad) Luck", description = "I heard that this ship here is the Damsel's Luck.  Didn't you used to be the captain of that thing?  You must know your way around it, then.\n\nThe Brashtide are our main concern, but we still don't want to take an unnecessary pummeling from those cannons of theirs.  Grab this rope behind me and take out some of those angry-looking corsairs.  Check in with the Baron when you're done.", objectives = "Kill 8 Bloodsail Corsairs in Booty Bay.", completion = "Attacking your former crewmen...\n\nYou really have grown into a real pirate, <name>!" }
WordHunterWoW_QuestEN[26701] = { title = "Flight to Brackenwall", description = "Listen, I got no special love for the Horde... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.\n\nThat two-headed ogre and his pet fish left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Krog.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", objectives = "Speak with Bragok in Ratchet to fly to Brackenwall Village. Then report to Krog.", completion = "Lok'tar, <race>.  Welcome to Brackenwall." }
WordHunterWoW_QuestEN[26702] = { title = "Flight to Theramore", description = "Listen, I got no special love for the Alliance... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.  Sometimes better.\n\nJeyne left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Calia Hastings.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", objectives = "Speak with Bragok in Ratchet to fly to Theramore. Then report to Calia Hastings.", completion = "Welcome to Theramore." }
WordHunterWoW_QuestEN[26703] = { title = "Bloodsail's End", description = "We've nearly won the day, largely thanks to you.  One task remains, however... kill Fleet Master Firallon.\n\nIt looks like most of Firallon's crew is already dead, but I know that old sea dog well enough to know that he's not done yet.  No, he's cooped up tight in his cabin, ready to go down with his ship.\n\nSpeak with Kebok again to get a wind rider.  I'll try to hold off the cannonfire while you're on board.", objectives = "Speak with Kebok in Booty Bay to get a wind rider, then kill Fleet Master Firallon.", completion = "<name>!  You're awake!  We found you bobbing in the harbor, shortly after the remaining attackers had turned tail.  We were worried about you for a while there...\n\nI've been meaning to thank you, <name>.  Not only did you provide us with the intelligence to prepare for this attack, but you helped fight off the Bloodsail AND the Brashtide.  Your name will always be remembered here in Booty Bay.\n\nWe here in Booty Bay pride ourselves on our booty.  Care to take first pick?" }
WordHunterWoW_QuestEN[26704] = { title = "REUSE", description = "", objectives = "" }
WordHunterWoW_QuestEN[26705] = { title = "It's a Town-In-A-Box Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[26706] = { title = "Endgame", description = "We need to get rid of that flying gunship if our people have any chance of escaping.\n\nHere's the plan.  Keel Harbor had its share of rebel sympathizers in the old days.  I've managed to round up a hefty amount of incendiary explosives from one of our storehouses.\n\nWe're going to hit the enemy with a force small enough to fly undetected.  The night elf hippogryphs should do the trick.\n\nTobias will give you the signal when we're ready to go.", objectives = "Jump on a Hippogryph when Tobias signals you and destroy the Horde Gunship.", progress = "The only risks worth taking are the ones that lead to victories worth having.", completion = "We did it, <name>.  We've started the evacuation.  If we leave soon we'll leave the Forsaken fleet in the dust." }
WordHunterWoW_QuestEN[26707] = { title = "A Deadly Vine", description = "I need large amounts of corpseweed for Master Harris's concoctions. It's difficult to obtain, but we can't let our supply dwindle.\n\nCorpseweed is tough stuff to tangle with... the plant will get you before you get it, if you're not careful! But if you'd like to help out, I'll eagerly pay you for any you gather yourself.\n\nYou'll find plenty of it all over the Yorgen Stead to the southeast.", objectives = "Collect 5 pieces of Corpseweed.", progress = "Do you have the corpseweed?", completion = "I thank you, <class>... and I'm sure the worgen that may be returned to sanity with the potion this will make would thank you too." }
WordHunterWoW_QuestEN[26708] = { title = "AHHHHHHHHHHHH! AHHHHHHHHH!!!", description = "I'm here to help you and Bravo Company end this mess. You're to get in the Bravo Company siege tank and clear a path to Keeshan's Post on the other side of the valley, north of here.\n\nThis is a high alert situation soldier as the Blackrock orcs are now aware of your location and sending a large force to meet you head on. Terminate them all with extreme prejudice.\n\nI'll see you on the other side. May the Light have mercy on your soul.", objectives = "Use the Bravo Company Siege Tank to kill 200 Blackrock soldiers.", progress = "We're ready for the final assault.", completion = "The only thing left to deal with now are the orcs holding out at Stonewatch Keep." }
WordHunterWoW_QuestEN[26709] = { title = "The Stone Throne", description = "I am returning to my throne. I've no desire to see any more of these Earthen Ring, but you remain welcome here, {race}. If you wish to help us rebuild our realm, perhaps we can help you in return.\n\nAll things in time.\n", objectives = "Seek out Therazane at Therazane's Throne.", completion = "You returned. This is good. The Stone Lords have been asking after you." }
WordHunterWoW_QuestEN[26710] = { title = "Lost In The Deeps", description = "Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths.\n\nHe's fortunate that his size makes him unworthy of the effort for those gyreworms, but it's only a matter of time before he stumbles too close to one and gets eaten. Whatever he's so intent on down there is certainly not worth it.\n\nHe seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.", objectives = "Find Pebble within the Crumbling Depths and lead him safely out of the tunnels.", progress = "Pebble is much smarter than he lets on, but he is spoiled. I fear one day he may suffer for it.", completion = "You've done well. Now that these are rocklings are free to learn our ways, they will grow tall and strong.\n\nOne day, we will extinguish the gyreworm infestation from our realm, and these rocklings shall no longer be plagued in their youth." }
WordHunterWoW_QuestEN[26711] = { title = "Off to the Bank", description = "Yo, baby. Wassup? You ready for the party?\n\nNo?! You know I love you, so I don't know how to say this, but check it... I think you need to swing into town to buy a new outfit for the party.\n\nDon't look at me like that... you want to look gooood, right? Don't you want to look super fine for me? I am your contractually-obligated boyfriend after all!\n\nSwing by the bank first and pull out plenty of macaroons. You don't want to buy any of that cheap stuff!", objectives = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan.", completion = "Oh, it's you, ma'am! Sorry, I didn't recognize you at first with all of these commoners milling about.\n\nYou people cool your heels! <name> is here!\n\nHere are your macaroons, ma'am. Come back anytime if you need more." }
WordHunterWoW_QuestEN[26712] = { title = "Off to the Bank", description = "Hi, babe. Are you ready for the party?\n\nNo?! You know I love you, right? I think you need to swing into town and buy a new outfit for the party.\n\nDon't look at me like that... you want to look your best? Don't you want to look good for me? I am your contractually-obligated girlfriend after all!\n\nMake sure you swing by the bank first and pull out plenty of macaroons. Don't buy any of that cheap stuff!", objectives = "Speak with the FBoK Bank Teller at the First Bank of Kezan on Kezan.", completion = "Oh, it's you, sir! Sorry, I didn't recognize you at first with all of these commoners milling about.\n\nYou people cool your heels! <name> is here!\n\nHere are your macaroons, sir. Come back anytime if you need more." }
WordHunterWoW_QuestEN[26713] = { title = "Showdown at Stonewatch", description = "Only the Blackrock high command remains, {name}. They're all holed up in Stonewatch Keep, directly south of our position here at Keeshan's Post. I want you and the rest of Bravo Company to enter Stonewatch and put an end to the Blackrock orc invasion.\n\n{name}, no survivors.", objectives = "Kill Tharil'zun and Gath'Ilzogg.", progress = "This doesn't look good.", completion = "<The Bravo Company field kit beeps loudly.>\n\nCome in, <name>. Are you there? If you can hear me: Blackrock has the upper hand. I repeat. Blackrock has the upper hand. GET BRAVO COMPANY OUT OF TH..." }
WordHunterWoW_QuestEN[26714] = { title = "Darkblaze, Brood of the Worldbreaker", description = "As Troteman cuts out, the world around you grows eerily silent. In the distance you see a full grown black dragon!", objectives = "Use the Horn of Summoning to call for Darkblaze. Defeat Darkblaze.", completion = "<A single tear rolls down Troteman's left cheek.>\n\nThey died in defense of the Alliance. In defense of our kingdom! Heroes, all of them, and they will be laid to rest as such." }
WordHunterWoW_QuestEN[26715] = { title = "Malfurion Stormrage", description = "I've spoken to Malfurion of your coming. He seemed very interested in meeting you himself.\n\nYou should go to him in the Temple of the Moon. You'll find him standing beside our beloved Tyrande Whisperwind, where he's remained diligently ever since his return.\n\nI must warn you... Malfurion has his reservations. You may be carrying a great burden for your people by being the one to meet with him.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Malfurion Stormrage in the Temple of the Moon in Darnassus.I've spoken to Malfurion of your coming. He seemed very interested in meeting you himself.\n\nYou should go to him in the Temple of the Moon. You'll find him standing beside our beloved Tyrande Whisperwind, where he's remained diligently ever since his return.\n\nI must warn you... Malfurion has his reservations. You may be carrying a great burden for your people by being the one to meet with him.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26716] = { title = "A Bit of Privacy", description = "I greatly wish to speak with you, but I'd prefer a more intimate environment. One where we might have a bit of privacy from prying ears.\n\nIf you would, meet me in the Temple Garden in just a moment.", objectives = "Meet Malfurion Stormrage in the Temple Garden in Darnassus.I greatly wish to speak with you, but I'd prefer a more intimate environment. One where we might have a bit of privacy from prying ears.\n\nIf you would, meet me in the Temple Garden in just a moment." }
WordHunterWoW_QuestEN[26717] = { title = "The Yorgen Worgen", description = "My kinsmen at Raven Hill are concerned with curing the feral worgen in these forests. The condition itself cannot be lifted, but sanity can be restored to those not too far gone.\n\nWhile most here have proven beyond help, we keep an eye out for those that retain vestiges of their minds... attachments to their old lives.\n\nI've seen a lone worgen lurking the Yorgen Farmstead, digging in a pile of dirt between the buildings...could you check out that pile and see if he's left anything?", objectives = "Examine the Mound of Loose Dirt at the Yorgen Farmstead.", progress = "Did you go look yet?", completion = "Sounds like a close call! But he ran off without harming you further...\n\nHe might be still fighting it. Master Harris must know!" }
WordHunterWoW_QuestEN[26718] = { title = "Breadcrumb to Badlands", description = "Something bad happened.", objectives = "Something bad happened." }
WordHunterWoW_QuestEN[26719] = { title = "Delivery to Master Harris", description = "Master Harris will want to know of this immediately.\n\nHere, take this package of corpseweed down the road to the camp at Raven Hill. Tell him what we saw at the Yorgen Stead.", objectives = "Deliver the Bundle of Corpseweed to Oliver Harris at Raven Hill.", progress = "What brings you out this way, my good sir?", completion = "Welcome to our humble camp. I wouldn't call it pleasant, but it's at least somewhat private.\n\nBeg your pardon? A worgen at the farm?" }
WordHunterWoW_QuestEN[26720] = { title = "A Curse We Cannot Lift", description = "What we do here is not a cure. The transformation cannot be removed once inflicted. But the mind...\n\nThe mind can be restored, through alchemy,  if enough is left intact. This worgen you've encountered sounds like he's fighting to stay aware, {name}. We've got to find him again.\n\nIf he's fled the Yorgen Stead, search the Addle Stead to the south; he may be lurking in one of the buildings.\n\nInject him with this ampule to tranquilize him. You'll need to be quite close.", objectives = "Search the Addle Stead for the Lurking Worgen and use Harris's Ampule to tranquilize it.", completion = "You've got him!\n\nNo time to lose, then. We'll prepare to administer the serum right away.\n\nJITTERS! Get ready!" }
WordHunterWoW_QuestEN[26721] = { title = "The Jitters-Bugs", description = "M-Master Harris requires many reagents for his serums. He has me gather them for him.\n\nMost of it's not so bad... I mean, the corpseweed is pretty bad, but it's not as bad as the widow venom. Have you seen the widows around here? The hatchlings are the size of a man. Even with a gun, I can't stand to go out hunting them!\n\nIt's just too terrifying. If you'll go do it for me, I'll gladly pay you! Just bring me back some widow venom! You'll find them all in the woods to the east, just north of the road.", objectives = "Collect 8 Widow Venom Sacs from Black Widows.", progress = "Did you get it? Please tell me you got it...", completion = "Oh thank you, thank you! You've saved me from having to go out in the woods with those awful things!\n\nAt least for a day, that is..." }
WordHunterWoW_QuestEN[26722] = { title = "Buried Below", description = "<You attach the arch to the rod, and the artifact is nearly complete. A large gap still sits at the center of the holy symbol's head.>\n\n<Once again you feel it tug your arm, urging you towards the hole in the wall and the winding tunnel ahead. The last piece must be through there.>", objectives = "Search the tunnel under the Dawning Woods Catacombs for the Lightforged Crest.", completion = "<In the darkest depths of this earthen tunnel, you spy the faintest gleam. The last piece is found!>" }
WordHunterWoW_QuestEN[26723] = { title = "The Fate of Morbent Fel", description = "Before I was lost to the woods, the last thing I remember is Morbent Fel. He was a vile necromancer, and the reason this land swarms with so many vile undead.\n\nI asked an adventurer to help me put an end to him. I thought they did! But Sister Elsington tells me the land still crawls with ghouls and spectres ripped from the grave.\n\nMorbent Fel should have breathed his last in the house on Forlorn Rowe, north of Raven Hill Cemetery. Go there and see what's become of him...", objectives = "Search Forlorn Rowe for signs of Morbent Fel.", progress = "What did you find?", completion = "His clothes and bloodstains? If it's not tricks, it's something worse..." }
WordHunterWoW_QuestEN[26724] = { title = "The Lurking Lich", description = "The others here share my suspicion. Morbent Fel lives on in undeath...and may be even more powerful than before. A necromancer was struck down, but a lich may have risen in his place. And now he continues to ruin this land.\n\nI remember Duskwood before all this, {name}. I remember bright skies and peaceful woods. This can't stand! Morbent Fel must be stopped for good.\n\nSpeak to Sister Elsington. Her vision might guide you to where Morbent Fel is, and how he can be defeated.", objectives = "Speak with Sister Elsington.", completion = "It's heartening to see one so recently recovered be so concerned with the plight of others. Sven spares himself suffering by not dwelling on his own misfortune." }
WordHunterWoW_QuestEN[26725] = { title = "Guided by the Light", description = "Sven is correct. I can feel the presence of a powerful evil deep beneath the Raven Hill Cemetery. Evil lurks in its catacombs, and Morbent Fel must be the source.\n\nYou will need the power of the Light to strike him down, {name}. Sven told me the heroes who first slew Morbent Fel wielded an artifact of lightforged iron, imbued with holy power. That artifact is still here!\n\nI can feel it as well, a glimmer of light amidst the darkness. Search Raven Hill for it, and let the Light guide you through it.", objectives = "Find the Lightforged Rod in Raven Hill Cemetery.", completion = "<Buried in the cold dirt, you find a brilliant metal shaft. But there are holes where pieces of the artifact are clearly missing.>" }
WordHunterWoW_QuestEN[26726] = { title = "Triumphant Return", description = "Return to Lakeshire and let Solomon know that the Blackrock invasion has been stopped. Make sure he understands the cost at which our freedom came - that we lost five of our finest heroes to save Redridge and ultimately, Stormwind.\n\nYou are the last surviving member of Bravo Company, {name}. It is up to you to keep its legacy alive.\n\nDismissed.", objectives = "Report to Magistrate Solomon at Lakeshire in Redridge.", completion = "They will never be forgotten, <name>. What you and the rest of Bravo Company sacrificed in order to save Redridge will be a tale told for ages to come.\n\nWhile I can in no way make up for the loss of your friends, I feel that you must be rewarded for such a heroic deed. These are Keeshan's possessions - the only things we found when we dredged the lake for his body. Troteman has informed me that Keeshan would have wanted you to take something as the lone surviving member of Bravo Company. Remember them, <name>!" }
WordHunterWoW_QuestEN[26727] = { title = "The Embalmer's Revenge", description = "You're not the first fool to be manipulated by Abercrombie! That doddering old man is known as The Embalmer to us. He's a vile necromancer and a blight upon this town.\n\nAnd now, sewn together and given life by the very materials you brought him, his horrible creation approaches!\n\nThat hideous creature will be upon us in mere moments! If you have any heart, {name}, you'll help the Night Watch drive off the abomination and save our town!", objectives = "Slay Stitches in Darkshire.", progress = "Don't just stand there! He's right outside! By the light, man, do something!", completion = "Thank the Light, he's gone...\n\nI'll say you've made amends by helping save the lives of those here, <name>." }
WordHunterWoW_QuestEN[26728] = { title = "Hero's Call: Duskwood!", description = "{name}, the citizens of Duskwood are in dire need of your assistance! I have here a letter from Commander Althea Ebonlocke, leader of the Night Watch, pleading for help.\n\nTo reach Darkshire you should travel across the bridge located in the southwest corner of Redridge. Once you cross the bridge you will be in Duskwood. Then you just follow the road to Darkshire. Beware of the savage beasts that stalk the countryside!", objectives = "Report to Commander Althea Ebonlocke at Darkshire in Duskwood.", completion = "You are the help that we requested?\n\n<Althea sighs.>\n\nI suppose you will have to do." }
WordHunterWoW_QuestEN[26729] = { title = "Water Elementals", description = "I arrived in Stranglethorn to study a feature known as the Altar of Naias, but made the unfortunate choice of denying Colonel Kurzen's advances, which earned me several years in that cage.  Now that I'm out, I figure I might as well continue with my original studies.\n\nThe altar is on an island to the west, south of Zul'Kunda.  Gather some of the bracers from the island's water elementals.\n\nOh, and you can use this device when you're finished.  No need to make you walk all the way back here.", objectives = "Acquire 6 Water Elemental Bracers.", progress = "Yes, <name>?", completion = "These will do for my purposes.  Though we can't activate the altar with bracers alone..." }
WordHunterWoW_QuestEN[26730] = { title = "You Can Take the Murloc Out of the Ocean...", description = "I need something to cut into the raw, elemental power of these bracers... something strong and abrasive, but still of the sea.\n\nThe Murkgill murlocs have moved inland from the sea, but they still carry vials of sea salt on them.  What they use it for, I can't be sure, but it will serve for our studies.  You can find the Murkgill in the glade south of the Rebel Camp and east of Bal'lal ruins.", objectives = "Obtain 6 vials of Sea Salt from Murkgill murlocs in Northern Stranglethorn.", progress = "The salt?", completion = "We have what we need.  Are you ready to activate the Altar of Naias, <name>?" }
WordHunterWoW_QuestEN[26731] = { title = "The Altar of Naias", description = "The salt you brought was sufficient to activate the bracers' innate enchantments.  I have taken these enchantments and combined them into a summoning token... a gift, if you will.\n\nReturn to the Isle of Naias, and place the gift on Naias' altar.  Call me again once you have Naias' heart.", objectives = "Use the Gift of Naias to summon Naias, then obtain the Heart of Naias.", progress = "I eagerly await the results.", completion = "My colleagues within the Kirin Tor will be happy to learn that the heart is ours.\n\nThank you for your assistance, <name>.  I couldn't have done it without you." }
WordHunterWoW_QuestEN[26732] = { title = "Bad Medicine", description = "I have a feeling that Kurzen's Medicine Men are distributing more than just medicine.  Kurzen needs some way to quelch insubordination, and an elixir under the guise of \"medicine\" would be the perfect way to do that.\n\nWe need those remedies for research.  Search the Kurzen Compound to the southeast - his medicine men and jungle fighters should carry the remedies on their bodies.", objectives = "Obtain 7 Jungle Remedies from the Kurzen Compound.", progress = "I'm a little bit of an alchemist in my spare time, you know.", completion = "Well done, <name>.  Now, let's see what they've got in this elixir of theirs..." }
WordHunterWoW_QuestEN[26733] = { title = "Control Sample", description = "<Brother Nimetz analyzes the samples you've given him.>\n\nThis... this is just basilisk blood!\n\nNo, it's mostly basilisk blood.  They've added something to it though.  I'll need a control sample to perform a proper comparison.\n\nThey most likely obtained the blood from the crystal spine basilisks, found to the east of their compound.  Bring me back some pure samples, and I'll have this elixir figured out.", objectives = "Obtain 7 samples of Crystal Spine Basilisk Blood.", progress = "There's something not quite healthy about this elixir, <name>.  Even though I haven't completed my analysis, I can sense it.", completion = "This will do.  Please hold on for a moment while I test this out." }
WordHunterWoW_QuestEN[26734] = { title = "The Source of the Madness", description = "After reducing the basilisk blood out of the elixir, I've uncovered an unusual precipitate.  It appears to be a blue crystal of some sort...\n\n<Brother Nimetz consults his notes.>\n\nIt's not a singing blue crystal... not a pulsing blue shard...\n\n<He flips forward a few pages.>\n\n... not a piece of the Mind's Eye.  Nope, this isn't something we've seen before in Stranglethorn.  If anyone has any more of this substance, I want it.  Check the high-ranking Kurzen troops, in the back of their cave.", objectives = "Obtain a Whispering Blue Stone from Kurzen troops within the Stockpile.", progress = "Make sure you handle that stuff carefully, <name>.  We don't know what it is.", completion = "<Brother Nimetz opens up a pouch and lets you place the crystal inside.>\n\nI knew they'd have some more of this substance.  I'm going to send this to my contacts at Fort Livingston, to the south.  Hopefully they'll have some more luck with it.\n\nThank you for everything, <name>." }
WordHunterWoW_QuestEN[26735] = { title = "The Fate of Kurzen", description = "Hello, {class}.\n\nWe are soldiers of Stormwind, and rebels from Kurzen's Compound, a large outpost that you'll find just to the southeast of here.  We were under the command of Colonel Kurzen, until he and those close to him started to descend into madness...\n\nWe rebelled, set up camp here, and stood against Kurzen.  Now, my sources are telling me Kurzen has disappeared.  I trust my source, but it would help to hear from a third party.  Please, head into the compound and find some documentation of his fate.", objectives = "Obtain the Kurzen Compound Prison Records and the Kurzen Compound Officers' Dossier.", progress = "What were you able to find, <name>?", completion = "They KILLED him?  And all this time, I thought he had them underneath an iron bootheel..." }
WordHunterWoW_QuestEN[26736] = { title = "Spared from Madness", description = "Kurzen's death is a relief, but what's more interesting, and perhaps more immediate, is the sign of some potential allies within the compound.\n\nI don't care what it says on that prison record, I know EXACTLY why those 3 were locked up: refusal to follow orders.  They must have been spared from the madness, much like my fellow rebels here, and incarcerated for speaking up.\n\nFind them, {name}.  Find them, and send them back here.", objectives = "Rescue Berrin Burnquill, Emerine Junis, and Osborn Obnoticus inside Kurzen's Compound.", completion = "Thank you, <name>.  It looks like my suspicions were correct... the three prisoners seem to have escaped the affliction that gripped Kurzen and the rest of his men.\n\nBefore you arrived, Emerine teleported them over to Stormwind to get cleaned up after their ordeal.  They promised to return soon." }
WordHunterWoW_QuestEN[26737] = { title = "Stopping Kurzen's Legacy", description = "Now that our allies have been evacuated, it's time to run a final raid on Kurzen's Compound.  They will never be weaker than they are right now, and with your help, we may be able to weaken them beyond repair.\n\nThose four names that were listed in the Officers' Dossier - Anders, Gaulus, Miranda, and Esquivel - will be the highest-ranking personnel remaining.  Look for them in that cave in the back of their compound.  Removing all four will be devastating to Kurzen's forces.\n\nGo with honor, {name}.", objectives = "Kill Chief Anders, Chief Gaulus, Chief Miranda, and Chief Esquivel within The Stockpile.", progress = "Remove the heads, <name>.  I know you can do it.  My men will clean up the remainder of their forces after you are done.", completion = "Marvelously executed, <name>.  My men and I can handle the rest.\n\nWith Kurzen out of the picture, we may be able to continue our original expedition here in Stranglethorn, which was... ahh...\n\nNo matter.  Please, feel free to peruse our armor stores.  You may find something that fits you well." }
WordHunterWoW_QuestEN[26738] = { title = "Just Hatched", description = "While looking through this soldier's possessions, you look down to see a newborn raptor hatchling looking back up at you.  Was it following this Kurzen militiaman the whole time?\n\nYou can see it studying you, learning your features and following your movements.\n\nThe lashtail hatchling has formed a bond with you.\n\nPerhaps someone back at the Rebel Camp will know what to do with a raptor hatchling.", objectives = "Bring the Lashtail Hatchling to Corporal Sethman at the Rebel Camp in Northern Stranglethorn.\n\nProvided item:", completion = "Yes, the little one seems to have taken a liking to you.  You're lucky... at this age, the raptors are calm, peaceful, and easily trained.  Keep her, <name>... she may come in handy.\n\nIn fact..." }
WordHunterWoW_QuestEN[26739] = { title = "I Think She's Hungry", description = "It looks like your young raptor is hungry.  If you're looking to keep her, why don't you find something for her to eat?  The lashtail often attack the basilisks of Stranglethorn, which can be found to the east, beyond Kurzen's Compound.\n\nShe probably isn't strong enough to hunt on her own yet, but I'm sure she will eat freshly killed basilisk meat.", objectives = "Kill Crystal Spine Basilisks in Northern Stranglethorn, and let your Lashtail Raptor eat 40 bites of their meat.", completion = "She looks bigger already!  You can see, these raptors grow quickly.  You are lucky to have found such a strong companion.\n\nKeep her by your side as long as you can, <name>.  I'm sure she will prove to be an asset in the future." }
WordHunterWoW_QuestEN[26740] = { title = "Krazek's Cookery", description = "I do most of the cooking at the camp.  It used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.  Last I heard, he was staying with Nesingwary in the hunters' camp just to the south.", objectives = "Bring Krazek's Crock Pot to Krazek.", progress = "Hello!  You brought me something?", completion = "Oh I see, it's a Krazek's Crock Pot!  An ingenious piece of work, but it can break a spring or throw a gear now and then.  Let me see what's wrong with this one...\n\nAha!  Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth.  I'm surprised the pot could even boil a turnip in this state!\n\nCan I fix it?  Of course I can fix it!\n\nBut there's a price.  Oh yes, there is always a price..." }
WordHunterWoW_QuestEN[26741] = { title = "REUSE", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26742] = { title = "Bloodscalp Insight", description = "I never got to properly thank you for saving me.\n\nThank you, {name}.\n\nI'm still a little fatigued from my captivity, so I thought you might help me with my studies.  As a shaman of the Wildhammer clan, I'm very interested in the shamanic practices of the Bloodscalp tribe.\n\nTheir magic seems to have diverged in an interesting direction.  If I had one of the totems that their shaman use, I could begin my studies.  You'll find them at the Bal'lal ruins, on the coast to the southwest.", objectives = "Obtain a Bloodscalp Totem from a Bloodscalp Shaman.", progress = "Beware: they may put up a fight.", completion = "<Berrin studies the inscriptions on the totem.>\n\nI think I can read this text... Fascinating!\n\nTsul'kalu, Mahamba, Pogeyan... what are these names?" }
WordHunterWoW_QuestEN[26743] = { title = "Sacred to the Bloodscalp", description = "Ahh... these must be names of their totemic creatures - the animals that they attribute to the spirits.  Let's see... Mahamba as water, Tsul'Kalu as earth, Pogeyan as... air?  Fire?  I can't make this part out.\n\nI'd like some more information on these spirits of theirs.  The Bloodscalp have a camp close to here, in the Tkashi ruins.  Maybe you can find some details there.", objectives = "Obtain an Icon of Tsul'kalu, an Icon of Mahamba, and an Icon of Pogeyan from Bloodscalp trolls in the Tkashi Ruins.", progress = "It's likely that these totemic creatures are based on some of the fantastic creatures that roam this jungle.", completion = "First you save me from the madman's jail cell, and now you bring me some keys to understanding trollish shamanism.\n\nThis is turning out to be a pretty good week!\n\nThank you again, <name>.  I will see to it that you have the support of the Wildhammer clan as you continue on your journeys." }
WordHunterWoW_QuestEN[26744] = { title = "Deep Roots", description = "On a somewhat unrelated note, I've been putting together a collection of troll stories and legends for a... personal project.  I was just thinking you might be able to help me find some of them.\n\nThe Bloodscalps at the Bal'lal ruins, on the coast to the southwest, maintain a large tablet documenting some of their stories.  Of course, I'll reimburse you if you're able to bring any of these stories back to me.", objectives = "Obtain the Bloodscalp Lore Tablet from the Bal'lal Ruins in Northern Stranglethorn.", progress = "Did you make it down to Bal'lal Ruins yet?  Did you find the tablet?", completion = "To be honest, I'm sending this information home to Stormwind, for my wife and son.  They love to hear about what I've been doing out here in the jungle, and I only get to visit so often.  Every little bit helps.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[26745] = { title = "Favored Skull", description = "Your pet raptor seems to have found a new toy: a skull, from a nearby troll skull pile.\n\nWhat sets this skull apart from the rest is beyond you, but for some reason, she won't put it down.\n\nOsborn Obnoticus, the gnome you saved from Kurzen's Compound, is an expert in troll history and physiology.  Maybe he'll have some idea what makes this one so special.", objectives = "Report to Osborn Obnoticus at the Rebel Camp and show him your Lashtail Hatchling's new skull.\n\nProvided item:", completion = "What do we have here?  A young raptor, and her pet <race>.  Hah!\n\nMore importantly, what is that skull you have there?  This was no ordinary troll.  He was big...\n\n\n\n... and strong, too.  You know, I've been meaning to try my hand at some troll magic.  How hard could it be?  Let's use this strong fellow as a test subject, shall we?" }
WordHunterWoW_QuestEN[26746] = { title = "A Nose for This Sort of Thing", description = "<Osborn looks at the skull again.>\n\nIn life, he was strong, powerful, a lord among trolls.  With our help, he can be a lord once more.\n\nThe Bloodscalp scavengers that wander the ruins to the southwest hoard magical fetishes that can help us.  They hide these artifacts under the ground.  Use your hatchling to find these artifacts, {name}... then bring them here.", objectives = "Use your Lashtail Hatchling to sniff out 8 Tkashi Fetishes.", progress = "How many did you find?", completion = "These will provide a bit of... what's the troll word?  Voodoo?  Juju?  Tiklabang?\n\nIt doesn't matter.  If we're going to re-build a troll, we need troll magic, and these fetishes are full of it." }
WordHunterWoW_QuestEN[26747] = { title = "A Physical Specimen", description = "The soul is ready, but the body is not.  For a skull as well-formed, as marvelous, as beautiful as this... we will need a suitable body.\n\nThe chief of the Bloodscalps, Gan'zulah, won his throne with brute force.  If he still lives, you'll find him in Zul'Kunda, to the west.\n\nTaking his body won't be easy, but nothing a sturdy {class} like yourself couldn't handle.  Bring it back here when you're done.", objectives = "Obtain Gan'zulah's Body from Zul'Kunda.", progress = "Gan'zulah was a brute and a tyrant.  I've got a feeling that this troll will be different.  This troll magic is easier than I thought it would be!", completion = "You have done well, <race>.  We have a head, a body, and some juju-voodoo-mojo nonsense.  Now, just a little shock of electricity to get things started, and..." }
WordHunterWoW_QuestEN[26748] = { title = "Bloodlord Mandokir", description = "{race}.  You just resurrected your worst nightmare.  You didn't think I was a friend, did you, {race}?  Ah, ha ha haaaa!\n\nYou've served your purpose.  I've returned to the realm of the living, and it's all thanks to you.  So, instead of killing you, I'm going to make you a deal instead.\n\nGive me that raptor.\n\nYou must already know that she's no normal raptor, and I need a replacement for Ohgan.  Do it, or both you and the gnome will taste my rage.", objectives = "Deliver the Lashtail Raptor Egg Fragment to Bloodlord Mandokir in the Rebel Camp.", progress = "All I ask is the raptor, <race>.  Give it to me, and the gnome lives.", completion = "I'm glad to see you've come to your senses.\n\nCome and visit us in Zul'Gurub sometime, <race>.  I'll be watching..." }
WordHunterWoW_QuestEN[26749] = { title = "Priestess Thaalia", description = "Thank you, {name}.  I know you didn't have to save my life.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe explorers at Fort Livingston, far to the south, may know more.  Speak with their priestess.", objectives = "Speak with Priestess Thaalia at Fort Livingston in Northern Stranglethorn.", completion = "Mandokir is alive, yes.\n\nYou are responsible, yes.\n\nYou may be able to stop him still, yes." }
WordHunterWoW_QuestEN[26750] = { title = "At the Stonemother's Call", description = "It is time. The Stonemother will speak with you. You can find her throne in northern Deepholm, above the Scoured Reach.", objectives = "Speak to Therazane, the Stonemother.", completion = "So you've come.\n\nFleshlings just like you killed my daughter... my only daughter. With no provocation.\n\nNot sated at stripping me of my family, more of you flocked to Deathwing to serve him in ravaging my home.\n\nYou're quite arrogant to come before me asking for MY help. I'm tempted to crush you where you stand." }
WordHunterWoW_QuestEN[26751] = { title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", objectives = "Slay 7 Bloodscalp Mystics, 7 Bloodscalp Hunters, 7 Bloodscalp Scouts, and 1 Bloodscalp Beastmaster.", completion = "Balance is restored - for now.  We may call on you again in the future, <name>." }
WordHunterWoW_QuestEN[26752] = { title = "Audience with the Stonemother", description = "Stay where you are, champion. I have not yet decided what to do with you or your Earthen Ring.", objectives = "Attend the Audience with the Stonemother.", completion = "Ya've done well, brotha. Da Stonemother be listenin' and da World Pillar is not far from our reach." }
WordHunterWoW_QuestEN[26753] = { title = "The Halls of the Dead", description = "<In front of you, the bare earth slopes down towards the dark entrance to the crypts.>\n\n<You can feel the tug of the lightforged artifact urging you towards it. Perhaps the other piece is down there?>", objectives = "Find the Lightforged Arch within the Dawning Woods Catacombs.", completion = "<In the dirt of this alcove, your eye catches the shine of brilliant metal. You've found another piece of the artifact!>" }
WordHunterWoW_QuestEN[26754] = { title = "Morbent's Bane", description = "<The pieces fit, and the holy artifact is restored, gleaming with sacred light. This should let you defeat Morbent Fel's dark magic.>\n\n<Further down the tunnel, away from the direction you came from, a heinous cackle rings out. It's the clattering laugh of a lich. Morbent Fel is just ahead!>", objectives = "Use Morbent's Bane to weaken Morbent Fel and defeat him.", completion = "May the disgusting monster stay dead this time!\n\nI'll head down there and scatter his remains to ash myself, <name>. You've done a great thing; perhaps in time Duskwood can return to its former peaceful state." }
WordHunterWoW_QuestEN[26755] = { title = "Keep Them off the Front", description = "Oh good, you brought another catapult with you! Clay might be older than dirt, but he makes a mean war machine.\n\nWell, you didn't bring it all the way out here for your health, flesh bag. Get in one of those things and bombard the fungal terrors and reinforcements streaming out of Needlerock Slag.\n\nWe have to keep them off the front!", objectives = "Bombard 30 Fungal Terrors and/or Stone Trogg Reinforcements.", progress = "Get back in a catapult and put those things back in the ground. The line's barely holding!", completion = "That's a great start, <name>, but we're going to need you to fly over into the town and stir up some trouble." }
WordHunterWoW_QuestEN[26756] = { title = "Nessa Shadowsong", description = "A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut'theran Village.  She needs a parcel taken to Darkshore, and is looking for someone to help her.\n\nIf you're interested, then to reach Nessa you must take the portal in Darnassus to Rut'theran Village.  You will find the portal west of the Temple Gardens.Upon completion of this quest you will gain:", objectives = "Speak with Nessa Shadowsong.A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut'theran Village. She needs a parcel taken to Darkshore, and is looking for someone to help her.\n\nIf you're interested, then to reach Nessa you must take the portal in Darnassus to Rut'theran Village. You will find the portal west of the Temple Gardens.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26757] = { title = "The Bounty of Teldrassil", description = "The fishermen of Rut'theran village do very well, for the fish here are extremely large and abundant.  I would like to compare the bounty here with that of the mainland.\n\nI have a collection of fish bones and scales that I would like taken to a colleague of mine in Darkshore.  His name is Laird, he is a fish vendor in the village of Auberdine.\n\nBring my collection to our hippogryph master, Vesprystus, and speak to him about traveling to Auberdine.Upon completion of this quest you will gain:", objectives = "Bring Nessa's Collection to Vesprystus." }
WordHunterWoW_QuestEN[26758] = { title = "Flight to Auberdine", description = "From Rut'theran, there are two methods of travel to Auberdine: by ferry and by hippogryph.  Both are quick and reliable, but if you have not yet flown to Auberdine by hippogryph, then I suggest you do.\n\nIt is sound advice to speak with the hippogryph master in every town that has one.  Once you speak to the master, you can then fly there from other towns.\n\nHere is Nessa's collection.  Speak with me again when you are ready to fly to Auberdine and deliver Nessa's collection to Laird.Upon completion of this quest you will gain:", objectives = "Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird." }
WordHunterWoW_QuestEN[26759] = { title = "Return to Nessa", description = "I must send a response to Nessa.  She'll be very interested to know how different the fish here are from those along Teldrassil's coastline.  We can only guess the cause, but it is my suspicion that the world tree itself is affecting the wildlife around it!\n\nPlease, take this response to Nessa.  If you wish to take a hippogryph back to Rut'theran then speak with the hippogryph master Caylais Moonfeather.  If you wish to take the ferry, then one regularly departs from the dock to the northwest.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring Laird's Response to Nessa Shadowsong." }
WordHunterWoW_QuestEN[26760] = { title = "Cry For The Moon", description = "I'm hopeful, but let's remain professional. It's business as usual for this one.\n\nInto the guillotine he goes... and if the alchemy doesn't take, he won't be getting back out of it.\n\nJitters and I will attend to this. Please, just stand back and watch from a safe distance.", objectives = "Watch Oliver Harris and Jitters attempt to cure the Lurking Worgen.", completion = "Success... Finally! I can't thank you enough for giving me the chance to work the cure myself.\n\nOur new friend may be in need of some help as well. You might want to speak with him." }
WordHunterWoW_QuestEN[26761] = { title = "Threat to the Kingdom", description = "There is no doubt that the Defias pose a great threat to the kingdom, but we certainly cannot enter their hideout and hope that everything will work itself out. No, an assault against the Defias is going to take time and planning. I want you to leave the logistics to me. Our kingdom has other threats that must be dealt with immediately!\n\nTravel east through Elwynn to Redridge and report to Magistrate Solomon in Lakeshire. I will call for you when we are ready to attack the Defias.", objectives = "Report to Magistrate Solomon at Lakeshire in Redridge.", completion = "I heard about the Defias making a return. Terrible news. I wish I had better news, but it would appear that Lakeshire is under attack! We are losing citizens left and right. Our own guards are spread far too thin to handle the situation. We need a hero to step up!" }
WordHunterWoW_QuestEN[26762] = { title = "Reactivate the Constructs", description = "We sent a number of our war constructs north into Needlerock Slag, but none of them ever returned. We know that the stone trogg mystics have done something to them.\n\nWhat we're concerned about is that the mystics will control and turn them against us, like they have with the fungal giants.\n\n{name}, go into the stone trogg town and reactivate the constructs.", objectives = "Reactivate 5 Deactivated War Constructs.", completion = "That was a nice bit of work, <name>.\n\nWith our constructs back up and running behind their main lines, it's only a matter of time now before we make the big push through and rescue the Stonefather." }
WordHunterWoW_QuestEN[26763] = { title = "Venture Company Mining", description = "If I'm going to repair this pot, I'm going to need reagents.  And to get them, you're going to have to do an eensy little bit of killing.  I hope you don't mind.\n\nThose dastardly Venture Company geologists have been collecting some tumbled crystals that will suffice for what I need.  You'll find them around their Base Camp, on the other side of Lake Nazferiti, to the east.\n\nI don't care what you have to do to get them. ", objectives = "Obtain 5 Tumbled Crystals from Venture Co. forces near Lake Nazferiti.", progress = "Do you have those crystals?", completion = "These will work fine.  Just a moment please.\n\n<Krazek thrusts the stones into the cooking pot and wiggles them around a bit.>\n\nAll fixed!" }
WordHunterWoW_QuestEN[26764] = { title = "A New Low", description = "You may notice that the Venture Company has completely clear-cut all the trees around their Base Camp to the east.  Not one to miss out an opportunity for profit, their foreman has enslaved druids, and is forcing them to re-grow the forest so they can chop it down again!\n\nPersonally, I find this abhorrent, and not just because I didn't think of it first.\n\nRelease a few of these druids from their captors.  I'm sure they'll appreciate it.", objectives = "Free 3 Enslaved Druids from the Venture Co. Base Camp.You may notice that the Venture Company has completely clear-cut all the trees around their Base Camp to the east. Not one to miss out an opportunity for profit, their foreman has enslaved druids, and is forcing them to re-grow the forest so they can chop it down again!\n\nPersonally, I find this abhorrent, and not just because I didn't think of it first.\n\nRelease a few of these druids from their captors. I'm sure they'll appreciate it.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26765] = { title = "Return to Corporal Kaleb", description = "So, this pot is fixed.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", objectives = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp in Northern Stranglethorn.", progress = "Hello, <name>.  Did the goblin Krazek fix my pot??", completion = "It's fixed!  This is great, now I can get dinner started!  Thanks so much, <name>.\n\nI hope Krazek didn't give you too much trouble." }
WordHunterWoW_QuestEN[26766] = { title = "Big Game, Big Bait", description = "We're only going to get one shot at capturing Abyssion, {name}.  Let's make it count.\n\nWe'll test out the trap on the biggest of the stone dragons in the Alabaster Shelf.\n\nTo lure the stone matriarch, we're going to need to gather sufficient bait.\n\nTake this knife and carve 5 sides of basilisk meat.  That ought to be enough even for her appetite.", objectives = "Use Mylra's Knife to obtain 5 Sides of Basilisk Meat from dead Jadecrest Basilisks.", progress = "Did you obtain the meat?", completion = "That should be enough to lure the beast, <name>." }
WordHunterWoW_QuestEN[26767] = { title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.", objectives = "Make a breadcrumb quest.Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26768] = { title = "To Catch a Dragon", description = "Having a dragon guard the fragment was a smart move on the enemy's part.  They can keep moving its location any time we get close to it.\n\nCatching Abyssion will be extremely difficult, but I have a plan that might help.\n\nThe Twilight's Hammer uses magical traps to bind stone drakes to the ground while they drain their energy.\n\nIf we can get our hands on one of these, we might be able to ground the Twilight Dragon for just long enough.\n\nGo east of here, to the Alabaster Shelf, and obtain a trap.", objectives = "Obtain a Dragon Snare from the Twilight Dragonstalkers.", progress = "If the snares are good enough for stone drakes, they might work on Abyssion.", completion = "Let's see if the snare can ground something larger than a drake." }
WordHunterWoW_QuestEN[26769] = { title = "Raging River Ride", description = "Enjoy your cut of the loot, {name}!\n\nI hate to share, but business is business. And that double-dealer Nozzlepot is guaranteed a 10% cut of this treasure. Can you deliver this to him at his outpost in the north?\n\nHe's got a little research station upstream, along the river. If you travel just northeast of town here, Horton Hornblower can give you a free ride on one of his riverboats. Tell him I sent ya!", objectives = "Board Horton Hornblower's Riverboat northeast of Ratchet and get a riverboat ride to Nozzlepot's Outpost.", progress = "Welcome, <class>. Fresh off the boat from Ratchet? Any news?", completion = "<Nozzlepot snatches the bag of gems from you.>\n\nGazlowe calls this 10%? You tell him I'm going to weigh these!\n\nI suppose he expects me to pay you a delivery fee, as well? Fine, fine. Have some spoils!" }
WordHunterWoW_QuestEN[26770] = { title = "Mystic Masters", description = "The Needlerock mystics have taken control of the fungal giants that have sprouted in their chasm, down below. Now they seek to control our war constructs.\n\nGo north into Needlerock Slag and do something about it! Isn't that what you're here for?", objectives = "Slay 5 Needlerock Mystics.", completion = "A few less stone troggs is always a good thing. Glad to see that you're a decent <class> after all.\n\nWe'll soon know the exact location where they're keeping my father captive. Hope you survive until then." }
WordHunterWoW_QuestEN[26771] = { title = "Testing the Trap", description = "You must set the trap for the matriarch now.\n\nGo to the western end of the Alabaster Shelf and place the trapped basilisk meat in the center of the feeding grounds.", objectives = "Place the trapped meat in the western end of the Alabaster Shelf.", completion = "Well done, <name>.  Here's to hoping the trap performs as well when we try it on Abyssion." }
WordHunterWoW_QuestEN[26772] = { title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go northeast, and you will find the feathers, yes.", objectives = "Obtain 5 Jungle Stalker Feathers from Jungle Stalkers in Northern Stranglethorn.", progress = "Raptor named Ohgan'aka, still your friend.", completion = "You bring feathers, yes.\n\nYou can follow directions, yes." }
WordHunterWoW_QuestEN[26773] = { title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", objectives = "Speak with Priestess Thaalia at Fort Livingston to participate in the Mind Vision ritual.", progress = "Your vision not Ohgan'aka's, no.\n\nYou are not ready.", completion = "What did Priestess tell you?\n\nThe raptor is daughter of Ohgan, heir to Mandokir's seat.\n\nHah!" }
WordHunterWoW_QuestEN[26774] = { title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", objectives = "Obtain Braddok's Big Brain from Braddok in Zul'Mamwe.", progress = "Extra-big spells need extra-big brains, yes.", completion = "Hold on, next part is tough, yes.\n\nLots of chances to fail, yes.\n\nBut <name> and <name>'aka going to be reunited... yes they will." }
WordHunterWoW_QuestEN[26775] = { title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", objectives = "Speak with Priestess Thaalia, then help the Captured Lashtail Hatchling escape from Zul'Gurub.", completion = "What a shame, yes.\n\nThis is what the spirits wanted, yes.\n\nMaybe when you are stronger, you will go into Zul'Gurub and take back your <name>'aka from Mandokir, yes.\n\nFor now, Priestess give you this." }
WordHunterWoW_QuestEN[26776] = { title = "Ghaliri", description = "Priestess is not very good at speaking Common, no.\n\nMaybe you go speak with Ghaliri, in front of that tent.\n\nTell him about what you've seen inside Zul'Gurub, yes.", objectives = "Report to Ghaliri at Fort Livingston in Northern Stranglethorn.", completion = "<You explain to Ghaliri what has happened up to this point.>\n\nIt would seem that Jin'do has survived, and he is rallying his brothers to once again summon Hakkar into this world.  It was good of you to come to speak with me.\n\nThere is not much we can do now but to wait, and watch.  Jin'do is weak, and prime for striking, but I must wait for word from Rastakhan before issuing orders.  Until then, you and your raptor will have to wait." }
WordHunterWoW_QuestEN[26777] = { title = "Soothing Spirits", description = "This is a tragic land, with a history of violence and despair. While many of the dead roam in the flesh, some are simply lost souls, wandering in confusion.\n\nThey deserve to be put at ease.\n\nMany of these souls gather at the Addle Stead to the south, appearing before travelers. Take this censer of holy incense. Sway it before the forlorn spirits, and let the offering of its gentle scent give them peace.", objectives = "Use the Holy Censer to soothe 5 Forlorn Spirits at the Addle Stead.", completion = "You have brought peace to those who knew only misery, <name>. Be proud." }
WordHunterWoW_QuestEN[26778] = { title = "The Cries of the Dead", description = "Can you hear them, {name}? There's so many of them. They wander their graves, shuffling across the cold ground on rotting limbs.\n\nThe dead cry out in the still air. They suffer in their own flesh, forced from sleep! Every night I venture to the graveyard to put more of them to rest, but it's never enough.\n\nHelp me, {name}. Put the ghouls that swarm Raven Hill Cemetery out of their misery. Strike down as many as you can.", objectives = "Kill 20 ghouls of any kind in Raven Hill Cemetery.", completion = "The cries grow softer for now. Light bless you, <name>." }
WordHunterWoW_QuestEN[26779] = { title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel east into Zul'Mamwe and cull their wayward tribe.", objectives = "Kill 16 Skullsplitter Trolls within Zul'Mamwe.", progress = "Zul'Mamwe, though ruined, is still a defensible stronghold.  Take heed, <race>.", completion = "As promised, your reward.  You do the troll nation proud." }
WordHunterWoW_QuestEN[26780] = { title = "Nighttime in the Jungle", description = "Nighttime in Stranglethorn is a beautiful thing.  The skies fill with stars, and the moon casts its rays right between those leaves, right there.  I could stare at these skies all night.\n\nUnfortunately, the trolls that walk the ruins of Zul'Mamwe are interfering with my astronomy.  They burn braziers, day and night, which rob me of the darkness I need.\n\nPlease, {name}... travel east into Zul'Mamwe and put them out.", objectives = "Put out 8 Zul'Mamwe Braziers at Zul'Mamwe in Northern Stranglethorn.", completion = "I can see the difference already.  I can't wait until later tonight, when I get to perform my observations again!" }
WordHunterWoW_QuestEN[26781] = { title = "The Mind's Eye", description = "One of the Vale's many treasures lies nearby, on OUR side of the giant whirlpool.  The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the northeast.  His name is Mai'Zoth.  From what I understand, he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nThus far I've been unable to get near enough to take it from him.  Will you give it a try?", objectives = "Obtain the Mind's Eye from Mai'Zoth.", progress = "Do you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, <name>!\n\nAnd to think my brother and sister said we wouldn't find anything of worth here in the Vale.  Hah!  And I'm just getting started!" }
WordHunterWoW_QuestEN[26782] = { title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that some {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it..." }
WordHunterWoW_QuestEN[26783] = { title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that a {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", objectives = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Wulfred peers into the box.>\n\nThis... this is not like what I expected.  I had thought it would be a... a...\n\n<His eyes glaze over.>\n\nAhem!  I'm sorry.  I'm not sure what came over me.  I'll be sending this south, to the Explorers' League Digsite in the Cape.  Maybe they'll know what to do with it..." }
WordHunterWoW_QuestEN[26784] = { title = "Muddied Waters", description = "The elemental powers are strong here in the Highlands, {name}. It is why the Twilight's Hammer chose to build their stronghold here.\n\nIn the right hands, we can channel this energy into something productive... like a portal directly to Orgrimmar.\n\nNorthwest of here, at the Verrall River Delta, water elementals have been stirred up by the actions of our foes upstream. Destroy them and gather 5 whirlpool cores. You'll not only calm the river, you'll power up our portal. ", objectives = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", progress = "I hope the fighting within the river wasn't too dangerous.", completion = "These are perfect! The restless waters of that troubled river will now do much more than move silt or stone... They'll move you across continents.\n\nFinish up the rest of your business here in Dragonmaw and then we should be able to proceed." }
WordHunterWoW_QuestEN[26785] = { title = "Part of the Pack", description = "I've been trying to keep my true self hidden away from the people of Darkshire... they seem to react poorly to worgen. There are more of us here, though, beyond the city.\n\nThe companions I first traveled here with search the woods for wild worgen. They believe some of them, ones with telltale signs, can still be returned to sanity.\n\nI'm not quite ready to rejoin them. Please send word to Apprentice Fess at the crossroads west of town that I'll be staying in Darkshire a while longer.", objectives = "Speak to Apprentice Fess at the crossroads west of Darkshire in Duskwood.", completion = "Tobias is staying in town still?\n\nMaster Harris warned him not to pursue his brother's fate. We all lead new lives now, after all. But the past is hard to let go of..." }
WordHunterWoW_QuestEN[26786] = { title = "Securing the Beach Head", description = "Something troubles me, {name}. The Twilight dragons knew just where and when to strike our airfleet. It's as if they knew our plans.\n\nTwilight spies cower within our midst!\n\nI'm going to take one of our remaining ships back to Orgrimmar to roll some heads. I need you to stay behind and secure this front. The Dragonmaw shaman are powerful; I have asked them to open up a portal to Orgrimmar, and I need you to help.\n\nSo. Start helping!", objectives = "Speak with Artesh at Dragonmaw Port in Twilight Highlands.", completion = "Your Warchief is decisive, <name>. He makes things happen. I like him.\n\nLet's talk about this portal that he wants!" }
WordHunterWoW_QuestEN[26787] = { title = "Bear In Mind", description = "I'm afraid that... well, I'm just plain afraid, but I'm also sorry to have to ask for another favor.\n\nMaster Harris needs brains. Bear brains. They're part of the serum apparently, or at least a proper substitute.\n\nThere's plenty of black bears in the woods to the west, and along the riverbank, but... I can't do it! I'm too terrified to go out there and face those huge things, even with a rifle. Please, let me pay you to bring back some!", objectives = "Collect 8 Black Bear Brains.", progress = "Did you get them? Did you?", completion = "Thank you! Oh, thank you. I never thought I'd be happy to smell those brains, but I am now that I didn't have to get them!\n\nHere's your reward as promised..." }
WordHunterWoW_QuestEN[26788] = { title = "Cementing Our Victory", description = "Our alliance with the Dragonmaw is secured, but this port is far from combat ready. These flimsy wooden walls are an embarrassment to the Warchief.\n\nWhen water elementals carve their way through rock, as they have in the Verrall River, they create a peculiar kind of muck. It spreads easily and dries harder than the hardest stone. It's the perfect mortar for large-scale construction.\n\nGo to the river delta northwest of here and collect some Verrall River muck. Even a little will go a long way.", objectives = "Collect 10 piles of Verrall River Muck.", progress = "Do you have the mud? Construction of the new walls has already begun!", completion = "<Ornak allows the muck to drip from his fingertips.>\n\nNow that's the stuff! I'll start mixing and diluting this with gravel and water. Just a few handfuls of this can enhance enough cement for an entire stone tower.\n\nWe've got big plans for this port, <name>. You'll see!" }
WordHunterWoW_QuestEN[26789] = { title = "You no take axe!", description = "<Name>, we have a problem! I've tracked down the demon-hound Magmadar to this clearing, but when we resting a band of kobolds took our battle axes! I need you to retrieve them, lest Magmadar catch us off guard! Hurry, he could awaken at any moment!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 5 Test Kobolds." }
WordHunterWoW_QuestEN[26790] = { title = "Magmadar Must Die!", description = "There he is, <name>. The foolish beast fell asleep right out in the open! Good news for us, eh? Come, hero, we fight now! You can even have the honor of severing his head from his massive body. What's that? Too big for your bags? Why, carry it, of course! <Thrall grins.>You will receive:", objectives = "Bring Magmadar's head to Thrall in Stonetalon Mountains." }
WordHunterWoW_QuestEN[26791] = { title = "Sprout No More", description = "The stone trogg mystics are creating those fungal monstrosities from the giant mushrooms to the north.\n\nI want you to take a war guardian to help deal with the giants and stone troggs. Make your way to the giant mushrooms and target them. I and my geomancers will sink them into the ground before the mystics have a chance to finish their ritual.", objectives = "Interact with and gain a War Guardian, and destroy 5 Giant Mushrooms.", completion = "They won't have any more of those fungal giants to throw against us!" }
WordHunterWoW_QuestEN[26792] = { title = "Fungal Monstrosities", description = "Grab yourself a war guardian, and destroy those fungal monstrosities while you're out there.", objectives = "Slay 5 Fungal Monstrosities.", completion = "Thank you, <name>. We've never had such a problem in Deepholm before the destruction of the World Pillar.\n\nYour Earthen Ring must repair the damage before it's too late." }
WordHunterWoW_QuestEN[26793] = { title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", objectives = "Speak with Sirra Von'Indi in Darkshire.", completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections..." }
WordHunterWoW_QuestEN[26794] = { title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", objectives = "Speak with Commander Althea Ebonlocke in Darkshire.", completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A powerful undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n<She sizes you up.>\n\nYou seem to be capable enough, maybe you could lay him to rest." }
WordHunterWoW_QuestEN[26795] = { title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", objectives = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", progress = "I don't blame you if you're having trouble with him, <name>. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, <name>! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however..." }
WordHunterWoW_QuestEN[26796] = { title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", objectives = "Speak with Watcher Sarah Ladimore in Darkshire.", completion = "Yes? My father...\n\n<Her eyes become downcast.>\n\nI wish... there was something I could have done for him... If only I had talked to him before he..." }
WordHunterWoW_QuestEN[26797] = { title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, {name}.", objectives = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", progress = "Leave me be...", completion = "<A ghostly voice sounds on the wind...>\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n<name>. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love..." }
WordHunterWoW_QuestEN[26798] = { title = "Saurfang Will be Pleased", description = "The portal is ready!\n\nIt's not powerful enough to transport an army, but we can maintain the connection long enough to allow important individuals to pass back and forth.\n\nSaurfang will want to know about our progress here. Walk through the portal to Orgrimmar, then deliver the news him.", objectives = "Use the portal in Dragonmaw Port to go to Orgrimmar and report to High Overlord Saurfang.", completion = "<class>, you've returned from Dragonmaw. The portal is functioning then? Good.\n\nBefore you return to your work there, we've got some dirty business to clean up right here in Orgrimmar..." }
WordHunterWoW_QuestEN[26799] = { title = "Those That Couldn't Be Saved", description = "The val'kyr raise hundreds of corpses every day.  Agatha raised you just a few moments ago.  Not all are as lucky as you, however.\n\nSome maintain their free will, but live in constant fear and confusion.  They usually run off into the woods, cowering at their own reflections.\n\nOthers lose their minds completely, shambling about aimlessly.  They often turn to violence, and must be destroyed.\n\nThis is your task, {name}.  Destroy them, our former brothers and sisters though they might be.", objectives = "Kill 6 Mindless Zombies.", progress = "You will not go far in this new life if you are unable to kill even the weakest, most brainless creatures, <name>.  Do not return until you have success to report.", completion = "Not even the power of the val'kyr was enough to save these creatures.  They were doomed from the beginning.\n\nI have obtained some equipment for you, <name>.  It's not much, but it will help.  Please, take your pick." }
WordHunterWoW_QuestEN[26800] = { title = "Recruitment", description = "We've been shipping in dead bodies from Silverpine, Hillsbrad... hell, anywhere we can get them from.  We can't, however, afford to ignore the bodies which are sitting right on our front doorstep.\n\nThe last vestiges of the Scarlet Crusade roam here in Tirisfal Glades.  While we've managed to push them from Deathknell, several of their bodies litter the buildings to the north and the east.\n\nGo find them... and bring that Darnell fellow with you.  He looks strong enough to carry a few corpses.", objectives = "Search Deathknell and the vicinity for 6 Scarlet Corpses, then point at them so Darnell can pick them up.", progress = "Have you managed to scavenge up some corpses?", completion = "Great work <name>.  I knew you weren't useless.\n\nHere, take one of these.  We deathguards have piles of these things just sitting around." }
WordHunterWoW_QuestEN[26801] = { title = "Scourge on our Perimeter", description = "If you're going to be an asset to the Forsaken, you need to learn how to fight.  And there's no better target than the Scourge minions that continue to pester us.\n\nThe wretched ghouls and Rattlecage skeletons that roam the north and to the east are former troopers of the fallen Scourge.  They should prove to be an even match for a fledgling {class} like you.\n\nDo not tarry - when you are done, speak to me again.", objectives = "Kill 8 undead outside of Deathknell. You may kill either Wretched Ghouls or Rattlecage Skeletons.", progress = "Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let's hope you will fare better than them, yes?", completion = "You're growing in strength, <name>.  I've seen your type before.  You will be moving out of Deathknell and on to greater things before long.  Just make sure you don't lose sight of where you started.\n\nYou have much to accomplish, <class>." }
WordHunterWoW_QuestEN[26802] = { title = "The Damned", description = "First of all, look at your armor.  You're a mess, {class}.\n\nIf you'd like to stay in one piece--and I've no doubt you do--perhaps I can help.  If you can gather some paws and wings from the wolves and bats nearby, maybe I'll find some armor for you.  You'll find the creatures to the north and to the west of here.", objectives = "Obtain 4 Scavenger Paws and 4 Duskbat Wings.", progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, <name>. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it..." }
WordHunterWoW_QuestEN[26803] = { title = "Missing Reports", description = "Saurfang is wise, and his intentions are good. In time, he will grow to see your people as a valuable ally.\n\nI am awaiting reports about recent Alliance activity in Durotar, but they haven't arrived yet. Would you be willing to visit Razor Hill and ask him for the reports in person? The easiest way to get there is by wind rider. Doras, Orgrimmar's wind rider master will let you use one of his wind riders for a small fee. Look for him on the rise north of the Valley of Strength.", objectives = "Talk to Orgrimmar's wind rider master, Doras.", completion = "So you need to get to Razor Hill in a hurry? That's no problem at all. One of my wind riders will get you there very quickly and it only costs a few coins to hire one." }
WordHunterWoW_QuestEN[26804] = { title = "Flight to Razor Hill", description = "When you're ready to take the wind rider down to Razor Hill, simply speak with me again. When you get there, waste no time in finding Gar'Thok. He's the one responsible for preparing reports on recent Alliance activity in Durotar.", objectives = "Speak to Doras to purchase a wind rider ride to Razor Hill. Once you arrive, speak with Gar'Thok.", completion = "Eitrigg sent you? The warchief must be getting anxious to read my reports. I'd've sent them long ago, but each day we discover more about the Alliance's plans for invading Durotar." }
WordHunterWoW_QuestEN[26805] = { title = "To the Cape!", description = "The Explorers' League is growing, {name}.  Not only have they taken in worgen like me, but they have expanded their range in search of artifacts.  One of our best, Bronwyn Hewstrike, has set up a camp in the south, where he believes an item of titan origin may be hidden.\n\nBronwyn asked me to perform some duties here in the north, one of which was to identify potential recruits.  You seem to be made of the right stuff.  Talk to Robert Rhodes, the flight master, and he'll send you down there.  Bronwyn's treat.", objectives = "Speak with Robert Rhodes to obtain a flight to the Explorers' League Digsite in the Cape of Stranglethorn.", completion = "Wulfred has a good eye.  I think you'll do just fine here at my camp." }
WordHunterWoW_QuestEN[26806] = { title = "Reports to Orgrimmar", description = "Eitrigg will have to be happy with the part of the report that I've finished. Tell him to expect more in the future.\n\n<Gar'Thok hands you a stack of roughly folded papers.>\n\nThis should cover the most important details of the increase in Alliance forces working out of Northwatch. Please apologize to Eitrigg for me and let him know that we've had our hands full here, trying to keep Razor Hill secure and supplied. When you're ready to return to Orgrimmar, simply speak to Burok and hire a wind rider.", objectives = "Take Gar'Thok's Reports to Burok at Razor Hill.", progress = "Are you ready to return to Orgrimmar?", completion = "Ready to return to Orgrimmar with those reports? I can arrange a flight for you right away." }
WordHunterWoW_QuestEN[26807] = { title = "Return to Eitrigg", description = "Since you've already spoken to Doras, you'll be able to hire a wind rider to take you right back to Orgrimmar. Each time you arrive in a new town, be sure to speak with the town's flight master. After that, you'll be able to use the flight master's services to travel quickly.\n\nSpeak to me again when you're ready to purchase a return flight to Orgrimmar. Bring those reports to Eitrigg in the Valley of Strength once you've landed.", objectives = "Speak with Burok and purchase a flight back to Orgrimmar. Once in Orgrimmar, bring Gar'Thok's Reports to Eitrigg in the Valley of Strength.", progress = "Did you bring those reports?", completion = "<Eitrigg examines the reports.>\n\nThe Alliance has grown bolder than we'd thought! I'll talk to the warchief about sending reinforcements right away. Thank you for getting these reports to me so quickly. I hope this coin is enough to cover your travel expenses." }
WordHunterWoW_QuestEN[26808] = { title = "Maywiki", description = "<Linzi looks troubled.>\n\nYou know, there's a troll hiding behind that pile of boxes.  She must be awfully sad, if she doesn't want to come out and talk to anyone.\n\n<Linzi places some of the Akiris reeds in a kerchief and ties it together.>\n\nHere, give these to her.  They're very soft, and that maybe they will make her feel a little more comfortable back there.", objectives = "Bring Linzi's Gift to Maywiki of Zuldazar at the Explorers' League Digsite.", progress = "Care to explain yourself, <class>?", completion = "<The troll looks into the package.>\n\nYou have my thanks.  You may tell your young dwarven friend that I am not sad.  I am waiting.  For you.\n\nI have identified you as the most promising <race> here in this strange town.  I have a task for you, if you would be willing to take it." }
WordHunterWoW_QuestEN[26809] = { title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the north.  Hir'eek will guide you from there.", objectives = "Place the Gurubashi Incense in front of the Totem of Hir'eek, then listen to Zanzil's plot.", completion = "It is as I suspected.  Zanzil is too haughty to interfere with the squabbles between the Bloodscalps and the Skullsplitters.  No, he is playing a part in a grander scheme... Jin'do the Hexxer is using him to help bring Hakkar back to Zul'Gurub.\n\nIt's good that we found this out now, because it offers us a simple solution." }
WordHunterWoW_QuestEN[26810] = { title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return swiftly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", objectives = "Travel to the Ruins of Aboraz in the Cape of Stranglethorn and deal with Zanzil the Outcast." }
WordHunterWoW_QuestEN[26811] = { title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Maywiki entrusted this task to you.\n\nThe portal lies in wait in front of you.", objectives = "Use Zanzil's Portal and enter Zul'Gurub.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite." }
WordHunterWoW_QuestEN[26812] = { title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", objectives = "Destroy High Priestess Jeklik's body before Zanzil can resurrect her.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite." }
WordHunterWoW_QuestEN[26813] = { title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", objectives = "Pass through Zanzil's Portal.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite." }
WordHunterWoW_QuestEN[26814] = { title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", objectives = "Deal with Zanzil the Outcast and High Priest Venoxis.\n\nIf you become lost or need to return to Zul'Gurub, speak with Maywiki at the Explorers' League Digsite.", completion = "I ask you to slay Zanzil the Outcast, a lowly, hermetic exile of the Gurubashi, and what do you do?  You dash headfirst into the Gurubashi capital and eliminate one of their High Priests!  Very nearly two!  Only one word suffices to explain such a rash and foolhardy endeavor:\n\nHeroism.\n\nJin'do the Hexxer still walks within Zul'Gurub's walls, but he lost one of his legs when you crushed Jeklik.  Today's battle is ours." }
WordHunterWoW_QuestEN[26815] = { title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI need his mixture for my next test.  Check the zombies to the north.", objectives = "Obtain 5 vials of Zanzil's Mixture.", progress = "Excellent... you're not a zombie yet.  That's good.\n\nOh, umm... nothing.  It's just that... that was a potential risk.  Did I forget to warn you?", completion = "<Dask carefully analyzes the strange compound.>\n\nThis mixture is... PERFECT!  Let's see what it does to your potentially-titan artifact here!" }
WordHunterWoW_QuestEN[26816] = { title = "Recipe for Disaster", description = "Did you see that explosion I made?  I must have flown 10 inches off the ground!\n\nI've just got to get Zanzil's recipe so I can find out why it did that.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the coast of the Cape, and snatch it for me!", objectives = "Obtain Zanzil's Formulation from one of Zanzil's followers in the Ruins of Aboraz.", progress = "Did he use shimmerweed?  I'm guessing he used shimmerweed.\n\nNo wait... amberseeds!  It's gotta be amberseeds.", completion = "This is fascinating!  Just think of all the applications!\n\nThanks again, <name>.  Remember, if you ever need anything mixed for you... and I mean ANYTHING... you can always ask The Flask." }
WordHunterWoW_QuestEN[26817] = { title = "Perfectly Pure", description = "This humour won't serve on its own.  Too thick.  WAY too thick.\n\nThe nagas to our west maintain a shrine that dispenses the only clean water this side of Duskwood.  For most potions, I'll use river water, but Bronwyn demands accuracy!\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", objectives = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", progress = "<Dask looks eagerly at your pack as you approach.>", completion = "Do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nAlright, let's get this mix started!" }
WordHunterWoW_QuestEN[26818] = { title = "Plush Pelts", description = "Hi, I'm the town merchant!  And Bronwyn's my dad!\n\nSorry, I shouldn't get too excited.  Father says it's not professional.\n\nAnyhow, people always come to me asking for heavy leather, or rough hides, but I think they might also like it if I had some soft materials... like tiger fur!  Think you could get some for me?\n\nYou'll find a few panthers nearby, but if you want to see the big tigers, you'll have to go northwest from here... north of that big troll arena.", objectives = "Obtain 4 Supple Tiger Furs and 4 Velvety Panther Furs.", progress = "Oooh... I hope they're soft!", completion = "<Linzi feels the hides and smiles to herself.>\n\nThese are so nice and cushy!  I think my customers are going to LOVE them!" }
WordHunterWoW_QuestEN[26819] = { title = "Akiris by the Bundle", description = "The naga explorers to our west carry a valuable ocean reed - Akiris reeds.  Traders use them to make medicines and poultices, and craftsmen use them to line armor or even wrap cigars!\n\nIn the evenings, when digging's done, father's been teaching me how to use them... but unfortunately, we ran out.  Would you mind getting us some more?", objectives = "Obtain 6 Akiris Reeds from Naga Explorers.", progress = "Welcome back!", completion = "Hooray!  It's been days and days since we last had Akiris reeds!" }
WordHunterWoW_QuestEN[26820] = { title = "If They're Just Going to Leave Them Lying Around...", description = "Father says that a responsible merchant is always keeping an eye out for good deals.  I've been trying to look for deals everywhere I go, and I think I've just found one!\n\nThe naga to the west have dozens of statues that they place on the ground where they live.  They couldn't possibly need all of them... so I was thinking that we'd take some for ourselves!\n\nFree statues!  That's a good deal, right?", objectives = "Obtain 6 Naga Icons from the Southern Savage Coast in the Cape of Stranglethorn.", progress = "Let's see 'em!", completion = "These statues are beautiful...\n\nWow, I had no idea the naga were so talented.  Thanks, <name>!" }
WordHunterWoW_QuestEN[26821] = { title = "Airwyn Bantamflax", description = "Well, we have no idea what this artifact is.  It's old, older than dirt... but not titan.  I'm completely dumbstruck.\n\nAirwyn Bantamflax in Booty Bay is my direct superior.  Our next step should be to inform her of this find.  Please, would you bring it to her?", objectives = "Bring the Opened Mosh'ogg Bounty to Airwyn Bantamflax at Booty Bay in the Cape of Stranglethorn.", progress = "Yes, <race>?  I'm quite busy.", completion = "Fascinating!\n\nI'll need some time to study this.  Why don't you have a look around Booty Bay and come back later?" }
WordHunterWoW_QuestEN[26822] = { title = "Good-Fer-Nothin' Slither-Dogs", description = "Ahem!  Hrm, hrm...\n\n<The dwarf clears his throat for several seconds.>\n\nYou're lookin' fer somethin' ta do?  And ya come askin' ME?  Lowly ol' Goris?!\n\nWell, ah... this is a first.  Ah, I've got it!\n\nThe vale ta tha north is filled with a bunch o' useless, belly-scrapin' basilisks.  They don't do nothin' for no one, and I hear they turned a guy ta stone once.\n\nIf ya kill 'em, I'll give ya some o' my stuff.", objectives = "Kill 12 Thrashtail or Ironjaw Basilisks.", progress = "This is kinda fun.  Sendin' folks out ta do work for me... better than lousy ol' guard duty.", completion = "Ahem!  Ahhh... right...\n\nWell done!  And, congratulations, on killing them, I mean.\n\nHere you go." }
WordHunterWoW_QuestEN[26823] = { title = "Too Big For His Britches", description = "Whatever it is you want to do: I've got a recipe that'll do exactly that.  You want an exploding potion?  BOOM!!  You want a lightning potion?  ZAP!!  You want a shrinking potion?  Smeerp.\n\nSo Bronwyn says he wants a carbon-dating potion?  Easy.  I could make that in my sleep.  The thing is... if we want it to be accurate, I need you to get some quality ingredients.\n\nStart with some humour from a basilisk to the north.  It'll need to be a pretty big basilisk...", objectives = "Obtain a vial of Ironjaw Humour from the Ironjaw Behemoth in the Crystalvein Mine.", progress = "You got the task?  I got the flask.", completion = "Alright!  Step one - getting ingredients - is all done.  Time for the next step: getting more ingredients." }
WordHunterWoW_QuestEN[26824] = { title = "Results: Inconclusive", description = "I did all I could, {name}.  I had the right potions... I had the right recipes... but the source of this sample eludes me.  It's tens of thousands of years old, but we've shown that it's not of titan origin.  And it's not saronite, I can tell you just by looking at it.  So... what in Brann's name is it?\n\nTell Bronwyn that I tried my best.  Sorry.", objectives = "Return the Opened Mosh'Ogg Bounty to Bronwyn at the Explorers' League Camp in the Cape of Stranglethorn.", progress = "I saw smoke.  Everything alright?", completion = "I knew that alchemist was all talk.  Well, thanks for your help, <name>.  I know you tried." }
WordHunterWoW_QuestEN[26825] = { title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that fella' that Wulfred was talkin' about!  The one who found the ogre artifact, and helped him test out those strange stones from up north.  Welcome to the digsite, {name}!\n\nWe were actually working on identifying those samples right as you got here.  Would you mind bringing the sample over to Dask?  I need him to help me find out how old it is.", objectives = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there." }
WordHunterWoW_QuestEN[26826] = { title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that fella' that Wulfred was talkin' about!  Welcome to the digsite, {name}.\n\nWe were actually just starting a project when you arrived.  Would you mind bringing this sample over to Dask?  I need him to help me find out how old it is.", objectives = "Bring the Opened Mosh'Ogg Bounty to Dask \"The Flask\" Gobfizzle at the Explorers' League Digsite in the Cape of Stranglethorn.", progress = "You got something that needs mixing?", completion = "So once again, it falls upon tiny Dask to get the Explorers' League work done!  Alright... let's see what you've got in there." }
WordHunterWoW_QuestEN[26827] = { title = "Rallying the Earthen Ring", description = "We must be rallyin' da Earthen Ring for dis fight. What we be lackin' in numbers, we make up for in strength.\n\nGo to tha temple and gather da restin' shaman from tha rear rooms. Norsala, Lorvarius, and I will be meetin' them at Lorthuna's Gate.", objectives = "Rally 5 shaman in the rear of the Temple of Earth, and then speak to Maruut Stonebinder.", completion = "You've done what I thought not possible. Quite impressive, <class>." }
WordHunterWoW_QuestEN[26828] = { title = "Our Part of the Bargain", description = "Sadly, I must stay and hold the rift, so you will have to battle without me. Go now to Therazane and join the battle, as promised. You should find her at the Halcyon Egress, north of Lorthuna's Gate and east of the Scoured Reach.\n\nWhen our part of the bargain is fulfilled, bring the last piece of the World Pillar here as quickly as possible. ", objectives = "Speak to Therazane on the Halcyon Egress.", completion = "And so you arrive, fleshling.  As promised." }
WordHunterWoW_QuestEN[26829] = { title = "The Stone March", description = "My forces have already begun the assault. Join them. Spill the blood of these cultists upon the ground, that I might feel how they suffer.", objectives = "Kill 15 Twilight Precipice Cultists.", completion = "Their blood upon the earth is a sweet thing. I shall cherish every moment, slowly extinguishing the stragglers from my realm." }
WordHunterWoW_QuestEN[26830] = { title = "Traitor's Bait", description = "The Twilight's Hammer agents still lurk within the confines of Orgrimmar. I need someone I trust to collect the final evidence of treachery.\n\n<Eitrigg pulls you aside.>\n\nI suspect that Sauranok the Mystic is involved. I need you to uncover the truth, {name}.  The Twilight's Hammer has placed their agents within the ranks of the workers at the airship docks to spread their lies across the land. Speak with them. If you find evidence of Sauranok's guilt then show him what happens to traitors of the Horde.", objectives = "Question Orgrimmar Skyway Peons around the Zeppelin Towers. Look for any Suspicious Peons. Try to flush out Sauranok the Mystic and kill him.", completion = "Sauranok, Sauranok. His own visions worked against him. Twilight's Hammer probably corrupted him from afar. Bah! Weak! We'll speak his name no more.\n\nI told him you were investigating the airship docks, <name>. To flush him out. Yes, I used you as bait. You served your Horde well, and deserve a reward for outing this viper from our midst." }
WordHunterWoW_QuestEN[26831] = { title = "The Twilight Flight", description = "Terrath wants you to make your way to the far end of the precipice to fight Zoltrik Drakebane. He is on his way there as well, but he thinks Zoltrik is likely to take to the sky.\n\nQuite an impression you seem to have made, little one. Have you ever mused that none of this would have happened if I had just stepped on you during our first meeting? Fate is a strange thing.", objectives = "Defeat Zoltrik Drakebane.", progress = "It is good to see you on the battlefield again.", completion = "It is good that you were here. I find my size to be inhibiting when it comes to dragon riding, strangely." }
WordHunterWoW_QuestEN[26832] = { title = "Therazane's Mercy", description = "There are two leaders among the Twilight that need to be killed.\n\nOne is a human by the name of Boldrich. Small, as you are. But still dangerous, as you also are.\n\nThe other is a priestess by the name of Lorthuna. She is wily and hard to corner. Strike swiftly and do not let her escape, or I promise you, you will regret it later.", objectives = "Defeat Boldrich Stonerender and High Priestess Lorthuna.", completion = "You let Lorthuna escape? I warned you of this.\n\nStill, their forces are shattered and their resources cut off. There is little they can do to me or my allies." }
WordHunterWoW_QuestEN[26833] = { title = "Word In Stone", description = "You have done as I've asked of you, {race}. I shall honor my word. Gorsik will meet you at the temple with our piece of the World Pillar.\n\nFinish your ritual and bind the rift. After you have done such, tell your Earthen Ring to leave this place.\n\nYou however... you can stay for a time if you want. You've earned at least that.", objectives = "Speak to Maruut Stonebinder in the Temple of Earth.", completion = "Gorsik has arrived. All of the pieces of the World Pillar are here, thanks to you.\n\nWhat you have done for us is immeasurable.  These final moments shall be the most crucial.  I hesitate to ask more of you, but I'd like you to stay with us and see this through.\n\nThe Twilight's Hammer was devastated by your attacks, but not destroyed.  It's no stretch to assume they will try to stop us from completing our ritual." }
WordHunterWoW_QuestEN[26834] = { title = "Down Into the Chasm", description = "Down below in Needlerock Chasm is where the mystics are sprouting all of these fungal monstrosities. I sent Slate Quicksand and a small force to deal with it, but they've run into a snag.\n\nYou remember the Arch Geomancer? Would you fly down there to the northeast and lend him a hand?", objectives = "Speak with Slate Quicksand at Needlerock Chasm in Deepholm.", completion = "Good to see you again, <name>. Now we'll get somewhere." }
WordHunterWoW_QuestEN[26835] = { title = "A Slight Problem", description = "While you were out there, Pyrium Lodestone contacted me. He said that there is a matter of great urgency and that your assistance is needed immediately. Return to him at the entrance to Needlerock Slag to the southwest.\n\nI wish you luck with the rescue of the Stonefather and the recovery of the middle fragment.", objectives = "Return to Pyrium Lodestone at Needlerock Slag in Deepholm.", completion = "<name>, we have good news and a slight problem...." }
WordHunterWoW_QuestEN[26836] = { title = "Rescue the Stonefather... and Flint", description = "We found out where the Stonefather is being held and young Flint ran off on his own to rescue him!\n\nI don't have to tell you that this is bad. Flint is going to get himself captured as well, or worse!\n\nThe stone trogg chieftain, Bouldergut, is at the end of the ledges above Needlerock Chasm to the north.\n\nPlease, {name}, you must go after Flint and free the Stonefather before we lose them both!", objectives = "Free Stonefather Oremantle.", completion = "<name>! You did it! How will we ever repay you?" }
WordHunterWoW_QuestEN[26837] = { title = "The Explorers' League Digsite", description = "Say, {name}... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn.  Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle.  I wonder what it is?", objectives = "Report to Bronwyn Hewstrike at the Explorers' League Digsite in the Cape of Stranglethorn.Say, <name>... you seem suitable.\n\nBronwyn Hewstrike of the Explorers' League has been asking for recruits at his digsite in the Cape of Stranglethorn. Personally, I don't understand why he can't just go down to Booty Bay and find his recruits there... pirates are easily swayed by a couple pieces of gold.\n\nEither way... rumors are he's finally found something in that jungle. I wonder what it is?You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26838] = { title = "Rebels Without a Clue", description = "Several years ago, Stormwind's Captain Kurzen brought a brigade into Stranglethorn Vale on a mission whose details are still murky.  Kurzen swiftly descended into madness, as did his men... except for a few rebels who made it their mission to undo the evils that Kurzen had wrought.\n\nAs I said, that was years ago.  I'm now hearing rumors that Kurzen is dead, but those rebels still persist at their rebellion.  If you wish to investigate, you'll find them at a camp on Stranglethorn's northern border.", objectives = "Report to Lieutenant Doren at the Rebel Camp in Northern Stranglethorn.", completion = "Welcome to our camp, <class>.  You couldn't have arrived at a better time." }
WordHunterWoW_QuestEN[26839] = { title = "Get Away From It All!", description = "Say, {class}, you look tired.  Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor {race} back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn.  Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit.  I can tell just by looking that you need a break after so many difficult, lucrative adventures.", objectives = "Visit Sassy Hardwrench at Hardwrench Hideaway in the Cape of Stranglethorn.Say, <class>, you look tired. Carrying around that heavy wallet... er, I mean... heavy equipment... must be a strain on your poor <race> back.\n\nSassy Hardwrench has recently established a premier five-star resort on the sparkling coast off the Cape of Stranglethorn. Balloon tours, rowboating, day trips to Booty Bay... they've got it all.\n\nYou should really go visit. I can tell just by looking that you need a break after so many difficult, lucrative adventures.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26840] = { title = "Return to the Highlands", description = "With Orgrimmar secure and our Dragonmaw allies behind us, we can turn our attention to the conquest of the Twilight Highlands and the utter destruction of Deathwing's forces there.\n\nI need the Horde's best on the front lines. That means you. And all your friends.\n\nThe Highlands WILL be ours!\n\nUse the new portal you created to return to Dragonmaw Port. Report to Zaela to see where she needs you the most.", objectives = "Use the Twilight Highlands Portal in Orgrimmar to return to Dragonmaw Port in the Twilight Highlands and speak to Zaela.", completion = "<name>! I trust Orgrimmar fares well?\n\nAs you can see, construction of Dragonmaw Port continues at a breakneck pace. If my people questioned the Horde's power before... the sight of this imposing edifice and the speed in which it was constructed leaves no doubt.\n\nA new day dawns for the Dragonmaw." }
WordHunterWoW_QuestEN[26841] = { title = "Forbidden Sigil", description = "This sigil was given to me by a messenger from our mage trainer, Rhyanda. It seems Rhyanda would have words with you when you have a moment. Read it and bring it to her afterwards.", objectives = "Speak to Rhyanda inside Aldrassil in Shadowglen.", progress = "I'm glad that you've come, <name>.", completion = "I will be your mentor and guide for now. It is my duty to teach you the arcane arts and how you might best fit in among our people.\n\nAs you learn and grow in power, you will learn an immense variety of spells that should allow you to deal with nearly any situation. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind." }
WordHunterWoW_QuestEN[26842] = { title = "Out of Gnoll-where", description = "Well met, {class}. We've got a problem, and I'd ask you to lend a hand.\n\nIt's gnolls. There's a mess of the things west of town, roaming the hills. Not usually any cause for alarm, but we've not usually had gnolls here in Loch Modan.\n\nI'm curious where they came from, but not curious enough to bother asking the mangy things. Clear 'em out, I say. Bring back proof of your kills and I'll pay a solid bounty.", objectives = "Collect 12 Gnoll Ears from Mosshide Scouts or Mosshide Bashers.", progress = "Got some ears for me, then?", completion = "Nicely done, lad. I could use a <class> like you around here." }
WordHunterWoW_QuestEN[26843] = { title = "A Tiny, Clever Commander", description = "We've dealt with kobolds in these lands for years. Not much other than a nuisance. But they've been getting craftier at their stealing.\n\nI think one of them's ended up smarter than usual. Won't be that way for long, though!\n\nI want you to go to the camp south of here and make sure there's not a \"big shot\" kobold stirrin' up the other ones. Make sure to check the cave; it's a likely spot.\n\nAnd don't be shy about clearing out the other kobolds along the way.", objectives = "Slay Commander Nazrim.", progress = "Don't forget to find that \"commander\" down in the cave.", completion = "So I was right! Now the question is what the little freaks were plotting..." }
WordHunterWoW_QuestEN[26844] = { title = "Kobold and Kobolder", description = "Now that those little blighters are dealt with, we've got more to take care of.\n\nThe tunnel rats are swarming all over the Silver Stream Mine, setting up camps and sniffing around further and further every day. Greedy little things are looking for loot, I gather.\n\nSurveying and foraging is all fine and dandy when it's not on dwarven land! Take care of those tunnel rats and report back to me.", objectives = "Slay 5 Tunnel Rat Surveyors and 5 Tunnel Rat Foragers.", progress = "We'll deal with the mine proper once you've cleaned up the outer perimeter.", completion = "Good, good. Now we can see what's going on down in that mine." }
WordHunterWoW_QuestEN[26845] = { title = "Who's In Charge Here?", description = "Dorli's filled me in on this crazy trogg-slave operation the kobolds have going, and if you haven't talked to her about it yet, I suggest you do.\n\nI'd like to get to the bottom of this. Literally! Whoever's running this show is bound to be at the bottom of the mine, calling the shots, and I want them dealt with.\n\nFind whatever crafty bugger is directing the geomancers and diggers and bring me back their head.", objectives = "Collect the head of Foreman Sharpsneer.", progress = "I don't suppose it was Moira down there? Miracles do happen.", completion = "That's a gnoll head. Are you trying to pull some funny business, <name>?\n\nIf you're not, I've not the faintest idea what's going on here." }
WordHunterWoW_QuestEN[26846] = { title = "A Nasty Exploit", description = "I've found out what those rats are up to. There's so many of them outside because they've got troggs digging for them in the mine!\n\nThe tunnel rat geomancers figured out some kind of parlor trick to control the troggs, as creatures of the earth or somesuch.\n\nFascinating, but not something we want to let them practice. Take out those geomancers right away.", objectives = "Slay 5 Tunnel Rat Geomancers.", completion = "I'm sure that only worked because the troggs aren't bright to begin with. But then again, us dwarves were once creatures of the earth as well.\n\nBeing bossed around by a kobold doesn't sound quite dignified, and I'm glad we didn't get to find out if they could pull that off." }
WordHunterWoW_QuestEN[26847] = { title = "The Quaking Fields", description = "The king has moved south, just past Stonehearth, to the Quaking Fields.\n\nGood luck in retrieving the middle fragment of the World Pillar, but beware the giants and other creatures of the field, <name>.You will receive:", objectives = "Speak with King Oremantle at the Quaking Fields in Deepholm.The king has moved south, just past Stonehearth, to the Quaking Fields.\n\nGood luck in retrieving the middle fragment of the World Pillar, but beware the giants and other creatures of the field, <name>.You will receive:" }
WordHunterWoW_QuestEN[26848] = { title = "X Marks the Spot", description = "<The king marks a spot on your map.>\n\nThat's where I buried it. Head on out there and dig it up for me.\n\nJust avoid those giants. I can tell you from experience that they hit like a... well, like a giant!You will receive:", objectives = "Head out to where King Oremantle buried the second World Pillar fragment." }
WordHunterWoW_QuestEN[26849] = { title = "The Axe of Earthly Sundering", description = "The emerald colossi need to be removed from the field. It's conceivable that one of them has the fragment. Regardless, Therzane has moved her forces too close to Stonehearth and they pose a threat.\n\nSunder the giants with my axe. That should bring them down to a more manageable size so that you can finish them off.You will be able to choose one of these rewards:", objectives = "Slay 5 Sundered Emerald Colossi." }
WordHunterWoW_QuestEN[26850] = { title = "Elemental Ore", description = "We'll need to perform a ritual to pinpoint where the World Pillar fragment's been taken.\n\nGo out into the field and collect elemental ore from the ragers. With enough of it, I should be able to make you one with the ground to learn what we need.You will receive:", objectives = "Collect 6 Elemental Ore." }
WordHunterWoW_QuestEN[26851] = { title = "One With the Ground", description = "I know a ritual of the earth that will make you one with the ground. Because I have already handled the fragment, the spirits of the ground will take you near to it.\n\nKeep your mind focused on the World Pillar and let me know when you are ready, <name>.You will receive:", objectives = "Through the One With the Ground ritual, discover the location of the Middle Fragment of the World Pillar." }
WordHunterWoW_QuestEN[26852] = { title = "The Fragment's Inside", description = "The Middle Fragment of the World Pillar is within Avalanchion's Vault. Enter and retrieve it.You will receive:", objectives = "Collect the Middle Fragment of the World Pillar." }
WordHunterWoW_QuestEN[26853] = { title = "The Middle Fragment", description = "Fly. Fly as fast as you can, <name>!\n\nGet the middle fragment back to the Temple of Earth in the middle of Deepholm!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver the Middle Fragment of the World Pillar to Earthcaller Yevaa at the Temple of Earth in Deepholm." }
WordHunterWoW_QuestEN[26854] = { title = "The Lost Pilot", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills. We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot.\n\nIt's been days, and I've heard some beastly growls north of Helm's Bed Lake, west of the tunnel. Mori's tough as nails, but I'm worried.\n\nPlease, {name}. Find him.", objectives = "Find Pilot Hildelve north of Helm's Bed Lake.", completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end." }
WordHunterWoW_QuestEN[26855] = { title = "A Pilot's Revenge", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", objectives = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot at the South Gate Outpost.", progress = "Hello, <name>.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, <name>. Your deed will be remembered by the pilots of the Ironforge Siege Brigade." }
WordHunterWoW_QuestEN[26856] = { title = "Repel the Invasion", description = "This cavern was once a place of great honor. Young warriors were taken here to slay an Earthborer worm for their first kill - something we Orcs remember for our entire lives.\n\nThe Burning Blade agents inside have enslaved the cave's inhabitants and plan to launch a full-scale attack on Orgrimmar along with their Trogg allies.\n\nIf you strike down their Lieutenants, you may be able to catch them unprepared and stop this invasion before it starts.", objectives = "Kill Oggleflint, Bazzalan, and Jergosh the Invoker.", completion = "You've done it, <name>! You've upturned the Searing Blade's invasion before it could even start! Take this, as a token of my thanks." }
WordHunterWoW_QuestEN[26857] = { title = "Abyssion's Minions", description = "If it's the dragon that's got the fragment, we're going to need to draw his attention back to his den.\n\nGo to Abyssion's Lair just east of here and defeat his underlings.  That should get him to show up with the World Pillar fragment sooner or later.", objectives = "Defeat 8 Twilight or Dragonkin units at Abyssion's Lair.", completion = "That ought to get the dragon's attention, <name>." }
WordHunterWoW_QuestEN[26858] = { title = "Taragaman the Hungerer", description = "The Searing Blade has managed to summon a foul demon they call Taragaman the Hungerer to lead the first attack in their takeover of Orgrimmar!\n\nMake haste and slay Taragaman in the name of the Warchief! Lok'tar ogar!", objectives = "Take Taragaman the Hungerer's heart.", progress = "If Taragaman is dead, show me his heart.", completion = "My children will sing songs of your glories, <name>!" }
WordHunterWoW_QuestEN[26859] = { title = "Searching for the Lost Satchel", description = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.Upon completion of this quest you will gain:", objectives = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26860] = { title = "Thelsamar Blood Sausages", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy {class}, you'll be any exception.\n\nYou get me some fresh bear rumps and leave the cooking to me!", objectives = "Collect 8 Bear Rumps from Black Bears in Loch Modan.", progress = "I'm all ready to start cooking, do you have the bear meat for me?", completion = "Much obliged! The rump's part of my own secret twist on the recipe... but here's instructions on how to make it with any kind of bear meat.\n\nAnd here's a fresh batch of me own. Mind you eat them fresh!" }
WordHunterWoW_QuestEN[26861] = { title = "Block the Gates", description = "If we're to have a shot against Abyssion, we must make sure he receives no aid from reinforcements.\n\nYou will find two gateways in his lair to the east.  Use this stormstone to disrupt their operation.\n\nIf everything goes as planned, we'll be able to tackle Abyssion without him being able to receive much assistance.", objectives = "Use the Stormstone at the Twilight Gate and Elemental Gate in Abyssion's Lair.", completion = "Excellent.  When we make our move against Abyssion, we should be able to do so without reinforcements coming to his aid." }
WordHunterWoW_QuestEN[26862] = { title = "Elemental Tampering", description = "The Searing Blade's warlocks have enslaved Ragefire Chasm's elemental spirits, {name}. They aren't a threat to the city while my spell keeps them at bay, but I can't maintain it much longer.\n\nBring me six of the Searing Bindings used to control them and I will release their spirits back into the Chasm.", objectives = "Obtain 6 Searing Bindings.", progress = "Do you have the bindings?", completion = "Thank you, <class>. The Molten Elementals' spirits are finally back to rest." }
WordHunterWoW_QuestEN[26863] = { title = "Filthy Paws", description = "The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now kobolds have moved in, putting their filthy paws on good, dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", objectives = "Collect 6 loads of Miners' Gear from the Silver Stream Mine.", progress = "Do you have that Miners' Gear, <name>?", completion = "Did you see a lot of kobolds in there? The thought of their grimy hands clawing around our mine makes my stomach rumble!" }
WordHunterWoW_QuestEN[26864] = { title = "The Bearer of Gnoll-edge", description = "I need you to take this back to Mountaineer Kadrell. Show it to him and tell him the nasty critters around here might be having some kind of get-together.", objectives = "Deliver Foreman Sharpsneer's Head to Mountaineer Kadrell.", progress = "Any news from Algaz Station?", completion = "Gnolls and kobolds, and troggs? Oh my.\n\nI'd laugh if I didn't have another twist in the story for you." }
WordHunterWoW_QuestEN[26865] = { title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Stone Guard Kurjack just inside Ragefire Chasm. He will have further orders for you. ", objectives = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, <name>." }
WordHunterWoW_QuestEN[26866] = { title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Searing Blade. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Stone Guard Kurjack just inside the Chasm. Help him in any way you can, for our fates are intertwined.", objectives = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, <name>." }
WordHunterWoW_QuestEN[26867] = { title = "Enemies Below", description = "With all his usual grace, Warchief Garrosh has kindly requested your presence in Ragefire Chasm to help retake it from the Searing Blade. Apparently, his reinforced city isn't as impenetrable as he thought.\n\nGo speak with Stone Guard Kurjack just inside Ragefire, I'm sure he'll be glad to have competent help.", objectives = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, <name>." }
WordHunterWoW_QuestEN[26868] = { title = "Axis of Awful", description = "Alright, now just shut yer gob and lemme talk, 'cause here's the plan.\n\nThose gnolls and murlocs are liable to be meetin' out there somewhere. So you take this clever plant disguise of mine, and you wear it and look like a plant. Then you sneak up on 'em, and you throw this scent pheromone you gathered on the mosshide standin' with the murlocs.\n\nThen the murlocs'll flip their spit, and the mosshides will think twice about trying to work with such crazy lil' buggers!", objectives = "Use the Clever Plant Disguise Kit to sneak up on the Mosshide Representative and use the Potent Murloc Pheromones on him.", progress = "Well don't just stand around here like some kinda idiot! Get out there and act like a plant!", completion = "Worked like a charm, didn't it? Maybe Kadrell will get off my darn back now what with savin' the whole town and all!\n\nI suppose you've done earned yourself some proper goods." }
WordHunterWoW_QuestEN[26869] = { title = "Depth of the Depths", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nWell done, {race}.\n\nWithin the tunnels below, you will find the stone which you seek. Painite.\n\nThe dangers ahead are many...\n\nDangers that the Stone Lords themselves fear.\n\nRemain steady.\n\nRemain strong.\n\nThe strength of the rock itself is beneath your feet.", objectives = "Find the Painite within the Crumbling Depths.", completion = "<This is it. This is the stone Diamant sent you for.>" }
WordHunterWoW_QuestEN[26870] = { title = "Cleansing the Caverns", description = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was.\n\nBut something went terribly wrong.\n\nNaralex's trusted allies, the Druids of the Fang, turned on him! They seek not to heal the Barrens, but to dominate it.\n\n{name}, before we can awaken Naralex and restore balance to this vital place, you need to eradicate the Fanglords. Their influence has sunk too deeply.", objectives = "Ebru in the Wailing Caverns wants you to kill the Fanglords Cobrahn, Anacondra, Pythas, and Serpentis.", progress = "Are the Fanglords dead? Muyoh cannot awaken Naralex until they are!", completion = "I can already feel the balance returning! Quick, talk to Muyoh to help him awaken Naralex!" }
WordHunterWoW_QuestEN[26871] = { title = "A Rock Amongst Many", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nYou've done as I've asked.\n\nTurn back and escape the cave in one piece.\n\nDon't forget the gemstone.", objectives = "Return to Diamant at Lorthuna's Gate with the Painite Chunk.", progress = "You're alive. This is good.\n\nIs the gemstone with you?", completion = "Well done, fleshling!\n\nThe gyreworms are among our most dangerous enemies.\n\nThe other Stone Lords shall have trouble not turning their head to this accomplishment." }
WordHunterWoW_QuestEN[26872] = { title = "Deviate Hides", description = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. Their very existence causes great pain to the earth. I believe that slaying them will greatly aid our work in healing the caverns.\n\nIf you feel up to the task, slay as many as you can and bring me their hides as proof of their demise.", objectives = "Nalpak wants 10 Deviate Hides.", progress = "How many of the beasts have you slain?", completion = "Your efforts shall not go unnoticed, <name>.\n\nThank you for your dedication." }
WordHunterWoW_QuestEN[26873] = { title = "Preemptive Methods", description = "There is an herb in these caverns that holds untold power, {name}. Perhaps you wish to help me collect it?\n\nIt is a rare flower called Serpentbloom. I believe that in greater quantities it has the potential to prevent nightmares like Naralex's from ever occuring.\n\nUnfortunately, Serpentbloom can only be found in the darkest recesses of this place.", objectives = "Nalpak wants you to collect 5 Serpentbloom.", progress = "I am eager to see if you can gather enough Serpentbloom.", completion = "You have done well, <name>. Hopefully we can use these to prevent further nightmares." }
WordHunterWoW_QuestEN[26874] = { title = "Awakening Naralex", description = "Now that the Fanglords are dead, speak with Muyoh. He will help you awaken Naralex and end this nightmare.", objectives = "Speak with Muyoh.Now that the Fanglords are dead, speak with Muyoh. He will help you awaken Naralex and end this nightmare.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26875] = { title = "Undying Twilight", description = "The Twilight Cultists are here! They're trying to stop the ritual! Get to the back chambers and help fight them off!", objectives = "Kill 12 Twilight invaders and 1 Desecrated Earthrager.", completion = "The Twilight forces continue to stream in, but it looks like the Earthen Ring defenders can handle them." }
WordHunterWoW_QuestEN[26876] = { title = "The World Pillar Fragment", description = "It is time, {name}.  We have spotted Abyssion making his way to the lair.\n\nThe Twilight's Hammer might've thought the fragment would be safe if a dragon guarded it, but I've met enough dragons to know their one weakness.  Pride.\n\nAbyssion's not going to run from a fight with us puny mortals.\n\nPlace the banner of the Earthen Ring in the middle of his lair.  Once we defeat him, bring the fragment to Maruut.  We need to repair the World Pillar as soon as possible.", objectives = "Place the Earthen Ring Banner in the center of Abyssion's Lair, slay him and obtain the Upper World Pillar Fragment.", progress = "<name>!  You've returned!", completion = "Your efforts in repairing the World Pillar are invaluable, <name>.  Once the Temple of Earth's structure is stable again, the rift between the worlds will begin to stabilize." }
WordHunterWoW_QuestEN[26877] = { title = "The Fragment's Inside", description = "<name>, you need to enter Avalanchion's Vault to the southeast and retrieve the Middle Fragment of the World Pillar!You will receive:", objectives = "Collect the Middle Fragment of the World Pillar." }
WordHunterWoW_QuestEN[26878] = { title = "Disciples of Naralex", description = "{class}, the Barrens used to be one of the most beautiful places in all of Kalimdor. It teemed with life and promise.\n\nNow, as you can see, that is no longer true. It is a land of great torment and strife.\n\nThe Disciples of Naralex seek to cleanse the Wailing Caverns and bring them back to their former beauty. Speak with Nalpak just inside the Wailing Caverns to help.", objectives = "Speak with Nalpak in the Wailing Caverns.", completion = "Yes, <class>? What brings you to this place?" }
WordHunterWoW_QuestEN[26879] = { title = "Disciples of Naralex", description = "<class>, this place is, shall I say, not optimal for my business endeavors. If it were more lively, I have an idea that would make me the richest goblin that's ever lived!\n\nA <class> of your stature must see the potential in that, or at least care about the environment or something.\n\nGo talk to Nalpak just inside the Wailing Caverns, he's a Disciple of Naralex and, just between you and me, I think they're going to fix this blasted place for good! It's my big break!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Nalpak in the Wailing Caverns.<class>, this place is, shall I say, not optimal for my business endeavors. If it were more lively, I have an idea that would make me the richest goblin that's ever lived!\n\nA <class> of your stature must see the potential in that, or at least care about the environment or something.\n\nGo talk to Nalpak just inside the Wailing Caverns, he's a Disciple of Naralex and, just between you and me, I think they're going to fix this blasted place for good! It's my big break!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26880] = { title = "Gilneas City Unphase Cheat", description = "", objectives = "" }
WordHunterWoW_QuestEN[26881] = { title = "In Search of Aluwyn", description = "There's something sinister going on within this place, {name}. We fear that the rumors of the Twilight's Hammer in Blackfathom Deeps are true.\n\nI sent Sentinel Aluwyn, one of our best scouts, further in to investigate the matter, but she hasn't returned.\n\nSeek her out. If she's still alive, find out all that she's learned.", objectives = "Seek out Sentinel Aluwyn at Blackfathom Deeps.There's something sinister going on within this place, <name>. We fear that the rumors of the Twilight's Hammer in Blackfathom Deeps are true.\n\nI sent Sentinel Aluwyn, one of our best scouts, further in to investigate the matter, but she hasn't returned.\n\nSeek her out. If she's still alive, find out all that she's learned.", completion = "Ashelan was good to send you. There is indeed a wicked plot underway in this corrupted place." }
WordHunterWoW_QuestEN[26882] = { title = "Blackfathom Villainy", description = "My strength has left me. I need your help!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, a servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan.", objectives = "Get the head of Twilight Lord Kelris.", progress = "It is good to see you again, <name>. What news do you bring?\n\nWas your foray successful? Did you find Thaelrid?", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him either dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nTo sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, <name>. I thank you on behalf of Ashenvale.\n\nIf only Thaelrid had survived...." }
WordHunterWoW_QuestEN[26883] = { title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing here.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", objectives = "Obtain 3 Twilight Pendants.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding the temple of their presence?", completion = "You are no doubt of brave and noble blood, <name>. We and all of the people of Ashenvale commend you for your efforts against evil." }
WordHunterWoW_QuestEN[26884] = { title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the sin'dorei are headed toward. Try to avoid harming the stems while you kill them, I won't take anything but perfect specimens.", objectives = "Gather 8 Corrupt Brain Stems.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have undoubtedly faced great peril to obtain these.\n\nYour actions have been selfless. It is for the good of all Azeroth that you help me with my research. I thank you, <name>, for all that you have done.\n\nNow if you'll excuse me I have much work to do." }
WordHunterWoW_QuestEN[26885] = { title = "Knowledge in the Deeps", description = "It is my duty as a trainee to collect lore for my superiors. Old lore. Powerful lore. Lore that opens doorways, and lore that could awaken more of Those Who Sleep if it is mishandled.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of the Pool of Ask'ar in a Pitted Iron Chest. It is the old dwelling of our long-dead ancestors. They held great knowledge before their city fell to ruin.\n\nSearch for the manuscript, please. I'm not skilled enough to venture further!", objectives = "Find the Lorgalis Manuscript.", progress = "Your task is not an easy one, my friend.\n\nBut if you get me the manuscript, <name>...then your reward will be great and we will gain a better understanding of what it is that the Twilight's Hammer and the naga are up to.", completion = "You found the manuscript! What a joyous day this is! I will study it exhaustively and learn all there is to know.\n\nI'll make full sentinel yet!\n\nYour service to us is more than you know, <name>. I hope that this gift shows you my gratitude." }
WordHunterWoW_QuestEN[26886] = { title = "Going Off-Task", description = "That nasty ship on the east side of the cove keeps firing its cannons at us. It's kinda funny seeing all the goblins get hit by cannonballs, but some of my gnome friends are being hit too!\n\nIt'd be really, really nice if you could make your way past those cannons and onto the ship. There's a mean ol' taskmaster yelling at the other deckhands in there, and I'm sure if you beat him up or kill him, they'll stop shooting at us!", objectives = "Kill the Southsea Taskmaster.", completion = "Wonderful! I hope you didn't get hit with too many cannonballs." }
WordHunterWoW_QuestEN[26887] = { title = "Filling Our Pockets", description = "I know we're here to make friends with the Steamwheedle goblins, but those awful Bilgewater goblins are so rude.\n\nWhy, I just saw a bunch of them pulling gold fillings out of the teeth of the Southsea musketeers and strongarms. Do they think they can just take that for themselves?\n\nObviously, the nice thing to do is kill those pirates ourselves, take their fillings, and then give some of them to the Steamwheedle as a thank-you gift! Head on down there and beat those goblins to the punch.", objectives = "Collect 20 Gold Fillings from Southsea Musketeers or Southsea Strongarms.", progress = "Have you got the fillings?", completion = "More gold! We'll be sure to give some of this to Mister Noggenfogger to smoothly ensure our continued relations.\n\nAnd only a little bit of it will go back to Gnomeregan for experimental weapons development!" }
WordHunterWoW_QuestEN[26888] = { title = "Nightmare of the Deeps", description = "In the darkest recesses of Blackfathom, a monster spawned by the Old Gods lurks. We know it only as Aku'mai.\n\nThe Old Gods and their servants are incredibly dangerous to our world. Long ago, they ruled over Azeroth and I fear that they seek to do so again, or destroy it while trying.\n\n<name>, Aku'mai is a creature of untold nightmare. We simply cannot allow his continued existence. Destroy him.", objectives = "Kill Aku'mai.", completion = "The beast is slain. I can feel his dark presence fading away forever." }
WordHunterWoW_QuestEN[26889] = { title = "All Cheered Out", description = "Well gosh, we've cleaned up quite a bit here!\n\n<Kelsey clears her throat.>\n\nListen, {name}, I'm looking forward to finally vacating this killbox so I can get away from these goblins and drop the cheer-act. If you'd like to continue to advance the interests of Gnomeregan, and by extension the Alliance, in the area, head south to Bootlegger Outpost.\n\nTalk to Zeke Bootscuff there, and remember that any work for the Steamwheedle will help us shut the Bilgewater out of Tanaris for good.", objectives = "Talk to Zeke Bootscuff at Bootlegger Outpost.", completion = "You know, I'm usually not impressed when I see a <race>, but I've heard about what you've been doin' for the Steamwheedle. You're alright, kid." }
WordHunterWoW_QuestEN[26890] = { title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, there are large sapphire clusters along the cave walls. We noticed that the naga started harvesting the crystals around the same time their weaponry greatly improved.\n\nThe crystals seem to have great elemental power and, if used inappropriately, could make for a powerful component for my smithing.\n\nWill you help me, {name}? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", objectives = "Collect 20 Sapphires of Aku'Mai.", progress = "How goes your search for the crystals, <name>? Do you think they'll make an item we can use to stop the naga?", completion = "Excellent! These will do nicely. Here's a reward for your hard work." }
WordHunterWoW_QuestEN[26891] = { title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins here.  Their presence can only serve to coerce the elements into working against us.\n\n<name>, find the Twilight agents here, then find the ruin's fathom stone; it should be somewhere underwater, probably right underneath their own noses. In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, the Earthen Ring and I can hopefully do something to stop them!", objectives = "Extract the Fathom Core.", progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud." }
WordHunterWoW_QuestEN[26892] = { title = "Deep in the Deeps", description = "The Naga and the Twilight's Hammer work together to undo all the progress we've made in this area. What's more, Je'neu tells me that he feels the presence of an Old God lingering far beneath us.\n\nIf they wish to witness chaos, we will give them just that.\n\n<name>, cut down their strongest warriors, and we'll see how much they enjoy it.\n\nSearch carefully, Blackfathom Deeps is full of underwater passages and side paths in the caves that may hide your targets.", objectives = "Slay Ghamoo-Ra, Lady Sarevess, and Gelihast.", completion = "I can hear their cries from here! Maybe this will show them how foolish it is to wish for the return of an Old God." }
WordHunterWoW_QuestEN[26893] = { title = "Blackfathom Deeps", description = "There's a task to be done that you're perfect for, {class}. We need to secure the area around Blackfathom Deeps to help with the Alliance that are threatening Zoram'gar Outpost west of here.\n\nGo to Blackfathom Deeps, north of Zoram'gar Outpost, and speak with Je'neu of the Earthen Ring. He will have plenty for you to do.", objectives = "Speak with Je'neu Sancrea.There's a task to be done that you're perfect for, <class>. We need to secure the area around Blackfathom Deeps to help with the Alliance that are threatening Zoram'gar Outpost west of here.\n\nGo to Blackfathom Deeps, north of Zoram'gar Outpost, and speak with Je'neu of the Earthen Ring. He will have plenty for you to do.You will receive:\n\nUpon completion of this quest you will gain:" }
